/* Custom fighters from Register a Fighter sit above the base roster. */
const CUSTOM_FIGHTER_BASE = FIGHTERS.length;
const CUSTOM_FIGHTERS = [];
function isCustomFighter(fid){ return fid >= CUSTOM_FIGHTER_BASE; }
function syncCustomFighters(){
  CUSTOM_FIGHTERS.length = 0;
  const saved = (typeof SAVE !== "undefined" && Array.isArray(SAVE.customFighters)) ? SAVE.customFighters : [];
  saved.forEach((cf, idx) => {
    if(!cf || typeof cf !== "object" || !cf.name) return;
    const fid = CUSTOM_FIGHTER_BASE + idx;
    const entry = { name: cf.name, deck: cf.deck != null ? cf.deck : 0, role: "custom", customIdx: idx, cafId: cf.id || ("caf_"+idx) };
    CUSTOM_FIGHTERS.push(entry);
    FIGHTERS[fid] = entry;
    if(cf.bio) BIOS[cf.name] = cf.bio;
    TRAITS[fid] = null;
  });
  FIGHTERS.length = CUSTOM_FIGHTER_BASE + CUSTOM_FIGHTERS.length;
}
function drawCustomPortrait(fid,x,y,w,h,paletteOverride){
  let pal = paletteOverride;
  if(!pal && isCustomFighter(fid)){
    const cf = CUSTOM_FIGHTERS[fid - CUSTOM_FIGHTER_BASE];
    const saved = cf && SAVE.customFighters ? SAVE.customFighters[cf.customIdx] : null;
    pal = (saved && saved.colorPalette) || { primary: "#e03a2f", secondary: "#111318" };
  }
  if(!pal) pal = { primary: "#e03a2f", secondary: "#111318" };
  cx.save();
  panel(x,y,w,h,"rgba(8,11,16,.92)",pal.primary,null,6);
  cx.fillStyle = pal.primary;
  cx.beginPath();
  cx.arc(x+w*0.5, y+h*0.38, w*0.22, 0, Math.PI*2);
  cx.fill();
  cx.fillRect(x+w*0.32, y+h*0.52, w*0.36, h*0.38);
  cx.fillStyle = pal.secondary;
  cx.fillRect(x+w*0.28, y+h*0.78, w*0.44, h*0.08);
  cx.restore();
}
/* who else is on your data deck - shown in the readout so the sharing is honest */
const DECK_SHARERS={};
FIGHTERS.forEach((f,i)=>{ (DECK_SHARERS[f.deck]=DECK_SHARERS[f.deck]||[]).push(i); });

