/* Core legacy aliases for 100% backward compatibility with save files & tests */
ARCHETYPES.pressure = ARCHETYPES.pressure_fighter;
ARCHETYPES.counter = ARCHETYPES.counter_puncher;
ARCHETYPES.grappler = ARCHETYPES.wrestler;
ARCHETYPES.outfighter = ARCHETYPES.out_boxer;

const ARCHETYPE_IDS = Object.keys(ARCHETYPES);

/* A fighter's own dossier decides their gameplan, so it is theirs rather
   than a die roll - the same opponent always fights the same way. */
function archetypeFor(fid, seed) {
  const discs = (typeof disciplinesOf === "function") ? disciplinesOf(fid) : [];
  const b = (typeof bioOf === "function") ? bioOf(fid) : null;
  if (b && b.a) {
    const power = b.a[0] || 80;
    if (power >= 92) return "finisher";
  }
  if (discs.indexOf("bjj") >= 0) return "bjj";
  if (discs.indexOf("sambo") >= 0) return "sambo";
  if (discs.indexOf("judo") >= 0) return "judo";
  if (discs.indexOf("wrestling") >= 0) return "wrestler";
  if (discs.indexOf("muaythai") >= 0 || discs.indexOf("lethwei") >= 0) return "muay_thai";
  if (discs.indexOf("taekwondo") >= 0) return "taekwondo";
  if (discs.indexOf("shotokan") >= 0) return "karate";
  if (discs.indexOf("kickboxing") >= 0) return "kickboxer";
  if (discs.indexOf("boxing") >= 0) return ((fid + (seed || 0)) % 2) ? "counter_puncher" : "power_puncher";

  const grap = ["bjj", "wrestling", "sambo", "judo", "grappling", "subgrap", "jiujitsu", "sumo"];
  if (discs.some((d) => grap.indexOf(d) >= 0)) {
    return discs.length > 1 && discs.some((d) => grap.indexOf(d) < 0) ? "pressure_fighter" : "wrestler";
  }
  const longr = ["taekwondo", "wushu", "kickboxing"];
  if (discs.some((d) => longr.indexOf(d) >= 0)) return "out_boxer";

  return ((fid + (seed || 0)) % 2) ? "counter_puncher" : "pressure_fighter";
}

const archetypeOf = (id) => ARCHETYPES[id] || ARCHETYPES.pressure_fighter;

/* ---- src/progress/mastery.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - fighter mastery
   Luminary Digital

   The answer to "I lost, so that run was worth nothing".

   Every fight you take with a fighter earns them mastery, win or lose -
   a loss earns less, never zero. Mastery is permanent, per fighter, and
   pays out as small standing perks the next time you pick them. So a run
   that ends badly still moved something forward, and the roster's long
   tail is worth exploring rather than settling on one favourite.

   Deliberately modest: mastery smooths a fighter out, it does not win
   fights for you. The ceiling is roughly one good camp benefit.
   ===================================================================== */
const MASTERY_RANKS = [
  { level: 0, name: "Unranked",  need: 0,   perk: "" },
  { level: 1, name: "White",     need: 40,  perk: "+1 starting focus" },
  { level: 2, name: "Blue",      need: 110, perk: "start adventures at level 2" },
  { level: 3, name: "Purple",    need: 230, perk: "+10 stamina ceiling" },
  { level: 4, name: "Brown",     need: 400, perk: "signature meter starts at 25%" },
  { level: 5, name: "Black",     need: 640, perk: "one more technique in their kit" },
];
const MASTERY_MAX = MASTERY_RANKS.length - 1;
const MASTERY_COLORS = ["#6b7280", "#e8e6e1", "#3a8ae0", "#8b5cf6", "#a0642a", "#111318"];

/* what a single fight is worth */
const MASTERY_AWARD = { win: 18, loss: 7, perfect: 8, boss: 20, ranked: 6, survival: 4 };
function masteryFor(result) {
  let xp = result.win ? MASTERY_AWARD.win : MASTERY_AWARD.loss;
  if (result.win && result.perfect) xp += MASTERY_AWARD.perfect;
  if (result.boss && result.win) xp += MASTERY_AWARD.boss;
  if (result.matchType === "ranked") xp += MASTERY_AWARD.ranked;
  if (result.matchType === "survival") xp += MASTERY_AWARD.survival;
  return xp;
}

const masteryXp = (save, fid) => ((save.mastery || {})[fid] || 0);
function masteryRank(xp) {
  let r = MASTERY_RANKS[0];
  for (const m of MASTERY_RANKS) if (xp >= m.need) r = m;
  return r;
}
function masteryProgress(xp) {
  const r = masteryRank(xp);
  if (r.level >= MASTERY_MAX) return 1;
  const next = MASTERY_RANKS[r.level + 1];
  return Math.max(0, Math.min(1, (xp - r.need) / (next.need - r.need)));
}
function masteryToNext(xp) {
  const r = masteryRank(xp);
  return r.level >= MASTERY_MAX ? 0 : MASTERY_RANKS[r.level + 1].need - xp;
}
/* returns {gained, from, to, levelled} */
function awardMastery(save, fid, result) {
  if (!save.mastery) save.mastery = {};
  const before = masteryXp(save, fid);
  const gained = (typeof masteryForWithArc === "function")
    ? masteryForWithArc(result, save, fid)
    : masteryFor(result);
  const after = before + gained;
  save.mastery[fid] = after;
  const from = masteryRank(before), to = masteryRank(after);
  return { gained, from, to, levelled: to.level > from.level };
}

/* the standing perks, applied where the fighter is built */
const masteryLevel = (save, fid) => masteryRank(masteryXp(save, fid)).level;
function applyMastery(side, level) {
  if (level >= 1) { side.focusMax += 1; side.focus = Math.min(side.focusMax, side.focus + 1); }
  if (level >= 3) side.maxStam += 10;
  if (level >= 4) side.sup = Math.max(side.sup, Math.round(SUP_MAX * 0.25));
  side.stam = side.maxStam;
  return side;
}
/* level 2 starts adventures further along; level 5 widens the elite kit */
const masteryStartLevel = (save, fid) => (masteryLevel(save, fid) >= 2 ? 2 : 1);
const masteryKitBonus = (save, fid) => (masteryLevel(save, fid) >= 5 ? 1 : 0);

/* ---- src/progress/career-arcs.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - career arcs
   Luminara Digital

   Potential is a ceiling, not a destination. Each fighter has a permanent
   Career Arc that shapes how mastery accrues over a career:

     early_peak     fast early gains, softer late
     standard       balanced
     late_developer slow start, strong mid
     long_prime     steady gains for longer

   Fight count (save.fr wins+losses) is the age proxy - no calendar needed.
   ===================================================================== */

const CAREER_ARCS = {
  early_peak: {
    id: "early_peak", name: "EARLY PEAK",
    note: "climbs fast, then plateaus",
    /* primeStart was 0, and careerPhase asks `n < primeStart` - which is never
       true at zero, so the 1.35 early bonus was unreachable and an early peaker
       debuted on primeMul 1.05, growing SLOWER than a standard fighter's 1.10.
       The arc that says "climbs fast" was the worst opener in the game. Six
       fights of early, against standard's eight: the peak comes sooner, which
       is what the arc is for. */
    primeStart: 6, primeEnd: 18, earlyMul: 1.35, primeMul: 1.05, lateMul: 0.70,
  },
  standard: {
    id: "standard", name: "STANDARD PRIME",
    note: "textbook development curve",
    primeStart: 8, primeEnd: 40, earlyMul: 1.10, primeMul: 1.15, lateMul: 0.85,
  },
  late_developer: {
    id: "late_developer", name: "LATE DEVELOPER",
    note: "slow start, strong mid career",
    primeStart: 16, primeEnd: 55, earlyMul: 0.75, primeMul: 1.30, lateMul: 0.95,
  },
  long_prime: {
    id: "long_prime", name: "LONG PRIME",
    note: "holds form deep into the career",
    primeStart: 6, primeEnd: 70, earlyMul: 1.00, primeMul: 1.12, lateMul: 1.05,
  },
};
const CAREER_ARC_IDS = Object.keys(CAREER_ARCS);

function careerArcOf(fid) {
  const discs = (typeof disciplinesOf === "function") ? disciplinesOf(fid) : [];
  const grapple = discs.some((d) =>
    ["bjj", "wrestling", "judo", "sambo", "subgrap", "grappling", "jiujitsu"].indexOf(d) >= 0);
  let h = ((fid | 0) * 2246822519) >>> 0;
  /* Grapplers bias toward long_prime / late_developer. */
  const pool = grapple
    ? ["long_prime", "late_developer", "standard", "long_prime"]
    : ["early_peak", "standard", "late_developer", "early_peak", "standard"];
  const id = pool[h % pool.length];
  return CAREER_ARCS[id] || CAREER_ARCS.standard;
}

function careerFightCount(save, fid) {
  if (!save || !save.fr) return 0;
  const row = save.fr[fid] || save.fr[String(fid)];
  if (!row) return 0;
  return Math.max(0, (row.w | 0) + (row.l | 0));
}

function careerPhase(arc, fights) {
  const a = arc || CAREER_ARCS.standard;
  const n = Math.max(0, fights | 0);
  if (n < a.primeStart) return "early";
  if (n <= a.primeEnd) return "prime";
  return "late";
}

function careerArcGrowthMul(arc, fights) {
  const a = typeof arc === "string" ? CAREER_ARCS[arc] : (arc || CAREER_ARCS.standard);
  if (!a) return 1;
  const phase = careerPhase(a, fights);
  if (phase === "early") return a.earlyMul;
  if (phase === "prime") return a.primeMul;
  return a.lateMul;
}

/* Rare post-prime resurgence: capped, needs a win, falls off with age. */
function careerArcResurgeChance(arc, fights, won, rnd) {
  const R = rnd || Math.random;
  if (!won) return false;
  const a = arc || CAREER_ARCS.standard;
  const n = fights | 0;
  if (n <= a.primeEnd) return false;
  const yearsPast = n - a.primeEnd;
  let chance = 0.045;
  if (yearsPast > 20) chance *= 0.35;
  else if (yearsPast > 10) chance *= 0.6;
  return R() < chance;
}

function masteryForWithArc(result, save, fid) {
  const base = (typeof masteryFor === "function") ? masteryFor(result) : 10;
  const arc = careerArcOf(fid);
  const fights = careerFightCount(save, fid);
  let xp = Math.round(base * careerArcGrowthMul(arc, fights));
  if (careerArcResurgeChance(arc, fights, !!(result && result.win))) {
    xp = Math.round(xp * 1.25);
  }
  return Math.max(1, xp);
}

/* ---- src/progress/rivalry-heat.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - player callouts and rivalry heat
   Luminara Digital

   Player-initiated same-division callouts raise media heat and feed the
   next bout. Heat is stored on the save, decays slowly, and never grants
   ranked points by itself.
   ===================================================================== */

const CALLOUT_CONFIG = {
  heatGain: 2,
  heatCap: 8,
  heatDecay: 1,
  atkMulPerHeat: 0.015,
  purseBonusPerHeat: 4,
  maxStored: 48,
};

function calloutKey(a, b) {
  const x = Math.min(a | 0, b | 0);
  const y = Math.max(a | 0, b | 0);
  return x + ":" + y;
}

function ensureCallouts(save) {
  if (!save) return { heat: {}, log: [] };
  if (!save.callouts || typeof save.callouts !== "object") {
    save.callouts = { heat: {}, log: [] };
  }
  if (!save.callouts.heat || typeof save.callouts.heat !== "object") save.callouts.heat = {};
  if (!Array.isArray(save.callouts.log)) save.callouts.log = [];
  return save.callouts;
}

function rivalryHeatOf(save, a, b) {
  if (a == null || b == null || a === b) return 0;
  const bag = ensureCallouts(save);
  const n = bag.heat[calloutKey(a, b)] | 0;
  return Math.max(0, Math.min(CALLOUT_CONFIG.heatCap, n));
}

/* Issue a callout. Same division preferred; authored rivals get a bonus. */
function issueCallout(save, fromFid, toFid) {
  if (!save || fromFid == null || toFid == null || fromFid === toFid) {
    return { ok: false, reason: "bad_pair" };
  }
  const bag = ensureCallouts(save);
  const key = calloutKey(fromFid, toFid);
  let gain = CALLOUT_CONFIG.heatGain;
  if (typeof isRivalPair === "function" && isRivalPair(fromFid, toFid)) gain += 1;
  if (typeof rivalOf === "function") {
    /* soft same-card check: if either already has the other as rival, fine */
  }
  const prev = bag.heat[key] | 0;
  const next = Math.min(CALLOUT_CONFIG.heatCap, prev + gain);
  bag.heat[key] = next;
  bag.log.push({
    from: fromFid | 0,
    to: toFid | 0,
    at: Date.now(),
    heat: next,
  });
  if (bag.log.length > CALLOUT_CONFIG.maxStored) {
    bag.log = bag.log.slice(bag.log.length - CALLOUT_CONFIG.maxStored);
  }
  return { ok: true, heat: next, gained: next - prev, key: key };
}

function decayCalloutHeat(save, a, b) {
  if (!save || a == null || b == null) return 0;
  const bag = ensureCallouts(save);
  const key = calloutKey(a, b);
  const prev = bag.heat[key] | 0;
  if (prev <= 0) return 0;
  const next = Math.max(0, prev - CALLOUT_CONFIG.heatDecay);
  if (next <= 0) delete bag.heat[key];
  else bag.heat[key] = next;
  return next;
}

/* Apply heat to a duel at the bell: both corners get a little bite. */
function applyCalloutHeatToDuel(d, save) {
  if (!d || !d.p || !d.e || !save) return 0;
  const heat = rivalryHeatOf(save, d.p.fid, d.e.fid);
  if (heat <= 0) return 0;
  const mul = 1 + heat * CALLOUT_CONFIG.atkMulPerHeat;
  d.p.atkMul = (d.p.atkMul || 1) * mul;
  d.e.atkMul = (d.e.atkMul || 1) * mul;
  d.calloutHeat = heat;
  d.calloutLine = heat >= 4
    ? "THE CALLOUT MADE THIS PERSONAL"
    : "MEDIA HEAT ON THIS CARD";
  return heat;
}

function calloutPurseBonus(save, a, b) {
  const heat = rivalryHeatOf(save, a, b);
  return heat * CALLOUT_CONFIG.purseBonusPerHeat;
}

/* ---- src/progress/meta.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - RENOWN, the currency that outlives a run
   Luminara Digital

   The measured problem this file exists to fix: the only thing surviving
   a loss today is per-fighter mastery, spread thin across 25 fighters and
   deliberately modest by its own documentation (ranks at 40/110/230/400/
   640 XP, 18 per win). Nothing a player owns after ten runs changes what
   run eleven OFFERS them. Run ten is run one with better hands.

   RENOWN is the fix. It is earned by EVERY run, win or lose, scaled by
   how deep the run got, and it is spent on permanent additions to the RUN
   POOL - the set of things a future run can be dealt.

   Two hard lines, both of them rules of the game rather than taste:

     1. RENOWN NEVER BUYS A FIGHTER. Everyone is playable from a fresh
        save; SAVE.unlocked means "mastered", not "selectable". Nothing in
        this catalogue touches fighter selection, and nothing in it should
        ever be allowed to.
     2. RENOWN NEVER BUYS RAW NUMBERS. It buys BREADTH - one more art the
        drafter may reach into, one more slot in the corner bag, one more
        map layout, the option of a harder opening that pays more. A
        player who owns everything here has a wider pool to be dealt
        from, not a bigger hitting stat.

   Why breadth and not power: the run already has three tuned economies
   (draft budget, camp benefits, the purse) and every one of them was
   balanced against the pool it draws from. Widening the pool changes what
   a run can BECOME without moving a single damage number, so none of the
   measured balance work has to be redone.

   PRICED AGAINST MEASURED REALITY
   A full clear is roughly 11-22 fights and a stage carries 5-7, so most
   runs die in stage two or three having won eight to fourteen fights.
   That run pays about 23-40 renown. The cheapest meaningful purchase is
   55, so the first one lands in two or three runs - not thirty. Owning
   the whole catalogue is around 1,350, which is a long tail on purpose:
   the first purchase must be soon, the last one must be far.

   PURE LOGIC. This module renders nothing, reads no input, touches no
   canvas and never looks at SAVE. Every function here takes the save
   block as an argument and RETURNS A NEW ONE - nothing below is allowed
   to mutate what it was handed, so a caller can price a purchase, show
   it, and only then commit it. It also reads no other module, by design:
   the numbers it needs to agree with (the corner bag's base of three)
   are restated here as constants and pinned by a test, so this file has
   no load-order dependency of any kind.

   Assumed globals: none.
   Save block: SAVE.meta, shape below, created by DEF_META().
   ===================================================================== */

const META_SAVE_VERSION = 1;

const META_CONFIG = {
  /* the currency, in copy */
  name: "RENOWN",
  unit: "RN",

  /* the corner bag starts at three (SHOP_CONFIG.cornerCarry). Restated
     rather than read so this module has no load order; meta.test.js
     asserts the two agree, which is what keeps the restatement honest. */
  cornerBase: 3,

  /* every save carries at least the stock map layout */
  baseLayout: "standard",

  /* hard ceilings, so a corrupt or hand-edited save cannot print money
     and no arithmetic below can run away */
  balanceCap: 99999,
  awardCap: 400,
};

/* ---------------------------------------------------------------------
   WHAT A FINISHED RUN PAYS

   Depth is the driver, because depth is what the run actually records.
   `stage` is tracked on every run; a lifetime win counter is not (a.beaten
   is cleared at every stage clear - see the BENEFIT handler), so wins are
   an optional refinement the caller may pass and the award never depends
   on them.

   The clear bonus is large and the per-stage step is not, because the
   thing worth rewarding is getting further than last time, and the thing
   worth NOT rewarding is farming stage one.
   --------------------------------------------------------------------- */
const META_AWARD = {
  base: 6,             // you turned up. A run that dies in stage one still pays.
  perStage: 9,         // per stage actually cleared (stage reached, minus the one you died in)
  perWin: 1,           // a small hand on top, when the caller can count them
  clear: 40,           // the Daemon King put away
  ngStep: 0.15,        // NG+ pays more because everyone hits harder
  ngCap: 0.45,
  openStep: 0.12,      // and so does electing to start on a harder card
  openCap: 0.24,
  stageCap: 9,         // clamps, so a junk stage number cannot pay out
  winCap: 40,
  ngLevelCap: 9,
};

/* ---------------------------------------------------------------------
   THE CATALOGUE

   kind      what buying it adds to the run pool
     disc    one more discipline the drafter may offer from
     corner  one more slot in the corner bag
     camp    the run starts holding one rolled camp benefit
     layout  one more map layout the field generator may pick
     open    one more opening tier: start deeper, get paid more

   price     the first purchase
   tiers     how many times it can be bought
   step      what each repeat multiplies the price by
   --------------------------------------------------------------------- */
const META_ITEMS = {};
const META_ITEM_IDS = [];
function MI(id, name, desc, tag, price, tiers, step, grant) {
  META_ITEMS[id] = { id, name, desc, tag, price, tiers: tiers || 1, step: step || 1, grant: grant || {} };
  META_ITEM_IDS.push(id);
}

/* --- the arts ---
   Six passes, one price. There is no best buy here on purpose: they cost
   the same and differ only in which ranges they open, so the decision is
   "what do I want my runs to be able to become", not "which is bigger".
   Between them they cover all four ranges twice over. */
const META_ART_PRICE = 70;
MI("art_boxing", "Boxing Pass", "the drafter may offer boxing - punching range, fast and accurate",
   "ART", META_ART_PRICE, 1, 1, { kind: "disc", disc: "boxing" });
MI("art_taekwondo", "Taekwondo Pass", "the drafter may offer taekwondo - kicking range, long and quick",
   "ART", META_ART_PRICE, 1, 1, { kind: "disc", disc: "taekwondo" });
MI("art_muaythai", "Muay Thai Pass", "the drafter may offer muay thai - long, punching and the tie-up",
   "ART", META_ART_PRICE, 1, 1, { kind: "disc", disc: "muaythai" });
MI("art_judo", "Judo Pass", "the drafter may offer judo - the tie-up, and the throw out of it",
   "ART", META_ART_PRICE, 1, 1, { kind: "disc", disc: "judo" });
MI("art_bjj", "Jiu-Jitsu Pass", "the drafter may offer Brazilian jiu-jitsu - the mat, and the finish on it",
   "ART", META_ART_PRICE, 1, 1, { kind: "disc", disc: "bjj" });
MI("art_sambo", "Sambo Pass", "the drafter may offer sambo - the tie-up and the mat together",
   "ART", META_ART_PRICE, 1, 1, { kind: "disc", disc: "sambo" });

/* --- the corner ---
   Three is the stock bag and the shop already refuses a fourth item
   (corner_full). A fourth and fifth slot is the cheapest thing here
   because it is the smallest thing here: more consumables carried, none
   of them stronger. */
MI("corner_slot", "Corner Bag", "one more corner item in the bag, carried into every fight",
   "CORNER", 55, 2, 1.8, { kind: "corner", slots: 1 });

/* --- the camp ---
   The camp hands out one benefit per stage clear, so starting with one is
   worth roughly a stage's head start and is priced at four ordinary runs.
   The benefit is ROLLED from the normal camp pool, never chosen: this buys
   a head start, not the pick of the best modifier in the game. */
MI("camp_start", "Standing Camp", "every run begins holding one camp benefit, rolled the usual way",
   "CAMP", 150, 1, 1, { kind: "camp", benefits: 1 });

/* --- the map ---
   Alternate field layouts. Neither is easier; both change what a stage
   asks of you, which is the only thing the field has ever asked. */
MI("map_gauntlet", "Gauntlet Layout", "an alternate field: open ground, more men on it",
   "MAP", 85, 1, 1, { kind: "layout", layout: "gauntlet" });
MI("map_labyrinth", "Labyrinth Layout", "an alternate field: tight walls, fewer ways past",
   "MAP", 85, 1, 1, { kind: "layout", layout: "labyrinth" });

/* --- the opening ---
   The one purchase that can make a run harder. It UNLOCKS an option; it
   never forces it. Starting on the main card skips the easy money and
   pays a premium for the whole run, which is a bet, not a buff - and the
   award below pays a little more for having taken it. */
const META_OPEN_TIERS = [
  { tier: 0, stage: 1, purseMul: 1.00, label: "FULL CARD" },
  { tier: 1, stage: 2, purseMul: 1.15, label: "UNDERCARD SKIPPED" },
  { tier: 2, stage: 3, purseMul: 1.30, label: "MAIN CARD ONLY" },
];
MI("open_stage", "Hard Opening", "opens a deeper starting stage that pays a premium all run",
   "OPENING", 60, 2, 2, { kind: "open", tiers: 1 });

/* --- adventure permanent perks --- */
const ADV_PERKS = {};
const ADV_PERK_IDS = [];
function defineAdvPerk(id, name, desc, tag, price, tiers, step, grant) {
  ADV_PERKS[id] = { id, name, desc, tag: tag || "CAMP", price, tiers: tiers || 1, step: step || 1, grant: grant || {} };
  ADV_PERK_IDS.push(id);
}
defineAdvPerk("adv_focus", "Starting Focus", "Adventure: start every combat with +1 Focus point",
   "CAMP", 85, 2, 1.6, { focus: 1 });
defineAdvPerk("adv_grit", "Iron Grit", "Adventure: +10% maximum health ceiling",
   "CAMP", 95, 2, 1.5, { hpMul: 0.10 });
defineAdvPerk("adv_second_wind", "Second Wind", "Adventure: survive a fatal blow once per run at 20% health",
   "CORNER", 150, 1, 1, { revives: 1 });
defineAdvPerk("adv_corner", "Field Bag Slot", "Adventure: carry +1 extra corner consumable into every fight",
   "CORNER", 70, 2, 1.6, { slots: 1 });

const META_BUY_REASON = {
  ok: "bought",
  bad_save: "no renown ledger on this save",
  unknown_item: "no such purchase",
  maxed: "already fully bought",
  cannot_afford: "not enough renown yet",
};

/* ---------------------------------------------------------------------
   ARITHMETIC THAT CANNOT THROW

   Every entry point below is total. Junk in gives a defined answer out:
   no exceptions, no NaN, no negative balance, ever. A meta-currency that
   can throw on a hand-edited save takes the whole page down on load.
   --------------------------------------------------------------------- */
function metaInt(n, lo, hi) {
  const v = Math.round(+n);
  if (!(v === v) || v === Infinity || v === -Infinity) return lo;
  return v < lo ? lo : (v > hi ? hi : v);
}
const metaSafeKey = (k) => (k === "__proto__" || k === "constructor" || k === "prototype");

/* Catalogue lookup, and the reason it is a function rather than an index:
   META_ITEMS["__proto__"] is TRUTHY on a plain object, so a naive lookup
   answers "yes, that is an item" for an id no one authored and then reads
   tiers and prices off Object.prototype. Every id that arrives from
   outside this file goes through here. */
function metaItem(id) {
  if (typeof id !== "string" || metaSafeKey(id)) return null;
  return Object.prototype.hasOwnProperty.call(META_ITEMS, id) ? META_ITEMS[id] : null;
}

/* ---------------------------------------------------------------------
   THE SAVE BLOCK
     { v, renown, earned, spent, runs, owned:{ itemId: tiersOwned } }
   renown is what you can spend. earned is lifetime, for the readout, and
   is never decreased - the two are separate numbers because "you have 12"
   and "you have won 340 across 19 runs" are different sentences.
   --------------------------------------------------------------------- */
function DEF_META() {
  return { v: META_SAVE_VERSION, renown: 0, earned: 0, spent: 0, runs: 0, owned: {} };
}

/* Takes anything at all and returns a clean block. Unknown item ids are
   dropped rather than kept, so a catalogue entry retired later cannot
   leave a ghost in the pool query. */
function metaNormalize(block) {
  const out = DEF_META();
  if (!block || typeof block !== "object" || Array.isArray(block)) return out;
  out.v = metaInt(block.v, 1, 999) || META_SAVE_VERSION;
  out.renown = metaInt(block.renown, 0, META_CONFIG.balanceCap);
  out.earned = metaInt(block.earned, 0, META_CONFIG.balanceCap * 10);
  out.spent = metaInt(block.spent, 0, META_CONFIG.balanceCap * 10);
  out.runs = metaInt(block.runs, 0, 999999);
  const owned = block.owned;
  if (owned && typeof owned === "object" && !Array.isArray(owned)) {
    META_ITEM_IDS.forEach((id) => {
      if (metaSafeKey(id)) return;
      if (!Object.prototype.hasOwnProperty.call(owned, id)) return;
      const t = metaInt(owned[id], 0, META_ITEMS[id].tiers);
      if (t > 0) out.owned[id] = t;
    });
    ADV_PERK_IDS.forEach((id) => {
      if (metaSafeKey(id)) return;
      if (!Object.prototype.hasOwnProperty.call(owned, id)) return;
      const t = metaInt(owned[id], 0, ADV_PERKS[id].tiers);
      if (t > 0) out.owned[id] = t;
    });
  }
  if (out.earned < out.renown) out.earned = out.renown;   // lifetime cannot be under the wallet
  return out;
}

const metaHasBlock = (save) =>
  !!save && typeof save === "object" && !!save.meta && typeof save.meta === "object" && !Array.isArray(save.meta);

/* The migration. A save from before renown existed has no `meta` key at
   all; one from a tampered blob may have garbage there. Both come out the
   same way, and the save handed in is not touched. */
function metaMigrate(save) {
  if (!save || typeof save !== "object" || Array.isArray(save)) return { meta: DEF_META() };
  const out = {};
  for (const k in save) {
    if (!Object.prototype.hasOwnProperty.call(save, k) || metaSafeKey(k)) continue;
    out[k] = save[k];
  }
  out.meta = metaHasBlock(save) ? metaNormalize(save.meta) : DEF_META();
  return out;
}

/* ---------------------------------------------------------------------
   THE AWARD

   Accepts a run object (G.adv shaped) or a plain summary. Reads, all
   optional:
     stage      how deep it got, 1-based. The whole award leans on this.
     wins       fights won across the run, if the caller counts them
     cleared    the run was finished (the boss went down)
     ng         new game + tier
     openTier   which opening tier the run elected to start on
   Returns { total, lines:[{ label, amount }], mult } so a results screen
   can show the arithmetic instead of a number nobody trusts.
   --------------------------------------------------------------------- */
function metaRunTally(run) {
  const r = (run && typeof run === "object") ? run : {};
  let wins = null;
  if (r.wins !== undefined && r.wins !== null) wins = metaInt(r.wins, 0, META_AWARD.winCap);
  else if (r.beaten && typeof r.beaten === "object") {
    // a.beaten is cleared at every stage clear, so this is this stage's
    // work only - depth carries the award, this is the garnish
    let n = 0;
    for (const k in r.beaten) if (Object.prototype.hasOwnProperty.call(r.beaten, k) && r.beaten[k]) n++;
    wins = metaInt(n, 0, META_AWARD.winCap);
  }
  return {
    stage: metaInt(r.stage, 1, META_AWARD.stageCap),
    wins: wins === null ? 0 : wins,
    cleared: !!(r.cleared || r.bossBeaten),
    ng: metaInt(r.ng, 0, META_AWARD.ngLevelCap),
    openTier: metaInt(r.openTier, 0, META_OPEN_TIERS.length - 1),
    renownMul: (typeof r.renownMul === "number" && r.renownMul > 0) ? r.renownMul : 1,
  };
}

function metaAwardFor(run) {
  const t = metaRunTally(run);
  const lines = [];
  const push = (label, amount) => { if (amount > 0) lines.push({ label, amount }); };

  let sub = META_AWARD.base;
  push("SHOWED UP", META_AWARD.base);

  const stagesDone = Math.max(0, t.stage - 1);
  const depth = stagesDone * META_AWARD.perStage;
  sub += depth;
  push("STAGES CLEARED x" + stagesDone, depth);

  const won = t.wins * META_AWARD.perWin;
  sub += won;
  push("FIGHTS WON x" + t.wins, won);

  if (t.cleared) { sub += META_AWARD.clear; push("THE CLIMB FINISHED", META_AWARD.clear); }

  const ngMul = Math.min(META_AWARD.ngCap, META_AWARD.ngStep * t.ng);
  const openMul = Math.min(META_AWARD.openCap, META_AWARD.openStep * t.openTier);
  const rMul = (t.renownMul && t.renownMul !== 1) ? t.renownMul : 1;
  const mult = (1 + ngMul + openMul) * rMul;

  const total = metaInt(sub * mult, 1, META_CONFIG.awardCap);
  return { total, lines, mult, ngMul, openMul, subtotal: sub, tally: t };
}

/* Banks an award. Returns a NEW block; the one handed in is untouched.
   `amount` may be a number or the object metaAwardFor() returned. The
   amount is clamped to the wallet ceiling rather than to awardCap: capping
   what a RUN can pay is metaAwardFor's job, and doing it twice here would
   silently swallow a legitimate grant (a restored save, a test fixture)
   without anyone being able to tell which cap bit. */
function metaCredit(block, amount) {
  const meta = metaNormalize(block);
  const n = metaInt((amount && typeof amount === "object") ? amount.total : amount,
                    0, META_CONFIG.balanceCap);
  meta.renown = metaInt(meta.renown + n, 0, META_CONFIG.balanceCap);
  meta.earned = metaInt(meta.earned + n, 0, META_CONFIG.balanceCap * 10);
  meta.runs = metaInt(meta.runs + 1, 0, 999999);
  return meta;
}

/* ---------------------------------------------------------------------
   BUYING
   --------------------------------------------------------------------- */
const metaTier = (block, id) => {
  const it = metaItem(id) || (typeof ADV_PERKS !== "undefined" && ADV_PERKS[id]);
  if (!it) return 0;
  const owned = (block && block.owned) || {};
  return metaInt(Object.prototype.hasOwnProperty.call(owned, id) ? owned[id] : 0, 0, it.tiers);
};

/* the price of the NEXT one. 0 when there is no next one. */
function metaPriceOf(block, id) {
  const it = metaItem(id);
  if (!it) return 0;
  const have = metaTier(block, id);
  if (have >= it.tiers) return 0;
  return Math.round(it.price * Math.pow(it.step, have));
}

/* Never throws. Always answers with a reason, so a shop row can be drawn
   greyed out with the reason under it rather than simply missing. */
function metaCanBuy(block, id) {
  const it = metaItem(id);
  if (!it) return { ok: false, reason: "unknown_item", price: 0, tier: 0 };
  if (!block || typeof block !== "object" || Array.isArray(block)) {
    return { ok: false, reason: "bad_save", price: it.price, tier: 0 };
  }
  const have = metaTier(block, id);
  if (have >= it.tiers) return { ok: false, reason: "maxed", price: 0, tier: have };
  const price = metaPriceOf(block, id);
  const purse = metaInt(block.renown, 0, META_CONFIG.balanceCap);
  if (purse < price) return { ok: false, reason: "cannot_afford", price, tier: have, short: price - purse };
  return { ok: true, reason: "ok", price, tier: have };
}

/* Buys one tier. Returns { ok, reason, meta, price, tier } where `meta` is
   always a usable block - the normalised original when the purchase was
   refused, a new one with the tier added when it went through. The balance
   is spent through metaInt with a floor of zero, so no path here can put a
   save into debt even if the catalogue is edited badly. */
function metaBuy(block, id) {
  const check = metaCanBuy(block, id);
  const base = metaNormalize(block);
  if (!check.ok) return { ok: false, reason: check.reason, meta: base, price: check.price, tier: check.tier };
  base.renown = metaInt(base.renown - check.price, 0, META_CONFIG.balanceCap);
  base.spent = metaInt(base.spent + check.price, 0, META_CONFIG.balanceCap * 10);
  base.owned[id] = check.tier + 1;
  return { ok: true, reason: "ok", meta: base, price: check.price, tier: base.owned[id] };
}

/* One row per catalogue entry, keyed by id - a screen picks rows by id and
   never by index, so inserting an entry cannot re-point its neighbour. */
function metaRows(block) {
  const meta = metaNormalize(block);
  return META_ITEM_IDS.map((id) => {
    const it = META_ITEMS[id], can = metaCanBuy(meta, id);
    return {
      id, name: it.name, desc: it.desc, tag: it.tag,
      tier: metaTier(meta, id), tiers: it.tiers,
      price: metaPriceOf(meta, id),
      can: can.ok, reason: can.reason,
      note: META_BUY_REASON[can.reason] || "",
    };
  });
}

function metaSummary(block) {
  const meta = metaNormalize(block);
  let owned = 0, maxed = 0;
  META_ITEM_IDS.forEach((id) => {
    const t = metaTier(meta, id);
    owned += t;
    if (t >= META_ITEMS[id].tiers) maxed++;
  });
  let total = 0;
  META_ITEM_IDS.forEach((id) => (total += META_ITEMS[id].tiers));
  return meta.renown + " " + META_CONFIG.unit + " - " + owned + " OF " + total + " BOUGHT" +
         (meta.runs ? " OVER " + meta.runs + (meta.runs === 1 ? " RUN" : " RUNS") : "") +
         (maxed >= META_ITEM_IDS.length ? " - THE WALL IS BARE" : "");
}

/* ---------------------------------------------------------------------
   WHAT A RUN POOL SHOULD CONTAIN

   The single query the run builder asks. Everything is ADDITIVE and
   absolute: `discs` are extra arts on top of the fighter's own, never a
   replacement for them; `cornerSlots` is the whole capacity, not a delta;
   `layouts` and `openStages` always contain the stock option, so a save
   that has bought nothing still gets a complete, playable answer. There is
   no branch in here that can return a pool a fresh save cannot use.

   Note what is NOT in it: no fighter list, no stat, no damage number.
   --------------------------------------------------------------------- */
function metaRunPool(save) {
  const block = metaHasBlock(save) ? save.meta
              : (save && typeof save === "object" && !Array.isArray(save) && save.owned !== undefined ? save : null);
  const meta = metaNormalize(block);
  const pool = {
    renown: meta.renown,
    discs: [],
    cornerSlots: META_CONFIG.cornerBase,
    startBenefits: 0,
    layouts: [META_CONFIG.baseLayout],
    openStages: [META_OPEN_TIERS[0]],
    owned: {},
  };
  META_ITEM_IDS.forEach((id) => {
    const tier = metaTier(meta, id);
    if (tier <= 0) return;
    pool.owned[id] = tier;
    const g = META_ITEMS[id].grant || {};
    if (g.kind === "disc" && g.disc && pool.discs.indexOf(g.disc) < 0) pool.discs.push(g.disc);
    else if (g.kind === "corner") pool.cornerSlots += (g.slots || 1) * tier;
    else if (g.kind === "camp") pool.startBenefits += (g.benefits || 1) * tier;
    else if (g.kind === "layout" && g.layout && pool.layouts.indexOf(g.layout) < 0) pool.layouts.push(g.layout);
    else if (g.kind === "open") {
      const top = Math.min(META_OPEN_TIERS.length - 1, (g.tiers || 1) * tier);
      for (let i = 1; i <= top; i++) if (pool.openStages.indexOf(META_OPEN_TIERS[i]) < 0) pool.openStages.push(META_OPEN_TIERS[i]);
    }
  });
  ADV_PERK_IDS.forEach((id) => {
    const tier = metaTier(meta, id);
    if (tier <= 0) return;
    pool.owned[id] = tier;
    const g = ADV_PERKS[id].grant || {};
    if (g.focus) pool.startFocus = (pool.startFocus || 0) + (g.focus * tier);
    if (g.hpMul) pool.ironGritMul = (pool.ironGritMul || 0) + (g.hpMul * tier);
    if (g.revives) pool.revives = (pool.revives || 0) + (g.revives * tier);
    if (g.slots) pool.cornerSlots += (g.slots * tier);
  });
  return pool;
}

function buyAdvPerk(save, id) {
  if (!metaHasBlock(save)) return { ok: false, reason: "bad_save" };
  const p = ADV_PERKS[id];
  if (!p) return { ok: false, reason: "unknown_item" };
  const meta = save.meta;
  if (!meta.owned || typeof meta.owned !== "object") meta.owned = {};
  const cur = meta.owned[id] || 0;
  if (cur >= p.tiers) return { ok: false, reason: "maxed" };
  const cost = Math.round(p.price * Math.pow(p.step, cur));
  if (meta.renown < cost) return { ok: false, reason: "cannot_afford" };
  meta.renown -= cost;
  meta.spent += cost;
  meta.owned[id] = cur + 1;
  return { ok: true, reason: "bought", tier: cur + 1, cost };
}

/* the opening the run elected to take, resolved against what is owned -
   an unowned tier silently falls back to the full card rather than
   handing the run a premium it never paid for */
function metaOpenTier(save, want) {
  const allowed = metaRunPool(save).openStages;
  const w = metaInt(want, 0, META_OPEN_TIERS.length - 1);
  for (let i = allowed.length - 1; i >= 0; i--) if (allowed[i].tier <= w) return allowed[i];
  return META_OPEN_TIERS[0];
}

/* ---- src/progress/discipline-mastery.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - discipline mastery
   Luminary Digital

   The second progression axis, and the one that always moves.

   Fighter mastery (progress/mastery.js) answers "I lost, so that run was
   worth nothing". It does not answer "I have 25 fighters and 640 XP of
   belt to earn on each of them at 18 a win". Per-fighter progress is
   diffuse by construction: pick a different fighter and you start again.

   This axis is keyed on the ART instead of the man. Every technique you
   actually throw feeds the discipline it came from, win or lose, and the
   arts overlap the roster heavily - so the boxing you did with one fighter
   is boxing you already own when you pick the next one. Whatever you play,
   something is climbing.

   Three things make it worth having rather than a second XP bar:

     IT POOLS      one art is fed by every fighter who trains it, and by
                   every cross-art technique the draft ever hands you.
     IT IS EARNED  XP comes from techniques USED, not from fights entered.
                   Lean on your kicks and your kicking art climbs; the art
                   you never throw stays where it is.
     IT FEEDS THE  a mastered art is likelier to be OFFERED. Mastery stops
     DRAFT         being a number on a menu and becomes the shape of the
                   next run's movelist.

   Ranks are plain English grades rather than belts, for two reasons: the
   belt ladder is already spoken for by fighter mastery, and these nineteen
   arts come from a dozen traditions whose own grading systems do not agree
   with each other.

   THE POWER BUDGET, stated so it can be argued with. A fully mastered art
   is worth, on that art's techniques only: +5 accuracy, +8% power, 2 less
   stamina, +5% initiative. For scale, one DRILL tier in the gym is +15%
   power and +5 accuracy and there are two of them, and the camp benefit
   ceiling is 1.35x damage. This is permanent and free, so it is
   deliberately smaller than either - it sharpens an art, it does not win
   with it. Priority is untouched on purpose: brackets are worth 1000
   initiative each, so a +1 there would quietly repeal "a sprawl always
   beats a takedown".

   Nothing here is gated behind anything. On a fresh save every bonus
   below is 0 and every multiplier is exactly 1, so wiring these into the
   resolver and the drafter changes no existing behaviour until the player
   has earned something.

   Pure logic. The save block is passed in and returned; no rendering, no
   input, no globals written.
   ===================================================================== */
const DISC_RANKS = [
  { level: 0, name: "Untrained",    need: 0,   perk: "",
    acc: 0, powMul: 1.00, stamCut: 0, spdMul: 1.00 },
  { level: 1, name: "Novice",       need: 25,  perk: "+2 accuracy with this art",
    acc: 2, powMul: 1.00, stamCut: 0, spdMul: 1.00 },
  { level: 2, name: "Practitioner", need: 80,  perk: "its techniques cost 1 less stamina",
    acc: 2, powMul: 1.00, stamCut: 1, spdMul: 1.00 },
  { level: 3, name: "Adept",        need: 180, perk: "+4% power with this art",
    acc: 3, powMul: 1.04, stamCut: 1, spdMul: 1.00 },
  { level: 4, name: "Instructor",   need: 340, perk: "+5% initiative with this art",
    acc: 4, powMul: 1.04, stamCut: 1, spdMul: 1.05 },
  { level: 5, name: "Master",       need: 560, perk: "+8% power, 2 less stamina",
    acc: 5, powMul: 1.08, stamCut: 2, spdMul: 1.05 },
];
const DISC_MASTERY_MAX = DISC_RANKS.length - 1;
const DISC_RANK_COLORS = ["#6b7280", "#c9c4bb", "#5aa860", "#3a8ae0", "#8b5cf6", "#d8b64a"];

const DISC_CONFIG = {
  /* --- what one fight is worth, per art --- */
  perUse: 2,              // each recorded technique of that art
  useCap: 7,              // uses counted per art per fight: spamming one
                          // technique is not training, so the base tops
                          // out at 14 and the flat awards carry the rest
  win: 5,                 // per art you actually used, on a win
  loss: 2,                // and on a loss, because nothing is lost on a defeat
  boss: 4,                // a won boss fight sharpens whatever won it
  finish: 3,              // the art that landed the finishing blow
  xpMax: 9999,            // a save can never carry an unbounded number

  /* --- the draft hook ---
     draft.js shades every offer by a handful of multipliers: ownMul 2.6,
     the invested ladder up to 3.4, gapMul 1.35, doorMul 2.2. This one sits
     in the same slot and is capped just under doorMul, the largest single
     shade already in that file - a mastered art is at most as loud as a
     door into a range you cannot reach. It composes multiplicatively with
     the rest, which is fine and is why the cap is where it is: draft.js
     documents that pool composition, not weight size, decides the offer
     mix (2.6 -> 9 on ownMul moved home picks 36% -> 42%). */
  draftStep: 0.20,        // per rank: level 5 lands exactly on 2.00
};

/* The arts, read at call time so this file does not care where it lands in
   MODULE_ORDER and picks up a twentieth discipline for free. Techniques
   with no discipline - the shared fundamentals - are deliberately absent:
   everyone owns them, so they would climb uniformly for every player and
   mean nothing. Same reasoning that keeps `shift` footwork out of
   draftRanges(). */
function discMasteryIds() {
  if (typeof DISCIPLINES === "undefined" || !DISCIPLINES) return [];
  return Object.keys(DISCIPLINES);
}
const discIsArt = (id) => typeof DISCIPLINES !== "undefined" && !!DISCIPLINES && !!DISCIPLINES[id];
const discXpNum = (v) => (typeof v === "number" && isFinite(v) && v > 0 ? Math.floor(v) : 0);

/* ---------------- reading the save ---------------- */
const discMasteryXp = (save, disc) => discXpNum(((save && save.discMastery) || {})[disc]);
function discMasteryRank(xp) {
  const n = discXpNum(xp);
  let r = DISC_RANKS[0];
  for (const d of DISC_RANKS) if (n >= d.need) r = d;
  return r;
}
const discMasteryLevel = (save, disc) => discMasteryRank(discMasteryXp(save, disc)).level;
function discMasteryProgress(xp) {
  const r = discMasteryRank(xp);
  if (r.level >= DISC_MASTERY_MAX) return 1;
  const next = DISC_RANKS[r.level + 1];
  return Math.max(0, Math.min(1, (discXpNum(xp) - r.need) / (next.need - r.need)));
}
function discMasteryToNext(xp) {
  const r = discMasteryRank(xp);
  return r.level >= DISC_MASTERY_MAX ? 0 : DISC_RANKS[r.level + 1].need - discXpNum(xp);
}

/* The save-block sanitiser. sanitizeSavePayload() whitelists the keys it knows
   and delegates this one straight to here, so import, cloud pull and cloud push
   all preserve it. Total: anything at all comes out a clean {art: xp} map with
   no ghost arts, no prototype keys and nothing above the ceiling. */
function discMasteryNormalize(raw) {
  const out = {};
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return out;
  discMasteryIds().forEach((id) => {
    if (!Object.prototype.hasOwnProperty.call(raw, id)) return;
    const xp = Math.min(DISC_CONFIG.xpMax, discXpNum(raw[id]));
    if (xp > 0) out[id] = xp;
  });
  return out;
}

/* ---------------- what a fight used ----------------
   One normaliser, because the caller should never have to know which shape
   the battle layer happens to hand over. Accepts a list of technique ids,
   a list of technique objects, a {techId: count} map, or a {disc: count}
   map - anything that is not a real art is dropped rather than guessed at.
   d.stats.discs is declared in newDuelStats() and never written to by the
   battle layer, so the count has to come from somewhere the caller owns:
   ev.tech at the moment a technique resolves. */
function discKeyToId(key) {
  if (!key) return null;
  if (typeof key === "object") return discKeyToId(key.disc || key.id || null);
  if (discIsArt(key)) return key;
  if (typeof TECH !== "undefined" && TECH && TECH[key] && discIsArt(TECH[key].disc)) return TECH[key].disc;
  return null;
}
function discTally(used) {
  const out = {};
  const bump = (key, n) => {
    const id = discKeyToId(key);
    if (!id || n <= 0) return;
    out[id] = (out[id] || 0) + n;
  };
  if (Array.isArray(used)) used.forEach((k) => bump(k, 1));
  else if (used && typeof used === "object") for (const k in used) bump(k, discXpNum(used[k]));
  return out;
}
/* Adds one use to a tally in place and returns it, so a caller can count as
   the fight happens instead of keeping a list. Total: an unknown id or a
   technique with no art is a no-op. */
function discNoteUse(tally, key, n) {
  const t = tally && typeof tally === "object" ? tally : {};
  const id = discKeyToId(key);
  const add = n === undefined ? 1 : discXpNum(n);
  if (id && add > 0) t[id] = (t[id] || 0) + add;
  return t;
}

/* what one art earns from one fight */
function discMasteryFor(uses, result) {
  const r = result || {};
  const n = Math.min(DISC_CONFIG.useCap, discXpNum(uses));
  if (n <= 0) return 0;
  let xp = DISC_CONFIG.perUse * n;
  xp += r.win ? DISC_CONFIG.win : DISC_CONFIG.loss;
  if (r.win && r.boss) xp += DISC_CONFIG.boss;
  return xp;
}

/* ---------------- earning it ----------------
   Returns {total, gained, ranks, levelled}. `ranks` carries one row per art
   that earned anything, in DISCIPLINES order so the readout is stable, and
   every row is addressed by its `disc` id rather than by position.
   result.finishDisc is optional: pass the art of the technique that ended
   the fight and it takes a small bonus. */
function awardDiscMastery(save, used, result) {
  if (!save) return { total: 0, gained: {}, ranks: [], levelled: [] };
  if (!save.discMastery) save.discMastery = {};
  const r = result || {};
  const tally = discTally(used);
  const finish = r.win ? discKeyToId(r.finishDisc) : null;
  if (finish && !tally[finish]) tally[finish] = 1;

  const gained = {}, ranks = [], levelled = [];
  discMasteryIds().forEach((id) => {
    let xp = discMasteryFor(tally[id] || 0, r);
    if (finish === id && xp > 0) xp += DISC_CONFIG.finish;
    if (xp <= 0) return;
    const before = discMasteryXp(save, id);
    const after = Math.min(DISC_CONFIG.xpMax, before + xp);
    save.discMastery[id] = after;
    const from = discMasteryRank(before), to = discMasteryRank(after);
    const row = { disc: id, gained: after - before, from, to, levelled: to.level > from.level };
    gained[id] = row.gained;
    ranks.push(row);
    if (row.levelled) levelled.push(row);
  });
  let total = 0;
  ranks.forEach((row) => (total += row.gained));
  return { total, gained, ranks, levelled };
}

/* ---------------- the perks ----------------
   Four accessors instead of one applyDiscMastery(side), because these are
   per-TECHNIQUE and not per-fighter: a Muay Thai master hits harder with
   elbows and no harder with the jab they also happen to know. Each is
   total against a null save, a null technique and a technique with no art,
   and each returns the neutral value in those cases. */
function discPerks(save, disc) {
  return DISC_RANKS[discMasteryLevel(save, discKeyToId(disc))] || DISC_RANKS[0];
}
const discAccBonus  = (save, tech) => discPerks(save, tech).acc;
const discPowerMul  = (save, tech) => discPerks(save, tech).powMul;
const discStamCut   = (save, tech) => discPerks(save, tech).stamCut;
const discSpeedMul  = (save, tech) => discPerks(save, tech).spdMul;

/* ---------------- the draft hook ----------------
   Handed to draft.js without draft.js having to know this file exists: it
   already has `t.disc` in hand where it applies ownMul and crossMul, and
   this is one more multiplier in that same expression. Exactly 1 for an
   unmastered art, so a fresh save drafts precisely as it does today. */
function discDraftMul(save, disc) {
  const id = discKeyToId(disc);
  if (!id) return 1;
  return 1 + DISC_CONFIG.draftStep * discMasteryLevel(save, id);
}

/* ---------------- readouts ----------------
   One row per art, best first, each addressed by id. Rows are data: the
   caller decides what to draw and how many to show. */
function discMasteryRows(save) {
  return discMasteryIds().map((id) => {
    const xp = discMasteryXp(save, id);
    const rank = discMasteryRank(xp);
    const d = DISCIPLINES[id];
    return {
      disc: id, name: (d && d.name) || id, color: (d && d.color) || DISC_RANK_COLORS[0],
      xp, rank: rank.name, level: rank.level, perk: rank.perk,
      progress: discMasteryProgress(xp), toNext: discMasteryToNext(xp),
      draftMul: discDraftMul(save, id),
    };
  }).sort((a, b) => b.xp - a.xp || a.name.localeCompare(b.name));
}
function discMasterySummary(save) {
  const rows = discMasteryRows(save).filter((r) => r.xp > 0);
  if (!rows.length) return "NO ART TRAINED YET";
  const top = rows.slice(0, 3).map((r) => r.name.toUpperCase() + " " + r.rank.toUpperCase());
  return rows.length + " ART" + (rows.length === 1 ? "" : "S") + " TRAINED - " + top.join(", ");
}

/* ---- src/progress/infusions.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - Technique Infusion Seals
   Luminara Digital

   Allows players to forge elemental / tactical seals onto individual cards
   in their deck at the Gym or via high-stakes bounties.
   Creates emergent build synergies and game-breaking deck combos.
   ===================================================================== */

const SEALS = {
  SEAL_LIGHTNING: {
    id: "SEAL_LIGHTNING",
    name: "Lightning Seal",
    desc: "-25% stamina cost and +15 speed priority",
    tag: "TEMPO",
    price: 65,
    color: "#22d3ee",
    stamMul: 0.75,
    spdBoost: 15,
  },
  SEAL_HEAVY: {
    id: "SEAL_HEAVY",
    name: "Heavy Breaker Seal",
    desc: "+25% power and ignores 50% of guard mitigation",
    tag: "BREAKER",
    price: 75,
    color: "#f59e0b",
    powMul: 1.25,
    guardPen: 0.50,
  },
  SEAL_VIPER: {
    id: "SEAL_VIPER",
    name: "Viper Venom Seal",
    desc: "Inflicts bleeding on hit (75% chance)",
    tag: "STATUS",
    price: 70,
    color: "#10b981",
    statusEffect: "BLEEDING",
    statusChance: 75,
  },
  SEAL_VAMPIRE: {
    id: "SEAL_VAMPIRE",
    name: "Vampiric Leech Seal",
    desc: "Siphons 25% of unmitigated damage dealt as health",
    tag: "SUSTAIN",
    price: 85,
    color: "#ec4899",
    leechRatio: 0.25,
  },
  SEAL_COUNTER: {
    id: "SEAL_COUNTER",
    name: "Counter Specialist Seal",
    desc: "+45% damage when thrown as a predictive counter",
    tag: "PRECISION",
    price: 70,
    color: "#e6392f",
    counterMul: 1.45,
  },
  SEAL_FLOW: {
    id: "SEAL_FLOW",
    name: "Wind Flow Seal",
    desc: "+12 accuracy and refunds 10 stamina on clean contact",
    tag: "FLOW",
    price: 60,
    color: "#a855f7",
    accBoost: 12,
    stamRefund: 10,
  },
};

const SEAL_IDS = Object.keys(SEALS);

function getTechSeal(runOrSide, techId) {
  if (!runOrSide || !techId) return null;
  const seals = runOrSide.seals || (runOrSide.run && runOrSide.run.seals) || {};
  const sealId = seals[techId];
  return sealId && SEALS[sealId] ? SEALS[sealId] : null;
}

function applySealToTech(run, techId, sealId) {
  if (!run || !techId || !sealId) return false;
  if (!SEALS[sealId]) return false;
  const techMap = (typeof TECH !== "undefined" && TECH) || (typeof global !== "undefined" && global.TECH);
  if (techMap && !techMap[techId]) return false;
  if (!run.seals) run.seals = {};
  run.seals[techId] = sealId;
  return true;
}

function removeSealFromTech(run, techId) {
  if (!run || !run.seals || !run.seals[techId]) return false;
  delete run.seals[techId];
  return true;
}

function sealCandidates(run) {
  if (!run) return [];
  const list = typeof draftMovelist === "function" ? draftMovelist(run) : [];
  const retired = run.retired || [];
  const techMap = (typeof TECH !== "undefined" && TECH) || (typeof global !== "undefined" && global.TECH);
  return list.filter((id) => retired.indexOf(id) < 0 && (!techMap || techMap[id]));
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    SEALS,
    SEAL_IDS,
    getTechSeal,
    applySealToTech,
    removeSealFromTech,
    sealCandidates,
  };
}

/* ---- src/progress/codex.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - Martial Arts Codex & Technique Compendium
   Luminara Digital

   Tracks mastery across all 425 techniques and 20 disciplines.
   Tiers: UNSEEN -> DISCOVERED -> PRACTITIONER -> ADEPT -> EXPERT -> GRANDMASTER.
   Provides completionist statistics, mastery badges, and titles.
   ===================================================================== */

const CODEX_TIERS = [
  { tier: 0, id: "UNSEEN", label: "Unseen", needUses: 0, needKOs: 0, color: "#6b7280" },
  { tier: 1, id: "DISCOVERED", label: "Discovered", needUses: 1, needKOs: 0, color: "#9ca3af" },
  { tier: 2, id: "PRACTITIONER", label: "Practitioner (Bronze)", needUses: 5, needKOs: 1, color: "#d97706" },
  { tier: 3, id: "ADEPT", label: "Adept (Silver)", needUses: 15, needKOs: 3, color: "#cbd5e1" },
  { tier: 4, id: "EXPERT", label: "Expert (Gold)", needUses: 30, needKOs: 8, color: "#fbbf24" },
  { tier: 5, id: "GRANDMASTER", label: "Grandmaster", needUses: 50, needKOs: 15, color: "#ec4899" },
];

function DEF_CODEX() {
  return {
    v: 1,
    entries: {}, // techId: { uses, kos, maxDmg, firstUsedAt }
  };
}

function codexNormalize(raw) {
  const out = DEF_CODEX();
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return out;
  if (raw.entries && typeof raw.entries === "object" && !Array.isArray(raw.entries)) {
    for (const id in raw.entries) {
      if (typeof id === "string" && !id.startsWith("__")) {
        const item = raw.entries[id];
        if (item && typeof item === "object") {
          out.entries[id] = {
            uses: Math.max(0, Math.min(9999, Math.round(item.uses || 0))),
            kos: Math.max(0, Math.min(9999, Math.round(item.kos || 0))),
            maxDmg: Math.max(0, Math.min(9999, Math.round(item.maxDmg || 0))),
          };
        }
      }
    }
  }
  return out;
}

function codexTierFor(uses, kos) {
  const u = Math.max(0, uses || 0);
  const k = Math.max(0, kos || 0);
  let best = CODEX_TIERS[0];
  for (let i = 0; i < CODEX_TIERS.length; i++) {
    const t = CODEX_TIERS[i];
    if (u >= t.needUses && k >= t.needKOs) {
      best = t;
    }
  }
  return best;
}

function codexRecordUse(codex, techId, dmg, isKO) {
  if (!codex || !techId) return;
  if (!codex.entries) codex.entries = {};
  if (!codex.entries[techId]) {
    codex.entries[techId] = { uses: 0, kos: 0, maxDmg: 0 };
  }
  const entry = codex.entries[techId];
  entry.uses = (entry.uses || 0) + 1;
  if (dmg && dmg > (entry.maxDmg || 0)) entry.maxDmg = dmg;
  if (isKO) entry.kos = (entry.kos || 0) + 1;
}

function codexDisciplineStats(codex, discId) {
  const safeCodex = codexNormalize(codex);
  const techMap = (typeof TECH !== "undefined" && TECH) || (typeof global !== "undefined" && global.TECH);
  if (!techMap) return { total: 0, discovered: 0, mastered: 0, percent: 0 };

  let total = 0;
  let discovered = 0;
  let mastered = 0;

  for (const id in techMap) {
    const t = techMap[id];
    if (t && t.disc === discId) {
      total++;
      const entry = safeCodex.entries[id];
      if (entry && entry.uses > 0) {
        discovered++;
        const tier = codexTierFor(entry.uses, entry.kos);
        if (tier.tier >= 4) mastered++; // Expert or Grandmaster
      }
    }
  }

  const percent = total > 0 ? Math.round((discovered / total) * 100) : 0;
  return { total, discovered, mastered, percent };
}

function codexTotalStats(codex) {
  const safeCodex = codexNormalize(codex);
  const techMap = (typeof TECH !== "undefined" && TECH) || (typeof global !== "undefined" && global.TECH);
  if (!techMap) return { total: 425, discovered: 0, mastered: 0, percent: 0 };

  let total = 0;
  let discovered = 0;
  let mastered = 0;

  for (const id in techMap) {
    total++;
    const entry = safeCodex.entries[id];
    if (entry && entry.uses > 0) {
      discovered++;
      const tier = codexTierFor(entry.uses, entry.kos);
      if (tier.tier >= 4) mastered++;
    }
  }

  const percent = total > 0 ? Math.round((discovered / total) * 100) : 0;
  return { total, discovered, mastered, percent };
}

const Codex = {
  CODEX_TIERS,
  DEF_CODEX,
  codexNormalize,
  codexTierFor,
  codexRecordUse,
  codexDisciplineStats,
  codexTotalStats,
};

if (typeof module !== "undefined" && module.exports) {
  module.exports = Codex;
}

/* ---- src/data/challenges.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - challenges and titles
   Luminara Digital

   Optional objectives that teach the game rather than count grind. Every
   one of these is a sentence about how to fight - "finish it on the mat",
   "win without leaving the clinch" - so chasing them pushes you into
   parts of the system you would otherwise skip.

   The reward is a TITLE and nothing else. No stat, no unlock, no power.
   That is deliberate: an achievement that pays out power quietly becomes
   the reason you play, and the fight stops being the point.

   Each challenge tests the stat block a finished fight leaves behind
   (see duelStats), so nothing has to be special-cased in the fight code.

   WEIGHT AND TIER. A first patrol fight - one committed exchange against
   a 50 HP silhouette - used to hand out six titles at once: Debutant,
   Untouchable, Quick Work, Striker, Highlight Reel, Reckless. Every one
   of them was technically true and none of them was earned. So each
   title now carries the lightest encounter it can be won on (patrol /
   rival / boss) and a rarity tier, and a patrol can award at most ONE
   title, from the "first steps" set - the titles whose weight is
   `patrol`. That set is Debutant. Everything else waits for a real bout.
   ===================================================================== */
const ENCOUNTER_WEIGHTS = ["patrol", "rival", "boss"];
const ENCOUNTER_RANK = { patrol: 0, rival: 1, boss: 2 };
const TITLE_TIERS = ["common", "rare", "epic"];
/* titles a single result may award, by the weight of the fight */
const TITLE_CAP = { patrol: 1, rival: Infinity, boss: Infinity };
const CHALLENGES = [];
function C(id, title, name, desc, test, meta) {
  const m = meta || {};
  CHALLENGES.push({
    id, title, name, desc, test,
    weight: ENCOUNTER_RANK[m.weight] !== undefined ? m.weight : "rival",
    tier: TITLE_TIERS.indexOf(m.tier) >= 0 ? m.tier : "common",
  });
}

/* st = { win, perfect, turns, dmgDealt, dmgTaken, hpLeft, subs, throws, strikes,
         guards, ranges:{}, discs:{}, conds:{}, sigHits, comboMax, koRange,
         koClass, boss, ranked, forfeit, opponentRankIndex, myRankIndex } */

/* --- the fundamentals --- */
C("first_blood", "Debutant", "First Blood", "Win your first fight.", (st) => st.win,
  { weight: "patrol", tier: "common" });
C("untouched", "Untouchable", "Untouched", "Win without taking a single point of damage.",
  (st) => st.win && st.dmgTaken === 0, { tier: "rare" });
C("quick_work", "Quick Work", "Inside The Distance", "Win in four turns or fewer.",
  (st) => st.win && st.turns <= 4);
C("comeback", "Never Out", "Comeback", "Win a fight after dropping below 15% health.",
  (st) => st.win && st.lowest <= 0.15, { tier: "rare" });

/* --- the ground game --- */
C("tap_them", "Ippon Artist", "Tap Them Out", "Finish a fight with a submission.",
  (st) => st.win && st.koClass === "SUB", { tier: "rare" });
C("mat_master", "Mat Master", "Ground Control", "Win a fight spending most of it on the ground.",
  (st) => st.win && (st.ranges.GROUND || 0) > st.turns / 2);
C("sub_hunter", "Sub Hunter", "Sub Hunter", "Land three submissions in one fight.",
  (st) => (st.subs || 0) >= 3, { tier: "rare" });
C("throw_artist", "Throw Artist", "Nage-Waza", "Land four throws or takedowns in one fight.",
  (st) => (st.throws || 0) >= 4, { tier: "rare" });

/* --- the stand-up --- */
C("striker", "Striker", "Pure Striking", "Win a fight without a single grapple.",
  (st) => st.win && (st.throws || 0) === 0 && (st.subs || 0) === 0);
C("head_kick_ko", "Highlight Reel", "Highlight Reel", "Finish a fight with a strike from kicking range.",
  (st) => st.win && st.koClass === "STRIKE" && st.koRange === "LONG", { tier: "rare" });
C("clinch_war", "Clinch Fighter", "Clinch War", "Win a fight that spent most of its time in the clinch.",
  (st) => st.win && (st.ranges.CLINCH || 0) > st.turns / 2);
C("cutman", "Bloodletter", "Bloodletter", "Open a cut and win the fight it started.",
  (st) => st.win && (st.conds.BLEEDING || 0) > 0, { tier: "rare" });

/* --- the system --- */
C("perfect_sig", "Signature Move", "Perfect Signature", "Land a signature hitting all three beats.",
  (st) => (st.sigPerfect || 0) > 0, { tier: "rare" });
C("aerial", "Air Superiority", "Aerial Rave", "Complete a full three-hit air combo.",
  (st) => (st.comboMax || 0) >= 3, { tier: "rare" });
C("perfect_guard", "Immovable", "Read And Guard", "Land three perfect guards in one fight.",
  (st) => (st.perfectGuards || 0) >= 3, { tier: "rare" });
C("no_guard", "Reckless", "Nothing But Offence", "Win a fight without ever choosing guard.",
  (st) => st.win && (st.guards || 0) === 0);

/* --- the long game --- */
C("giant_killer", "Giant Killer", "Giant Killer", "Beat someone three grades above you on the ladder.",
  (st) => st.win && st.ranked && (st.opponentRankIndex - st.myRankIndex) >= 3, { tier: "epic" });
C("champion", "Heavens Champion", "Take The Tower", "Beat the champion at the top of the tower.",
  (st) => st.win && st.boss, { weight: "boss", tier: "epic" });
C("polyglot", "Polyglot", "Many Roads", "Win with fighters from five different disciplines.",
  null, { tier: "rare" });                   // tracked across fights, see challengeSweep
C("dedicated", "Devoted", "Devoted", "Take one fighter to a black belt of mastery.", null,
  { tier: "epic" });

const CHALLENGE_BY_ID = {};
CHALLENGES.forEach((c) => (CHALLENGE_BY_ID[c.id] = c));

/* the weight a result was fought at, normalised - anything unknown is a
   full bout, so an older caller that never says loses nothing */
function encounterOf(opts) {
  const w = opts && opts.encounter;
  return ENCOUNTER_RANK[w] !== undefined ? w : "rival";
}
/* can this title be won on a fight of this weight */
function titleEligible(c, encounter) {
  if (!c) return false;
  return ENCOUNTER_RANK[encounterOf({ encounter })] >= ENCOUNTER_RANK[c.weight || "rival"];
}
/* the "first steps" set - what a patrol is allowed to hand out */
function patrolTitles() {
  return CHALLENGES.filter((c) => c.weight === "patrol").map((c) => c.id);
}
const tierOf = (id) => (CHALLENGE_BY_ID[id] ? CHALLENGE_BY_ID[id].tier : null);
const weightOf = (id) => (CHALLENGE_BY_ID[id] ? CHALLENGE_BY_ID[id].weight : null);

/* fresh stat block for a fight */
function newDuelStats() {
  return { win: false, perfect: true, turns: 0, dmgDealt: 0, dmgTaken: 0, hpLeft: 0,
           lowest: 1, subs: 0, throws: 0, strikes: 0, guards: 0, sigPerfect: 0,
           perfectGuards: 0, comboMax: 0, koClass: null, koRange: null,
           ranges: {}, discs: {}, conds: {}, boss: false, ranked: false, forfeit: false,
           opponentRankIndex: 0, myRankIndex: 0,
           zonesDealt: { head: 0, body: 0, legs: 0 },
           cutDealt: 0, controlSeconds: 0 };
}
/* run every per-fight challenge; returns the ids newly earned.
   opts.encounter is the fight's weight (patrol / rival / boss). A title
   too heavy for the fight is skipped, not consumed - it is still open the
   next time a real bout meets its terms - and a patrol stops after one. */
function evaluateChallenges(save, st, opts) {
  if (!save.titles) save.titles = [];
  const encounter = encounterOf(opts);
  const cap = TITLE_CAP[encounter] !== undefined ? TITLE_CAP[encounter] : Infinity;
  const won = [];
  CHALLENGES.forEach((c) => {
    if (!c.test) return;
    if (won.length >= cap) return;
    if (!titleEligible(c, encounter)) return;
    if (save.titles.indexOf(c.id) >= 0) return;
    let ok = false;
    try { ok = !!c.test(st); } catch (e) { ok = false; }
    if (ok) { save.titles.push(c.id); won.push(c.id); }
  });
  return won;
}
/* the two that watch the whole save rather than one fight. They are
   rival-weight titles, so a patrol defers them to the next real bout. */
function challengeSweep(save, opts) {
  if (!save.titles) save.titles = [];
  const won = [];
  if (ENCOUNTER_RANK[encounterOf(opts)] < ENCOUNTER_RANK.rival) return won;
  const add = (id) => { if (save.titles.indexOf(id) < 0) { save.titles.push(id); won.push(id); } };
  const discs = {};
  Object.keys(save.fr || {}).forEach((fid) => {
    if ((save.fr[fid].w || 0) > 0) disciplinesOf(+fid).forEach((d) => (discs[d] = 1));
  });
  if (Object.keys(discs).length >= 5) add("polyglot");
  const m = save.mastery || {};
  if (Object.keys(m).some((fid) => masteryRank(m[fid]).level >= MASTERY_MAX)) add("dedicated");
  return won;
}
const titleOf = (id) => (CHALLENGE_BY_ID[id] ? CHALLENGE_BY_ID[id].title : null);
/* the title you are wearing - the most recently earned, unless you picked one */
function activeTitle(save) {
  if (save.title && (save.titles || []).indexOf(save.title) >= 0) return titleOf(save.title);
  const t = save.titles || [];
  return t.length ? titleOf(t[t.length - 1]) : null;
}

/* ---- src/modes/challenge-run.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - Challenge Run mode layer
   Luminara Digital

   Standing objectives from data/challenges.js become a real run mode here:
   coach tips, light mutators that shape the climb, live progress / fail
   feedback, meet eligibility (no stage-1 mook cheese), scaled renown, and
   mastery replays once every title is already on the shelf.

   Titles stay cosmetic. Renown is the only purse this mode adds.
   ===================================================================== */

const CHALLENGE_RUN_DEFAULT = {
  tip: "Meet the terms in a real bout. Patrol silhouettes do not count.",
  meet: "bout",
  needHits: 1,
  renownMul: 1,
  mutator: null,
};

/* meet:
     any  - every fromAdv fight, including AZX Force one-shots
     bout - full rivals only (!tf)
     boss - tower champion only
   needHits: qualifying meets required before challengeDone latches
   renownMul: scales META_AWARD.clear (or 40) at run payout
   mutator: light run/duel shaping - never a power unlock */
const CHALLENGE_RUN_META = {
  first_blood: {
    tip: "Win any fight on the field. Even a patrol clash counts for Debutant.",
    meet: "any", needHits: 1, renownMul: 0.6,
    mutator: null,
  },
  untouched: {
    tip: "Do not take damage. Guard, range control, and reads keep the bar green.",
    meet: "bout", needHits: 1, renownMul: 1.35,
    mutator: { healMul: 0.55, label: "THINNER CORNER HEALS" },
  },
  quick_work: {
    tip: "End it by turn 4. Commit early and finish - do not grind.",
    meet: "bout", needHits: 1, renownMul: 1.15,
    mutator: { oppAtkMul: 1.08, label: "FASTER RIVALS" },
  },
  comeback: {
    tip: "Drop below 15% HP, then still win. Survive the brink.",
    meet: "bout", needHits: 1, renownMul: 1.4,
    mutator: { healMul: 0.7, label: "LEANER RECOVERY" },
  },
  tap_them: {
    tip: "Close to clinch or ground, then finish with a submission.",
    meet: "bout", needHits: 1, renownMul: 1.2,
    mutator: { startRange: "CLINCH", label: "OPENS IN THE CLINCH" },
  },
  mat_master: {
    tip: "Spend more than half the fight on the ground, then win.",
    meet: "bout", needHits: 1, renownMul: 1.2,
    mutator: { startRange: "GROUND", label: "OPENS ON THE MAT" },
  },
  sub_hunter: {
    tip: "Land three submission attempts in one bout - success counts, finish optional.",
    meet: "bout", needHits: 1, renownMul: 1.25,
    mutator: { startRange: "CLINCH", label: "OPENS IN THE CLINCH" },
  },
  throw_artist: {
    tip: "Chain four throws or takedowns in a single bout.",
    meet: "bout", needHits: 1, renownMul: 1.15,
    mutator: { startRange: "MID", label: "STAND-UP ENTRIES" },
  },
  striker: {
    tip: "Win without a throw or submission. Stay upright and strike.",
    meet: "bout", needHits: 1, renownMul: 1.1,
    mutator: { startRange: "LONG", banGroundStart: true, label: "KICKING RANGE BIAS" },
  },
  head_kick_ko: {
    tip: "Finish with a strike while at kicking range.",
    meet: "bout", needHits: 1, renownMul: 1.35,
    mutator: { startRange: "LONG", label: "OPENS AT KICKING RANGE" },
  },
  clinch_war: {
    tip: "Spend more than half the fight in the clinch, then win.",
    meet: "bout", needHits: 1, renownMul: 1.2,
    mutator: { startRange: "CLINCH", label: "OPENS IN THE CLINCH" },
  },
  cutman: {
    tip: "Open a cut (BLEEDING) on them, then win that same fight.",
    meet: "bout", needHits: 1, renownMul: 1.25,
    mutator: { oppAtkMul: 1.05, label: "MEANER RIVALS" },
  },
  perfect_sig: {
    tip: "Bank signature meter, fire it, and land all three beats.",
    meet: "bout", needHits: 1, renownMul: 1.3,
    mutator: null,
  },
  aerial: {
    tip: "Launch and complete a three-hit air combo.",
    meet: "bout", needHits: 1, renownMul: 1.3,
    mutator: { startRange: "MID", label: "LAUNCH RANGE" },
  },
  perfect_guard: {
    tip: "Time three perfect guards in one bout.",
    meet: "bout", needHits: 1, renownMul: 1.2,
    mutator: { oppAtkMul: 1.1, label: "HEAVIER PRESSURE" },
  },
  no_guard: {
    tip: "Win without ever choosing Guard. Offence only.",
    meet: "bout", needHits: 1, renownMul: 1.25,
    mutator: { healMul: 0.65, label: "THINNER HEALS" },
  },
  giant_killer: {
    tip: "Beat a rival three ladder grades above you. Hunt tougher names.",
    meet: "bout", needHits: 1, renownMul: 1.6,
    mutator: { oppAtkMul: 1.12, label: "HARDER RIVALS" },
  },
  champion: {
    tip: "Reach the tower and beat the champion. Nothing else counts.",
    meet: "boss", needHits: 1, renownMul: 2,
    mutator: { healMul: 0.75, label: "CHAMPION CLIMB" },
  },
};

/* NOT OFFERED AS A RUN OBJECTIVE.

   An objective is only worth offering if it can latch, and challengeNoteMeet
   only ever runs on a fromAdv fight - so a test that needs st.ranked can
   never be met from inside a run. giant_killer needs exactly that, and it was
   offered, selectable, and impossible: you could pick "Beat a rival three
   ladder grades above you", clear the run, and never complete it.

   It is not weakened to suit this mode - it stays fully earnable as an epic
   title on the ladder, which is where a ladder achievement belongs. Its META
   entry below stays so a run already carrying it keeps its tip and mutator
   rather than falling back to the default. */
const CHALLENGE_RUN_EXCLUDED = { giant_killer: 1 };

function challengeRunOffered(c) {
  return !!(c && c.test && !CHALLENGE_RUN_EXCLUDED[c.id]);
}

function challengeRunMeta(id) {
  if (!id || !CHALLENGE_RUN_META[id]) return CHALLENGE_RUN_DEFAULT;
  return CHALLENGE_RUN_META[id];
}

function challengeCoachTip(id) {
  const c = typeof CHALLENGE_BY_ID !== "undefined" ? CHALLENGE_BY_ID[id] : null;
  const m = challengeRunMeta(id);
  if (!c) return m.tip;
  return m.tip;
}

function challengeMutatorLabel(id) {
  const mut = challengeRunMeta(id).mutator;
  return mut && mut.label ? mut.label : null;
}

function challengeRenownBonus(id, opts) {
  const base = (typeof META_AWARD !== "undefined" && META_AWARD.clear) ? META_AWARD.clear : 40;
  const mul = challengeRunMeta(id).renownMul || 1;
  let amt = Math.round(base * mul);
  if (opts && opts.mastery) amt = Math.round(amt * 0.75);
  return Math.max(8, amt);
}

function challengeMeetEligible(id, d) {
  if (!d || !d.fromAdv) return false;
  const meet = challengeRunMeta(id).meet || "bout";
  if (meet === "boss") return !!d.boss;
  if (meet === "bout") return !d.tf && !d.oneShot;
  return true;
}

function challengeNeedHits(id) {
  return Math.max(1, challengeRunMeta(id).needHits || 1);
}

/* Live meter for the duel HUD. Returns null if unknown. */
function challengeProgress(id, st, d) {
  if (!id || !st) return null;
  const turns = st.turns || 0;
  const ranges = st.ranges || {};
  switch (id) {
    case "untouched":
      return {
        label: st.dmgTaken > 0 ? ("BROKEN - " + Math.round(st.dmgTaken) + " DMG") : "CLEAN - 0 DMG",
        frac: st.dmgTaken > 0 ? 0 : 1,
        broken: st.dmgTaken > 0,
        ok: false,
      };
    case "quick_work":
      return {
        label: "TURN " + turns + " / 4",
        frac: Math.max(0, Math.min(1, (4 - turns) / 4)),
        broken: turns > 4,
        ok: false,
      };
    case "comeback":
      return {
        label: st.lowest <= 0.15 ? "BRINK HIT - NOW WIN" : ("LOWEST " + Math.round((st.lowest || 1) * 100) + "%"),
        frac: st.lowest <= 0.15 ? 1 : Math.max(0, 1 - (st.lowest || 1)),
        broken: false,
        ok: st.lowest <= 0.15,
      };
    case "tap_them":
      return {
        label: "NEED SUB FINISH" + (st.subs ? (" - " + st.subs + " SUB ATTEMPTS") : ""),
        frac: st.koClass === "SUB" ? 1 : Math.min(1, (st.subs || 0) / 3),
        broken: false,
        ok: st.koClass === "SUB",
      };
    case "mat_master": {
      const g = ranges.GROUND || 0;
      const need = Math.floor(turns / 2) + 1;
      return {
        label: "GROUND " + g + " / " + Math.max(need, 1) + " TURNS",
        frac: turns ? Math.min(1, g / Math.max(turns * 0.5 + 0.01, 1)) : 0,
        broken: false,
        ok: turns > 0 && g > turns / 2,
      };
    }
    case "clinch_war": {
      const c = ranges.CLINCH || 0;
      return {
        label: "CLINCH " + c + (turns ? (" / " + Math.floor(turns / 2) + "+") : ""),
        frac: turns ? Math.min(1, c / Math.max(turns * 0.5 + 0.01, 1)) : 0,
        broken: false,
        ok: turns > 0 && c > turns / 2,
      };
    }
    case "sub_hunter":
      return {
        label: "SUBS " + (st.subs || 0) + " / 3",
        frac: Math.min(1, (st.subs || 0) / 3),
        broken: false,
        ok: (st.subs || 0) >= 3,
      };
    case "throw_artist":
      return {
        label: "THROWS " + (st.throws || 0) + " / 4",
        frac: Math.min(1, (st.throws || 0) / 4),
        broken: false,
        ok: (st.throws || 0) >= 4,
      };
    case "striker":
      return {
        label: ((st.throws || 0) + (st.subs || 0)) > 0 ? "BROKEN - GRAPPLED" : "PURE STRIKING",
        frac: ((st.throws || 0) + (st.subs || 0)) > 0 ? 0 : 1,
        broken: ((st.throws || 0) + (st.subs || 0)) > 0,
        ok: false,
      };
    case "head_kick_ko":
      return {
        label: d && d.range === "LONG" ? "AT KICKING RANGE - FINISH IT" : "GET TO KICKING RANGE",
        frac: d && d.range === "LONG" ? 0.7 : 0.2,
        broken: false,
        ok: st.koClass === "STRIKE" && st.koRange === "LONG",
      };
    case "cutman":
      return {
        label: (st.conds && st.conds.BLEEDING) ? "CUT OPEN - NOW WIN" : "OPEN A CUT",
        frac: (st.conds && st.conds.BLEEDING) ? 0.8 : 0.15,
        broken: false,
        ok: !!(st.conds && st.conds.BLEEDING),
      };
    case "perfect_sig":
      return {
        label: "PERFECT SIG " + (st.sigPerfect || 0),
        frac: (st.sigPerfect || 0) > 0 ? 1 : 0.2,
        broken: false,
        ok: (st.sigPerfect || 0) > 0,
      };
    case "aerial":
      return {
        label: "AIR COMBO " + (st.comboMax || 0) + " / 3",
        frac: Math.min(1, (st.comboMax || 0) / 3),
        broken: false,
        ok: (st.comboMax || 0) >= 3,
      };
    case "perfect_guard":
      return {
        label: "PERFECT GUARDS " + (st.perfectGuards || 0) + " / 3",
        frac: Math.min(1, (st.perfectGuards || 0) / 3),
        broken: false,
        ok: (st.perfectGuards || 0) >= 3,
      };
    case "no_guard":
      return {
        label: (st.guards || 0) > 0 ? "BROKEN - GUARDED" : "NO GUARD",
        frac: (st.guards || 0) > 0 ? 0 : 1,
        broken: (st.guards || 0) > 0,
        ok: false,
      };
    case "giant_killer": {
      const gap = (st.opponentRankIndex || 0) - (st.myRankIndex || 0);
      return {
        label: "GRADE GAP " + gap + " / 3",
        frac: Math.min(1, Math.max(0, gap) / 3),
        broken: false,
        ok: gap >= 3,
      };
    }
    case "champion":
      return {
        label: (d && d.boss) ? "THE CHAMPION - WIN IT" : "REACH THE TOWER BOSS",
        frac: d && d.boss ? 0.85 : 0.1,
        broken: false,
        ok: !!(st.boss && st.win),
      };
    case "first_blood":
      return {
        label: "WIN THIS FIGHT",
        frac: 0.5,
        broken: false,
        ok: !!st.win,
      };
    default:
      return {
        label: "IN PROGRESS",
        frac: 0.35,
        broken: false,
        ok: false,
      };
  }
}

/* Returns a fail message the first time a challenge breaks mid-fight, else null. */
function challengeCheckBreak(id, st, track) {
  const prog = challengeProgress(id, st, null);
  if (!prog || !prog.broken) return null;
  if (track && track.broken) return null;
  if (track) track.broken = true;
  switch (id) {
    case "untouched": return "CHALLENGE BROKEN - TOOK DAMAGE";
    case "quick_work": return "CHALLENGE BROKEN - TOO SLOW";
    case "striker": return "CHALLENGE BROKEN - GRAPPLED";
    case "no_guard": return "CHALLENGE BROKEN - GUARDED";
    default: return "CHALLENGE BROKEN";
  }
}

function challengeApplyToAdv(a) {
  if (!a || !a.challenge) return a;
  const mut = challengeRunMeta(a.challenge).mutator;
  a.chalMut = mut ? Object.assign({}, mut) : null;
  a.challengeHits = a.challengeHits || 0;
  return a;
}

function challengeApplyToDuel(d, a) {
  if (!d || !a || !a.challenge) return d;
  const mut = a.chalMut || challengeRunMeta(a.challenge).mutator;
  if (!mut) {
    d.challengeTrack = { broken: false };
    return d;
  }
  if (mut.startRange && !d.boss && !d.tf) {
    if (!(mut.banGroundStart && mut.startRange === "GROUND")) d.range = mut.startRange;
  }
  if (mut.oppAtkMul && d.e && !d.boss) {
    d.e.atkMul = (d.e.atkMul || 1) * mut.oppAtkMul;
  }
  d.chalHealMul = (mut.healMul != null) ? mut.healMul : 1;
  d.challengeTrack = { broken: false };
  return d;
}

function challengeScaleHeal(a, amount) {
  const n = Math.round(Number(amount) || 0);
  if (!a || !a.chalMut || a.chalMut.healMul == null) return n;
  return Math.max(0, Math.round(n * a.chalMut.healMul));
}

/* Latch challengeDone when terms are met on an eligible fight enough times. */
function challengeNoteMeet(a, d, st) {
  if (!a || !a.challenge || a.challengeDone || !d || !d.fromAdv) return false;
  const c = typeof CHALLENGE_BY_ID !== "undefined" ? CHALLENGE_BY_ID[a.challenge] : null;
  if (!c || !c.test) return false;
  if (!challengeMeetEligible(a.challenge, d)) return false;
  let met = false;
  try { met = !!c.test(st); } catch (e) { met = false; }
  if (!met) return false;
  a.challengeHits = (a.challengeHits || 0) + 1;
  if (a.challengeHits < challengeNeedHits(a.challenge)) return false;
  a.challengeDone = true;
  return true;
}

function challengeBuildRows(save) {
  const owned = (save && save.titles) || [];
  const rows = [{
    id: "none",
    name: "NO STANDING OBJECTIVE",
    desc: "the ordinary run - fight it however you like.",
    title: null,
    tip: "No mutator, no extra renown, no standing objective.",
    mastery: false,
    earned: false,
    mutLabel: null,
    renown: 0,
  }];
  const playable = (typeof CHALLENGES !== "undefined" ? CHALLENGES : []).filter(challengeRunOffered);
  const open = playable.filter((c) => owned.indexOf(c.id) < 0);
  const done = playable.filter((c) => owned.indexOf(c.id) >= 0);
  const pushRow = (c, mastery) => {
    const tip = challengeCoachTip(c.id);
    const mutLabel = challengeMutatorLabel(c.id);
    const renown = challengeRenownBonus(c.id, { mastery: !!mastery });
    rows.push({
      id: c.id,
      name: mastery ? ("MASTERY - " + c.name) : c.name,
      desc: mastery
        ? (c.desc + " Renown only - title already owned.")
        : c.desc,
      title: c.title,
      tip: tip,
      mastery: !!mastery,
      earned: !!mastery,
      mutLabel: mutLabel,
      renown: renown,
    });
  };
  open.forEach((c) => pushRow(c, false));
  if (open.length === 0) done.forEach((c) => pushRow(c, true));
  return rows;
}

const ChallengeRun = {
  META: CHALLENGE_RUN_META,
  DEFAULT: CHALLENGE_RUN_DEFAULT,
  EXCLUDED: CHALLENGE_RUN_EXCLUDED,
  offered: challengeRunOffered,
  meta: challengeRunMeta,
  coachTip: challengeCoachTip,
  mutatorLabel: challengeMutatorLabel,
  renownBonus: challengeRenownBonus,
  meetEligible: challengeMeetEligible,
  needHits: challengeNeedHits,
  progress: challengeProgress,
  checkBreak: challengeCheckBreak,
  applyToAdv: challengeApplyToAdv,
  applyToDuel: challengeApplyToDuel,
  scaleHeal: challengeScaleHeal,
  noteMeet: challengeNoteMeet,
  buildRows: challengeBuildRows,
};

if (typeof module !== "undefined" && module.exports) {
  module.exports = ChallengeRun;
}

/* ---- src/modes/daily.js ---- */
/* =====================================================================
   Aqua Zero Heavens Arena - the daily gauntlet
   Luminara Digital

   One fight a day, the same fight for everybody, decided by the date. No
   server involved: the date seeds a small deterministic generator, so two
   people on the same day get the same fighter, the same opponent and the
   same stipulations, and can compare scores honestly.

   The streak counts days you SHOWED UP, not days you won. Losing a hard
   gauntlet should not cost you a fortnight's streak - that turns a habit
   into a punishment and people quit rather than break it.
   ===================================================================== */
/* mulberry32 - tiny, fast, and identical everywhere */
function seededRng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
/* local calendar day, not UTC - the gauntlet should turn over at your midnight */
function dayKey(date) {
  const d = date || new Date();
  return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
}
const dayBefore = (key) => {
  const y = Math.floor(key / 10000), m = Math.floor(key / 100) % 100, d = key % 100;
  const t = new Date(y, m - 1, d); t.setDate(t.getDate() - 1);
  return dayKey(t);
};

/* the stipulations that make each day feel different */
const STIPULATIONS = {
  glass:    { name: "GLASS ROUND", desc: "both fighters have half health", hpMul: 0.5 },
  ironman:  { name: "IRON MAN", desc: "both fighters have double health", hpMul: 2 },
  gassed:   { name: "DEEP WATER", desc: "everyone starts on half a tank", stamMul: 0.5 },
  brawl:    { name: "PHONE BOOTH", desc: "the fight opens in the clinch", range: "CLINCH" },
  mat:      { name: "MAT WORK", desc: "the fight opens on the ground", range: "GROUND" },
  kickers:  { name: "LONG RANGE", desc: "the fight opens at kicking distance", range: "LONG" },
  loaded:   { name: "LOADED", desc: "both signature meters start full", superStart: true },
  sharp:    { name: "SHARP", desc: "everything hits 25% harder", dmgMul: 1.25 },
  ironchin: { name: "IRON CHIN", desc: "everything hits 25% softer, so it goes long", dmgMul: 0.75 },
  hunted:   { name: "HUNTED", desc: "your opponent starts with two focus banked", foeFocus: 2 },
};
const STIP_IDS = Object.keys(STIPULATIONS);

/* everything about today's fight, derived from the date alone */
function dailySetup(key, roster) {
  const R = seededRng(key);
  const n = roster || 25;
  const hero = (R() * n) | 0;
  let opp = (R() * n) | 0;
  if (opp === hero) opp = (opp + 1 + ((R() * (n - 1)) | 0)) % n;
  const stips = [];
  const pool = STIP_IDS.slice();
  const count = 1 + ((R() * 2) | 0);                     // one or two, never a soup
  for (let i = 0; i < count && pool.length; i++) stips.push(pool.splice((R() * pool.length) | 0, 1)[0]);
  const level = 5 + ((R() * 5) | 0);
  return { key, hero, opp, stips, level };
}
const stipMul = (stips, field, dflt) =>
  (stips || []).reduce((v, id) => (STIPULATIONS[id] && STIPULATIONS[id][field] !== undefined
    ? v * STIPULATIONS[id][field] : v), dflt === undefined ? 1 : dflt);
const stipFlag = (stips, field) => {
  for (const id of stips || []) { const s = STIPULATIONS[id]; if (s && s[field] !== undefined) return s[field]; }
  return null;
};

/* score rewards finishing healthy and finishing fast */
function dailyScore(st) {
  if (!st.win) return 0;
  const health = Math.round(st.hpLeft * 1000);
  const speed = Math.max(0, 400 - st.turns * 25);
  const flair = (st.sigPerfect || 0) * 60 + (st.comboMax >= 3 ? 80 : 0) + (st.perfectGuards || 0) * 25;
  return health + speed + flair;
}

/* the save's daily block, rolled forward to today */
function dailyState(save, today) {
  if (!save.daily) save.daily = { day: 0, done: false, score: 0, streak: 0, best: 0, bestStreak: 0, plays: 0 };
  const D = save.daily;
  if (D.day !== today) {
    // showing up yesterday keeps the streak; a missed day ends it
    if (!(D.day && D.done && dayBefore(today) === D.day)) D.streak = 0;
    D.day = today; D.done = false; D.score = 0;
  }
  return D;
}
function completeDaily(save, today, score) {
  const D = dailyState(save, today);
  if (D.done) return { already: true, D };
  D.done = true; D.score = score; D.plays = (D.plays || 0) + 1;
  D.streak = (D.streak || 0) + 1;
  if (D.streak > (D.bestStreak || 0)) D.bestStreak = D.streak;
  const record = score > (D.best || 0);
  if (record) D.best = score;
  return { already: false, record, D };
}

/* ---- src/modes/tower.js ---- */
// src/modes/tower.js
// 200-Floor Heavens Arena Tower Mode with Multi-Phase Milestone Bosses
/* =====================================================================
   Aqua Zero Heavens Arena - Tower of Heavens & Milestone Boss Engine
   Luminara Digital - Multi-phase boss encounters and tactical floor rules
   ===================================================================== */

var TowerMode = (function() {
    var state = {
        currentFloor: 1,
        maxFloor: 200,
        unlockedFloors: 1,
        floorRules: [],
        floorMasters: {},
        activeBossPhase: 1
    };

    var RULES = {
        CLINCH_ONLY: "Clinch-Only Mat Rules",
        STAMINA_DRAIN: "Stamina Drain Hazards",
        NO_TELL: "No-Tell Dark Matches",
        CAGE_WALLS: "Steel Cage Enclosure - Wall Escapes Active",
        UNDERGROUND_PIT: "Underground Pit - Uncapped Power",
        STANDARD: "Standard Rules"
    };

    var MILESTONE_BOSSES = {
        50: {
            title: "Gatekeeper of Copper Peak",
            phases: 2,
            phase2Threshold: 0.30,
            phase2Buff: { dmgMul: 1.15, stamRecover: 30, aura: "AURA_COPPER", title: "Enraged Gatekeeper" }
        },
        100: {
            title: "Silver Division Sovereign",
            phases: 2,
            phase2Threshold: 0.35,
            phase2Buff: { dmgMul: 1.20, stamRecover: 40, aura: "AURA_SILVER", title: "Second Wind Sovereign" }
        },
        150: {
            title: "Obsidian Mat Executioner",
            phases: 2,
            phase2Threshold: 0.35,
            phase2Buff: { dmgMul: 1.25, stamRecover: 50, aura: "AURA_OBSIDIAN", title: "Bloodbound Executioner" }
        },
        200: {
            title: "Supreme Sovereign of the Heavens",
            phases: 3,
            phase2Threshold: 0.65,
            phase3Threshold: 0.30,
            phase2Buff: { dmgMul: 1.20, stamRecover: 45, aura: "AURA_GOLDEN", stance: "CLINCH_MASTER", title: "Awakened Sovereign" },
            phase3Buff: { dmgMul: 1.40, stamRecover: 60, aura: "AURA_HEAVENS", stance: "GROUND_DEITY", title: "Apex Transcendence" }
        }
    };

    function generateFloorRule(floorNum) {
        if (floorNum % 50 === 0) return RULES.STANDARD;
        if (floorNum % 10 === 0) return (floorNum % 20 === 0) ? RULES.CAGE_WALLS : RULES.UNDERGROUND_PIT;
        var rand = Math.random();
        if (rand < 0.20) return RULES.CLINCH_ONLY;
        if (rand < 0.35) return RULES.STAMINA_DRAIN;
        if (rand < 0.50) return RULES.NO_TELL;
        if (rand < 0.65) return RULES.CAGE_WALLS;
        return RULES.STANDARD;
    }

    function generateFloorMaster(floorNum) {
        if (MILESTONE_BOSSES[floorNum]) {
            var b = MILESTONE_BOSSES[floorNum];
            return {
                name: b.title,
                milestone: true,
                phases: b.phases,
                difficultyMult: 1.2 + (floorNum / 100),
                rewards: floorNum * 250,
                bossConfig: b
            };
        }
        if (floorNum % 10 === 0) {
            return {
                name: "Floor Master " + floorNum,
                milestone: false,
                difficultyMult: 1 + (floorNum / 100),
                rewards: floorNum * 100
            };
        }
        return null;
    }

    function init() {
        for (var i = 1; i <= state.maxFloor; i++) {
            state.floorRules[i] = generateFloorRule(i);
            state.floorMasters[i] = generateFloorMaster(i);
        }
        loadSave();
        console.log("TowerMode initialized. Max floor: " + state.maxFloor);
    }

    function startFloor(floorNum) {
        if (floorNum > state.unlockedFloors) {
            console.log("Floor " + floorNum + " is locked!");
            return false;
        }
        state.currentFloor = floorNum;
        state.activeBossPhase = 1;
        console.log("Starting floor " + floorNum);
        console.log("Rule: " + state.floorRules[floorNum]);
        if (state.floorMasters[floorNum]) {
            console.log("Challenger: " + state.floorMasters[floorNum].name);
        }
        return true;
    }

    function checkBossPhaseTransition(floorNum, currentHp, maxHp) {
        var boss = MILESTONE_BOSSES[floorNum];
        if (!boss || !maxHp || maxHp <= 0) return null;
        var hpPct = currentHp / maxHp;

        if (boss.phases === 3) {
            if (state.activeBossPhase === 1 && hpPct <= boss.phase2Threshold) {
                state.activeBossPhase = 2;
                return { phase: 2, buff: boss.phase2Buff, message: "BOSS PHASE 2: " + boss.phase2Buff.title };
            } else if (state.activeBossPhase === 2 && hpPct <= boss.phase3Threshold) {
                state.activeBossPhase = 3;
                return { phase: 3, buff: boss.phase3Buff, message: "FINAL PHASE: " + boss.phase3Buff.title };
            }
        } else if (boss.phases === 2) {
            if (state.activeBossPhase === 1 && hpPct <= boss.phase2Threshold) {
                state.activeBossPhase = 2;
                return { phase: 2, buff: boss.phase2Buff, message: "SECOND WIND: " + boss.phase2Buff.title };
            }
        }
        return null;
    }

    function winFloor() {
        var rewards = 50;
        if (state.floorMasters[state.currentFloor]) {
            rewards = state.floorMasters[state.currentFloor].rewards;
            console.log("Defeated Floor Master!");
        }
        console.log("Won floor " + state.currentFloor + ". Reward: " + rewards);
        if (state.currentFloor === state.unlockedFloors && state.unlockedFloors < state.maxFloor) {
            state.unlockedFloors++;
            console.log("Unlocked floor " + state.unlockedFloors);
        }
        saveProgress();
        return { floor: state.currentFloor, rewards: rewards, unlocked: state.unlockedFloors };
    }

    function loadSave() {
        try {
            var saved = localStorage.getItem("HeavensArenaTower");
            if (saved) {
                var parsed = JSON.parse(saved);
                state.unlockedFloors = parsed.unlockedFloors || 1;
            }
        } catch (e) {
            console.warn("Failed to load tower save", e);
        }
    }

    function saveProgress() {
        try {
            localStorage.setItem("HeavensArenaTower", JSON.stringify({
                unlockedFloors: state.unlockedFloors
            }));
        } catch (e) {
            console.warn("Failed to save tower progress", e);
        }
    }

    return {
        init: init,
        startFloor: startFloor,
        winFloor: winFloor,
        checkBossPhaseTransition: checkBossPhaseTransition,
        getState: function() { return state; },
        RULES: RULES,
        MILESTONE_BOSSES: MILESTONE_BOSSES
    };
})();

if (typeof module !== "undefined" && module.exports) {
    module.exports = TowerMode;
}

