const settingsToggleBtn=document.getElementById("settingsToggleBtn");
const settingsCloseBtn=document.getElementById("settingsCloseBtn");
const settingsDrawer=document.getElementById("settingsDrawer");
/* Closing the drawer used to leave focus on the close button, which sits
   outside the arena. The next key then dropped on the floor until the
   canvas was clicked again, so pause (the key the map names) did nothing. */
function focusArena(){
  setFocused(true);
  if(cvEl&&typeof cvEl.focus==="function"){
    try{ cvEl.focus({preventScroll:true}); }
    catch(err){ try{ cvEl.focus(); }catch(e2){} }
  }
}
function closeSettingsDrawer(){
  if(settingsDrawer&&settingsDrawer.classList&&settingsDrawer.classList.remove)
    settingsDrawer.classList.remove("open");
  focusArena();
}
if(settingsToggleBtn && settingsDrawer){
  settingsToggleBtn.addEventListener("click",()=>{
    if(settingsDrawer.classList.contains("open")) closeSettingsDrawer();
    else { settingsDrawer.classList.add("open"); if(typeof sPick==="function") sPick(); }
  });
}
if(settingsCloseBtn && settingsDrawer){
  settingsCloseBtn.addEventListener("click",()=>{
    closeSettingsDrawer();
    if(typeof sPick==="function") sPick();
  });
}
if(typeof addEventListener==="function"){
  addEventListener("pointerdown",e=>{
    if(settingsDrawer && settingsDrawer.classList && settingsDrawer.classList.contains && settingsDrawer.classList.contains("open")){
      if(settingsDrawer.contains && !settingsDrawer.contains(e.target) && settingsToggleBtn && settingsToggleBtn.contains && !settingsToggleBtn.contains(e.target)){
        closeSettingsDrawer();
      }
    }
  });
}

