let lastShowcaseFid=-1;
const scTagEl=document.getElementById("showcaseTag"), scNameEl=document.getElementById("showcaseName"), scMetaEl=document.getElementById("showcaseMeta");
const scAvatarCv=document.getElementById("scAvatarCv"), scAudioCv=document.getElementById("scAudioCv");
function syncShowcaseBar(){
  if(typeof Interactive3DBG==="undefined") return;
  const st=Interactive3DBG.getState();
  if(st.fighterId!==lastShowcaseFid && typeof FIGHTERS!=="undefined" && FIGHTERS[st.fighterId]){
    lastShowcaseFid=st.fighterId;
    const f=FIGHTERS[st.fighterId];
    if(scNameEl) scNameEl.textContent=f.name.toUpperCase();
    const discs=typeof disciplinesOf==="function"?disciplinesOf(st.fighterId):[];
    const arch=typeof archetypeFor==="function"?archetypeOf(archetypeFor(st.fighterId)).name:"FIGHTER";
    const discNames=discs.map(d=>(typeof DISCIPLINES!=="undefined"&&DISCIPLINES[d])?DISCIPLINES[d].name:d).join(" / ");
    if(scMetaEl) scMetaEl.textContent=(discNames?discNames.toUpperCase()+" \u00B7 ":"")+arch;
    if(scAvatarCv && typeof drawPortrait==="function"){
      const acx=scAvatarCv.getContext("2d");
      if(acx){
        acx.clearRect(0,0,48,48);
        drawPortrait(st.fighterId,0,0,48,48);
      }
    }
  }
  // Render mini audio visualizer bars
  if(scAudioCv && typeof scAudioCv.getContext==="function"){
    const acx=scAudioCv.getContext("2d");
    if(acx){
      acx.clearRect(0,0,88,22);
      const bars=st.audioBars||[];
      const th=(Interactive3DBG.THEMES&&Interactive3DBG.THEMES[st.theme])||{primary:"#22d3ee"};
      acx.fillStyle=th.primary;
      const barW=4, gap=1.5;
      for(let i=0;i<Math.min(14,bars.length);i++){
        const bh=Math.max(2,bars[i]*20);
        acx.fillRect(i*(barW+gap)+2, 22-bh, barW, bh);
      }
    }
  }
}

/* screen-reader narration - the canvas is the whole game, so say what changed */
const annEl=document.getElementById("ann");
let lastSaid="";
function say(s){ if(!s||s===lastSaid) return; lastSaid=s; annEl.textContent=s; }

function selList(){ // fighters listed on the select screen
  const base = [];
  for(let i = 0; i < CUSTOM_FIGHTER_BASE; i++) base.push(i);
  /* A custom fighter was barred from the adventure and the tower - the campaign
     and the climb - so the register-fighter flow built somebody who could only
     spar. newAdv and startTower both go through hpOf/battlePool, which resolve
     custom ids, so there was nothing behind the bar. */
  const customModes = ["vs1","vs2","dojo","browse","endless","weekly","ranked",
                       "adventure","ngplus","survival","tower"];
  if(customModes.indexOf(G.selMode) >= 0 && CUSTOM_FIGHTERS.length){
    return base.concat(CUSTOM_FIGHTERS.map((_,i)=>CUSTOM_FIGHTER_BASE + i));
  }
  return base;
}
function openDossier(id,from){
  if(!bioOf(id)){ sDeny(); return; }
  G.dossier=id; G.dossierFrom=from; G.scene=S.FIGHTER; sPick(); updateRom();
}
/* ---------- menu is built from what the save actually holds ---------- */
/* A fighter is mastered when they have earned a belt, not when they appear in
   the select grid. STARTERS are handed to every save and are not belts.
   Title, select, records and the board all ask this, so they cannot disagree. */
function fighterMastered(fid){
  if(typeof masteryLevel==="function") return masteryLevel(SAVE,fid)>0;
  const m=(SAVE&&SAVE.mastery)||{};
  return (m[fid]|0)>0;
}
function masteredCount(){
  let n=0;
  for(let i=0;i<FIGHTERS.length;i++) if(fighterMastered(i)) n++;
  return n;
}
function rosterMasteredLabel(){ return masteredCount()+" / "+FIGHTERS.length; }
function menuItems(){
  const it=[];
  if(SAVE.run&&SAVE.run.adv) it.push(["CONTINUE RUN","stage "+SAVE.run.adv.stage+" - lv "+SAVE.run.adv.level+" - "+FIGHTERS[SAVE.run.adv.hero].name,"cont"]);
  if(SAVE.run&&SAVE.run.gauntlet) it.push(["CONTINUE GAUNTLET","WAVE "+SAVE.run.gauntlet.wave+(SAVE.run.gauntlet.overdrive?" [OVERDRIVE]":" [TIER "+(SAVE.run.gauntlet.stage||1)+"]")+" - "+FIGHTERS[SAVE.run.gauntlet.hero].name+" ("+SAVE.run.gauntlet.hp+"/"+SAVE.run.gauntlet.maxhp+" HP)","cont_gauntlet"]);
  if(SAVE.run&&SAVE.run.weekly) it.push(["CONTINUE WEEKLY TOURNAMENT","TIER "+SAVE.run.weekly.tier+(SAVE.run.weekly.overdrive?" [OVERDRIVE]":"/5")+" - "+FIGHTERS[SAVE.run.weekly.hero].name+" ("+SAVE.run.weekly.hp+"/"+SAVE.run.weekly.maxhp+" HP)","cont_weekly"]);
  it.push(["NEW ADVENTURE","15x15 fields - 60 steps - unlock the roster","adv"]);
  /* The two between-runs decisions sit directly under the run that uses them.
     Neither is gated: the challenge picker is always there, and the renown wall
     is always there even at zero, because a currency you cannot see the price
     list for is a currency nobody saves up. */
  it.push(["CHALLENGE RUN",
    G.challengePick?("standing objective: "+((CHALLENGE_BY_ID[G.challengePick]||{}).name||""))
                   :"take a standing objective into the next run","chal"]);
  {
    const meta=metaNormalize(SAVE.meta);
    it.push(["RENOWN",meta.renown+" "+META_CONFIG.unit+" - spend it on what a run can be dealt","renown"]);
  }
  if((SAVE.rec.ngplus||0)>0) it.push(["NEW GAME +","the roster carries - everyone hits harder","ng"]);
  /* THIS ROW USED TO LIE. Its blurb describes the endless gauntlet - drafts,
     sacred seals, the Apex Sovereign - and its key was "surv", which starts the
     stripped survival loop: a random opponent, no draft, no seal, no perk, no
     purse, no save and no score. Nothing in menuItems ever emitted "endless",
     so the handler for it, endless-gauntlet.js, the perk screen, the draft
     screen, the Apex Sovereign, its 500 RN and its two trophies were all
     unreachable from the menu. The blurb was right; the key was wrong. */
  it.push(["SURVIVAL GAUNTLET","10-wave rogue-lite arena - draft cards, sacred seals & apex sovereign","endless"]);
  {
    const wm = typeof getWeeklyMutator === "function" ? getWeeklyMutator() : null;
    it.push(["WEEKLY MUTATOR",(wm ? wm.name.toUpperCase()+" - "+wm.tag : "rotating weekly global ruleset"),"weekly"]);
  }
  it.push(["MARTIAL ARTS CODEX","425 techniques compendium - mastery badges & lore","codex"]);
  it.push(["TROPHY ROOM","championship belts - streak rings - tournament cups","trophy"]);
  const D=dailyState(SAVE,dayKey());
  it.push(["DAILY GAUNTLET",
    (D.done?"done - "+D.score+" pts":"one fight, everyone gets the same one")
    +(D.streak?"   streak "+D.streak:""),"daily"]);
  const rk=myRanking();
  const bt=typeof beltTestStatus==="function"?beltTestStatus(SAVE):null;
  const rkBlurb=rk.rank.title.toUpperCase()+" - "+rk.promotionPoints+" PTS - "+rk.wins+"W "+rk.losses+"L"
    +(bt&&bt.pending?" - BELT TEST READY":"");
  it.push(["RANKED MATCH",rkBlurb,"ranked"]);
  it.push(["HEAVENS ARENA TOWER","200-floor climb - custom floor rules & masters","tower"]);
  it.push(["DOJO PRACTICE","training dummy - frame data & initiative sandbox","dojo"]);
  it.push(["REGISTER FIGHTER","AZX dossier entry - gameplan, ratings, corner colors","create"]);
  it.push(["DECK BUILDER","100-pt custom technique loadouts for ranked & versus","deckbuild"]);
  it.push(["REPLAY VIEWER","load and step through match streams (.ws)","replay"]);
  it.push(["EXHIBITION","lab duel - rematch, rules, codes - no rank at stake","vs"]);
  it.push(["VS 2 PLAYER","hot-seat - pass the device each round","vs2"]);
  it.push(["GHOST BATTLES","import & fight champion passcode builds","ghost"]);
  it.push(["P2P MULTIPLAYER","WebRTC peer-to-peer arena duel","p2p"]);
  it.push(["FIGHTER LIST","dossiers - ratings - card decks","list"]);
  it.push(["LEADERBOARDS","ladder standings - hall of records","board"]);
  it.push(["RECORDS","wins - perfects - streaks - per fighter","rec"]);
  it.push(["OPTIONS","difficulty - sound - motion - data deck - erase save","opt"]);
  it.push(["HOW TO PLAY","rules - controls - focus - modes","how"]);
  return it;
}
/* Plan C3 (docs/IMPLEMENTATION_PLAN.md): three launch modes ship; the rest
   wait behind one flag. tools/build.js bakes this from AZHA_SHELVED - the
   same env value that un-shelves the three battle modules - so one flag
   restores modules, launch rows and infra rows together. var, not const:
   the test harness flips it in-page to prove both hub shapes against the
   real menu code below. */
var AZHA_SHELVED_MODES=false;
/* Fresh launches only (C3). No cont* resume row is ever in this list: a
   player mid-run in a shelved mode keeps their way back in, and the LAB
   rows that stay (replay, list) read saves rather than start runs. */
const SHELVED_LAUNCH_KEYS=["endless","weekly","daily","tower","dojo","vs","vs2","ghost","p2p"];
/* THE MENU IS FOUR DIFFERENT MENUS WEARING ONE COAT. Twenty-three rows in a
   2x3 grid is four pages of arrow-key paging with no grouping, so page one of a
   brand-new save offered CHALLENGE RUN ("take a standing objective into the
   next run"), RENOWN ("0 RN") and the 425-technique codex - three things that
   mean nothing until you have played - while HOW TO PLAY sat at row 22, three
   page-turns away, and both time-limited hooks (the daily and the ladder) sat
   on page two where nothing opening the menu can see them.

   These are the same rows in the same order, filtered into the four things a
   player is ever actually here to do. Nothing is removed and no key changes,
   so every dispatch, preview and test keeps working. */
const MENU_TABS=[
  {id:"play",  name:"FIGHT",
   keys:["cont","cont_gauntlet","cont_weekly","adv","ng","daily","ranked","endless","weekly","tower","chal"]},
  {id:"build", name:"PROGRESS",
   keys:["renown","deckbuild","create","codex","trophy","rec","board"]},
  {id:"lab",   name:"LAB",
   keys:["dojo","vs","vs2","ghost","p2p","replay","list"]},
  {id:"sys",   name:"SETUP", keys:["opt","how"]},
];
/* Address a menu row by its key rather than by an index into a list whose
   shape depends on which tab is open. Every caller that wants "open the renown
   wall" should say that, not compute a number. */
function menuGoTo(key){
  for(let t=0;t<MENU_TABS.length;t++){
    const rows=menuTabItems(t);
    for(let i=0;i<rows.length;i++){
      if(rows[i][2]===key){ G.menuTab=t; G.menuSel=i; return true; }
    }
  }
  return false;
}
function menuTabItems(tabIx){
  const all=menuItems();
  const tab=MENU_TABS[Math.max(0,Math.min(MENU_TABS.length-1,tabIx|0))];
  let inTab=all.filter(it=>tab.keys.indexOf(it[2])>=0);
  /* a row nobody claimed still has to be reachable, so it falls to SETUP
      rather than disappearing when somebody adds a mode and forgets this list */
  if(tab.id==="sys"){
    const claimed=[];
    MENU_TABS.forEach(t=>t.keys.forEach(k=>claimed.push(k)));
    all.forEach(it=>{ if(claimed.indexOf(it[2])<0) inTab.push(it); });
  }
  /* C3: gate FRESH LAUNCHES ONLY, and only while the flag is off. Filtering
     here rather than in menuItems() keeps the row model complete - previews,
     the a-key dispatch and every cont* resume row still know these keys -
     while the drawn tabs, the cursor and menuGoTo all agree, so a hidden key
     cannot be drawn, selected or navigated to, and menuGoTo's false return
     stays the one graceful answer for a caller that asks anyway. */
  if(!AZHA_SHELVED_MODES){
    inTab=inTab.filter(it=>SHELVED_LAUNCH_KEYS.indexOf(it[2])<0);
  }
  return inTab;
}
/* Pair you with someone near your own grade. Ladder matches are only worth
   anything if the opponent is plausibly your level. */
function findLadderOpponent(hero){
  const mine=myRanking().rank.index;
  const pool=FIGHTERS.map((f,i)=>i).filter(i=>i!==hero&&FIGHTERS[i].role!=="boss");
  let best=pool[0], bd=1e9;
  pool.forEach(id=>{
    const lv=Math.max(1,Math.min(9,1+Math.round(mine*.45)));
    const idx=cpuRankIndexFor(id,lv);
    const dist=Math.abs(idx-mine)+Math.random()*1.4;   // a little spread so it is not always the same face
    if(dist<bd){ bd=dist; best=id; }
  });
  const lv=Math.max(1,Math.min(9,1+Math.round(mine*.45)));
  return { id:best, level:lv, rankIndex:cpuRankIndexFor(best,lv) };
}
/* The gauntlet is fully determined by the date, so it is the same fight
   for everyone and can be compared without a server. */
function startDailyGauntlet(){
  const key=dayKey(), setup=dailySetup(key,FIGHTERS.length);
  const hpMul=stipMul(setup.stips,"hpMul"), dmgMul=stipMul(setup.stips,"dmgMul");
  const stamMul=stipMul(setup.stips,"stamMul");
  const range=stipFlag(setup.stips,"range");
  G.adv=null; G.surv=null;
  startDuel({p1:setup.hero,p1hp:Math.round(hpOf(setup.hero)*hpMul),
             p1pool:battlePool(setup.hero,9),p1level:9,
             oppFid:setup.opp,oppHp:Math.round(hpOf(setup.opp)*hpMul),
             oppPool:battlePool(setup.opp,setup.level),oppLv:setup.level,
             oppAtk:dmgMul,fromAdv:false,stage:5,
             daily:true,stips:setup.stips,range:range||undefined});
  const d=G.duel;
  d.p.atkMul*=dmgMul;
  if(stamMul!==1){ [d.p,d.e].forEach(s=>{ s.stam=Math.round(s.maxStam*stamMul); }); }
  if(stipFlag(setup.stips,"superStart")){ d.p.sup=SUP_MAX; d.e.sup=SUP_MAX; }
  const ff=stipFlag(setup.stips,"foeFocus");
  if(ff) d.e.focus=Math.min(d.e.focusMax,ff);
  say("Daily gauntlet. "+FIGHTERS[setup.hero].name+" versus "+FIGHTERS[setup.opp].name+".");
}
/* THE LADDER IS A SESSION, NOT A SINGLE BOUT. A ranked match used to end on
   the result screen and hand you back to the main menu, which made the one
   mode built entirely on repetition the only mode you could not repeat: every
   further match cost four menu presses and a fighter pick. The session below
   holds the fighter and the running record so that A on the result screen
   seats the next opponent, exactly the way the tower hands you the next floor
   and the gauntlet the next wave.

   IT ENDS ON YOUR TERMS, OR AT THE TOP. B leaves whenever you like - the grade
   and the points are already banked after every bout, so walking away costs
   nothing that was not already yours. The one automatic ending is 10th Dan:
   the ladder has no rung above it, so there is nothing left for the session to
   play for and it closes itself. */
function startRanked(hero){
  const mine=myRanking();
  G.adv=null; G.surv=null;
  /* If a division belt test is pending, the next bout is that exam. */
  const bt=typeof beltTestStatus==="function"?beltTestStatus(SAVE):null;
  G.ranked={ hero:hero, bouts:0, wins:0, losses:0,
             startPoints:mine.promotionPoints, startRankIndex:mine.rank.index,
             peakRankIndex:mine.rank.index, done:false,
             beltTest:!!(bt&&bt.pending) };
  if(typeof writeRankedSession==="function") writeRankedSession(SAVE, G.ranked);
  persist();
  rankedNextBout();
}
/* Seats the next ladder pairing. Matchmaking is re-run every bout rather than
   fixed for the session: your grade moves after each result, so the pool you
   deserve moves with it. */
function rankedNextBout(){
  const s=G.ranked;
  if(!s) return;
  const hero=s.hero;
  const bt=typeof beltTestStatus==="function"?beltTestStatus(SAVE):null;
  if(bt&&bt.pending){
    const idx=bt.pending.targetRankIndex|0;
    const pool=FIGHTERS.map((f,i)=>i).filter(i=>i!==hero&&FIGHTERS[i].role!=="boss");
    const oppFid=pool[Math.floor(Math.random()*pool.length)]||0;
    const rk=rankByIndex(idx);
    startDuel({p1:hero,p1hp:hpOf(hero),p1pool:battlePool(hero,9),p1level:9,
               oppFid:oppFid,oppHp:hpOf(oppFid),oppPool:battlePool(oppFid,Math.min(9,4+Math.floor(idx/3))),
               oppLv:Math.min(9,4+Math.floor(idx/3)),oppAtk:diff().dmg,fromAdv:false,
               stage:Math.max(1,Math.round(idx/2)),
               ranked:true,oppRankIndex:idx,beltTest:true});
    G.duel.oppId="cpu:belt:"+oppFid;
    G.duel.beltTest=true;
    say("Belt test for "+(DIVISION[bt.pending.targetDivision]||{}).name+" Division. Face a "
        +rk.title+".");
    return;
  }
  const opp=findLadderOpponent(hero);
  const rk=rankByIndex(opp.rankIndex);
  startDuel({p1:hero,p1hp:hpOf(hero),p1pool:battlePool(hero,9),p1level:9,
             oppFid:opp.id,oppHp:hpOf(opp.id),oppPool:battlePool(opp.id,opp.level),
             oppLv:opp.level,oppAtk:diff().dmg,fromAdv:false,stage:Math.max(1,Math.round(opp.rankIndex/2)),
             ranked:true,oppRankIndex:opp.rankIndex});
  G.duel.oppId="cpu:"+opp.id;
  say((s.bouts?("Ranked match "+(s.bouts+1)+" against "):"Ranked match against ")
      +FIGHTERS[opp.id].name+", "+rk.title+".");
}
/* Closing the session is the only route off the ladder, so it is also the only
   place the record gets read out. Grade was banked after every bout; here we
   only clear the session snapshot. */
function endRankedSession(){
  const s=G.ranked;
  G.ranked=null;
  if(typeof writeRankedSession==="function") writeRankedSession(SAVE, null);
  persist();
  if(s&&s.bouts){
    const now=myRanking();
    say("Ranked session over. "+s.wins+" won, "+s.losses+" lost. "
        +now.rank.title+", "+now.promotionPoints+" points.");
  }
  G.scene=S.MENU; G.menuSel=0;
}
function startSurvival(hero){
  G.surv={hero, round:1, streak:0, maxhp:hpOf(hero), hp:hpOf(hero)};
  survNext();
}
/* Exhibition / hot-seat entry. Settings, series bookkeeping and bout codes
   live in ExhibitionMode; this only seats the fighters and rings the bell. */
function startExhibitionBout(p1, p2, opts){
  opts=opts||{};
  if(typeof ExhibitionMode==="undefined"){
    startDuel({p1:p1,p1hp:hpOf(p1),p1pool:battlePool(p1,9),
               oppFid:p2,oppHp:hpOf(p2),oppPool:battlePool(p2,9),oppLv:9,
               oppAtk:diff().dmg,fromAdv:false,hotseat:!!opts.hotseat,stage:5});
    return;
  }
  const fresh=!opts.continueSeries;
  if(fresh){
    ExhibitionMode.beginSeries(p1,p2,{
      hotseat:!!opts.hotseat,
      rematch:!!opts.rematch,
      series:opts.series
    });
  }
  const duelOpts=ExhibitionMode.duelOpts(p1,p2,{
    hotseat:!!opts.hotseat,
    settings:opts.settings
  });
  duelOpts.exhibRematch=!!opts.rematch;
  if(opts.ghost) duelOpts.ghost=opts.ghost;
  const s=ExhibitionMode.getSettings();
  if(s.callout&&typeof issueCallout==="function"){
    issueCallout(SAVE, duelOpts.p1, duelOpts.oppFid);
  }
  startDuel(duelOpts);
  if(G.duel){
    if(opts.venue) G.duel.venue = opts.venue;
    G.duel.exhibition=true;
    const ser=ExhibitionMode.seriesSnapshot();
    if(ser&&ser.format==="bo3"){
      say("Best of 3 - bout "+ser.bout+". Score "+ser.score[0]+"-"+ser.score[1]+".");
    }
  }
}
function survNext(){
  const s=G.surv, r=s.round;
  const pool=FIGHTERS.map((f,i)=>i).filter(i=>i!==s.hero&&FIGHTERS[i].role!=="boss");
  const oppFid=pool[Math.floor(Math.random()*pool.length)];
  const hp=Math.round((70+r*14)*diff().hp);
  const oppLv=Math.min(9,3+r);
  const oppRank=typeof cpuRankIndexFor==="function"
    ?cpuRankIndexFor(oppFid,oppLv):Math.min(MAX_RANK_INDEX,r);
  startDuel({p1:s.hero,p1hp:s.hp,p1pool:battlePool(s.hero,9),
             oppFid,oppHp:hp,oppPool:battlePool(oppFid,oppLv),
             oppAtk:(1+r*.06)*diff().dmg, oppLv:oppLv,
             survival:true, stage:Math.min(9,r), oppRankIndex:oppRank});
  G.duel.p.maxhp=s.maxhp;
}
/* The climb remembers who is climbing. Without this the tower could only hand
   you back to its lobby and then to the fighter select, so a 200-floor climb
   asked you to re-pick your fighter two hundred times - and the defeat screen's
   own "PRESS A TO RETRY" was a promise nothing kept. */
function startTower(hero, floorNum){
  if(!FIGHTERS[hero]) hero=0;
  const fNum = floorNum || (typeof TowerMode !== "undefined" ? TowerMode.getState().currentFloor : 1) || 1;
  if(typeof TowerMode !== "undefined") TowerMode.startFloor(fNum);
  const st = typeof TowerMode !== "undefined" ? TowerMode.getState() : { floorRules: [], floorMasters: {} };
  const rule = (st.floorRules && st.floorRules[fNum]) || "Standard Rules";
  const master = st.floorMasters && st.floorMasters[fNum];
  const pool = FIGHTERS.map((f, i) => i).filter(i => i !== hero && (master ? true : FIGHTERS[i].role !== "boss"));
  const oppFid = master ? (fNum === 200 ? BOSS_ID : pool[Math.floor(Math.random() * pool.length)]) : pool[(fNum * 3 + 7) % pool.length];
  const oppLv = Math.min(9, Math.max(1, Math.round(fNum / 22)));
  const hpScale = (master ? (master.difficultyMult || 1.5) : (1 + fNum * 0.005)) * diff().hp;
  const dmgScale = (master ? (master.difficultyMult || 1.3) : (1 + fNum * 0.004)) * diff().dmg;
  let startRange = "MID";
  if(rule === (typeof TowerMode !== "undefined" ? TowerMode.RULES.CLINCH_ONLY : "Clinch-Only Mat Rules")) startRange = "CLINCH";
  G.adv = null; G.surv = null; G.endless = null;
  startDuel({
    p1: hero, p1hp: hpOf(hero), p1pool: battlePool(hero, 9), p1level: 9,
    oppFid: oppFid, oppHp: Math.round(hpOf(oppFid) * hpScale),
    oppPool: battlePool(oppFid, oppLv), oppLv: oppLv,
    oppAtk: dmgScale, fromAdv: false, stage: Math.min(6, Math.max(1, Math.round(fNum / 35))),
    tower: true, towerFloor: fNum, towerRule: rule, isTowerMaster: !!master,
    range: startRange
  });
  G.tower = { hero: hero, floor: fNum };
  if(rule === (typeof TowerMode !== "undefined" ? TowerMode.RULES.NO_TELL : "No-Tell Dark Matches")) G.duel.noTell = true;
  if(rule === (typeof TowerMode !== "undefined" ? TowerMode.RULES.STAMINA_DRAIN : "Stamina Drain Hazards")) G.duel.staminaDrain = true;
  say("Heavens Arena Tower Floor " + fNum + ". " + FIGHTERS[hero].name + " versus " + FIGHTERS[oppFid].name + (master ? " (" + master.name + ")" : "") + ". " + rule + ".");
}
function startDojo(hero){
  const dummyFid = hero === 0 ? 1 : 0;
  const cfg = typeof DojoMode !== "undefined" ? DojoMode.getConfig() : { aiDummy: { behavior: "stand", autoBlock: false } };
  G.adv = null; G.surv = null; G.endless = null;
  startDuel({
    p1: hero, p1hp: hpOf(hero), p1pool: battlePool(hero, 9), p1level: 9,
    oppFid: dummyFid, oppHp: 9999, oppPool: battlePool(dummyFid, 9), oppLv: 9,
    oppAtk: 0.5, fromAdv: false, stage: 1, dojo: true, dojoDummy: cfg.aiDummy
  });
  G.duel.p.maxhp = hpOf(hero);
  G.duel.e.maxhp = 9999;
  say("Dojo Sparring Sandbox. Training dummy active. Practice combinations, range control, and frame data.");
}
function startEndless(hero){
  G.adv = null; G.surv = null;
  G.endless = typeof DEF_ENDLESS_STATE === "function" ? DEF_ENDLESS_STATE(hero) : { hero, wave: 1, score: 0, highWave: 1, hp: hpOf(hero), maxhp: hpOf(hero), active: true, drafted: [], seals: {}, benefits: [], bag: ["salts","ice"], purse: 100 };
  G.endless.hp = hpOf(hero);
  G.endless.maxhp = hpOf(hero);
  saveRun();
  /* Wave one starts the fight. The lobby is the between-waves room - heal, buy,
     take a perk - and on a fresh run there is nothing in it to do: full health,
     a starting purse and no draft yet. Parking the player there first made
     entering the gauntlet a menu, a fighter select and then a second menu
     before anybody threw a punch. Every later wave still lands in the lobby. */
  endlessNext();
}
function endlessNext(){
  const st = G.endless;
  if(!st) return;
  const opp = typeof endlessOpponentForWave === "function" ? endlessOpponentForWave(st.wave, FIGHTERS.length) : { id: (st.wave * 7) % FIGHTERS.length, wave: st.wave, statMul: 1 + st.wave * 0.03, hpMul: 1 + st.wave * 0.04, isBoss: st.wave % 5 === 0, isApex: st.wave === 10, name: "Gladiator" };
  /* Same belt-and-braces the weekly tier match wears: a wave that cannot name a
     real fighter must still seat a fight, because this runs inside a key
     handler and a throw here strands the player in the lobby. */
  if(!FIGHTERS[opp.id]) opp.id = Math.max(0, (st.hero + 1) % FIGHTERS.length);
  const oppLv = Math.min(9, Math.max(1, 2 + Math.floor(st.wave / 3)));
  G.adv = null;
  startDuel({
    p1: st.hero, p1hp: st.hp, p1pool: battlePool(st.hero, 9), p1level: 9,
    oppFid: opp.id, oppHp: Math.round(hpOf(opp.id) * (opp.hpMul || 1) * diff().hp),
    oppPool: battlePool(opp.id, oppLv), oppLv: oppLv,
    oppAtk: (opp.statMul || 1) * diff().dmg, fromAdv: false,
    endless: true, survival: true, wave: st.wave, isBoss: opp.isBoss, isApex: opp.isApex,
    stage: st.stage || Math.min(6, Math.max(1, Math.floor(st.wave / 4))),
    seals: st.seals || {}, benefits: st.benefits || [], drilled: st.drilled || {}, bag: (st.bag || []).slice(),
    range: (opp.affix && opp.affix.range) || undefined
  });
  G.duel.p.maxhp = st.maxhp;
  if(opp.affix){
    if(opp.affix.superStart){ G.duel.p.sup = Math.max(G.duel.p.sup||0, 50); G.duel.e.sup = Math.max(G.duel.e.sup||0, 50); }
    if(opp.affix.counterBonus){ G.duel.counterMul = opp.affix.counterBonus; }
    if(opp.affix.defBonus){ G.duel.defMul = opp.affix.defBonus; }
  }
  say((opp.isApex ? "[APEX SOVEREIGN CLIMAX] " : (opp.isBoss ? "[BOSS WAVE] " : "")) + "Gauntlet Wave " + st.wave + ". Face " + FIGHTERS[opp.id].name + ".");
}
function startWeekly(hero){
  if(!FIGHTERS[hero]) hero=0;
  const st = typeof DEF_WEEKLY_STATE === "function" ? DEF_WEEKLY_STATE(hero) : { hero: hero, tier: 1, active: true, hp: hpOf(hero), maxhp: hpOf(hero), augments: [], bag: ["salts","syringe"], purse: 120, respitesLeft: 2 };
  if(!FIGHTERS[st.hero]) st.hero=0;
  G.weekly = st;
  G.adv = null; G.surv = null; G.endless = null;
  saveRun();
  startWeeklyTierMatch(st);
}

function startWeeklyTierMatch(st){
  if(!st) return;
  const t = st.tier || 1;
  const opp = typeof weeklyOpponentForTier === "function" ? weeklyOpponentForTier(st, t) : { id: (st.hero + 5) % FIGHTERS.length, statMul: 1.0, hpMul: 1.0, isApex: (t === 5) };
  if(!FIGHTERS[opp.id] && !opp.isApex) opp.id = Math.max(0, (st.hero + 1) % FIGHTERS.length);
  const wm = typeof getWeeklyMutator === "function" ? getWeeklyMutator() : null;
  const mut = (st.mutator) || (wm ? wm.mutator : { name: "Weekly Challenge", tag: "SPECIAL", powMul: 1.5, hpMul: 1.0, stamMul: 1.0 });
  const sec = opp.secondaryMutator || (wm ? wm.secondaryMutator : null);

  const heroHp = Math.max(1, st.hp || st.maxhp || hpOf(st.hero));
  const oppBaseHp = Math.round(hpOf(opp.isApex ? BOSS_ID : opp.id) * (mut.hpMul || 1.0) * (opp.hpMul || 1.0));
  const oppLv = Math.min(10, Math.max(5, 5 + t));

  G.adv = null; G.surv = null; G.endless = null;
  startDuel({
    p1: st.hero, p1hp: heroHp, p1pool: battlePool(st.hero, 9), p1level: 9,
    oppFid: opp.isApex ? BOSS_ID : opp.id, oppHp: oppBaseHp,
    oppPool: battlePool(opp.isApex ? BOSS_ID : opp.id, oppLv), oppLv: oppLv,
    oppAtk: (mut.powMul || 1.0) * (opp.statMul || 1.0) * diff().dmg,
    fromAdv: false,
    boss: !!opp.isApex,
    weekly: true, weeklyMutator: mut, secondaryMutator: sec,
    range: mut.startRange || undefined,
    stage: Math.min(6, t),
    bag: (st.bag || []).slice(),
    seals: st.seals || {},
    augments: (st.augments || []).slice()
  });

  G.duel.p.maxhp = st.maxhp;
  if(mut.stamRegenMul) G.duel.stamRegenMul = mut.stamRegenMul;
  if(mut.counterMul) G.duel.counterMul = mut.counterMul;
  if(mut.spdBoost){ [G.duel.p, G.duel.e].forEach(s => s.spdBoost = mut.spdBoost); }
  if(mut.superStart){ [G.duel.p, G.duel.e].forEach(s => s.sup = Math.max(s.sup||0, mut.superStart)); }

  if(sec){
    if(sec.stamRegenMul) G.duel.stamRegenMul = (G.duel.stamRegenMul || 1.0) * sec.stamRegenMul;
    if(sec.counterMul) G.duel.counterMul = (G.duel.counterMul || 1.0) * sec.counterMul;
    if(sec.superStart){ [G.duel.p, G.duel.e].forEach(s => s.sup = Math.max(s.sup||0, sec.superStart)); }
    if(sec.spdBoost){ [G.duel.p, G.duel.e].forEach(s => s.spdBoost = (s.spdBoost||0) + sec.spdBoost); }
  }

  // Apply Player Augments
  (st.augments || []).forEach(augId => {
    const aug = (typeof WEEKLY_AUGMENTS !== "undefined") ? WEEKLY_AUGMENTS.find(a => a.id === augId) : null;
    if(aug){
      if(aug.spdBoost) G.duel.p.spdBoost = (G.duel.p.spdBoost || 0) + aug.spdBoost;
      if(aug.superStart) G.duel.p.sup = Math.max(G.duel.p.sup || 0, aug.superStart);
      if(aug.counterBonus) G.duel.p.counterBonus = aug.counterBonus;
    }
  });

  const tierAnnounce = opp.isApex ? "[APEX WEEKLY SOVEREIGN CLIMAX] " : (opp.isOverdrive ? "[WEEKLY OVERDRIVE TIER " + t + "] " : ("Weekly Tournament Tier " + t + ": "));
  const heroName=(FIGHTERS[st.hero]&&FIGHTERS[st.hero].name)||"CHALLENGER";
  const oppNameStr=(FIGHTERS[opp.id]&&FIGHTERS[opp.id].name)||opp.name||"CONTENDER";
  say(tierAnnounce + heroName + " versus " + oppNameStr + " under " + mut.name + ".");
}
function onKey(k){
  /* every input path - keydown, the A/B/Y pad buttons, canvas pointerdown and
     hot-region clicks - funnels through here, so one line restarts the idle
     clock and kills a running demo for all of them */
  attractPoke(G.attract);
  const sc=G.scene;
  if(sc===S.LOAD) return;
  if(sc===S.TITLE){
    if(k==="diff"||k==="x"||k==="d"){ cycleDifficulty(); return; }
    if(k==="a"){G.scene=S.MENU;G.menuSel=0;sPick();}
    if(k==="b"){G.scene=S.HOW;G.howTopic="general";G.how=0;G.prevScene=S.TITLE;sPick();}
    return;
  }
  if(sc===S.MENU){
    /* the cursor addresses the CURRENT TAB's rows; the dispatch below still
       works off the row's key, so nothing downstream knows the tabs exist */
    const items=menuTabItems(G.menuTab|0);
    if(!items.length){ G.menuTab=0; return; }
    if(G.menuSel>=items.length) G.menuSel=0;
    if(k==="diff"){ cycleDifficulty(); return; }
    /* left/right at the ends of a tab step to the next tab rather than wrapping
       inside it, which is what makes four short lists feel like one menu */
    if(k==="up"){ G.menuSel=(G.menuSel-2+items.length)%items.length; sTick(); }
    else if(k==="down"){ G.menuSel=(G.menuSel+2)%items.length; sTick(); }
    else if(k==="left"){
      if(G.menuSel>0){ G.menuSel--; sTick(); }
      else { G.menuTab=((G.menuTab|0)-1+MENU_TABS.length)%MENU_TABS.length;
             G.menuSel=Math.max(0,menuTabItems(G.menuTab).length-1); sTick();
             say(MENU_TABS[G.menuTab].name+" tab."); }
    }
    else if(k==="right"){
      if(G.menuSel<items.length-1){ G.menuSel++; sTick(); }
      else { G.menuTab=((G.menuTab|0)+1)%MENU_TABS.length; G.menuSel=0; sTick();
             say(MENU_TABS[G.menuTab].name+" tab."); }
    }
    if(k==="y"){ G.menuTab=((G.menuTab|0)+1)%MENU_TABS.length; G.menuSel=0; sPick();
                 say(MENU_TABS[G.menuTab].name+" tab."); return; }
    if(k==="b"){ G.scene=S.TITLE; return; }
    if(k==="a"){ sPick();
      if(!items[G.menuSel]) return;
      const key=items[G.menuSel][2];
      if(key==="cont"||key==="cont_gauntlet"||key==="cont_weekly"){ if(!resumeRun()) sDeny(); }
      else if(key==="adv"){ G.challengePick=null; G.challengeMastery=false; G.selMode="adventure"; G.scene=S.SELECT; G.sel=0; }
      else if(key==="ng"){ G.challengePick=null; G.challengeMastery=false; G.selMode="ngplus"; G.scene=S.SELECT; G.sel=0; }
      else if(key==="surv"){ G.selMode="survival"; G.scene=S.SELECT; G.sel=0; }
      else if(key==="endless"){ G.selMode="endless"; G.scene=S.SELECT; G.sel=0; }
      else if(key==="weekly"){ G.scene=S.WEEKLY; }
      else if(key==="codex"){ G.scene=S.CODEX; if(typeof CodexViewer!=="undefined") CodexViewer.state.itemIndex=0; }
      else if(key==="trophy"){ G.scene=S.TROPHY; if(typeof TrophyRoom!=="undefined") TrophyRoom.state.selectedIndex=0; }
      else if(key==="daily"){ G.scene=S.DAILY;
        /* the board is asked for on ENTRY, in the key handler - never in
           render(), which runs at monitor cadence. lbRefreshBoard is deduped per
           day and returns a resolved promise when there is no server, so this
           costs nothing in the normal, unconfigured case. */
        try{ lbRefreshBoard(dayKey(),LB_TOP_N,localStorage); }catch(e){} }
      else if(key==="renown"){ G.scene=S.RENOWN; G.renownSel=0; G.renownScroll=0; G.renownMsg=""; }
      else if(key==="chal"){ G.scene=S.CHALLENGE; G.chalSel=0; G.chalScroll=0; }
      else if(key==="ranked"){ G.selMode="ranked"; G.vsHotseat=false; G.scene=S.SELECT; G.sel=0; }
      else if(key==="tower"){ G.scene=S.TOWER; if(typeof TowerMode!=="undefined") TowerMode.init(); }
      else if(key==="dojo"){ G.scene=S.DOJO; if(typeof DojoMode!=="undefined") DojoMode.init(); }
      else if(key==="create"){ cfResetWizard(); G.scene=S.CREATE_FIGHTER; }
      else if(key==="deckbuild"){ G.scene=S.DECK_BUILDER; }
      else if(key==="replay"){ G.scene=S.REPLAY; }
      else if(key==="vs"){ G.selMode="vs1"; G.vsHotseat=false; G.vsOpt=0; G.vsCodeMsg="";
        if(typeof ExhibitionMode!=="undefined") ExhibitionMode.clearSeries();
        G.scene=S.SELECT; G.sel=0; }
      else if(key==="vs2"){ G.selMode="vs1"; G.vsHotseat=true; G.vsOpt=0; G.vsCodeMsg="";
        if(typeof ExhibitionMode!=="undefined") ExhibitionMode.clearSeries();
        G.scene=S.SELECT; G.sel=0; }
      else if(key==="ghost"){
        let code=null;
        try{ code=window.prompt("Enter Champion Ghost Passcode (AZG1 / AZG2):"); }catch(e){}
        const gb = (typeof GhostBattles !== "undefined" ? GhostBattles : (typeof GhostCombat !== "undefined" ? GhostCombat : null));
        if(code && gb){
          const ghost = gb.importPasscode ? gb.importPasscode(code.trim()) : (gb.decodeGhostBuild ? gb.createGhostCombatant(gb.decodeGhostBuild(code.trim())) : null);
          if(ghost){
            G.selMode="vs1"; G.ghostFighter=ghost; G.scene=S.SELECT; G.sel=0;
            say("Ghost Challenger "+ghost.name+" loaded. Select your fighter.");
          } else { sDeny(); say("Invalid ghost passcode."); }
        }
      }
      else if(key==="p2p"){
        const net = (typeof P2PNetwork !== "undefined" ? P2PNetwork : (typeof P2PMultiplayer !== "undefined" ? P2PMultiplayer : null));
        if(net && typeof window !== "undefined" && typeof window.confirm === "function"){
          try {
            const isHost = window.confirm("P2P ARENA: Host new Arena Room (OK) or Join existing Room (Cancel)?");
            if(isHost){
              net.createRoom(function(offerCode){
                try{ window.prompt("Share your Host Room Offer Payload with Guest:", offerCode); }catch(e){}
                let ans = null;
                try{ ans = window.prompt("Paste Answer Payload from Guest:"); }catch(e){}
                if(ans) {
                  net.acceptAnswer(ans.trim());
                  say("P2P Host Connected. Choose your fighter.");
                  G.selMode="vs1"; G.scene=S.SELECT; G.sel=0;
                }
              });
            } else {
              let off = null;
              try{ off = window.prompt("Paste Host Room Offer Payload:"); }catch(e){}
              if(off){
                net.joinRoom(off.trim(), function(ansCode){
                  try{ window.prompt("Share your Answer Payload with Host:", ansCode); }catch(e){}
                  say("P2P Guest Connected. Choose your fighter.");
                  G.selMode="vs1"; G.scene=S.SELECT; G.sel=0;
                });
              }
            }
          } catch(e) {}
        }
      }
      else if(key==="list"){ G.selMode="browse"; G.scene=S.SELECT; G.sel=0; }
      else if(key==="rec"){ G.scene=S.RECORDS; G.recScroll=0; }
      else if(key==="board"){ G.scene=S.BOARD; G.boardTab=0; }
      else if(key==="opt"){ G.scene=S.OPTIONS; G.optSel=0; G.eraseArm=0; G.restoreArm=0; }
      else G.scene=S.HOW, G.how=0, G.howTopic="general", G.prevScene=S.MENU;
    }
    return;
  }
  if(sc===S.HOW){
    const last=howPages().length-1;
    const leave=()=>{ G.scene=G.prevScene||S.MENU; G.how=0; sPick();
                      if(G.scene===S.DUEL&&G.duel&&G.duel.ph===D.MENU) G.duel.ph=G.duel.retPh; };
    if(k==="a"){ if(G.how<last){G.how++;sTick();} else leave(); }
    if(k==="right"){ G.how=Math.min(last,G.how+1); sTick(); }
    if(k==="left"){ G.how=Math.max(0,G.how-1); sTick(); }
    if(k==="b"){ leave(); }
    return;
  }
  if(sc===S.RECORDS){
    if(k==="y"){ G.scene=S.TITLES; G.titleSel=0; sPick(); return; }
    if(k==="a"||k==="b"){G.scene=S.MENU;sPick();}
    return;
  }
  if(sc===S.BOARD){
    if(k==="left"||k==="right"||k==="up"||k==="down"){ G.boardTab=1-(G.boardTab|0); sTick(); }
    if(k==="a"||k==="b"){ G.scene=S.MENU; sPick(); }
    return;
  }
  if(sc===S.RENOWN){
    const rows=renownRows(), N=rows.length;
    if(G.renownSel>=N) G.renownSel=0;
    if(k==="up"){ G.renownSel=(G.renownSel+N-1)%N; sTick(); G.renownMsg=""; }
    if(k==="down"){ G.renownSel=(G.renownSel+1)%N; sTick(); G.renownMsg=""; }
    if(k==="b"){ G.scene=S.MENU; sPick(); return; }
    if(k==="a"||k==="left"||k==="right"){
      /* dispatch on the row's id, never on its index - inserting a catalogue
         entry must not re-point the row under it at somebody else's price */
      const row=rows[G.renownSel]||{}, id=row.id;
      if(id==="back"){ if(k==="a"){ G.scene=S.MENU; sPick(); } return; }
      if(id==="open_pick"){
        const tiers=metaRunPool(SAVE).openStages;
        const at=Math.max(0,tiers.findIndex(o=>o.tier===(G.openTier|0)));
        const nx=tiers[(at+(k==="left"?tiers.length-1:1))%tiers.length];
        /* session-scoped on purpose: what you OWN is on the save, which opening
           you elected to take is a decision about the next run and is made
           again the next time you stand here */
        G.openTier=nx.tier; sTick();
        say("Next run opens on stage "+nx.stage+", "+nx.label+".");
        return;
      }
      if(k!=="a") return;
      const r=metaBuy(SAVE.meta,id);
      if(!r.ok){ sDeny(); G.renownMsg=(META_BUY_REASON[r.reason]||"No.").toUpperCase(); return; }
      SAVE.meta=r.meta;
      /* an opening you just bought is not silently taken - metaOpenTier still
         resolves G.openTier against what is owned, so this only ever widens */
      persist(); sPick();
      G.renownMsg=(row.name||id).toUpperCase()+" BOUGHT FOR "+r.price+" "+META_CONFIG.unit;
      say(G.renownMsg+". "+metaSummary(SAVE.meta)+".");
    }
    return;
  }
  if(sc===S.CHALLENGE){
    const rows=challengeRows(), N=rows.length;
    if(G.chalSel>=N) G.chalSel=0;
    if(k==="up"){ G.chalSel=(G.chalSel+N-1)%N; sTick(); }
    if(k==="down"){ G.chalSel=(G.chalSel+1)%N; sTick(); }
    if(k==="b"){ G.scene=S.MENU; sPick(); return; }
    if(k==="a"){
      const row=rows[G.chalSel]||{};
      G.challengePick=row.id==="none"?null:row.id;
      G.challengeMastery=!!(G.challengePick&&row.mastery);
      sPick();
      /* the point of the screen: the objective IS the run mode, so taking one
         walks straight into fighter select rather than back to the menu */
      G.selMode="adventure"; G.scene=S.SELECT; G.sel=0;
      const tip=row.tip||row.desc||"";
      say(G.challengePick
          ? ((G.challengeMastery?"Mastery challenge: ":"Challenge run: ")+row.name+". "+tip+" Choose your fighter.")
          : "No standing objective. Choose your fighter.");
    }
    return;
  }
  if(sc===S.OPTIONS){
    if(k==="diff"||k==="x"||k==="d"){ cycleDifficulty(); return; }
    const rows=optionRows(), N=rows.length;
    if(k==="up"){G.optSel=(G.optSel+N-1)%N;sTick();G.eraseArm=0;G.restoreArm=0;}
    if(k==="down"){G.optSel=(G.optSel+1)%N;sTick();G.eraseArm=0;G.restoreArm=0;}
    if(k==="left"||k==="right"||k==="a"){
      /* dispatch on the row's id, never its index. Every handler below an
         inserted row used to shift by one silently, so adding a single
         option could re-point ERASE SAVE at the row above it. */
      const id=(rows[G.optSel]||{}).id;
      if(id==="diff"){ cycleDifficulty(k==="left"?-1:1); return; }
      else if(id==="sound"){ SAVE.sound=!SAVE.sound; syncSnd(); persist(); if(SAVE.sound) sPick(); }
      else if(id==="music"){ SAVE.music=!SAVE.music; persist(); sTick(); }
      else if(id==="motion"){ SAVE.motion=!SAVE.motion; persist(); sTick(); }
      else if(id==="pace"){ SAVE.pace=(((SAVE.pace|0)+1)%PACE_MODES.length); persist(); sTick();
                            say("Fight pace "+paceMode().name+". "+paceMode().blurb+"."); }
      else if(id==="deck"){ SAVE.dataDeck=!SAVE.dataDeck; syncDeckChrome(); persist(); sTick(); }
      else if(id==="name" && k==="a"){
        // fighter name: the OS prompt is the one honest text input a canvas
        // game has - it fails closed to the current name
        let nm=null;
        try{ nm=window.prompt("Fighter name (shown on the ladder):", SAVE.name||"CHALLENGER"); }catch(e){}
        if(nm!==null&&nm!==undefined){
          nm=sanitizeFighterName(nm);
          if(nm){ SAVE.name=nm; persist(); sPick(); say("Name set to "+nm+"."); }
        }
      }
      else if(id==="export" && k==="a"){ downloadSaveExport(); sPick(); say("Save exported."); }
      else if(id==="import" && k==="a"){ pickSaveImport(); }
      else if(id==="restore" && k==="a"){
        if(G.restoreArm){
          if(restoreLatestBackup()){ G.restoreArm=0; G.eraseArm=0; sPick(); say("Backup restored."); }
          else { G.restoreArm=0; }
        }
        else { G.restoreArm=1; G.eraseArm=0; sDeny(); }
      }
      else if(id==="erase" && k==="a"){
        if(G.eraseArm){
          SAVE=DEF_SAVE();
          try{ localStorage.removeItem(SAVE_KEY_LEGACY); }catch(e){}
          clearBackupVault(localStorage);
          clearSecurityLog(localStorage);
          invalidateRankApi();
          G.ranked=null;
          persist(true);
          syncSnd(); syncDeckChrome(); G.adv=null; G.surv=null; G.eraseArm=0; G.restoreArm=0; sBad(); say("Save erased.");
        }
        else { G.eraseArm=1; G.restoreArm=0; sDeny(); }
      }
      else if(id==="cloud" && k==="a"){ sDeny(); say("Set AZHA_SUPABASE_* and rebuild."); }
      else if((id==="cloud-up"||id==="cloud-in") && k==="a"){
        let em=null, pw=null;
        try{ em=window.prompt("Cloud email:", ""); }catch(e){}
        if(em===null||em===undefined) return;
        try{ pw=window.prompt("Cloud password (6+ chars):", ""); }catch(e){}
        if(pw===null||pw===undefined) return;
        (async()=>{
          const res=id==="cloud-up"
            ? await cloudSignUp(em, pw, localStorage)
            : await cloudSignIn(em, pw, localStorage);
          if(!res.ok){ sDeny(); say(String(res.error||"cloud auth failed").slice(0,80)); return; }
          if(res.needsConfirm){ sPick(); say("Check email to confirm, then sign in."); return; }
          sPick();
          say(id==="cloud-up"?"Account ready.":"Signed in.");
          await cloudSyncNow();
        })();
      }
      else if(id==="cloud-sync" && k==="a"){
        (async()=>{ sPick(); await cloudSyncNow(); })();
      }
      else if(id==="cloud-out" && k==="a"){
        (async()=>{
          await cloudSignOut(localStorage);
          sPick(); say("Signed out of cloud.");
        })();
      }
      else if(id==="ton" && k==="a"){
        (async()=>{
          if(tonReadWallet(localStorage)){
            const out=await tonDisconnect();
            sPick();
            say(out.ok?"TON wallet disconnected.":String(out.error||"disconnect failed").slice(0,80));
            return;
          }
          if(!tonCanConnect()){
            sDeny();
            say("TON needs HTTPS manifest (GitHub Pages).");
            return;
          }
          say("Opening TON Connect...");
          const res=await tonConnect();
          if(!res.ok){ sDeny(); say(String(res.error||"connect failed").slice(0,80)); return; }
          const w=tonReadWallet(localStorage);
          sPick();
          say(w?"TON "+tonShortAddress(w.address):"TON Connect closed.");
        })();
      }
      else if(id==="vol_sfx"){
        if(typeof SettingsGUI!=="undefined"){
          const delta = (k==="left" ? -10 : (k==="right" || k==="a" ? 10 : 0));
          if(delta !== 0){
            const nv = SettingsGUI.adjustVolume("sfxVolume", delta);
            sPick(); say("SFX Volume: " + nv + "%");
          }
        }
      }
      else if(id==="vol_bgm"){
        if(typeof SettingsGUI!=="undefined"){
          const delta = (k==="left" ? -10 : (k==="right" || k==="a" ? 10 : 0));
          if(delta !== 0){
            const nv = SettingsGUI.adjustVolume("bgmVolume", delta);
            sPick(); say("Music Volume: " + nv + "%");
          }
        }
      }
      else if(id==="rebind"){
        if(typeof SettingsGUI!=="undefined"){
          const actions=["attack", "jump", "special", "dash"];
          G.rebindIdx = G.rebindIdx || 0;
          if(k==="left"||k==="right"){
            G.rebindIdx = (G.rebindIdx + (k==="left"?actions.length-1:1)) % actions.length;
            sTick();
          } else if(k==="a"){
            const act = actions[G.rebindIdx];
            SettingsGUI.startRebinding(act, "combat");
            sPick(); say("Press any key to rebind " + act.toUpperCase());
          }
        }
      }
      else if(id==="lang"){
        if(typeof i18n!=="undefined"){
          const langs=i18n.getSupportedLanguages(), cur=i18n.getLanguage();
          const idx=langs.indexOf(cur);
          const next=langs[(idx+(k==="left"?langs.length-1:1))%langs.length];
          i18n.setLanguage(next); sPick(); say("Language: "+next.toUpperCase());
        }
      }
      else if(id==="touch"){
        if(typeof VirtualGamepad!=="undefined"){
          const act=!VirtualGamepad.isActive();
          VirtualGamepad.setVisible(act); SAVE.touchHud=act; persist();
          sPick(); say("Touch controls "+(act?"enabled":"disabled"));
        }
      }
      else if(id==="back" && k==="a"){ G.scene=S.MENU; sPick(); }
    }
    if(k==="b"){ G.scene=S.MENU; sPick(); }
    return;
  }
  if(sc===S.TOWER){
    if(k==="up"&&typeof TowerMode!=="undefined"){
      const st=TowerMode.getState();
      TowerMode.startFloor(Math.min(st.unlockedFloors, (st.currentFloor||1)+1)); sTick();
    }
    if(k==="down"&&typeof TowerMode!=="undefined"){
      const st=TowerMode.getState();
      TowerMode.startFloor(Math.max(1, (st.currentFloor||1)-1)); sTick();
    }
    if(k==="a"){
      sPick();
      G.selMode="tower"; G.scene=S.SELECT; G.sel=0;
    }
    if(k==="b"){ G.scene=S.MENU; sPick(); }
    return;
  }
  if(sc===S.DOJO){
    if(k==="y"&&typeof DojoMode!=="undefined"){
      if(DojoMode.isTutorialActive()){
        DojoMode.stopTutorial();
        say("Dojo tutorial ended.");
      } else {
        DojoMode.startTutorial();
        say("Dojo sparring tutorial started. " + DojoMode.getCurrentStage().title);
      }
      sPick();
      return;
    }
    if((k==="left"||k==="right")&&typeof DojoMode!=="undefined"){
      const behs=["stand","crouch","jump","block","attack"];
      const cfg=DojoMode.getConfig();
      const idx=behs.indexOf(cfg.aiDummy.behavior);
      const next=behs[(idx+(k==="left"?behs.length-1:1))%behs.length];
      DojoMode.setDummyBehavior(next); sTick();
    }
    if(k==="a"){ sPick(); G.selMode="dojo"; G.scene=S.SELECT; G.sel=0; }
    if(k==="b"){ G.scene=S.MENU; sPick(); }
    return;
  }
  if(sc===S.CREATE_FIGHTER){
    cfHandleInput(k);
    return;
  }
  if(sc===S.DECK_BUILDER){
    const heroId = G.sel || 0;
    const dbState = getDeckBuilderState(heroId);
    if(k==="b"){ G.scene=S.MENU; sPick(); return; }
    if(k==="left"){ G.sel = ((G.sel||0)-1+FIGHTERS.length)%FIGHTERS.length; G.deckBuilderState = null; sTick(); return; }
    if(k==="right"){ G.sel = ((G.sel||0)+1)%FIGHTERS.length; G.deckBuilderState = null; sTick(); return; }
    if(k==="y"&&typeof DeckBuilder!=="undefined"){
      const exp = DeckBuilder.exportDeckCode(heroId, dbState.deckName, dbState.deck);
      if(exp.ok){
        try{ window.prompt("Deck Code:", exp.code); }catch(e){}
        dbState.msg = "DECK CODE EXPORTED!";
        dbState.msgColor = GRN;
      } else {
        dbState.msg = exp.error;
        dbState.msgColor = RED;
      }
      sPick();
      return;
    }
    return;
  }
  if(sc===S.ENDLESS){
    if(k==="b"){ G.scene=S.MENU; sPick(); return; }
    const st = G.endless;
    if(!st){
      if(k==="left"){ G.sel = ((G.sel||0)-1+FIGHTERS.length)%FIGHTERS.length; sTick(); return; }
      if(k==="right"){ G.sel = ((G.sel||0)+1)%FIGHTERS.length; sTick(); return; }
      if(k==="a"){ G.selMode="endless"; startEndless(G.sel||0); sPick(); return; }
      return;
    }
    const maxOpt = (st.victorious && !st.overdrive) ? 5 : 4;
    if(k==="up"||k==="left"){ G.gauntletOpt = ((G.gauntletOpt||0) - 1 + maxOpt) % maxOpt; sTick(); return; }
    if(k==="down"||k==="right"){ G.gauntletOpt = ((G.gauntletOpt||0) + 1) % maxOpt; sTick(); return; }
    if(k==="a"){
      const opt = G.gauntletOpt || 0;
      if(opt === 0){
        sPick();
        endlessNext();
        return;
      } else if(opt === 1){
        if(st.hp < st.maxhp){
          const heal = Math.round(st.maxhp * 0.40);
          st.hp = Math.min(st.maxhp, st.hp + heal);
          saveRun();
          sPick();
          say("Medical clinic treatment applied. Restored " + heal + " HP.");
        } else {
          sDeny();
          say("Already at full health.");
        }
        return;
      } else if(opt === 2){
        st.bag = st.bag || [];
        if(st.bag.indexOf("salts") < 0 && st.purse >= 45){
          st.purse -= 45;
          st.bag.push("salts");
          saveRun();
          sPick();
          say("Bought Smelling Salts for your Corner Bag.");
        } else if(st.bag.indexOf("syringe") < 0 && st.purse >= 65){
          st.purse -= 65;
          st.bag.push("syringe");
          saveRun();
          sPick();
          say("Bought Adrenaline Syringe for your Corner Bag.");
        } else {
          sDeny();
          say(st.purse < 45 ? "Not enough purse coins." : "Corner bag fully stocked.");
        }
        return;
      } else if(opt === 3){
        if(st.victorious && !st.overdrive){
          st.overdrive = true;
          saveRun();
          sPick();
          say("Endless Overdrive Activated! Pushing beyond the Heavens!");
          return;
        } else {
          clearRun();
          G.scene = S.MENU;
          sPick();
          say("Gauntlet run retired and recorded. Returning to menu.");
          return;
        }
      } else if(opt === 4){
        clearRun();
        G.scene = S.MENU;
        sPick();
        say("Gauntlet victory claimed! Returning to menu as Champion.");
        return;
      }
    }
    return;
  }
  if(sc===S.PERK){
    const picks = G.perkChoices || [];
    const N = picks.length;
    if(!N){ G.scene=S.ENDLESS; return; }
    if(k==="left"||k==="up"){ G.perkSel=(G.perkSel+N-1)%N; sTick(); }
    if(k==="right"||k==="down"){ G.perkSel=(G.perkSel+1)%N; sTick(); }
    if(k==="b"){ G.scene=S.ENDLESS; sPick(); say("No perk chosen."); return; }
    if(k==="a"){
      const p = picks[G.perkSel];
      if(p && G.endless && typeof applyGauntletPerk === "function"){
        applyGauntletPerk(G.endless, p.id);
        saveRun();
        G.scene=S.ENDLESS;
        sPick();
        say("Acquired " + p.name + ". " + p.desc);
      } else {
        G.scene=S.ENDLESS;
      }
    }
    return;
  }
  if(sc===S.WEEKLY){
    const st = G.weekly;
    if(st && st.active){
      if(G.weeklyMode==="augment"){
        const picks = G.weeklyPicks || [];
        if(k==="b"){ G.weeklyMode="hub"; sPick(); return; }
        if(k==="left"){ G.weeklyAugmentSel = (G.weeklyAugmentSel - 1 + picks.length) % Math.max(1, picks.length); sTick(); return; }
        if(k==="right"){ G.weeklyAugmentSel = (G.weeklyAugmentSel + 1) % Math.max(1, picks.length); sTick(); return; }
        if(k==="a" && picks[G.weeklyAugmentSel]){
          const chosen = picks[G.weeklyAugmentSel];
          if(typeof applyWeeklyAugment === "function") applyWeeklyAugment(st, chosen.id);
          saveRun();
          G.weeklyMode = "hub";
          sPick();
          say("Infused Anomaly Augment: " + chosen.name + ". " + chosen.desc);
          return;
        }
        return;
      }
      if(G.weeklyMode==="clinic"){
        const acts = (typeof weeklyCornerActions === "function") ? weeklyCornerActions(st) : [];
        if(k==="b"){ G.weeklyMode="hub"; sPick(); return; }
        if(k==="up"){ G.weeklyClinicSel = (G.weeklyClinicSel - 1 + acts.length) % Math.max(1, acts.length); sTick(); return; }
        if(k==="down"){ G.weeklyClinicSel = (G.weeklyClinicSel + 1) % Math.max(1, acts.length); sTick(); return; }
        if(k==="a" && acts[G.weeklyClinicSel]){
          const act = acts[G.weeklyClinicSel];
          if(act.id==="clinic_heal"){
            if(st.hp < st.maxhp){
              const res = weeklyCornerActions.clinic(st);
              saveRun(); sPick(); say("Corner clinic applied: +" + res.healed + " HP restored.");
            } else { sDeny(); say("Already at full health."); }
          } else if(act.id==="buy_salts"){
            const res = weeklyCornerActions.buyItem(st, "salts");
            if(res.ok){ saveRun(); sPick(); say("Equipped Smelling Salts in corner bag."); }
            else { sDeny(); say(res.msg || "Cannot purchase."); }
          } else if(act.id==="buy_syringe"){
            const res = weeklyCornerActions.buyItem(st, "syringe");
            if(res.ok){ saveRun(); sPick(); say("Equipped Adrenaline Stim in corner bag."); }
            else { sDeny(); say(res.msg || "Cannot purchase."); }
          } else if(act.id==="buy_respite"){
            const res = weeklyCornerActions.buyItem(st, "respite");
            if(res.ok){ saveRun(); sPick(); say("Purchased Corner Respite retry token! (" + st.respitesLeft + " lives)"); }
            else { sDeny(); say(res.msg || "Cannot purchase."); }
          } else if(act.id==="spar_drill"){
            const res = weeklyCornerActions.buyItem(st, "drill");
            if(res.ok){ saveRun(); sPick(); say("Sparring drill completed: +15% technique power!"); }
            else { sDeny(); say(res.msg || "Cannot purchase."); }
          }
          return;
        }
        return;
      }
      // Main Active Weekly Hub
      if(k==="b"){ G.scene=S.MENU; sPick(); return; }
      if(k==="a"){
        // Fight next tier
        startWeeklyTierMatch(st);
        return;
      }
      if(k==="x"||k==="d"){
        // Open Augment Drafting
        G.weeklyPicks = (typeof weeklyAugmentChoices === "function") ? weeklyAugmentChoices(st, 3) : [];
        G.weeklyAugmentSel = 0;
        G.weeklyMode = "augment";
        sPick();
        return;
      }
      if(k==="c"){
        // Open Corner Clinic
        G.weeklyClinicSel = 0;
        G.weeklyMode = "clinic";
        sPick();
        return;
      }
      if(k==="y"||k==="r"){
        // Overdrive toggle or Abandon
        if(st.victorious && !st.overdrive){
          st.overdrive = true;
          saveRun();
          sPick();
          say("Weekly Overdrive engaged! Push into infinite difficulty.");
        } else {
          clearRun();
          sPick();
          say("Weekly campaign retired.");
        }
        return;
      }
      return;
    } else {
      if(k==="b"){ G.scene=S.MENU; sPick(); return; }
      if(k==="a"){ G.selMode="weekly"; G.scene=S.SELECT; sPick(); return; }
      return;
    }
  }
  if(sc===S.REPLAY){
    if(typeof ReplayViewer!=="undefined"){
      if(k==="left"){ ReplayViewer.stepPrev(); sTick(); }
      if(k==="right"){ ReplayViewer.stepNext(); sTick(); }
      if(k==="a"){
        if(!ReplayViewer.getState().activeReplay){
          const rep=ReplayEngine.createReplay({id:0,name:FIGHTERS[0].name},{id:2,name:FIGHTERS[2].name},12345);
          ReplayEngine.recordTurn(rep,{turnNum:1,p1Tech:"jab",p2Tech:"cross",p1Hp:100,p2Hp:92,range:"MID",position:"CENTRE"});
          ReplayEngine.recordTurn(rep,{turnNum:2,p1Tech:"cross",p2Tech:"low_kick",p1Hp:95,p2Hp:80,range:"MID",position:"ROPES"});
          ReplayEngine.recordTurn(rep,{turnNum:3,p1Tech:"lead_hook",p2Tech:"guard",p1Hp:95,p2Hp:65,range:"MID",position:"CORNER"});
          ReplayViewer.loadReplay(rep); sPick();
        } else {
          if(ReplayViewer.getState().isPlaying) ReplayViewer.pause();
          else ReplayViewer.play();
          sPick();
        }
      }
      if(k==="y"){
        const spds=[0.5, 1.0, 2.0];
        const cur=ReplayViewer.getState().playbackSpeed;
        const next=spds[(spds.indexOf(cur)+1)%spds.length];
        ReplayViewer.setSpeed(next); sPick();
      }
    }
    if(k==="b"){ G.scene=S.MENU; sPick(); }
    return;
  }
  if(sc===S.CODEX){
    if(typeof CodexViewer!=="undefined"){
      if(k==="up"){ CodexViewer.handleInput("UP"); sTick(); }
      if(k==="down"){ CodexViewer.handleInput("DOWN"); sTick(); }
      if(k==="left"){ CodexViewer.handleInput("LEFT"); sTick(); }
      if(k==="right"){ CodexViewer.handleInput("RIGHT"); sTick(); }
    }
    if(k==="b"){ G.scene=S.MENU; sPick(); }
    if(k==="a"){ sPick(); }
    return;
  }
  if(sc===S.TROPHY){
    if(typeof TrophyRoom!=="undefined"){
      if(k==="up"){ TrophyRoom.handleInput("UP", null, SAVE); sTick(); }
      if(k==="down"){ TrophyRoom.handleInput("DOWN", null, SAVE); sTick(); }
      if(k==="left"){ TrophyRoom.handleInput("LEFT", null, SAVE); sTick(); }
      if(k==="right"){ TrophyRoom.handleInput("RIGHT", null, SAVE); sTick(); }
    }
    if(k==="b"){ G.scene=S.MENU; sPick(); }
    if(k==="a"){ sPick(); }
    return;
  }
  if(sc===S.SELECT){
    if(k==="diff"){ cycleDifficulty(); return; }
    const vsMode=G.selMode==="vs1"||G.selMode==="vs2";
    if(vsMode&&typeof ExhibitionMode!=="undefined"){
      const optKeys=["cpuLv","arch","venue","rule","handicap","series","overlay","swapSides"];
      if(k==="1"||k==="2"||k==="3"||k==="4"||k==="5"||k==="6"||k==="7"||k==="8"){
        const ix=parseInt(k,10)-1;
        ExhibitionMode.cycleSetting(optKeys[ix],1);
        G.vsOpt=ix; sTick();
        const row=ExhibitionMode.optionRows()[ix];
        if(row) say(row.label+": "+row.value+".");
        return;
      }
      if(k==="rand"){
        const list=selList();
        if(G.selMode==="vs1"){
          G.sel=list.indexOf(ExhibitionMode.randomFighter(list));
          if(G.sel<0) G.sel=0;
          sTick(); say("Random fighter.");
        } else {
          const avoid=G.vsHotseat?-1:G.vsP1;
          const fid=ExhibitionMode.randomFighter(list,avoid);
          G.sel=list.indexOf(fid);
          if(G.sel<0) G.sel=0;
          sTick(); say("Random opponent.");
        }
        return;
      }
      if(k==="code"){
        let code="";
        try{ code=window.prompt("Paste Exhibition bout code (AZX1-...):")||""; }catch(e){ code=""; }
        const decoded=ExhibitionMode.decodeBout(String(code).trim());
        if(!decoded){ sDeny(); say("Invalid bout code."); return; }
        ExhibitionMode.setSettings(decoded.settings);
        startExhibitionBout(decoded.p1,decoded.p2,{hotseat:G.vsHotseat});
        G.selMode="vs1";
        say("Bout code loaded.");
        return;
      }
    }
    const list=selList(), cols=SEL_COLS;
    if(k==="left"){G.sel=(G.sel+list.length-1)%list.length;sTick();}
    if(k==="right"){G.sel=(G.sel+1)%list.length;sTick();}
    if(k==="up"){G.sel=(G.sel+list.length-cols)%list.length;sTick();}
    if(k==="down"){G.sel=(G.sel+cols)%list.length;sTick();}
    if(k==="b"){ if(G.selMode==="vs2"){G.selMode="vs1";sPick();} else {G.scene=S.MENU; sPick();} updateRom(); return; }
    if(k==="y"){ openDossier(list[G.sel],S.SELECT); return; }
    if(k==="a"){
      const id=list[G.sel];
      sPick();
      if(G.selMode==="browse"){ openDossier(id,S.SELECT); }
      else if(G.selMode==="adventure"||G.selMode==="ngplus"){
        G.adv=newAdv(id,G.selMode==="ngplus"?(SAVE.rec.ngplus||0):0);
        newField(G.adv); saveRun(); G.scene=S.MAP;
        say("Adventure started as "+FIGHTERS[id].name+". Stage 1, 60 steps.");
      }
      else if(G.selMode==="survival"){ startSurvival(id); }
      else if(G.selMode==="ranked"){ startRanked(id); }
      else if(G.selMode==="tower"){ startTower(id); }
      else if(G.selMode==="dojo"){ startDojo(id); }
      else if(G.selMode==="endless"){ startEndless(id); }
      else if(G.selMode==="weekly"){ startWeekly(id); }
      else if(G.selMode==="vs1"){
        if(G.ghostFighter){
          const gF = G.ghostFighter;
          G.ghostFighter = null;
          startExhibitionBout(id, gF.id, { ghost: gF });
          G.selMode="vs1";
          say("Match starting against Ghost Challenger "+gF.name+".");
        } else {
          G.vsP1=id; G.selMode="vs2";
          if(id===G.vsP1) {/* seat locked */}
          say((G.vsHotseat?"Player one locked. ":"Your fighter locked. ")+"Choose the opponent.");
        }
      }
      else if(G.selMode==="vs2"){
        startExhibitionBout(G.vsP1,id,{hotseat:G.vsHotseat});
        G.selMode="vs1";
      }
    }
    updateRom(); return;
  }
  if(sc===S.FIGHTER){
    const list=selList();
    const at=Math.max(0,list.indexOf(G.dossier));
    if(k==="left"||k==="up"){ G.dossier=list[(at+list.length-1)%list.length]; sTick(); updateRom(); }
    if(k==="right"||k==="down"){ G.dossier=list[(at+1)%list.length]; sTick(); updateRom(); }
    if(k==="b"||k==="a"||k==="y"){ G.scene=G.dossierFrom; sPick(); updateRom(); }
    return;
  }
  if(sc===S.MAP){
    if(k==="up")advMove(0,-1); else if(k==="down")advMove(0,1);
    else if(k==="left")advMove(-1,0); else if(k==="right")advMove(1,0);
    else if(k==="b"){ G.scene=S.PAUSE; G.pauseSel=0; sPick(); }
    else if(k==="y"){ openDossier(G.adv.hero,S.MAP); }
    return;
  }
  if(sc===S.PAUSE){
    const N=4;
    if(k==="up"){G.pauseSel=(G.pauseSel+N-1)%N;sTick();}
    if(k==="down"){G.pauseSel=(G.pauseSel+1)%N;sTick();}
    if(k==="b"){ G.scene=S.MAP; sPick(); }
    if(k==="a"){ sPick();
      if(G.pauseSel===0) G.scene=S.MAP;
      else if(G.pauseSel===1){ G.prevScene=S.PAUSE; G.how=0; G.howTopic="adventure"; G.scene=S.HOW; }
      else if(G.pauseSel===2){ saveRun(); G.adv=null; G.scene=S.MENU; G.menuSel=0; say("Run saved."); }
      else { clearRun(); G.adv=null; G.scene=S.MENU; G.menuSel=0; sBad(); say("Run abandoned."); }
    }
    return;
  }
  if(sc===S.STAGECLEAR){
    if(k==="b"){ G.scene=S.PAUSE; G.pauseSel=0; sPick(); return; }
    if(k==="a"){
      // the camp offers three, you take one, and it lasts the run
      openCamp(G.adv,false);
    }
    return;
  }
  if(sc===S.SHOP){
    const stock=G.shopStock||[];
    // rows: stock, then the trainer's three services, then LEAVE
    const N=stock.length+4;
    if(k==="up"){ G.shopSel=(G.shopSel+N-1)%N; sTick(); }
    if(k==="down"){ G.shopSel=(G.shopSel+1)%N; sTick(); }
    if(k==="b"){ G.scene=S.MAP; sPick(); return; }
    if(k==="y"){
      const cost=rerollCost(G.adv);
      const r=withCornerSlots(G.adv,()=>buyItem(G.adv,rerollTicket(G.adv)));
      if(r.ok){ G.shopStock=withCornerSlots(G.adv,()=>shopStock(G.adv)); G.shopSel=0; sPick(); say("Rerolled for "+cost+"."); }
      else { sDeny(); G.shopMsg=BUY_REASON[r.reason]||"No."; }
      return;
    }
    if(k==="a"){
      if(G.shopSel>=stock.length && G.shopSel<=stock.length+2){
        const kind=G.shopSel===stock.length?"CUT":(G.shopSel===stock.length+1?"DRILL":"SEAL");
        const list=kind==="CUT"?cutCandidates(G.adv):(kind==="DRILL"?drillCandidates(G.adv):(typeof sealCandidates==="function"?sealCandidates(G.adv):[]));
        if(!list.length){ sDeny();
          G.shopMsg=kind==="CUT"?"the trainer will not thin that list further":(kind==="DRILL"?"nothing left to sharpen":"no technique cards available to infuse");
          return; }
        G.svc={kind,list,sel:0,scroll:0}; G.scene=S.SERVICE; sPick();
        say(kind==="CUT"?"Choose a technique to retire.":(kind==="DRILL"?"Choose a technique to drill.":"Choose a technique to infuse with a seal."));
        return;
      }
      if(G.shopSel>=stock.length+3){ G.scene=S.MAP; sPick(); return; }
      const item=stock[G.shopSel];
      const r=withCornerSlots(G.adv,()=>buyItem(G.adv,item));
      if(r.ok){
        G.shopStock=stock.filter((_,i)=>i!==G.shopSel);
        G.shopSel=Math.min(G.shopSel,G.shopStock.length);
        G.shopMsg=item.name+" bought."; saveRun(); sPick();
        say(item.name+" bought. "+G.adv.purse+" left.");
      } else { G.shopMsg=BUY_REASON[r.reason]||"You cannot buy that."; sDeny(); }
    }
    return;
  }
  if(sc===S.SERVICE){
    const v=G.svc;
    if(!v){ G.scene=S.SHOP; return; }
    const N=v.list.length;
    if(k==="up"){ v.sel=(v.sel+N-1)%N; sTick(); }
    if(k==="down"){ v.sel=(v.sel+1)%N; sTick(); }
    if(k==="left"){ v.sel=Math.max(0,v.sel-10); sTick(); }
    if(k==="right"){ v.sel=Math.min(N-1,v.sel+10); sTick(); }
    if(k==="b"){ G.svc=null; G.scene=S.SHOP; sPick(); return; }
    if(k==="a"){
      const id=v.list[v.sel];
      let ticket=null;
      if(v.kind==="CUT") ticket=cutTicket(G.adv,id);
      else if(v.kind==="DRILL") ticket=drillTicket(G.adv,id);
      else if(v.kind==="SEAL") {
        const seals=typeof SEAL_IDS!=="undefined"?SEAL_IDS:["SEAL_LIGHTNING","SEAL_HEAVY","SEAL_VIPER","SEAL_VAMPIRE","SEAL_COUNTER","SEAL_FLOW"];
        const curSeal=((G.adv.seals||{})[id]);
        const nextSeal=seals[(seals.indexOf(curSeal)+1)%seals.length];
        ticket=sealTicket(G.adv,id,nextSeal);
      }
      const r=buyItem(G.adv,ticket);
      if(r.ok){
        G.shopMsg=ticket.name+" done.";
        G.svc=null; G.scene=S.SHOP; saveRun(); sPick();
        say(ticket.name+". "+G.adv.purse+" left.");
      } else { G.shopMsg=BUY_REASON[r.reason]||"No."; sDeny(); }
    }
    return;
  }
  if(sc===S.DRAFT){
    const N=G.draftPick.length;
    const runner=G.adv||G.endless;
    const destScene=G.endless?S.ENDLESS:S.MAP;
    if(!N){ G.scene=destScene; return; }
    if(k==="left"||k==="up"){ G.draftSel=(G.draftSel+N-1)%N; sTick(); }
    if(k==="right"||k==="down"){ G.draftSel=(G.draftSel+1)%N; sTick(); }
    if(k==="b"){ G.scene=destScene; sPick(); say("Nothing taken."); return; }   // skipping is allowed
    if(k==="a"){
      const id=G.draftPick[G.draftSel], res=applyDraft(runner,id);
      if(!res){ sDeny(); return; }
      runner.handNote={id:res.id, name:res.tech.name};
      saveRun(); G.scene=destScene; sPick();
      say("Learned "+res.tech.name+". It leads the next hand. "+draftSummary(runner));
    }
    return;
  }
  if(sc===S.BENEFIT){
    const N=G.benefitPick.length;
    if(k==="left"||k==="up"){ G.benefitSel=(G.benefitSel+N-1)%N; sTick(); }
    if(k==="right"||k==="down"){ G.benefitSel=(G.benefitSel+1)%N; sTick(); }
    if(k==="a"){
      const a=G.adv, id=G.benefitPick[G.benefitSel], b=BENEFITS[id];
      a.benefits.push(id);
      if(b.onPick) b.onPick(a);
      /* The opening camp is not a stage clear. It hands the run its first
         benefit and returns to the field: nothing advances, nothing heals, no
         fresh field, no gym. Everything below this block is the stage-clear
         path exactly as it was. */
      if(G.campFirst){
        G.campFirst=false; a.campTaken=true;
        if(a.map&&a.map.camps) a.map.camps.length=0;
        saveRun(); G.scene=S.MAP; sPick();
        say(b.name+" taken. "+b.desc+". Back to the field.");
        return;
      }
      a.stage++; a.reroll=0; a.beaten={}; a.used={};
      const heal=challengeScaleHeal(a, Math.round(a.maxhp*.2)+(benefitFlag(a.benefits,"stageHeal")||0));
      a.hp=Math.min(a.maxhp,a.hp+heal);
      bumpRec("stages"); newField(a); saveRun();
      openShop(a); sPick();
      say(b.name+" taken. Stage "+a.stage+". "+a.hp+" HP. "+a.purse+" in the purse.");
    }
    return;
  }
  if(sc===S.DAILY){
    if(k==="b"){ G.scene=S.MENU; sPick(); return; }
    if(k==="a"){
      const D=dailyState(SAVE,dayKey());
      if(D.done){ sDeny(); return; }
      startDailyGauntlet();
    }
    return;
  }
  if(sc===S.TITLES){
    const owned=(SAVE.titles||[]);
    if(!owned.length){ if(k==="a"||k==="b"){ G.scene=S.RECORDS; sPick(); } return; }
    if(k==="up"){ G.titleSel=(G.titleSel+owned.length-1)%owned.length; sTick(); }
    if(k==="down"){ G.titleSel=(G.titleSel+1)%owned.length; sTick(); }
    if(k==="a"){ SAVE.title=owned[G.titleSel]; persist(); sPick();
                 say("Title set to "+titleOf(SAVE.title)+"."); }
    if(k==="b"){ G.scene=S.RECORDS; sPick(); }
    return;
  }
  if(sc===S.BRIEF){
    if(k==="diff"||k==="x"||k==="d"){ cycleDifficulty(); return; }
    if(k==="a"){ const f=G.brief.f, a=G.adv, ambush=!!G.brief.ambush; sPick();
      const ng=a.ng||0, dm=diff();
      if(f.boss) startDuel({boss:true,fromAdv:true,ng,stage:9,
                             oppRankIndex:Math.min(MAX_RANK_INDEX,(myRanking().rank.index||0)+2)});
      else if(f.tf) startDuel({oppFid:f.art,oppHp:Math.round((40+a.stage*10+ng*12)*dm.hp),
                               oppPool:battlePool(f.art,f.lv),tf:true,tfArt:f.art,fromAdv:true,
                               oppLv:f.lv,oppAtk:(.9+a.stage*.05+ng*.15)*dm.dmg,stage:a.stage});
      else startDuel({oppFid:f.id,oppHp:Math.round((85+a.stage*14+ng*18)*dm.hp),
                      oppPool:battlePool(f.id,f.lv),fromAdv:true,oppLv:f.lv,
                      oppAtk:(.95+a.stage*.05+ng*.15)*dm.dmg,stage:a.stage,
                      oppRankIndex:typeof cpuRankIndexFor==="function"
                        ?cpuRankIndexFor(f.id,f.lv):Math.min(MAX_RANK_INDEX,a.stage+2)});
      if(ambush&&G.duel){ G.duel.p.focus=0; G.duel.e.focus=Math.min(G.duel.e.focusMax,2); }
    }
    if(k==="b"&&!G.brief.ambush){ const m=G.adv.map; m.steps=Math.max(0,m.steps-1); G.scene=S.MAP; sTick();
      if(m.steps<=0) outOfSteps(); else saveRun();
    }
    if(k==="y"){
      if(G.briefBounties && G.briefBounties.length > 0){
        G.acceptedBountyIndex = ((G.acceptedBountyIndex || 0) + 1) % G.briefBounties.length;
        G.acceptedBounty = G.briefBounties[G.acceptedBountyIndex];
        sPick();
        say("Bounty selected: " + G.acceptedBounty.title + ". " + G.acceptedBounty.desc);
        return;
      }
      const f=G.brief.f; if(!f.tf&&!f.boss) openDossier(f.id,S.BRIEF); else sDeny();
    }
    return;
  }
  if(sc===S.DUEL){ duelKey(k); return; }
  if(sc===S.RESULT){
    const r=G.result;
    /* Y only. A and B keep their exact existing behaviour - several suites
       reach this screen and press A expecting to leave immediately, so a
       "skip the reveal, then continue" two-press gate would break them.
       Exhibition is the exception: A rematches (or continues a Bo3), B leaves. */
    /* a patrol's short card has no stat tab and no brag card to open */
    const short=resultIsShort(r);
    if(k==="x"&&!short){ exportBragCard(); return; }
    if(G.resTab===1){ if(k==="b"||k==="y"){ G.resTab=0; sPick(); } return; }
    if(k==="y"&&G.lastStats&&r.kind!=="steps"&&!short){ G.resTab=1; sPick(); return; }
    const isExhib=(r.kind==="vswin"||r.kind==="vsloss")&&!!r.exhibition;
    if(isExhib&&(k==="a"||k==="b")){
      const ser=r.series;
      const seriesOpen=ser&&!ser.done&&ser.format==="bo3";
      if(k==="a"){
        sPick();
        const last=(typeof ExhibitionMode!=="undefined"&&ExhibitionMode.getLastBout)
          ?ExhibitionMode.getLastBout():null;
        if(!last){ G.scene=S.MENU; G.menuSel=0; return; }
        if(seriesOpen){
          startExhibitionBout(last.p1,last.p2,{
            hotseat:last.hotseat, continueSeries:true, rematch:true,
            settings:last.settings
          });
        } else {
          if(typeof ExhibitionMode!=="undefined") ExhibitionMode.clearSeries();
          startExhibitionBout(last.p1,last.p2,{
            hotseat:last.hotseat, rematch:true,
            settings:last.settings, series:"single"
          });
        }
        return;
      }
      if(k==="b"){
        sPick();
        if(typeof ExhibitionMode!=="undefined") ExhibitionMode.clearSeries();
        G.scene=S.MENU; G.menuSel=0;
        return;
      }
    }
    /* The climb keeps going too: A takes the next floor, or re-takes the one
       that just beat you, with the fighter already on the stairs. B is the way
       back to the lobby, where the floor list and the rules live. */
    const isTower=(r.kind==="towerwin"||r.kind==="towerloss")&&!!G.tower;
    if(isTower&&(k==="a"||k==="b")){
      sPick();
      const hero=G.tower.hero, tst=(typeof TowerMode!=="undefined")?TowerMode.getState():null;
      if(k==="b"){ G.scene=S.TOWER; return; }
      if(r.kind==="towerloss"){ startTower(hero,r.floor||1); return; }
      const next=(r.floor||1)+1;
      if(tst&&next<=tst.unlockedFloors){ startTower(hero,next); return; }
      /* the top of the tower, or a floor the climb has not earned yet */
      if(tst&&typeof TowerMode!=="undefined") TowerMode.startFloor(Math.min(tst.unlockedFloors,next));
      G.scene=S.TOWER;
      return;
    }
    /* The ladder keeps going. A seats the next opponent, B closes the session
       out - and at 10th Dan there is no next opponent, so A closes it too. */
    const isRanked=(r.kind==="rankwin"||r.kind==="rankloss")&&!!G.ranked;
    if(isRanked&&(k==="a"||k==="b")){
      sPick();
      if(k==="a"&&!G.ranked.done){ rankedNextBout(); return; }
      endRankedSession();
      return;
    }
    if(k==="a"){ sPick();
      if(r.kind==="towerwin"){
        G.scene=S.TOWER;
        if(typeof TowerMode!=="undefined"){
          const st=TowerMode.getState();
          TowerMode.startFloor(Math.min(st.unlockedFloors, (r.floor||1)+1));
        }
      }
      else if(r.kind==="towerloss"){
        G.scene=S.TOWER;
      }
      else if(r.kind==="gauntletvictory"){
        G.scene = S.ENDLESS;
      }
      else if(r.kind==="endlesswin"){
        if(r.needsPerk&&typeof gauntletPerkChoices==="function"&&G.endless){
          G.perkChoices = gauntletPerkChoices(G.endless, 3);
          G.perkSel = 0;
          G.scene = S.PERK;
        } else if(r.needsDraft&&typeof draftChoices==="function"&&G.endless){
          G.scene = S.DRAFT;
          G.draftPick = draftChoices({hero:G.endless.hero, stage:G.endless.stage||1, drafted:G.endless.drafted});
          G.draftSel = 0;
        } else if(G.endless){
          G.scene = S.ENDLESS;
        } else {
          G.scene = S.MENU; G.menuSel = 0;
        }
      }
      else if(r.kind==="endlessloss"){ G.scene=S.MENU; G.menuSel=0; }
      else if(r.kind==="weekly_tier_win"||r.kind==="weekly_respite"||r.kind==="weekly_grand_win"){
        if(G.weekly && G.weekly.active){
          G.scene = S.WEEKLY;
        } else {
          G.scene = S.MENU; G.menuSel = 0;
        }
      }
      else if(r.kind==="weekly_loss"||r.kind==="weeklywin"||r.kind==="weeklyloss"){ G.scene=S.MENU; G.menuSel=0; }
      else if(r.kind==="dojoend"){ G.scene=S.DOJO; }
      else if(r.kind==="win"){
        /* The reward for a win is a choice, not just a step forward - and it is
           the FIRST win of the run, not the first stage clear, that opens it.
           canDraft() asks only whether the run is full, so the very first mook
           put away offers a card; stage one lays the winnable fight in the near
           columns (see newField) so that first offer lands minutes in. */
        if(G.adv&&canDraft(G.adv)){
          const first=!draftedTechs(G.adv).length;
          G.draftPick=draftChoices(G.adv); G.draftSel=0;
          if(G.draftPick.length){ G.scene=S.DRAFT;
            say((first?"Your first draft. A run stops being the movelist you were dealt here. ":"")
                +"Draft a technique: "+G.draftPick.map(id=>TECH[id].name).join(", ")+"."); }
          else G.scene=S.MAP;
        } else G.scene=S.MAP;
      }
      else if(r.kind==="steps"){ G.scene=S.MAP; }
      /* a repel puts you straight back on the field, standing where you stood */
      else if(r.kind==="repel"){ G.scene=G.adv?S.MAP:S.MENU; }
      else if(r.kind==="ko"){
        if(r.cont&&G.adv){ const a=G.adv; a.continues--; a.hp=Math.max(1,Math.round(a.maxhp*.6));
          a.reroll=(a.reroll||0)+1; newField(a); saveRun(); G.scene=S.MAP;
          say("Continue used. "+a.continues+" left."); }
        /* the one changed line in this handler. A with continues left is
           untouched above; this is the branch that used to dump the player on
           the title with no account of the run at all. */
        else { openRunEnd(); }
      }
      else if(r.kind==="survwin"){ survNext(); }
      else if(r.kind==="survend"){ G.scene=S.MENU; G.menuSel=0; }
      else { G.scene=S.MENU; G.menuSel=0; }
    }
    if(k==="b"){
      /* GIVING UP IS STILL ENDING THE RUN. This used to drop the player on the
         title with no account of it and no renown for it, which is the same dead
         end the no-continues path had. Same door, same payment. */
      if(r.kind==="ko"&&r.cont){ if(G.adv) openRunEnd(); else { G.scene=S.TITLE; } sPick(); }
      else onKey("a");            // B never dead-ends on a result screen
    }
    return;
  }
  if(sc===S.RUNEND){
    if(k==="a"){ runItBack(); return; }
    if(k==="b"){ G.runEnd=null; G.scene=S.TITLE; sPick(); return; }
    return;
  }
  if(sc===S.CREDITS){
    if(G.credT<=120) return;
    if(k==="a"){ const hero=G.adv?G.adv.hero:0; G.adv=newAdv(hero,SAVE.rec.ngplus||1);
      newField(G.adv); saveRun(); G.scene=S.MAP; sPick(); say("New Game Plus started."); }
    if(k==="b"){ G.scene=S.TITLE; G.adv=null; sPick(); }
    return;
  }
}
/* Any moment you are choosing rather than reacting, B gets you out. */
const FIGHT_MENU=["RESUME","HOW TO FIGHT","FORFEIT MATCH"];
const canOpenFightMenu=(d)=>d.ph===D.TAPE||d.ph===D.INTRO||d.ph===D.CMD||d.ph===D.CMD2||d.ph===D.PASS||d.ph===D.END;
function openFightMenu(d){ d.retPh=d.ph; d.ph=D.MENU; d.menuSel=0; d.quitArm=0; sPick();
                           say("Fight menu. Resume, how to fight, or forfeit."); }
/* Forfeiting is a loss, not an escape hatch: it runs the same ending the
   fight would have had, so a ranked grade still pays for walking away. */
function forfeitDuel(d){
  /* a forfeit skips turnEnd entirely, so without this the bell never rings on a quit */
  d.forfeit=true; d.p.hp=0; d.ph=D.END; sKO(); ringBell(3);
  if(G.music) musicSwitch(G.music,"defeat",{hard:true});
  say("Match forfeited.");
  endDuel(d);
}
function duelKey(k){
  const d=G.duel; if(!d) return;
  if(d.ph===D.MENU){
    const N=FIGHT_MENU.length;
    if(k==="up"){ d.menuSel=(d.menuSel+N-1)%N; d.quitArm=0; sTick(); }
    if(k==="down"){ d.menuSel=(d.menuSel+1)%N; d.quitArm=0; sTick(); }
    if(k==="b"){ d.ph=d.retPh; sPick(); return; }
    if(k==="a"){
      if(d.menuSel===0){ d.ph=d.retPh; sPick(); }
      else if(d.menuSel===1){ G.prevScene=S.DUEL; G.howTopic="fight"; G.how=0; G.scene=S.HOW; sPick(); }
      else if(d.quitArm){ forfeitDuel(d); }
      else { d.quitArm=1; sDeny(); }
    }
    return;
  }
  if(k==="b"&&canOpenFightMenu(d)){ openFightMenu(d); return; }
  if(k==="t"||k==="tab"){
    d.turbo=!d.turbo;
    sPick();
    if(typeof FloatingFeedback!=="undefined"){
      FloatingFeedback.add(d.turbo?"TURBO MODE: ON [T]":"NORMAL SPEED [T]",W/2,190,"SYSTEM");
    }
    return;
  }
  if(d.ph===D.TAPE){
    if(k==="a"){ d.ph=D.INTRO; d.t=0; sPick(); }
    else if(k==="y"&&!d.tf&&!d.boss) openDossier(d.e.fid,S.DUEL);
    return;
  }
  /* entranceSkip slides the timeline under d.t so the bell still plays in full
     from the frame A went down. The old `d.t=999` shoved the clock past the
     end, so the bell was drawn on no frame at all and its cue fired unseen. */
  if(d.ph===D.INTRO){ if(k==="a"){ entranceSkip(d.ent,d.t); sPick(); } return; }
  /* ONE menu. Up/down walks the technique rows that are already on screen,
     left/right narrows them by category, A throws the row under the cursor.
     The corner bag is the last tab and still opens its own screen. */
  const cmdMenu=(side,next)=>{
    const tabs=cmdTabs(d,side), tab=tabs[cmdTabIx(d,side)].key;
    if(k==="left"||k==="right"){
      const n=tabs.length, step=k==="right"?1:n-1;
      d.cmdCat=(cmdTabIx(d,side)+step)%n;
      /* a new filter is a new list: start at its top rather than carrying a
         row index that meant something else */
      d.cmdSel=0; d.cmdKey=null; d.cmdScroll=0; sTick();
      const t=cmdTabs(d,side)[cmdTabIx(d,side)];
      if(side===d.p) say(t.label.replace(/[^\w\s]/g, "").trim()+" - "+t.hint+".");
      return;
    }
    if(k==="y"&&!d.hotseat&&side===d.p){
      if(d.readShown||side.focus<1){ sDeny(); return; }
      side.focus--; d.readShown=true; sFocus();
      say("Read: they are throwing "+(d.eSuper?"their signature":d.eTech.name)+".");
      return;
    }
    if(tab==="BAG"){
      if(k==="a"){
        d.ph=D.BAG; d.bagSel=0; d.t=0; sPick();
        say("Corner bag. "+(G.adv.corner||[]).map(id=>CORNER_ITEMS[id].name).join(", ")+".");
      }
      return;
    }
    const list=menuTechsFor(d,side);
    if(!list.length){ if(k==="a"||k==="1"||k==="2"||k==="3"||k==="4"||k==="5") sDeny(); return; }
    if(k==="1"||k==="2"||k==="3"||k==="4"||k==="5"){
      const num=parseInt(k,10)-1;
      if(num>=0 && (d.cmdScroll+num)<list.length){
        cmdPoint(d,side,d.cmdScroll+num,list);
        k="a"; // fall-through to commit action
      }
    }
    const ix=cmdFocus(d,side,list);
    if(k==="up"){ cmdPoint(d,side,(ix+list.length-1)%list.length,list); sTick(); return; }
    if(k==="down"){ cmdPoint(d,side,(ix+1)%list.length,list); sTick(); return; }
    if(k==="a"){
      const tech=list[ix];
      if(!tech){ sDeny(); return; }
      /* the signature is a row like any other, and it is still gated on the
         meter - SUP_MIN, not SUP_MAX: half a bar arms a weaker version */
      if(side.sig&&tech===side.sig){
        if(side.sup<SUP_MIN){ sDeny(); return; }
        if(side===d.p) d.pSuper=true; else d.eSuper=true;
        sPick(); next(); return;
      }
      if(side===d.p) d.pTech=tech; else d.eTech=tech;
      if(side===d.p&&d.lessonFight){
        d.tellGrade=gradeTell(d, tech);
        callout(d, d.tellGrade, 90);
      }
      sPick();
      // a technique that something legitimately follows opens the combination
      // menu; everything else just gets thrown
      if(side===d.p){
        d.seq=[tech];
        const opts=chainOptions(d,d.p);
        if(opts.length){ d.ph=D.CHAIN; d.chainSel=0; d.t=0;
                         say("Chain a follow-up, or throw it."); return; }
      }
      next();
    }
  };
  const lockIn=()=>{
    if(d.hotseat&&!d.eTech&&!d.eSuper){ d.ph=D.PASS; d.t=0; return; }
    buildTurn(d); d.ph=D.EXEC; d.t=0; d.qi=0; stepQueue(d);
  };
  if(d.ph===D.CMD){ cmdMenu(d.p,lockIn); return; }
  if(d.ph===D.BAG){
    const bag=(G.adv&&G.adv.corner)||[];
    if(!bag.length){ d.ph=D.CMD; return; }
    if(k==="up"){ d.bagSel=(d.bagSel+bag.length-1)%bag.length; sTick(); }
    if(k==="down"){ d.bagSel=(d.bagSel+1)%bag.length; sTick(); }
    if(k==="b"){ d.ph=D.CMD; sPick(); return; }
    if(k==="a"){ if(!useCornerItem(d,bag[d.bagSel])) sDeny(); }
    return;
  }
  /* D.TECH was the old second step, the category's own list. The list is the
     menu now, so the phase survives only as an alias - anything that still
     sets it (a save mid-turn, a test fixture) lands on the merged menu. */
  if(d.ph===D.TECH){ d.ph=D.CMD; cmdMenu(d.p,lockIn); return; }
  if(d.ph===D.CHAIN){
    const opts=chainOptions(d,d.p);
    if(k==="up"&&opts.length){ d.chainSel=(d.chainSel+opts.length-1)%opts.length; sTick(); }
    if(k==="down"&&opts.length){ d.chainSel=(d.chainSel+1)%opts.length; sTick(); }
    if(k==="b"){ commitChain(d); return; }          // throw what you have
    if(k==="y"){ d.seq=[d.seq[0]]; d.chainSel=0; sTick(); return; }   // clear back to one
    if(k==="a"){
      const pick=opts[d.chainSel];
      if(!pick){ commitChain(d); return; }
      d.seq.push(pick); sPick();
      if(d.seq.length>=seqMaxLen(d)||!chainOptions(d,d.p).length){ commitChain(d); return; }
      d.chainSel=0;
    }
    return;
  }
  if(d.ph===D.PASS){ if(k==="a"){ d.ph=D.CMD2; d.t=0; d.cmdCat=0; d.cmdSel=0; d.cmdKey=null; sPick(); } return; }
  if(d.ph===D.CMD2){ cmdMenu(d.e,lockIn); return; }
  if(d.ph===D.TECH2){ d.ph=D.CMD2; cmdMenu(d.e,lockIn); return; }
  if(d.ph===D.DEFEND){
    if((k==="b"||k==="a")&&!d.defDone){
      d.defDone=1;
      const off=Math.abs(d.t-30);
      resolveDefence(d, off<=4?0:off<=10?1:2);
    }
    return;
  }
  if(d.ph===D.SUPER){
    if(k==="a"&&(d.supFor==="p"||(d.hotseat&&d.supFor==="e"))) superBeat(d);
    return;
  }
  if(d.ph===D.JUGGLE){
    const mine=d.jugFor>0, side=mine?d.p:d.e;
    const controllable=mine||(d.hotseat&&d.jugFor<0);
    if(k==="a"&&controllable){ resolveJuggle(d,side); return; }
    if(k==="y"&&controllable&&!d.jugSlow&&side.focus>=1){ side.focus--; d.jugSlow=true; sFocus(); say("Air meter slowed."); return; }
    if(k==="y"||k==="a") sDeny();
    return;
  }
  if(d.ph===D.END){ if(k==="a") endDuel(d); return; }
}
/* superBeat() was also declared twice, the two bodies differing only by a
   `d.supHits+=0` no-op. The later declaration won; the earlier one is gone. */
function superBeat(d){
  const tier=jugTierAt(d,d.jugPos);
  if(tier>=1) d.supHits++;
  spark(d,W/2,300,tier>=1?GOLD:"#556",tier>=1?18:6);
  if(tier>=1) sHit(); else sBlock();
  d.supBeat++;
  if(d.supBeat>=3) finishSuper(d);
  else { d.jugBeat=Math.min(2,d.supBeat); nextBeat(d); d.jugSpd=3.6+d.supBeat*.9; }
}

/* ================================================================
   8. ART LOADING - never blocks the title for long
   ================================================================ */
const ART={"Akin":{"w":433,"h":640,"d":"data:image/webp;base64,"},"Kwon Won-Ri":{"w":438,"h":640,"d":"data:image/webp;base64,"},"Zhang Kai":{"w":463,"h":640,"d":"data:image/webp;base64,"},"Paul Thomas":{"w":428,"h":640,"d":"data:image/webp;base64,"},"Ry\u014dto Katou":{"w":435,"h":640,"d":"data:image/webp;base64,"},"King Yamsiri":{"w":428,"h":640,"d":"data:image/webp;base64,"},"Sanz\u014d":{"w":432,"h":640,"d":"data:image/webp;base64,"},"Mataemon Aoki":{"w":427,"h":640,"d":"data:image/webp;base64,"},"Kazushi Horiuchi":{"w":443,"h":640,"d":"data:image/webp;base64,"},"Craig Beast":{"w":427,"h":640,"d":"data:image/webp;base64,"},"Reinier Jansen":{"w":465,"h":640,"d":"data:image/webp;base64,"},"Frank Mason":{"w":443,"h":640,"d":"data:image/webp;base64,"},"Mike Takayama":{"w":489,"h":640,"d":"data:image/webp;base64,"},"Randall Stevens":{"w":438,"h":640,"d":"data:image/webp;base64,"},"Ogun Celsus":{"w":439,"h":640,"d":"data:image/webp;base64,"},"Abrafo Ocasio":{"w":349,"h":640,"d":"data:image/webp;base64,"},"Sergio Newton":{"w":289,"h":640,"d":"data:image/webp;base64,"},"Gregory Saint":{"w":440,"h":640,"d":"data:image/webp;base64,"},"Jairo Silva":{"w":442,"h":640,"d":"data:image/webp;base64,"},"Axel Vance":{"w":435,"h":640,"d":"data:image/webp;base64,"},"Derek Nichols":{"w":425,"h":640,"d":"data:image/webp;base64,"},"Tyson Reed":{"w":459,"h":640,"d":"data:image/webp;base64,"},"Roland Finch":{"w":443,"h":640,"d":"data:image/webp;base64,"},"Ruslan Magomedov":{"w":427,"h":640,"d":"data:image/webp;base64,"},"Timur Akhmedov":{"w":439,"h":640,"d":"data:image/webp;base64,"}};
const IMGS={}; let loadedN=0, loadTotal=0;
for(const name in ART){ loadTotal++;
  const im=new Image();
  try{ im.decoding="async"; }catch(e){}
  im.onload=()=>{loadedN++;}; im.onerror=()=>{loadedN++;};
  im.src=ART[name].d; IMGS[name]=im;
}
function artOf(fid){ return IMGS[FIGHTERS[fid].name]; }
const artReady=()=>loadedN>=loadTotal;

/* The Luminara Digital AZ mark. Kept out of the fighter-art count on purpose -
   the boot screen must be able to show the brand before anything else decodes.
   Written here by tools/embed-logo.js; the wordmark carries the screen alone
   if the slot is empty. */
const LOGO_SRC="data:image/png;base64,";
/* The arena render - the ring the whole game is fought in. Embedded by
   tools/embed-arena.js; an empty slot falls back to the flat gradient. */
const ARENA_SRC="data:image/png;base64,";
const ARENA=new Image();
if(ARENA_SRC){ try{ ARENA.decoding="async"; }catch(e){} ARENA.src=ARENA_SRC; }
const arenaReady=()=>!!ARENA_SRC&&ARENA.complete&&ARENA.naturalWidth>0;
const LOGO=new Image();
if(LOGO_SRC){ try{ LOGO.decoding="async"; }catch(e){} LOGO.src=LOGO_SRC; }
const logoReady=()=>!!LOGO_SRC&&LOGO.complete&&LOGO.naturalWidth>0;

/* ================================================================
   9. RENDER - 960x540
   ================================================================ */
const W=960,H=540, cv=document.getElementById("s"), cx=cv.getContext("2d");
/* Authored coordinates are 960x540 and every draw call in this file stays in
   that space. The BACKING STORE is not: the page shows the canvas at whatever
   width the column gives it (792px on a 1.0 laptop - a 0.825x downscale that
   turned every 10.5px label into 8.7px of mush). Scale the backing store by
   the device pixel ratio and pre-multiply the context by the same factor, so
   nothing moves and everything resolves. The test harness has no window.
   devicePixelRatio at all, hence the guard - and never a divide. */
let DPR=1;
function canvasDpr(){
  const r=(typeof window!=="undefined"&&window)?window.devicePixelRatio:undefined;
  const n=Number(r);
  if(!n||!isFinite(n)||n<=0) return 1;
  return Math.min(4,Math.max(1,n));
}
function syncBackingStore(){
  const d=canvasDpr();
  const bw=Math.round(W*d), bh=Math.round(H*d);
  if(typeof Interactive3DBG!=="undefined"&&typeof window!=="undefined"&&window.innerWidth&&window.innerHeight){
    Interactive3DBG.resize(window.innerWidth, window.innerHeight, d);
  }
  if(typeof ThreeEngine!=="undefined"&&typeof window!=="undefined"&&window.innerWidth&&window.innerHeight){
    ThreeEngine.resize(window.innerWidth, window.innerHeight, d);
  }
  if(DPR===d&&cv.width===bw&&cv.height===bh) return;
  DPR=d;
  cv.width=bw; cv.height=bh;              // resizing clears it; render redraws
  cx.setTransform(DPR,0,0,DPR,0,0);
}
syncBackingStore();
if(typeof addEventListener==="function") addEventListener("resize",syncBackingStore);
/* A PHONE GETS THE THUMB PAD WITHOUT ASKING. The pad was opt-in behind an
   Options row, which a phone player could only reach by navigating a menu with
   the controls they did not have. If the device says its pointer is coarse,
   the pad is the primary input and it comes up on its own; a save that has
   turned it off is still honoured. */
function syncTouchControls(){
  if(typeof VirtualGamepad==="undefined") return;
  const coarse=(typeof matchMedia==="function"&&matchMedia("(pointer:coarse)").matches)
             ||(typeof navigator!=="undefined"&&navigator.maxTouchPoints>0);
  const want=(SAVE&&SAVE.touchHud!==undefined)?!!SAVE.touchHud:coarse;
  try{ VirtualGamepad.setVisible(want); }catch(e){}
  try{ document.body.classList.toggle("touch-pad",want); }catch(e){}
}
const RED="#e6392f", GOLD="#f59e0b", INK="#f3f4f6", DIM="#9ca3af", GRN="#10b981", BLU="#38bdf8";
/* Luminara Digital brand ramp, taken off the AZ mark: cyan crown, navy foot.
   The arena itself stays red - the brand owns the boot, the fight owns the rest. */
const AQUA="#22d3ee", AQUA_DK="#0ea5e9", NAVY="#0b2545";
function bgFill(c1,c2){
  const g=cx.createLinearGradient(0,0,0,H); g.addColorStop(0,c1); g.addColorStop(1,c2);
  cx.fillStyle=g; cx.fillRect(0,0,W,H);
}
function txt(s,x,y,size,color,align,weight,italic,fontFamily){
  const ff = fontFamily || "'Rajdhani','Teko','Orbitron','Bahnschrift','Segoe UI Variable',system-ui,sans-serif";
  cx.font=(italic?"italic ":"")+(weight||700)+" "+size+"px "+ff;
  cx.textAlign=align||"left"; cx.textBaseline="alphabetic";
  cx.fillStyle=color||INK; cx.fillText(String(s).toUpperCase(),x,y);
}
function panel(x,y,w,h,fill,stroke,glow,radius){
  const r=radius||8;
  cx.save();
  if(glow&&motionOn()){ cx.shadowColor=glow; cx.shadowBlur=14; }
  if(typeof Path2D!=="undefined"){
    const p=new Path2D();
    p.moveTo(x+r,y); p.lineTo(x+w-r,y); p.arcTo(x+w,y,x+w,y+r,r);
    p.lineTo(x+w,y+h-r); p.arcTo(x+w,y+h,x+w-r,y+h,r);
    p.lineTo(x+r,y+h); p.arcTo(x,y+h,x,y+h-r,r);
    p.lineTo(x,y+r); p.arcTo(x,y,x+r,y,r); p.closePath();
    cx.fillStyle=fill||"rgba(14,17,24,.92)"; cx.fill(p);
    cx.strokeStyle=stroke||"#2a3142"; cx.lineWidth=1; cx.stroke(p);
  }else{
    cx.fillStyle=fill||"rgba(14,17,24,.92)"; cx.fillRect(x,y,w,h);
    cx.strokeStyle=stroke||"#2a3142"; cx.lineWidth=1; cx.strokeRect(x+.5,y+.5,w-1,h-1);
  }
  // glass top shine line
  cx.fillStyle="rgba(255,255,255,.05)";
  cx.fillRect(x+r,y+1,Math.max(0,w-2*r),1);
  cx.restore();
}
/* Patrols used to paint the borrowed fighter with brightness(0), which
   read as a dead black silhouette next to a lit player. The name stays
   AZX FORCE. The body is the borrowed art, lit the same way the player is.
   Art is embedded, so this holds on file:// and on a local server. */
function ringSilhouette(){ return false; }
function drawFighterArt(fid,cxr,baseY,maxH,flip,silhouette,alpha,flash,rot){
  if(isCustomFighter(fid)){
    const sz = Math.min(maxH * 0.55, 180);
    drawCustomPortrait(fid, cxr - sz/2, baseY - sz, sz, sz);
    return;
  }
  const im=artOf(fid); if(!im||!im.complete||!im.naturalWidth) return;
  const r=Math.min(maxH/im.naturalHeight, 420/im.naturalWidth);
  const w=im.naturalWidth*r, h=im.naturalHeight*r;
  const venue=(G.duel&&G.duel.venue)||G.titleVenue||null;
  const grade=(typeof fighterGradeFilter==="function")?fighterGradeFilter(venue):null;

  /* ground mat reflection beneath fighter on arena floor */
  if(typeof cx.drawImage==="function"&&!silhouette&&baseY>=350){
    cx.save();
    cx.globalAlpha=(alpha!==undefined?alpha:1)*0.20;
    cx.translate(cxr,baseY);
    if(flip) cx.scale(-1,1);
    cx.scale(1,-0.36);
    if(rot){ const rr=flip?-rot:rot; cx.translate(0,-h*.45); cx.rotate(rr); cx.translate(0,h*.45); }
    if(grade) cx.filter=grade;
    cx.drawImage(im,-w/2,-h,w,h);
    cx.restore();
  }

  /* contact shadow + mat rim sit under the feet so fighters belong to the floor */
  if(typeof paintContactShadow==="function"&&!silhouette){
    paintContactShadow(cx, cxr, baseY-2, Math.max(48,w*0.42), (alpha!==undefined?alpha:1)*0.65);
    if(venue&&typeof paintMatRim==="function")
      paintMatRim(cx, cxr, baseY-2, venue.rim||"rgba(34,211,238,.20)", (alpha!==undefined?alpha:1)*0.75);
  }

  /* dynamic colored rim-lighting glow behind silhouette */
  if(!silhouette&&venue&&venue.rim){
    cx.save();
    cx.globalCompositeOperation="screen";
    cx.globalAlpha=(alpha!==undefined?alpha:1)*0.22;
    cx.shadowColor=(venue.rim||"rgba(34,211,238,.35)").replace("$A","0.65");
    cx.shadowBlur=16;
    cx.translate(cxr,baseY);
    if(flip) cx.scale(-1,1);
    if(rot){ const rr=flip?-rot:rot; cx.translate(0,-h*.45); cx.rotate(rr); cx.translate(0,h*.45); }
    cx.drawImage(im,-w/2,-h,w,h);
    cx.restore();
  }

  cx.save();
  cx.globalAlpha=alpha!==undefined?alpha:1;
  if(silhouette) cx.filter="brightness(0) opacity(0.85)";
  else if(flash > 8 && motionOn()) cx.filter="brightness(10) saturate(0)";
  else if(flash) cx.filter="brightness("+(1+flash*.14)+") saturate(1.3)"+(grade?" "+grade:"");
  else if(grade) cx.filter=grade;
  cx.translate(cxr,baseY);
  if(flip) cx.scale(-1,1);
  if(rot){ const rr=flip?-rot:rot;
           cx.translate(0,-h*.45); cx.rotate(rr); cx.translate(0,h*.45); }
  cx.drawImage(im,-w/2,-h,w,h);
  cx.restore();
  cx.filter="none";
}
function drawPortrait(fid,x,y,w,h,silhouette){
  if(isCustomFighter(fid)){ drawCustomPortrait(fid,x,y,w,h); return; }
  const im=artOf(fid); if(!im||!im.complete||!im.naturalWidth) return;
  const nw=im.naturalWidth, nh=im.naturalHeight;
  const side=Math.min(nw, nh*0.62);
  const sx=(nw-side)/2, sy=Math.min(nh*0.02, nh-side);
  cx.save();
  if(silhouette) cx.filter="brightness(0) opacity(0.85)";
  cx.drawImage(im, sx, sy, side, side, x, y, w, h);
  cx.restore(); cx.filter="none";
}
function hpBar(x,y,w,cur,max,alignR,ghost){
  panel(x,y,w,18,"#080a10","#1f2430",null,5);
  // dual-stage ghost damage trail (yellow fast flash + red sustained loss)
  if(ghost!==undefined&&ghost>cur+.5){
    const fg=Math.max(0,(w-4)*ghost/max);
    // Yellow fast impact trail
    cx.fillStyle="rgba(251,191,36,.65)";
    cx.fillRect(alignR?x+2+(w-4-fg):x+2, y+2, fg, 14);
    // Red sustained damage trail
    const fMid=Math.max(0,(w-4)*(cur+(ghost-cur)*0.6)/max);
    cx.fillStyle="rgba(230,57,47,.75)";
    cx.fillRect(alignR?x+2+(w-4-fMid):x+2, y+2, fMid, 14);
  }
  const f=Math.max(0,(w-4)*cur/max);
  const g=cx.createLinearGradient(0,y,0,y+18);
  if(cur>max*.45){
    g.addColorStop(0,"#67e8f9"); g.addColorStop(0.35,"#22d3ee"); g.addColorStop(1,"#0284c7");
  } else if(cur>max*.22){
    g.addColorStop(0,"#fde047"); g.addColorStop(0.4,"#f59e0b"); g.addColorStop(1,"#b45309");
  } else {
    const pulse=motionOn()?Math.sin(G.t/5)*0.15:0;
    g.addColorStop(0,"#ff8a80"); g.addColorStop(0.4,"#ef4444"); g.addColorStop(1,"#991b1b");
  }
  cx.fillStyle=g;
  cx.fillRect(alignR?x+2+(w-4-f):x+2, y+2, f, 14);
  // segment divider notches (every 20%)
  cx.fillStyle="rgba(0,0,0,.45)";
  for(let s=1;s<5;s++){
    const nx=x+2+Math.round((w-4)*s/5);
    cx.fillRect(nx,y+2,1.5,14);
  }
  // top glass shine
  cx.fillStyle="rgba(255,255,255,.22)";
  cx.fillRect(alignR?x+2+(w-4-f):x+2, y+2, f, 5);
}
function supBar(x,y,w,side,alignR){
  const full=side.sup>=SUP_MAX, armed=side.sup>=SUP_MIN, blink=(G.t/8|0)%2;
  panel(x,y,w,8,"#080a10","#1f2430",null,4);
  const fr=Math.max(0,(w-2)*Math.min(1,side.sup/SUP_MAX));
  const sg=cx.createLinearGradient(0,y,0,y+8);
  if(full){
    sg.addColorStop(0,blink?"#fef08a":"#f59e0b"); sg.addColorStop(0.5,"#fbbf24"); sg.addColorStop(1,blink?"#f59e0b":"#b45309");
  } else if(armed){
    sg.addColorStop(0,"#fde047"); sg.addColorStop(1,"#92400e");
  } else {
    sg.addColorStop(0,"#64748b"); sg.addColorStop(1,"#334155");
  }
  cx.fillStyle=sg;
  cx.fillRect(alignR?x+1+(w-2-fr):x+1, y+1, fr, 6);
  /* the half-bar gate notch */
  const nx=alignR?x+1+(w-2)*(1-SUP_MIN/SUP_MAX):x+1+(w-2)*(SUP_MIN/SUP_MAX);
  cx.fillStyle=armed?"#090b10":"#d97706"; cx.fillRect(nx,y+1,1.5,6);
  // top glass shine
  cx.fillStyle="rgba(255,255,255,.22)";
  cx.fillRect(alignR?x+1+(w-2-fr):x+1, y+1, fr, 2.5);
  if(armed) txt(full?"SIGNATURE READY - FULL":"SIGNATURE READY - HALF",
                alignR?x+w:x,y+20,9,blink?GOLD:"#d97706",alignR?"right":"left",800);
}
function focusPips(x,y,side,alignR){
  const n=side.focusMax, r=6, gap=16;
  for(let i=0;i<n;i++){
    const px=alignR?x-i*gap:x+i*gap;
    cx.beginPath(); cx.arc(px,y,r,0,Math.PI*2);
    if(i<side.focus){
      const fg=cx.createRadialGradient(px-1,y-1,1,px,y,r);
      fg.addColorStop(0,"#fef08a"); fg.addColorStop(0.5,"#f59e0b"); fg.addColorStop(1,"#b45309");
      cx.fillStyle=fg; cx.fill();
      cx.strokeStyle="rgba(254,240,138,.6)"; cx.lineWidth=1; cx.stroke();
    } else {
      cx.fillStyle="#151922"; cx.fill();
      cx.strokeStyle="#333a4c"; cx.lineWidth=1; cx.stroke();
    }
  }
}
function cardFace(x,y,w,h,card,hi,faceDown,dimmed){
  cx.save();
  const r=8;
  if(hi){
    cx.shadowColor="rgba(230,57,47,.65)"; cx.shadowBlur=18;
    panel(x,y,w,h,"#1a1014",RED,"rgba(230,57,47,.35)",r);
  } else {
    panel(x,y,w,h,"#11141c","#262c3b",null,r);
  }
  cx.restore();
  if(faceDown||!card){
    cx.fillStyle="#161922"; cx.fillRect(x+6,y+6,w-12,h-12);
    txt("AZX",x+w/2,y+h/2+8,22,"#2d3340","center",900,true);
    return;
  }
  const kind=kindOf(card), sub=subOf(card);
  const isL=isLauncher(card);
  const kc=kind==="STRIKE"?(isL?GOLD:"#f87171"):kind==="THROW"?BLU:GRN;
  // card top category banner
  cx.fillStyle="rgba(255,255,255,.04)"; cx.fillRect(x+4,y+4,w-8,22);
  txt(kind==="GUARD"?sub:(isL?"LAUNCHER":kind),x+8,y+19,11,kc,"left",800);
  if(card[0]>0){
    txt(card[0],x+w/2,y+h/2+18,44,dimmed?"#555d6e":INK,"center",900);
  } else {
    txt("-",x+w/2,y+h/2+14,36,"#555d6e","center",800);
  }
  const hgt=heightOf(card);
  if(hgt) txt(hgt,x+8,y+h-10,10,DIM,"left",700);
  if(card[2]&F_UNBLK){
    cx.fillStyle="rgba(230,57,47,.2)"; cx.fillRect(x+w-76,y+6,70,16);
    txt("UNBLOCK",x+w-41,y+18,8.5,RED,"center",800);
  }
  if(card[2]&F_CTR){
    cx.fillStyle="rgba(245,158,11,.2)"; cx.fillRect(x+w-46,y+h-22,40,16);
    txt("CTR+",x+w-26,y+h-10,9,GOLD,"center",800);
  }
}

/* ---------- screens ---------- */
function drawLogo(cxr,cyr,h,glow,alpha){
  if(!logoReady()) return false;
  const r=h/LOGO.naturalHeight, w=LOGO.naturalWidth*r;
  cx.save();
  cx.globalAlpha=alpha===undefined?1:alpha;
  if(glow&&motionOn()){ cx.shadowColor="rgba(34,211,238,.85)"; cx.shadowBlur=glow; }
  else if(glow){ cx.shadowColor="rgba(34,211,238,.6)"; cx.shadowBlur=glow*.6; }
  cx.drawImage(LOGO,cxr-w/2,cyr-h/2,w,h);
  cx.restore();
  return true;
}
function rLoad(){
  bgFill("#080c14","#040609");
  const my=H/2-66, f=loadTotal?loadedN/loadTotal:1;
  const breathe=motionOn()?Math.sin(G.t/26)*4:0;
  // ambient background motes
  if(motionOn()){
    cx.save();
    for(let i=0;i<18;i++){
      const px=(i*127+G.t*0.6)%W, py=(H - ((i*83+G.t*0.8)%(H+20)));
      const sz=1+(i%3)*0.8, al=0.15+Math.sin(G.t/20+i)*0.1;
      cx.fillStyle="rgba(34,211,238,"+al+")";
      cx.fillRect(px,py,sz,sz);
    }
    cx.restore();
  }
  // aura behind the mark
  const g=cx.createRadialGradient(W/2,my,10,W/2,my,220);
  g.addColorStop(0,"rgba(34,211,238,.24)"); g.addColorStop(.5,"rgba(14,165,233,.09)");
  g.addColorStop(1,"rgba(11,37,69,0)");
  cx.fillStyle=g; cx.fillRect(W/2-220,my-220,440,440);
  if(!drawLogo(W/2,my+breathe,150,28)){
    txt("AZ",W/2,my+24+breathe,88,AQUA,"center",900,true);
  }
  txt("AQUA ZERO",W/2,H/2+108,42,INK,"center",900,true);
  txt("HEAVENS ARENA",W/2,H/2+134,19,AQUA,"center",800);
  // progress runs the brand ramp, cyan crown to navy foot
  const bw=340, bx=W/2-bw/2, by=H/2+164;
  panel(bx,by,bw,10,"rgba(8,14,24,.95)","#1f364d",null,5);
  const pg=cx.createLinearGradient(bx,0,bx+bw,0);
  pg.addColorStop(0,AQUA); pg.addColorStop(1,AQUA_DK);
  cx.fillStyle=pg; cx.fillRect(bx+1,by+1,(bw-2)*f,8);
  txt(artReady()?"SYSTEM READY":"LOADING FIGHTER ROSTER "+loadedN+" / "+loadTotal,W/2,by+28,11,"#738598","center",700);
  txt("LUMINARA DIGITAL \u00B7 AZX LEAGUE",W/2,H-24,10,"#475b6e","center",700);
}
function artNote(){ // art keeps streaming in behind the title - say so quietly
  if(artReady()) return;
  txt("STREAMING ART "+loadedN+"/"+loadTotal,W-14,H-10,9.5,"#4a5160","right",600);
}
function drawTitleDifficultyBar(cxPos, cyPos){
  const cur = diff();
  const curIdx = SAVE.diff || 0;
  const totalW = 380, h = 26;
  const startX = cxPos - totalW/2;

  // Background track
  cx.save();
  cx.fillStyle = "rgba(10, 14, 22, 0.75)";
  cx.strokeStyle = "rgba(34, 211, 238, 0.25)";
  cx.lineWidth = 1;
  if(typeof cx.roundRect === "function"){
    cx.beginPath(); cx.roundRect(startX, cyPos - 13, totalW, h, 6); cx.fill(); cx.stroke();
  } else {
    cx.fillRect(startX, cyPos - 13, totalW, h);
    cx.strokeRect(startX, cyPos - 13, totalW, h);
  }

  // Render clickable tier items
  const tabW = totalW / DIFFS.length;
  for(let i = 0; i < DIFFS.length; i++){
    const d = DIFFS[i];
    const tx = startX + i * tabW;
    const isAct = (i === curIdx);
    const col = d.color || GOLD;

    if(isAct){
      cx.save();
      const activeGrad = cx.createLinearGradient(tx + 2, cyPos - 11, tx + 2, cyPos + 11);
      activeGrad.addColorStop(0, "rgba(255,255,255,0.12)");
      activeGrad.addColorStop(1, "rgba(255,255,255,0.02)");
      cx.fillStyle = activeGrad;
      if(typeof cx.roundRect === "function"){
        cx.beginPath(); cx.roundRect(tx + 2, cyPos - 11, tabW - 4, h - 4, 4); cx.fill();
      } else {
        cx.fillRect(tx + 2, cyPos - 11, tabW - 4, h - 4);
      }
      cx.fillStyle = col;
      cx.shadowColor = col;
      cx.shadowBlur = 8;
      cx.fillRect(tx + 4, cyPos + 9, tabW - 8, 2.5);
      cx.restore();
      txt(d.name, tx + tabW/2, cyPos + 4, 11, col, "center", 900, false, "'Orbitron','Rajdhani',sans-serif");
    } else {
      txt(d.name, tx + tabW/2, cyPos + 4, 10, "rgba(156,163,175,0.55)", "center", 700, false, "'Rajdhani',sans-serif");
    }

    G.hot.push({ x: tx, y: cyPos - 13, w: tabW, h: h, click: () => { SAVE.diff = i; persist(); if(typeof sPick==="function") sPick(); } });
  }

  // Chevrons
  txt("\u25c0", startX - 12, cyPos + 4, 11, "rgba(34,211,238,0.75)", "center", 800);
  txt("\u25b6", startX + totalW + 12, cyPos + 4, 11, "rgba(34,211,238,0.75)", "center", 800);
  G.hot.push({ x: startX - 24, y: cyPos - 13, w: 22, h: h, click: () => { cycleDifficulty(-1); } });
  G.hot.push({ x: startX + totalW + 2, y: cyPos - 13, w: 22, h: h, click: () => { cycleDifficulty(1); } });
  cx.restore();
}

function rTitle(){
  G.titleVenue=(typeof pickVenue==="function")?pickVenue({mode:"title",stage:1}):null;
  const spotX=(G.mx!==undefined&&G.mx>0)?G.mx:W/2;

  // 1. Full-Bleed Atmospheric Backdrop & Volumetric Lighting
  if(typeof ThreeEngine!=="undefined"&&ThreeEngine.getState().initialized){
    ThreeEngine.setActiveScene("background");
  } else if(typeof paintTitleAtmosphere==="function")
    paintTitleAtmosphere(cx,W,H,G.titleVenue||"club",{crowdA:0.10,spot:{x:spotX,r:280,pulse:0.20},t:(motionOn()?G.t/60:0)});
  else {
    bgFill("#07090e","#040507");
    cx.save(); cx.globalAlpha=.09; cx.fillStyle="#fff";
    cx.beginPath(); cx.moveTo(180,0); cx.lineTo(430,H); cx.lineTo(80,H); cx.closePath(); cx.fill();
    cx.beginPath(); cx.moveTo(780,0); cx.lineTo(900,H); cx.lineTo(560,H); cx.closePath(); cx.fill();
    cx.restore();
  }

  // 2. Dual-Layer Atmospheric Dust & Drifting Neon Embers
  if(motionOn()){
    cx.save();
    for(let i=0;i<36;i++){
      const px=(i*137+G.t*(0.4+0.3*(i%3)))%W;
      const py=(H - ((i*83+G.t*(0.6+0.2*(i%2)))%(H+30)));
      const sz=1.0+(i%3)*0.8;
      const al=0.15+Math.sin(G.t/20+i*1.1)*0.10;
      cx.fillStyle=(i%3===0)?"rgba(34,211,238,"+al+")":(i%3===1)?"rgba(245,158,11,"+al+")":"rgba(230,57,47,"+al+")";
      cx.beginPath();
      cx.arc(px,py,sz,0,Math.PI*2);
      cx.fill();
    }
    cx.restore();
  }

  // 3. Dynamic Scaling, Idle Breathing & Fighter Framing
  const heroFid=(typeof Interactive3DBG!=="undefined")?Interactive3DBG.getState().fighterId:0;
  const rivalFid=(heroFid+1)%FIGHTERS.length;
  const breath = motionOn() ? Math.sin(G.t / 22) * 3.5 : 0;
  const breathScale = motionOn() ? 1 + Math.sin(G.t / 22) * 0.012 : 1;

  // Render Rival on Left (Scale ~540px, cropped below knee, imposing stance)
  cx.save();
  cx.translate(220, 570 + breath);
  cx.scale(breathScale, breathScale);
  drawFighterArt(rivalFid, 0, 0, 540, true, false, 0.92);
  cx.restore();

  // 4. Interactive Click Areas for Cycling Roster
  G.hot.push({ x: 30, y: 80, w: 340, h: 460, click: () => { if(typeof Interactive3DBG!=="undefined"){ Interactive3DBG.prevFighter(); if(typeof sPick==="function") sPick(); if(typeof syncShowcaseBar==="function") syncShowcaseBar(); } } });
  G.hot.push({ x: 590, y: 80, w: 340, h: 460, click: () => { if(typeof Interactive3DBG!=="undefined"){ Interactive3DBG.nextFighter(); if(typeof sPick==="function") sPick(); if(typeof syncShowcaseBar==="function") syncShowcaseBar(); } } });

  // 5. Center Title Branding & Layered Typographic Depth
  const tgGlow = cx.createRadialGradient(W/2, 175, 20, W/2, 175, 340);
  tgGlow.addColorStop(0, "rgba(230,57,47,0.18)");
  tgGlow.addColorStop(0.5, "rgba(34,211,238,0.08)");
  tgGlow.addColorStop(1, "rgba(0,0,0,0)");
  cx.fillStyle = tgGlow;
  cx.fillRect(W/2-360, 40, 720, 270);

  // Tournament Top Header
  txt("AZX HEAVENS TOURNAMENT \u00B7 OFFICIAL BROADCAST", W/2, 118, 12.5, "rgba(34,211,238,0.9)", "center", 800, false, "'Rajdhani','Orbitron',sans-serif");

  // Bold Metallic Title Typography (AQUA ZERO)
  cx.save();
  cx.shadowColor = "rgba(230,57,47,0.65)";
  cx.shadowBlur = 24;
  const titleGrad = cx.createLinearGradient(0, 130, 0, 210);
  titleGrad.addColorStop(0, "#ffffff");
  titleGrad.addColorStop(0.35, "#ff6b61");
  titleGrad.addColorStop(0.7, "#e6392f");
  titleGrad.addColorStop(1, "#8a140e");
  cx.fillStyle = titleGrad;
  cx.font = "900 88px 'Teko','Impact','Orbitron','Bahnschrift',sans-serif";
  cx.textAlign = "center";
  cx.textBaseline = "alphabetic";
  cx.fillText("AQUA ZERO", W/2, 198);
  cx.shadowBlur = 0;
  cx.strokeStyle = "rgba(255,255,255,0.4)";
  cx.lineWidth = 1.5;
  cx.strokeText("AQUA ZERO", W/2, 198);
  cx.restore();

  // Subtitle (HEAVENS ARENA)
  cx.save();
  cx.shadowColor = "rgba(34,211,238,0.5)";
  cx.shadowBlur = 14;
  txt("HEAVENS ARENA", W/2, 238, 32, "#f3f4f6", "center", 900, false, "'Orbitron','Rajdhani',sans-serif");
  cx.restore();

  txt("A LUMINARA DIGITAL FIGHTING CARD GAME", W/2, 262, 11, "rgba(156,163,175,0.85)", "center", 700, false, "'Rajdhani',sans-serif");

  // 6. Stylized Central "VS" Emblem with Neon Wing Accents
  cx.save();
  const vsX = W/2, vsY = 300;
  const wingL = cx.createLinearGradient(vsX-80, vsY, vsX-16, vsY);
  wingL.addColorStop(0, "rgba(34,211,238,0)"); wingL.addColorStop(1, "rgba(34,211,238,0.75)");
  cx.strokeStyle = wingL; cx.lineWidth = 2;
  cx.beginPath(); cx.moveTo(vsX-80, vsY); cx.lineTo(vsX-22, vsY); cx.stroke();

  const wingR = cx.createLinearGradient(vsX+16, vsY, vsX+80, vsY);
  wingR.addColorStop(0, "rgba(230,57,47,0.75)"); wingR.addColorStop(1, "rgba(230,57,47,0)");
  cx.strokeStyle = wingR; cx.lineWidth = 2;
  cx.beginPath(); cx.moveTo(vsX+22, vsY); cx.lineTo(vsX+80, vsY); cx.stroke();

  cx.fillStyle = "rgba(10,14,22,0.92)";
  cx.beginPath();
  cx.arc(vsX, vsY, 18, 0, Math.PI*2);
  cx.fill();
  cx.strokeStyle = "rgba(255,255,255,0.25)";
  cx.lineWidth = 1;
  cx.stroke();
  txt("VS", vsX, vsY+6, 14, "#fbbf24", "center", 900, true, "'Orbitron','Impact',sans-serif");
  cx.restore();

  // 7. Layer Hero Fighter in Front on Right (Scale ~560px, cropped below knee, overlapping title edge)
  cx.save();
  cx.translate(740, 570 - breath);
  cx.scale(breathScale, breathScale);
  drawFighterArt(heroFid, 0, 0, 560, false, false, 1.0);
  cx.restore();

  // 8. Integrated Branded Difficulty Selector (Underneath Title/VS, No Boxy Frame)
  drawTitleDifficultyBar(W/2, 342);

  // 9. High-Impact Arcade Action Prompt
  const pulseA = motionOn() ? (0.85 + 0.15 * Math.sin(G.t / 14)) : 1.0;
  cx.save();
  const bannerW = 280, bannerH = 40, bannerX = W/2 - bannerW/2, bannerY = 416;
  const btnGrad = cx.createLinearGradient(bannerX, bannerY, bannerX + bannerW, bannerY + bannerH);
  btnGrad.addColorStop(0, "rgba(22, 28, 42, 0.92)");
  btnGrad.addColorStop(0.5, "rgba(14, 18, 30, 0.96)");
  btnGrad.addColorStop(1, "rgba(22, 28, 42, 0.92)");
  cx.fillStyle = btnGrad;
  cx.shadowColor = "rgba(34,211,238," + (0.35 * pulseA).toFixed(2) + ")";
  cx.shadowBlur = 18;

  cx.beginPath();
  cx.moveTo(bannerX + 12, bannerY);
  cx.lineTo(bannerX + bannerW - 12, bannerY);
  cx.lineTo(bannerX + bannerW, bannerY + bannerH);
  cx.lineTo(bannerX, bannerY + bannerH);
  cx.closePath();
  cx.fill();

  cx.strokeStyle = "rgba(34,211,238," + (0.65 * pulseA).toFixed(2) + ")";
  cx.lineWidth = 1.5;
  cx.stroke();

  cx.fillStyle = "rgba(255,255,255,0.15)";
  cx.fillRect(bannerX + 16, bannerY + 1, bannerW - 32, 1);

  txt("[ ENTER ]", bannerX + 48, bannerY + 25, 14, "#67e8f9", "center", 900, false, "'Orbitron','Teko',sans-serif");
  txt("START FIGHT", bannerX + bannerW/2 + 28, bannerY + 26, 17, "#ffffff", "center", 800, false, "'Teko','Rajdhani',sans-serif");
  cx.restore();

  /* These two called sStart() and openHowToPlay(), neither of which has ever
     existed in this codebase - so the biggest button on the front screen took
     a click, showed a pointer cursor, and did nothing. The pointer handler
     returns as soon as a region owns the press, so the dead handler also ate
     the click that would otherwise have fallen through to "press A". */
  G.hot.push({ x: bannerX, y: bannerY, w: bannerW, h: bannerH, click: () => onKey("a") });

  // 10. Secondary Action Prompt & Progress Status
  txt(LGJ(LG("a","START"),LG("b","HOW TO PLAY"),LG("diff","DIFFICULTY")), W/2, 474, 12, "rgba(156,163,175,0.8)", "center", 700, false, "'Rajdhani',sans-serif");
  G.hot.push({ x: W/2-180, y: 460, w: 360, h: 22, click: () => onKey("b") });

  const rk=myRanking();
  /* SAVE.unlocked starts as STARTERS - the three fighters every save is handed -
     so the only visible progress bar in the game opened at 3/25 MASTERED before
     the player had thrown a punch, and the three tiles that looked finished
     were the three they were supposed to start with. Mastery is SAVE.mastery. */
  const progText = rosterMasteredLabel()+" FIGHTERS MASTERED" + ((SAVE.rec.ngplus||0)?"   \u00B7   NG+ "+SAVE.rec.ngplus:"");
  txt(progText, W/2, 502, 11, "rgba(156,163,175,0.65)", "center", 700, false, "'Rajdhani',sans-serif");

  if(rk.totalMatches) txt(rk.rank.title.toUpperCase()+"   \u00B7   "+rk.promotionPoints+" PTS", W/2, 522, 12, rk.rank.color, "center", 800, false, "'Rajdhani',sans-serif");
  else if(SAVE.run&&SAVE.run.adv) txt("RUN IN PROGRESS \u00B7 STAGE "+SAVE.run.adv.stage, W/2, 522, 11.5, GOLD, "center", 700, false, "'Rajdhani',sans-serif");

  artNote();
}

function rTitleBackdrop(){
  G.titleVenue=(typeof pickVenue==="function")?pickVenue({
    mode:"menu",
    stage:(G.adv&&G.adv.stage)||1,
    ogre:!!(G.adv&&G.adv.map&&G.adv.map.ogre)
  }):null;
  const spotX=(G.mx!==undefined&&G.mx>0)?(W*0.3+G.mx*0.4):(W*0.72);
  if(typeof paintTitleAtmosphere==="function")
    paintTitleAtmosphere(cx,W,H,G.titleVenue||"club",{crowdA:0.06,spot:{x:spotX,r:200,pulse:0.10},t:(motionOn()?G.t/60:0)});
  else bgFill("#0d1017","#07080a");
  const heroFid=(typeof Interactive3DBG!=="undefined")?Interactive3DBG.getState().fighterId:0;
  drawFighterArt(heroFid, 750, 540, 400, false, false, .28);
  drawFighterArt((heroFid+2)%FIGHTERS.length, 190, 540, 360, true, false, .25);
  txt("AQUA ZERO",W/2,74,40,RED,"center",900,true);
  txt("HEAVENS ARENA",W/2,98,17,INK,"center",800);
}

/* Solid frosted acrylic backdrop for modals so underlying title/map/sprites never bleed through */
function paintFrostedModalBackdrop(cx, W, H, title, subtitle, accentColor) {
  cx.fillStyle = "#07090e";
  cx.fillRect(0, 0, W, H);

  var col = accentColor || "rgba(34, 211, 238, 0.08)";
  var g1 = cx.createRadialGradient(W / 2, 0, 20, W / 2, 0, 520);
  g1.addColorStop(0, col);
  g1.addColorStop(1, "rgba(7, 9, 14, 0)");
  cx.fillStyle = g1;
  cx.fillRect(0, 0, W, H);

  var g2 = cx.createLinearGradient(0, H - 60, 0, H);
  g2.addColorStop(0, "rgba(0, 0, 0, 0)");
  g2.addColorStop(1, "rgba(0, 0, 0, 0.5)");
  cx.fillStyle = g2;
  cx.fillRect(0, H - 60, W, 60);

  if (title) {
    txt(title, W / 2, 46, 26, accentColor || GOLD, "center", 800, true);
  }
  if (subtitle) {
    txt(subtitle, W / 2, 68, 10.5, DIM, "center", 600);
  }
}

function fitMenuDesc(desc, budget) {
  var s = String(desc || "").toUpperCase();
  cx.font = "600 9.5px Bahnschrift,'Segoe UI Variable','Segoe UI',system-ui,sans-serif";
  if (cx.measureText(s).width <= budget) return s;
  while (s.length > 4 && cx.measureText(s + "...").width > budget) {
    s = s.slice(0, -1);
  }
  return s + "...";
}

/* The highlighted mode answers "where do I stand in this one?" with the save's
   own numbers. A list of thirteen labels reads like a debug menu; the same
   list with a live figure beside it reads like a front end. */
function menuPreview(key){
  const rec=SAVE.rec||{}, run=SAVE.run&&SAVE.run.adv;
  if(key==="cont"&&run) return ["THE RUN SO FAR", "STAGE "+run.stage, FIGHTERS[run.hero].name+" - LEVEL "+run.level];
  if(key==="adv")    return ["THE CLIMB", rosterMasteredLabel(), "ROSTER MASTERED"];
  if(key==="ng")     return ["NEW GAME +", "NG+ "+(rec.ngplus||0), "EVERYONE HITS HARDER"];
  if(key==="surv")   return ["SURVIVAL", String(rec.bestSurv||0), "BEST STREAK"];
  if(key==="daily"){ const D=dailyState(SAVE,dayKey());
                     return ["DAILY GAUNTLET", D.done?String(D.score):"OPEN", D.done?"TODAY'S SCORE":"NOT PLAYED TODAY"]; }
  if(key==="ranked"||key==="board"){ const rk=myRanking();
                     return [key==="board"?"THE LADDER":"RANKED", rk.rank.title.toUpperCase(),
                             rk.totalMatches?(rk.wins+"W "+rk.losses+"L"):"UNRANKED - PLAY A MATCH"]; }
  if(key==="tower"){ const unl=typeof TowerMode!=="undefined"?TowerMode.getState().unlockedFloors:1;
                     return ["HEAVENS TOWER", "FLOOR "+unl+" / 200", "200-FLOOR GAUNTLET"]; }
  if(key==="dojo")   return ["DOJO PRACTICE", "AI TARGET DUMMY", "FRAME DATA SANDBOX"];
  if(key==="create") return ["REGISTER FIGHTER", "AZX ENTRY", "18 RATINGS"];
  if(key==="replay") return ["REPLAY VIEWER", "MATCH STREAMS", "FRAME-BY-FRAME"];
  if(key==="ghost")  return ["GHOST BATTLES", "PASSCODE", "FIGHT COMM. BUILDS"];
  if(key==="p2p")    return ["P2P ARENA", "WEBRTC", "ONLINE 1V1 DUELS"];
  if(key==="vs")     return ["EXHIBITION", String(rec.wins||0), "CAREER WINS"];
  if(key==="vs2")    return ["TWO PLAYER", "HOT SEAT", "PASS THE DEVICE"];
  if(key==="list")   return ["THE ROSTER", String(FIGHTERS.length), "FIGHTERS ON FILE"];
  if(key==="rec")    return ["RECORDS", String(rec.duels||0), "FIGHTS CONTESTED"];
  if(key==="opt")    return ["OPTIONS", SAVE.dataDeck?"DATA DECK ON":diff().name, SAVE.dataDeck?"FIGHT TABLE VISIBLE":"CURRENT DIFFICULTY"];
  if(key==="how")    return ["HOW TO PLAY", "RULES", "RANGE - STAMINA - POSITION"];
  if(key==="renown"){ const m=metaNormalize(SAVE.meta);
                      return ["RENOWN", m.renown+" "+META_CONFIG.unit,
                              m.runs?(m.runs+(m.runs===1?" RUN BANKED":" RUNS BANKED")):"EVERY RUN PAYS"]; }
  if(key==="chal")   return ["CHALLENGE RUN",
                             G.challengePick?"SET":String((SAVE.titles||[]).length)+"/"+CHALLENGES.length,
                             G.challengePick?"OBJECTIVE CHOSEN":"TITLES EARNED"];
  return null;
}
function rMenu(){
  paintFrostedModalBackdrop(cx, W, H, null, null, "rgba(224, 58, 47, 0.08)");
  const items=menuTabItems(G.menuTab|0);
  if(G.menuSel>=items.length) G.menuSel=0;

  // Header Title & Telemetry
  txt("AQUA ZERO HEAVENS ARENA", 40, 42, 20, RED, "left", 900, true);
  const rk = myRanking();
  const rkStr = rk.rank.title.toUpperCase() + " \u00B7 " + (SAVE.name||"CHALLENGER") + " (" + (rk.wins||0) + "W-" + (rk.losses||0) + "L \u00B7 " + rk.promotionPoints + " PTS)";
  txt(rkStr, 40, 62, 10.5, rk.rank.color || GOLD, "left", 700);

  /* the page's own SOUND / SETTINGS buttons are fixed over the top-right of
     the canvas, so anything drawn there is behind them */
  drawDifficultyBadge(W - 200, 62, 160, 24);

  /* WHAT TO DO NEXT, SAID OUT LOUD. Nothing on this screen ever told a player
     where they were going - a returning player got a grid of twenty-three
     equally-weighted doors, and a new one got the same grid with three of the
     first six meaningless to them. */
  if(typeof Onboarding!=="undefined"){
    const goal=Onboarding.nextGoal(SAVE,{scene:"MENU"});
    if(goal&&goal.title){
      txt("NEXT:  "+String(goal.title).toUpperCase(),W/2-40,42,11,GOLD,"left",800);
      if(goal.line) txt(String(goal.line),W/2-40,60,10,DIM,"left",600);
    }
  }

  /* the four tabs, drawn as tabs so the shape of the menu is visible */
  {
    let tx=40;
    MENU_TABS.forEach((t,i)=>{
      const on=(G.menuTab|0)===i, cap=t.name, tw=cap.length*7.4+22;
      if(on){ cx.fillStyle="rgba(224,58,47,.20)"; cx.fillRect(tx,68,tw,18);
              cx.fillStyle=RED; cx.fillRect(tx,86,tw,2); }
      txt(cap,tx+tw/2,81,10.5,on?INK:"#6b7280","center",800);
      hot(tx,66,tw,22,()=>{},()=>{ if((G.menuTab|0)!==i){ G.menuTab=i; G.menuSel=0; sTick(); } });
      tx+=tw+6;
    });
  }

  // 2x3 Arcade Mode Tile Grid (x: 40..920, y: 84..470)
  const pageSize = 6;
  const pageIdx = Math.floor(G.menuSel / pageSize);
  const pageCount = Math.ceil(items.length / pageSize);
  const cardW = 426, cardH = 112, gapX = 28, gapY = 12;
  const startX = 40, startY = 96;

  const modeArtFid = [0, 5, 2, 7, 3, 8]; // Distinct fighter silhouettes for cards
  const modeColors = {
    adv: "#ef4444", cont: "#f59e0b", tower: "#a855f7", dojo: "#22d3ee",
    ranked: "#10b981", surv: "#f97316", deckbuild: "#3b82f6", create: "#eab308",
    codex: "#06b6d4", trophy: "#fbbf24", daily: "#14b8a6", weekly: "#ec4899",
    renown: "#8b5cf6", chal: "#e11d48", ng: "#ef4444", vs: "#64748b", vs2: "#64748b"
  };

  for(let k = 0; k < pageSize; k++){
    const i = pageIdx * pageSize + k;
    if(i >= items.length) break;
    const it = items[i];
    const col = k % 2, row = Math.floor(k / 2);
    const x = startX + col * (cardW + gapX);
    const y = startY + row * (cardH + gapY);
    const on = (i === G.menuSel);
    const key = it[2];
    const accent = modeColors[key] || "#22d3ee";
    const pv = menuPreview(key) || [it[0], "", it[1]];

    cx.save();
    // Card Chassis with angled cyber slits
    if(on){
      cx.shadowColor = accent;
      cx.shadowBlur = 14;
      panel(x, y, cardW, cardH, "rgba(14,18,28,.96)", accent, "rgba(255,255,255,.08)", 8);
      cx.restore(); cx.save();
      // Angled cyber corner slit highlight
      cx.fillStyle = accent;
      cx.beginPath();
      cx.moveTo(x, y + 16); cx.lineTo(x + 16, y); cx.lineTo(x + 32, y); cx.lineTo(x, y + 32);
      cx.closePath(); cx.fill();
      // Left vertical glowing strip
      cx.fillRect(x, y + 4, 4, cardH - 8);
    } else {
      panel(x, y, cardW, cardH, "rgba(10,13,20,.90)", "#202636", null, 8);
      // Subtle corner slit notch
      cx.strokeStyle = "rgba(255,255,255,.12)";
      cx.beginPath();
      cx.moveTo(x, y + 12); cx.lineTo(x + 12, y);
      cx.stroke();
    }

    // Mode Hero Art Silhouette / Badge on card right
    const heroFid = modeArtFid[k % modeArtFid.length];
    cx.save();
    cx.beginPath();
    cx.rect(x + cardW - 110, y + 4, 104, cardH - 8);
    cx.clip();
    drawPortrait(heroFid, x + cardW - 100, y + 14, 88, 88, false);
    const artOverlay = cx.createLinearGradient(x + cardW - 110, 0, x + cardW - 6, 0);
    artOverlay.addColorStop(0, on ? "rgba(14,18,28,.95)" : "rgba(10,13,20,.95)");
    artOverlay.addColorStop(0.5, "rgba(10,13,20,.45)");
    artOverlay.addColorStop(1, "rgba(10,13,20,.05)");
    cx.fillStyle = artOverlay;
    cx.fillRect(x + cardW - 110, y + 4, 104, cardH - 8);
    cx.restore();

    // Mode Title
    const isFtue = (SAVE.rec.duels === 0 && (key === "adv" || key === "dojo"));
    const titleStr = (it[0] + (isFtue ? " [NEW]" : "")).toUpperCase();
    txt(titleStr, x + 20, y + 28, on ? 16 : 14.5, on ? (key === "adv" ? RED : accent) : INK, "left", 900);

    // Live Save Telemetry Readout
    if(pv && pv[1]){
      panel(x + 20, y + 40, cardW - 150, 24, "rgba(8,10,15,.7)", on ? accent : "#252831", null, 4);
      txt(pv[0] + ": ", x + 28, y + 56, 9.5, DIM, "left", 700);
      txt(pv[1], x + 30 + cx.measureText(pv[0] + ": ").width, y + 56, 10.5, GOLD, "left", 800);
    }

    // Subtitle Description
    const maxDescW = cardW - 150;
    const descStr = fitMenuDesc(it[1], maxDescW);
    txt(descStr, x + 20, y + 84, 10, on ? INK : "#64748b", "left", 600);

    // Click & hover registration
    hot(x, y, cardW, cardH, () => { G.menuSel = i; }, () => { G.menuSel = i; onKey("a"); });
    cx.restore();
  }

  // Footer Navigation Bar
  const footerY = H - 42;
  panel(40, footerY, W - 80, 28, "rgba(10,14,22,.90)", "#202636", null, 6);
  txt(MENU_TABS[G.menuTab|0].name + "  " + (pageIdx + 1) + " / " + pageCount, 60, footerY + 18, 10.5, AQUA, "left", 800);
  txt(LGJ("ARROWS - MOVE", LG("y","NEXT TAB"), LG("a","SELECT"), LG("b","TITLE")), W / 2 + 30, footerY + 18, 10.5, DIM, "center", 700);
  artNote();
}
