/* Geometry for the fighter-select ribbon. Four rows of 25 fighters have to
   finish above the footer on the 960x540 canvas, which is what 1280x800
   letterboxes. */
function rosterRibbon(){
  const list=selList();
  const rows=Math.max(1, Math.ceil(list.length/SEL_COLS));
  const cw=122, ox=32, gapX=6;
  const footerY=H-40;
  /* Four rows of the stock 25 finish at 488, above the footer at 500.
     A registered fighter adds a row, and that row still has to clear it. */
  let ch=42, oy=308, gapY=4;
  let bottom=oy+(rows-1)*(ch+gapY)+ch;
  const limit=footerY-4;
  if(bottom>limit){
    gapY=3;
    const room=limit-oy;
    ch=Math.floor((room-(rows-1)*gapY)/rows);
    if(ch<26){
      ch=26; gapY=2;
      oy=Math.max(280, limit-((rows-1)*(ch+gapY)+ch));
    }
    bottom=oy+(rows-1)*(ch+gapY)+ch;
  }
  return {rows, cw, ch, ox, oy, gapX, gapY, footerY, bottom};
}

