  txt("STAGE "+a.stage+(m.ogre?" - HEAVENS GATE":"")+((a.ng||0)?"  NG+"+a.ng:""),121,218,10.5,m.ogre?RED:DIM,"center",700);
  txt("STEPS",30,250,11,DIM,"left",700); txt(m.steps,200,256,26,m.steps<=12?RED:INK,"right",800);
