  txt("LEVEL",30,324,10.5,DIM,"left",700);
  txt("LV "+a.level+(pendingLv(a)>0?"  (+"+pendingLv(a)+" AT TEMPLE)":""),200,324,11.5,pendingLv(a)>0?GRN:INK,"right",700);
  txt("CARD POINTS",30,344,10.5,DIM,"left",700); txt(a.points,200,344,11.5,INK,"right",700);
  txt("DECK",30,364,10.5,DIM,"left",700); txt(a.pool.length+" CARDS",200,364,11.5,INK,"right",700);
  txt("PURSE",30,384,10.5,DIM,"left",700); txt(a.purse||0,200,384,11.5,GOLD,"right",700);
