  txt("FORCE",48,470,12,INK,"left",700);
  cx.fillStyle=GOLD; cx.fillRect(112,458,12,12); txt("RIVAL",128,470,12,INK,"left",700);
  cx.fillStyle=GRN; cx.fillRect(28,478,12,12); txt("TEMPLE",48,488,12,INK,"left",700);
