  cx.closePath(); cx.stroke(); cx.lineWidth=1;
  txt("PATROL",128,488,12,INK,"left",700);
  const hunted=m.foes.filter(o=>!o.done&&o.hunting).length;
  txt(hunted?hunted+" CLOSING IN":LG("b","PAUSE")+"   "+LG("y","DOSSIER"),121,506,12,hunted?RED:INK,"center",hunted?800:700);
  // Dedicated Live Target & Hazard Telemetry HUD (x: 716..944, y: 28..504)
  panel(716, 28, 228, H-64, "rgba(12,15,22,.94)", "#262c3b", "rgba(34,211,238,.06)", 10);
