  txt("PATROLS: " + (hunted ? (hunted + " CLOSING IN") : "CLEAR"), 830, 257, 9.5, hunted ? RED : GRN, "center", 800);

  const carr = (a.carry || []).filter(k => STATUS[k]);
  panel(730, 272, 200, 26, carr.length ? "rgba(245,158,11,.15)" : "rgba(255,255,255,.03)", carr.length ? GOLD : "#283042", null, 4);
  txt(carr.length ? ("DEBUFF: " + carr.map(k=>STATUS[k].name).join("/")) : "STATUS: NORMAL", 830, 289, 9.5, carr.length ? GOLD : DIM, "center", 700);

  const bank = Math.min(SUP_BANK, Math.max(0, Math.round(a.meter || 0)));
  panel(730, 304, 200, 26, bank >= SUP_MIN ? "rgba(34,211,238,.15)" : "rgba(255,255,255,.03)", bank >= SUP_MIN ? AQUA : "#283042", null, 4);
