function rBrief(){
  rMap();
  cx.fillStyle="rgba(5,6,8,.86)"; cx.fillRect(0,0,W,H);
  const f=G.brief.f, a=G.adv, ng=a.ng||0, dm=diff();
  drawDifficultyBadge(W/2-80,24,160,24);
  drawFighterArt(a.hero, 240, 520, 400, false);
  const oppFid=f.boss?BOSS_ID:(f.tf?f.art:f.id);
  drawFighterArt(oppFid, 720, 520, 400, true, ringSilhouette(f));
  txt("VS",W/2,280,54,RED,"center",800,true);
  txt(FIGHTERS[a.hero].name,240,70,16,INK,"center",800);
  /* the banked meter rides the hero's own line rather than taking a row: the
     rows under it at 110 and 116/132 already belong to the carry readout, the
     ambush line and the patrol's terms */
  {
    const bank=Math.min(SUP_BANK,Math.max(0,Math.round(a.meter||0)));
    txt(a.hp+" / "+a.maxhp+" HP   "+traitsOf(a.hero).tag+(bank>0?"   SIG "+bank:""),
        240,92,11,DIM,"center",600);
  }
  const oname=foeName(f);
  txt(oname,720,70,16,f.boss?RED:INK,"center",800);
  const ohp=f.boss?Math.round((150+ng*45)*dm.hp)
        :f.tf?Math.round((40+a.stage*10+ng*12)*dm.hp)
        :Math.round((85+a.stage*14+ng*18)*dm.hp);
  txt((f.boss?"":"LV "+f.lv+"  -  ")+ohp+" HP"+(f.boss?" - 5 SEALED CARDS":""),720,92,11,DIM,"center",600);
  if(false)
    txt("RIVAL - WIN TO UNLOCK"+((SAVE.defeats[f.id]||0)>0?" (BEATEN "+SAVE.defeats[f.id]+"x)":""),720,112,10.5,GOLD,"center",700);
  /* what the field already put on you, read out before you accept the fight */
  {
    const carr=(a.carry||[]).filter(k=>STATUS[k]);
    if(carr.length) txt("CARRYING: "+carr.map(k=>STATUS[k].name).join(" / "),240,110,10.5,RED,"center",700);
  }
  if(G.brief.ambush) txt("AMBUSHED - THEY GET THE JUMP ON YOU",W/2,132,12,RED,"center",800);
  /* the patrol's terms, stated before the bell rather than discovered at it */
  if(f.tf) txt("ONE EXCHANGE - WHOEVER TAKES THE WORSE OF IT IS FINISHED",
               W/2,G.brief.ambush?116:132,12,AQUA,"center",800);
  /* THE BRIEF REMEMBERS. Inside a run the nemesis is the man who beat you this
     run; across runs he is the man who ENDED the last one, and SAVE.nem carries
     the record between you. Both are the same flag on the run object, so this is
     one line with two readings and the tally is only shown when there is one. */
  if(!f.boss&&!f.tf&&a.nemesis===f.id){
    const rec=(SAVE.nem&&SAVE.nem.fid===f.id)?SAVE.nem:null;
    txt(rec
        ? ("NEMESIS - HE ENDED YOUR LAST RUN - "+rec.wins+"-"+rec.losses+" BETWEEN YOU - REVENGE PAYS")
        : "NEMESIS - THEY BEAT YOU THIS RUN - REVENGE PAYS",
        W/2,G.brief.ambush?116:132,12,GOLD,"center",800);
  }
  /* the run's standing objective, stated before every bell it could be met in */
  if(a.challenge&&CHALLENGE_BY_ID[a.challenge]){
    const tip=(typeof challengeCoachTip==="function")?challengeCoachTip(a.challenge):CHALLENGE_BY_ID[a.challenge].desc;
    const mut=(typeof challengeMutatorLabel==="function")?challengeMutatorLabel(a.challenge):null;
    const eligible=!(G.brief&&G.brief.f&&G.brief.f.tf);
    txt((a.challengeDone?(a.challengeMastery?"MASTERY MET - ":"CHALLENGE MET - ")
                        :(a.challengeMastery?"MASTERY - ":"CHALLENGE - "))
        +CHALLENGE_BY_ID[a.challenge].desc.toUpperCase(),
        W/2,168,10,a.challengeDone?GRN:AQUA,"center",700);
    txt(String(tip||"").toUpperCase(),W/2,186,9,DIM,"center",600);
    if(!a.challengeDone)
      txt((eligible?"THIS BOUT CAN COUNT":"PATROL CLASH - DOES NOT COUNT")
          +(mut?("  \u00b7  "+mut):""),
          W/2,202,8.5,eligible?GOLD:DIM,"center",600);
  }
  // a fighter who wants something is worth beating
  if(!f.tf&&f.id!==undefined){
    const fr=(SAVE.fr&&SAVE.fr[f.id])||{w:0,l:0};
    const line=calloutFor(f.id,{first:!(fr.w||fr.l),beatenBefore:(fr.w||0)>0,
                                isRival:G.adv&&rivalOf(f.id).indexOf(G.adv.hero)>=0});
    if(line){
      panel(W/2-330,152,660,42,"rgba(10,11,14,.85)","#252831");
      txt('"'+line+'"',W/2,178,12.5,INK,"center",600);
    }
    if(G.adv&&rivalOf(f.id).indexOf(G.adv.hero)>=0){
      const why=rivalryReason(f.id,G.adv.hero);
      txt("RIVAL"+(why?" - "+why.toUpperCase():""),W/2,208,10,RED,"center",800);
    }
  }
  if(typeof generateBountiesForFight === "function" && G.adv){
    if(!G.briefBounties || G.briefBountiesSeed !== (G.adv.stage * 100 + G.adv.step)){
      G.briefBounties = generateBountiesForFight(G.adv.stage * 100 + G.adv.step);
      G.briefBountiesSeed = G.adv.stage * 100 + G.adv.step;
      G.acceptedBounty = null;
    }
    if(G.briefBounties && G.briefBounties.length > 0){
      const bIdx = G.acceptedBountyIndex || 0;
      const b = G.briefBounties[bIdx % G.briefBounties.length];
      const isAccepted = G.acceptedBounty === b;
      panel(W/2-240, 206, 480, 48, isAccepted ? "rgba(16,185,129,.16)" : "rgba(10,11,14,.85)", isAccepted ? GRN : GOLD);
      txt(isAccepted ? "BOUNTY CONTRACT ACCEPTED: " + b.title.toUpperCase() : "OPTIONAL UNDERWORLD BOUNTY: " + b.title.toUpperCase(), W/2, 222, 10.5, isAccepted ? GRN : GOLD, "center", 800);
      txt(b.desc + " (+" + Math.round((b.purseMul - 1) * 100) + "% Purse" + (b.renownReward ? ", +" + b.renownReward + " Renown" : "") + ")", W/2, 240, 9.5, INK, "center", 600);
    }
  }
  {
    const chips=[[LG("a","FIGHT"),"a",true],
                 [LG("b","RETREAT (1 STEP)"),"b",!G.brief.ambush],
                 [LG("y","BOUNTY / DOSSIER"),"y",true]].filter(c=>c[2]);
    const cwd=200, gap=18, ox2=W/2-(chips.length*cwd+(chips.length-1)*gap)/2;
    chips.forEach((c,i)=>{
      const bx=ox2+i*(cwd+gap);
      panel(bx,486,cwd,26,"rgba(10,11,14,.85)",i===0?RED:"#2a2d35");
      txt(c[0],bx+cwd/2,503,11.5,i===0?((G.t/30|0)%2?INK:RED):DIM,"center",800);
      hot(bx,486,cwd,26,null,()=>onKey(c[1]));
    });
  }
}
function shake(side){ return (motionOn()&&side.shakeT>0)?Math.sin(side.shakeT*1.7)*Math.min(8,side.shakeT):0; }
function lunge(side,toward){
  if(!side.animT||!motionOn()) return 0;
  const p=side.animT/22;
  if(side.anim==="atk") return toward*Math.sin(p*Math.PI)*38;
  if(side.anim==="hit") return -toward*Math.sin(p*Math.PI)*22;
  if(side.anim==="block") return -toward*Math.sin(p*Math.PI)*8;
  return 0;
}
/* ---------- fight furniture ---------- */
function rangeStrip(d){
  const w=94, gap=6, total=RANGE_ORDER.length*(w+gap)-gap, ox=(W-total)/2;
  RANGE_ORDER.forEach((r,i)=>{
    const x=ox+i*(w+gap), on=r===d.range;
    panel(x,104,w,22, on?"rgba(34,211,238,.20)":"rgba(10,13,18,.82)", on?AQUA:"#262c3b", on?"rgba(34,211,238,.25)":null, 6);
    txt(RANGE_LABEL[r],x+w/2,119,10,on?AQUA:"#6b7280","center",on?800:600);
  });
  const mine=homeRanges(d.p.discs);
  txt(describePosition(d),W/2,152,10.5,d.cornered==="p"?RED:(d.cornered==="e"?GRN:DIM),"center",800);
  txt(mine.indexOf(d.range)>=0?"YOUR OPTIMAL RANGE":"OUT OF OPTIMAL RANGE",W/2,138,9.5,
      mine.indexOf(d.range)>=0?GRN:RED,"center",700);
  /* the pressure ledger, on screen at last */
  const m=d.press;
  if(m&&m.n>0.05){
    const bw=160,bx=W/2-bw/2,by=158;
    const fr=Math.min(1,m.n/PRESS_STEP), hotFr=fr>=.8;
    panel(bx,by,bw,8,"#090b10",hotFr?(m.by==="p"?GRN:RED):"#262c3b",null,4);
    cx.fillStyle=m.by==="p"?"rgba(16,185,129,.9)":"rgba(230,57,47,.9)";
    cx.fillRect(bx+1,by+1,(bw-2)*fr,6);
    txt((m.by==="p"?"WALKING THEM DOWN":"THEY ARE WALKING YOU DOWN")
        +(hotFr?" \u00B7 CRITICAL":""),W/2,180,8.5,m.by==="p"?GRN:RED,"center",700);
  }
}
/* A CONDITION WITHOUT ITS CLOCK IS NOT INFORMATION. These chips drew the name
   and nothing else, so there was no way to tell a status that expires next turn
   from one that has four turns to run - and therefore no way to play around
   either. STAMINA BREAK disables guard outright and adds a third again to
   everything you take; PINNED takes throws away. addStatus has stored {turns,
   maxTurns} all along. The fifth and later chips were also silently dropped. */
function condChips(side,x,y,alignR){
  const keys=Object.keys(side.cond);
  let cx0=x;
  keys.slice(0,4).forEach(k=>{
    const s=STATUS[k], c=side.cond[k]||{};
    const turns=Math.max(0,Math.round(c.turns||0));
    const label=s.name+(turns?" "+turns:"");
    const w=label.length*5.8+14;
    const px=alignR?cx0-w:cx0;
    panel(px,y,w,16,"rgba(11,14,20,.9)",s.color,null,4);
    txt(label,px+w/2,y+12,8.5,s.color,"center",800);
    /* the sliver under the chip drains as the condition does, so "about to
       expire" reads at a glance without counting */
    const span=Math.max(1,c.maxTurns||turns||1);
    if(turns){ cx.fillStyle=s.color; cx.globalAlpha=.55;
               cx.fillRect(px+1,y+16,Math.max(1,(w-2)*Math.min(1,turns/span)),2);
               cx.globalAlpha=1; }
    cx0=alignR?px-5:px+w+5;
  });
  if(keys.length>4){
    const more="+"+(keys.length-4), w=more.length*5.8+10;
    const px=alignR?cx0-w:cx0;
    txt(more,px+w/2,y+12,8.5,"#8d929b","center",800);
  }
}
function stamBar(x,y,w,side,alignR){
  panel(x,y,w,8,"#080a10","#1f2430",null,4);
  const f=Math.max(0,(w-2)*Math.max(0,side.stam)/side.maxStam);
  const isLow=side.stam<side.maxStam*.25;
  const g=cx.createLinearGradient(0,y,0,y+8);
  if(isLow){
    g.addColorStop(0,"#fb923c"); g.addColorStop(1,"#c2410c");
  } else {
    g.addColorStop(0,"#38bdf8"); g.addColorStop(1,"#0284c7");
  }
  cx.fillStyle=g;
  cx.fillRect(alignR?x+1+(w-2-f):x+1,y+1,f,6);
  // battery cell divider notches (every 25%)
  cx.fillStyle="rgba(0,0,0,.5)";
  for(let s=1;s<4;s++){
    const nx=x+1+Math.round((w-2)*s/4);
    cx.fillRect(nx,y+1,1,6);
  }
  // top battery glass shine
  cx.fillStyle="rgba(255,255,255,.18)";
  cx.fillRect(alignR?x+1+(w-2-f):x+1,y+1,f,2.5);
}
/* One menu row is one honest forecast: what this technique would really
   do THIS turn - the resolver's own numbers, not the dossier's. Expected
   damage after every modifier, hit chance as a bar, who moves first, and
   how the row answers the tell. The player reads a decision, not a stat
   block they have to simulate in their head. */
/* 26 of the 426 technique names are wide enough at 12px to run into the slot
   the hint and the discipline share, and the menu now shows a lot more of
   them at once. The parenthetical is a translation, so it is the first thing
   to go; anything still too wide is clipped rather than overprinted. */
function fitName(name,budget,weight){
  const s=String(name).toUpperCase();
  const memo=fitName.memo||(fitName.memo={});
  const key=weight+"|"+budget+"|"+s;
  if(memo[key]!==undefined) return memo[key];
  const font=(weight||700)+" 12px Bahnschrift,'Segoe UI Variable','Segoe UI',system-ui,sans-serif";
  const wide=t=>{ cx.font=font; return cx.measureText(t).width>budget; };
  let out=s;
  if(wide(out)){
    const cut=out.indexOf(" (");
    if(cut>0) out=out.slice(0,cut);          // the parenthetical is a translation
    if(wide(out)){
      while(out.length>4&&wide(out+"...")) out=out.slice(0,-1);
      out=out+"...";
    }
  }
  memo[key]=out; return out;
}
function techRow(d,tech,x,y,w,on,side,note){
  const foe=side===d.p?d.e:d.p;
  const fit=rangeFit(tech.range,d.range);
  const col=fit>=1?GRN:fit>=.7?GOLD:"#8b5a4a";
  if(on){ cx.fillStyle="rgba(224,58,47,.16)"; cx.fillRect(x,y-13,w,20); }
  if(side.drill&&side.drill[tech.id]) txt("+",x+2,y,11,GOLD,"left",800);
  
  // Category Pill Badge (Strike, Throw, Sub, Guard, Setup)
  const catKey=tech.cls||"STRIKE";
  const catBg=catKey==="STRIKE"?"rgba(230,57,47,.22)":catKey==="THROW"?"rgba(245,158,11,.22)":catKey==="SUB"?"rgba(168,85,247,.22)":catKey==="GUARD"?"rgba(34,211,238,.22)":"rgba(16,185,129,.22)";
  const catBorder=catKey==="STRIKE"?"#e6392f":catKey==="THROW"?"#f59e0b":catKey==="SUB"?"#a855f7":catKey==="GUARD"?"#22d3ee":"#10b981";
  const catTag=catKey==="STRIKE"?"STR":catKey==="THROW"?"THR":catKey==="SUB"?"SUB":catKey==="GUARD"?"GRD":"SET";
  panel(x+6,y-10,24,12,catBg,catBorder,null,2);
  txt(catTag,x+18,y,7.5,catBorder,"center",800);

  txt(fitName(tech.name,186,on?800:600),x+34,y,12,on?INK:"#b9bcc4","left",on?800:600);
  /* the hint answers the tell; when there is nothing to say, name the art.
     `note` overrides both - the signature row spends the slot on its meter,
     which is the only thing standing between it and being thrown. */
  const hint=(side===d.p&&!d.hotseat)?intentHint(d,side,tech):null;
  if(note) txt(note.text,x+232,y,9,note.color||DIM,"left",800);
  else if(hint) txt(hint.note,x+232,y,8.5,hint.edge>0?GRN:"#c96a5a","left",800);
  else { const disc=DISCIPLINES[tech.disc];
         txt(disc?disc.name:"RINGCRAFT",x+232,y,9,on?DIM:"#5d626c","left",600); }
  cx.beginPath(); cx.arc(x+w-238,y-4,4,0,7); cx.fillStyle=col; cx.fill();
  txt(RANGE_LABEL[tech.range]||"ANY",x+w-230,y,8.5,col,"left",700);
  const fc=(side===d.p&&!d.hotseat)?forecastFirst(d,side,tech):0;
  txt(fc>0?"FIRST":fc<0?"AFTER":"EVEN",x+w-152,y,8,fc>0?GRN:fc<0?"#8b5a4a":"#5d626c","right",700);
  if((tech.flags||[]).indexOf("circle")>=0)
    txt("ESC "+Math.round(escapeChance(side,d.pos)*100)+"%",x+w-88,y,10,AQUA,"right",700);
  else{
    const est=tech.power?damageOf(d,side,foe,tech):0;
    txt(est?"~"+est:"-",x+w-88,y,11,est?INK:"#5d626c","right",700);
  }
  const acc=Math.round(accuracyOf(d,side,foe,tech));
  panel(x+w-76,y-11,42,9,"#0a0b0e","#2a2d35");
  cx.fillStyle=acc>=80?GRN:acc>=60?GOLD:RED;
  cx.fillRect(x+w-75,y-10,Math.max(1,40*acc/100),7);
  txt(acc,x+w-30,y,9,DIM,"right",600);
  const st=staminaCost(side,tech);
  txt(st,x+w-8,y,10,st>side.stam?RED:DIM,"right",600);
}
/* The whole turn on one screen. Every technique that can be thrown from
   where the fight is standing, each row carrying the forecast techRow()
   builds, with the categories along the top as tabs that NARROW the list
   rather than hiding it. Five rows are drawn; the geometry is the one the
   old technique list used, which is what keeps a level-nine movelist and a
   twelve-pick draft scrolling cleanly inside the same panel. */
const CMD_ROWS=5;
function drawCommand(d,side,label){
  panel(16,398,W-32,H-406,"rgba(8,9,11,.92)","#252831");
  const added=(side===d.p&&d.handNote&&d.handNote.name)
    ?("ADDED TO YOUR HAND: "+d.handNote.name):null;
  txt(added||label,30,414,added?13:12,added?GOLD:INK,"left",800);
  const tabs=cmdTabs(d,side), tabIx=cmdTabIx(d,side), tab=tabs[tabIx].key;
  const bag=(side===d.p&&bagOpen(d))?(G.adv.corner||[]):null;
  const bagReady=bag?bag.some(id=>bagLit(d,CORNER_ITEMS[id])):false;
  /* ---- the tab strip: a filter, addressed by key ---- */
  let tx=176;
  tabs.forEach((t,i)=>{
    const on=i===tabIx, isBag=t.key==="BAG";
    const cap=isBag?("\ud83c\udf92 BAG ("+bag.length+")"):t.label;
    const tw=Math.max(cap.length*6.8+16, 44);
    const dead=t.key==="SIGNATURE"&&(!side.sig||side.sup<SUP_MIN);
    if(on){
      const fillCol = t.key==="STRIKE" ? "rgba(239,68,68,.28)"
                    : t.key==="GUARD" ? "rgba(34,211,238,.28)"
                    : t.key==="SIGNATURE" ? "rgba(245,158,11,.32)"
                    : t.key==="GRAPPLE" ? "rgba(168,85,247,.28)"
                    : isBag ? "rgba(34,211,238,.22)" : "rgba(255,255,255,.16)";
      const borderCol = t.key==="STRIKE" ? "#ef4444"
                      : t.key==="GUARD" ? "#22d3ee"
                      : t.key==="SIGNATURE" ? "#fbbf24"
                      : t.key==="GRAPPLE" ? "#c084fc"
                      : isBag ? "#38bdf8" : "#94a3b8";
      cx.fillStyle=fillCol;
      cx.fillRect(tx,401,tw,18);
      cx.strokeStyle=borderCol;
      cx.lineWidth=1.2;
      cx.strokeRect(tx,401,tw,18);
    }
    const txtCol = on ? (t.key==="STRIKE" ? "#fca5a5"
                       : t.key==="GUARD" ? "#a5f3fc"
                       : t.key==="SIGNATURE" ? "#fde68a"
                       : t.key==="GRAPPLE" ? "#e9d5ff"
                       : isBag ? AQUA : INK)
                      : (isBag?(bagReady?"#3f8fa0":"#4a6a72"):(dead?"#5d626c":"#8d929b"));
    txt(cap,tx+tw/2,414,10,txtCol,"center",800);
    hot(tx,401,tw,18,
        ()=>{ if(d.cmdCat!==i){ d.cmdCat=i; d.cmdSel=0; d.cmdKey=null; d.cmdScroll=0; } },
        /* clicking a filter must never commit an attack, so a tab click is
           hover and nothing else - the bag is the one tab with an action */
        ()=>{ if(d.cmdCat!==i){ d.cmdCat=i; d.cmdSel=0; d.cmdKey=null; d.cmdScroll=0; }
              if(isBag) onKey("a"); else sTick(); });
    tx+=tw+5;
  });
  /* ---- column headers, over the columns techRow actually draws ----
     Only techRow draws columns. In card mode these five labels printed across
     the top of the hand naming columns that were not underneath them. */
  const rowMode=!!SAVE.dataDeck||typeof CardRenderer==="undefined";
  if(rowMode){
    txt("RANGE",700,414,8.5,"#5d626c","left",700);
    txt("FIRST",784,414,8.5,"#5d626c","right",700);
    txt("EST",W-112,414,8.5,DIM,"right",700);
    txt("HIT",W-58,414,8.5,DIM,"right",700);
    txt("STA",W-32,414,8.5,DIM,"right",700);
  }
  if(tab==="BAG"){
    txt("THE CORNER ANSWERS WHAT IS WRONG - USING ONE TAKES YOUR TURN",
        30,438,10,DIM,"left",600);
    (bag||[]).slice(0,3).forEach((id,i)=>{
      const item=CORNER_ITEMS[id]; if(!item) return;
      const ready=bagLit(d,item);
      txt(item.name,34,462+i*18,11.5,ready?"#b9bcc4":"#6a7078","left",600);
      txt(ready?"READY":"NOTHING TO FIX",300,462+i*18,9,ready?GRN:"#5d626c","left",700);
    });
    txt(LG("a","OPEN THE CORNER BAG")+"    LEFT/RIGHT - BACK TO YOUR TECHNIQUES",
        30,H-8,10.5,AQUA,"left",700);
    txt("STAMINA "+Math.max(0,Math.round(side.stam))+"/"+side.maxStam,W-30,H-8,10.5,DIM,"right",700);
    return;
  }
  const list=menuTechsFor(d,side);
  const focus=cmdFocus(d,side,list);
  if(!list.length){
    txt(tab==="SIGNATURE"?"THIS FIGHTER HAS NO SIGNATURE"
                         :"NOTHING IN THIS CATEGORY REACHES FROM HERE",
        W/2,470,12,DIM,"center",600);
  } else {
    if(focus<d.cmdScroll) d.cmdScroll=focus;
    if(focus>=d.cmdScroll+CMD_ROWS) d.cmdScroll=focus-CMD_ROWS+1;
    d.cmdScroll=Math.max(0,Math.min(d.cmdScroll,Math.max(0,list.length-CMD_ROWS)));
    if(list.length>CMD_ROWS) txt((focus+1)+" / "+list.length,596,414,9.5,DIM,"left",600);
    if(typeof CardRenderer!=="undefined" && typeof CardRenderer.paintCardHand==="function" && !SAVE.dataDeck){
      const visibleTechs=list.slice(d.cmdScroll, d.cmdScroll+CMD_ROWS);
      const cardIds=visibleTechs.map(tq=>tq.id);
      const selInHand=focus-d.cmdScroll;
      if(typeof ThreeEngine!=="undefined"&&ThreeEngine.getState().initialized&&typeof Card3D!=="undefined"){
        Card3D.syncHand(ThreeEngine.getThree(), ThreeEngine.getScene("venue"), visibleTechs, selInHand, -1, false, 0);
      }
      /* THE CARDS USED TO PRINT THE DEX AND NOTHING ELSE. tech.power, tech.acc
         and tech.speed are the technique's numbers on paper; what decides the
         turn is what those numbers become against THIS opponent, at THIS range,
         with this much stamina - which the row renderer below has always
         computed and the card path never saw. So the default way to read your
         hand was the one that showed a raw power figure the resolver scales by
         range fit, comfort, position, status and guard before it means
         anything, with no indication of whether the technique even reaches.
         Same forecast as techRow, same thresholds, now on the cards. */
      const foe=side===d.p?d.e:d.p;
      const mine=(side===d.p&&!d.hotseat);
      const live=visibleTechs.map(tq=>{
        const fit=rangeFit(tq.range,d.range);
        const circles=(tq.flags||[]).indexOf("circle")>=0;
        const st=staminaCost(side,tq);
        const hint=mine?intentHint(d,side,tq):null;
        return {
          dmg:(!circles&&tq.power)?damageOf(d,side,foe,tq):null,
          escape:circles?Math.round(escapeChance(side,d.pos)*100):null,
          acc:Math.round(accuracyOf(d,side,foe,tq)),
          fit:fit>=1?"good":fit>=.7?"ok":"bad",
          first:mine?(forecastFirst(d,side,tq)>0?1:forecastFirst(d,side,tq)<0?-1:0):0,
          stam:st, affordable:st<=side.stam,
          note:hint?((d.lessonFight?(hint.edge>0?"GOOD. ":hint.edge<0?"BAD. ":""):"")+hint.note):null,
          noteColor:hint?(hint.edge>0?GRN:"#c96a5a"):null
        };
      });
      const handBoxes=CardRenderer.paintCardHand(cx, undefined, 420, cardIds, selInHand, {
        cardWidth:124, cardHeight:98, gap:16, curved:true, hotkeys:true,
        /* the hand sits at 420 inside the 398-532 panel; the default 38px
           selection lift pushed the chosen card up into the y-band the TELL /
           READ banner owns (356-396) and covered the exact line a spent focus
           point had just paid for. 20 keeps the lift readable and clear of it. */
        live:live, liftPx:20
      });
      handBoxes.forEach(hb=>{
        const ix=d.cmdScroll+hb.index;
        hot(hb.x, hb.y, hb.w, hb.h,
            ()=>{ cmdPoint(d,side,ix,list);
                  /* CardTooltip.render runs every frame and setHoverCard had no
                     caller anywhere, so the whole inspection layer - what a
                     class beats, what it breaks - drew nothing, ever. */
                  if(typeof CardTooltip!=="undefined"&&CardTooltip.setHoverCard)
                    CardTooltip.setHoverCard(list[ix],side,hb.x+hb.w/2,hb.y); },
            ()=>{ cmdPoint(d,side,ix,list); onKey("a"); });
      });
    } else {
      for(let i=0;i<CMD_ROWS;i++){
        const ix=d.cmdScroll+i, tq=list[ix]; if(!tq) break;
        /* the signature spends its descriptive slot on the meter, because the
           meter is the only thing between it and being thrown */
        let note=null;
        if(side.sig&&tq===side.sig)
          note=side.sup>=SUP_MAX?{text:"METER FULL - FULL POWER",color:GOLD}
              :side.sup>=SUP_MIN?{text:"HALF BAR - ARMED, WEAKER",color:"#c39a4a"}
              :{text:Math.ceil(SUP_MIN-side.sup)+" MORE METER TO ARM",color:"#5d626c"};
        techRow(d,tq,24,436+i*20,W-48,ix===focus,side,note);
        hot(24,436+i*20-13,W-48,20,
            ()=>{ cmdPoint(d,side,ix,list); },
            ()=>{ cmdPoint(d,side,ix,list); onKey("a"); });
      }
    }
    if(tab==="SIGNATURE"&&side.sig&&side.sig.desc)
      txt(side.sig.desc,W/2,478,10,DIM,"center",600);
  }
  txt(LG("a","EXECUTE")+"   [1]-[5] PICK CARD   \u2190 \u2192 SWITCH [ATTACK / DEFENSE / SPECIAL]",30,H-8,12,INK,"left",800);
  if(!d.hotseat) txt(LG("y","READ (1 FOCUS)"),300,H-8,12,
                     (side.focus&&!d.readShown)?GOLD:"#d1d5db","left",700);
  txt("STAMINA "+Math.max(0,Math.round(side.stam))+"/"+side.maxStam,W-30,H-8,12,INK,"right",700);
  /* Exhibition practice overlay: initiative / power / stamina of the row under
     the cursor, so the lab can teach without a trip back to the Dojo. */
  if(d.exhibition&&d.exhib&&d.exhib.overlay&&list&&list.length){
    const tq=list[focus];
    if(tq){
      panel(W/2-210,360,420,34,"rgba(8,12,18,.92)",AQUA);
      const ini=(typeof initiativeOf==="function")?initiativeOf(side,tq):tq.speed;
      txt("OVERLAY  SPD "+(tq.speed||"-")
          +"  \u00b7  INIT "+Math.round(ini||0)
          +"  \u00b7  POW "+(tq.power||"-")
          +"  \u00b7  STA "+staminaCost(side,tq)
          +"  \u00b7  "+(RANGE_LABEL[tq.range]||"ANY"),
          W/2,382,11,AQUA,"center",700);
      if(typeof DojoMode!=="undefined"&&DojoMode.updateFrameData){
        DojoMode.updateFrameData({
          startup:Math.max(1,Math.round(100-(tq.speed||50))),
          active:3,
          recovery:Math.max(4,Math.round((tq.stam||8)/2)),
          advantage:Math.round(((tq.prio||0)-(tq.stam||0)/4))
        });
      }
    }
  }
}
/* The walkout. One fighter at a time gets the room: art slides in, the plate
   builds a row at a time, a sting lands, it holds - then the other man, then
   the card, then the bell. src/ui/entrance.js owns every number here; this
   function owns only pixels. A is instant and leaves the bell intact. */
function drawEntrance(d,eb){
  if(!eb) return;
  if(eb.stage==="p1"||eb.stage==="p2"){
    const px=eb.lit==="p"?60:W-560, sd=eb.lit==="p"?d.p:d.e, fid=eb.fid;
    panel(px,300,500*eb.plate,86,"rgba(8,9,11,.92)","#252831");
    if(eb.plate>.35){
      if(eb.rows>=1) txt(FIGHTERS[fid].name,px+18,330,24,INK,"left",800);
      if(eb.rows>=2) txt(sd.discs.map(x=>DISCIPLINES[x].name).join(" / "),px+18,352,11,GOLD,"left",600);
      if(eb.rows>=3) txt(eb.rec&&eb.rec.known?(eb.rec.w+" - "+eb.rec.l+" AGAINST THIS MAN"):"FIRST MEETING",
                         px+18,372,10,DIM,"left",600);
      if(eb.rows>=1&&eb.role!=="you"&&eb.role!=="challenger")
        txt(String(eb.role).replace("_"," "),px+482,330,11,eb.role==="champion"?RED:GOLD,"right",800);
    }
  }
  if(eb.stage==="vs"||eb.stage==="bell"){
    cx.globalAlpha=eb.vs;
    txt(FIGHTERS[d.p.fid].name,240,150,22,INK,"center",800);
    txt(oppName(d),720,150,22,d.boss?RED:INK,"center",800);
    txt("VS",W/2,150,30+50*eb.vs,RED,"center",800,true);
    if(eb.banner) txt(eb.banner,W/2,336,12,eb.billing>=.9?RED:eb.billing>=.6?GOLD:AQUA,"center",800);
    cx.globalAlpha=1;
  }
  if(eb.stage==="bell") txt("FIGHT!",W/2,300,74,GOLD,"center",800,true);
  if(eb.flash>0){ cx.fillStyle="rgba(255,255,255,"+(eb.flash*.35).toFixed(3)+")"; cx.fillRect(0,0,W,H); }
  txt(LG("a","SKIP")+"      "+LG("b","FIGHT MENU"),W/2,H-14,10,DIM,"center",600);
}
/* drawTechList used to draw the second step - one category's techniques,
   reached by pressing A on a bare word. drawCommand draws that list itself
   now, so there is no second screen to keep in sync. */
function beatMeter(d,label,sub,live,who){
  txt(label,W/2,428,18,GOLD,"center",800);
  txt(sub,W/2,455,13,live<0?"#667":INK,"center",800);
  const bx=W/2-220,bw=440,by=470, w=jugWindows(d);
  panel(bx,by,bw,22,"#0a0b0e","#3a3d45");
  cx.fillStyle="rgba(216,162,74,.22)"; cx.fillRect(bx+bw*w.o[0]/100,by+2,bw*(w.o[1]-w.o[0])/100,18);
  cx.fillStyle="rgba(216,162,74,.42)"; cx.fillRect(bx+bw*w.c[0]/100,by+2,bw*(w.c[1]-w.c[0])/100,18);
  cx.fillStyle=GOLD; cx.fillRect(bx+bw*w.p[0]/100,by+2,bw*(w.p[1]-w.p[0])/100,18);
  cx.fillStyle=INK; cx.fillRect(bx+2+(bw-8)*d.jugPos/100,by+2,4,18);
}
/* The tale of the tape. src/ui/matchup.js computes every number and every
   string; this draws them. For the AZX FORCE stand-in d.e.fid is the BORROWED
   artwork, not the opponent - passing {tf:true} makes the module ignore it,
   because printing that fighter's reach under the name AZX FORCE would be a
   lie the player cannot detect. */
function rTapeCard(d){
  const L={fid:d.p.fid, hp:d.p.hp, maxhp:d.p.maxhp};
  const R=d.tf ? {tf:true, art:d.e.fid, lv:d.e.level, hp:d.e.hp, maxhp:d.e.maxhp}
               : {fid:d.e.fid, boss:!!d.boss, lv:d.e.level, hp:d.e.hp, maxhp:d.e.maxhp};
  const o={ mode:d.ranked?"ranked":d.survival?"survival":d.daily?"daily":d.hotseat?"versus":(G.adv?"adventure":"exhibition"),
            stage:d.stage||1,
            oppRankIndex:d.ranked?(d.oppRankIndex||0):undefined,
            nemesis:!!d.nemesis, title:!!d.boss||!!d.ranked };
  const hl=tapeHeader(L,Object.assign({},o,{side:"l",self:!d.hotseat}));
  const hr=tapeHeader(R,Object.assign({},o,{side:"r",rankIndex:d.ranked?(d.oppRankIndex||0):undefined}));
  const rows=tapeRows(L,R,o), adv=tapeAdvantage(L,R,o), st=tapeStoryline(L,R,o);

  bgFill("#101318","#07080a");
  drawFighterArt(d.p.fid,150,470,300,false);
  drawFighterArt(d.boss?BOSS_ID:d.e.fid,810,470,300,true,ringSilhouette(d));
  cx.fillStyle="rgba(5,6,8,.72)"; cx.fillRect(0,0,W,H);

  txt("VS",W/2,46,26,RED,"center",800,true);
  [[hl,200],[hr,760]].forEach(pair=>{
    const hh=pair[0], x=pair[1];
    txt(hh.name,x,42,17,(hh===hr&&d.boss)?RED:INK,"center",800);
    if(hh.nick) txt(hh.nick,x,58,9.5,DIM,"center",600,true);
    if(hh.disciplines) txt(hh.disciplines,x,74,9,GOLD,"center",600);
    if(hh.archetype) txt(hh.archetype,x,88,9,AQUA,"center",600);
    if(hh.badge) txt(hh.badge,x,102,9,GOLD,"center",700);
    if(hh.record) txt((hh.recordLabel?hh.recordLabel+" ":"")+hh.record,x,116,9,DIM,"center",600);
  });

  const bw=520, bx=W/2-260;
  panel(bx,126,bw,10,"#0a0b0e","#2a2d35");
  /* an opponent the card knows nothing about draws a faint bar rather than a
     confident one - the lean is only as loud as the evidence behind it */
  cx.globalAlpha=.45+.55*adv.confidence;
  cx.fillStyle=AQUA;                  cx.fillRect(bx+1,127,(bw-2)*adv.lean,8);
  cx.fillStyle="rgba(224,58,47,.75)"; cx.fillRect(bx+1+(bw-2)*adv.lean,127,(bw-2)*(1-adv.lean),8);
  cx.globalAlpha=1;
  if(adv.reason) txt(adv.reason,W/2,150,9.5,adv.favours==="l"?AQUA:(adv.favours==="r"?RED:DIM),"center",700);

  rows.forEach((r,i)=>{
    const y=178+i*26;
    if(r.edge){ cx.fillStyle="rgba(216,162,74,.10)";
                cx.fillRect(r.edge==="l"?W/2-330:W/2+30,y-15,300,22); }
    txt(r.label,W/2,y,9.5,DIM,"center",700);
    txt(r.left ,W/2-46,y,13,r.edge==="l"?GOLD:INK,"right",r.edge==="l"?800:600);
    txt(r.right,W/2+46,y,13,r.edge==="r"?GOLD:INK,"left" ,r.edge==="r"?800:600);
  });

  // Modern 6-Axis Dual Radar Comparison
  if(typeof StatRadar!=="undefined"&&typeof StatRadar.renderComparison==="function"&&typeof BIOS!=="undefined"){
    const pBio=(BIOS[d.p.fid]&&BIOS[d.p.fid].a)||null;
    const eBio=(BIOS[d.boss?BOSS_ID:d.e.fid]&&BIOS[d.boss?BOSS_ID:d.e.fid].a)||null;
    if(pBio&&eBio){
      StatRadar.renderComparison(cx, W/2, 274, 48, pBio, eBio, {
        colorA: AQUA, fillA: "rgba(34,211,238,.20)",
        colorB: RED,  fillB: "rgba(230,57,47,.20)",
        gridColor: "rgba(255,255,255,.09)", labelColor: "#8b949e"
      });
    }
  }

  if(st&&st.line){
    panel(W/2-340,392,680,62,"rgba(10,11,14,.88)",st.key==="nemesis"?GOLD:st.key==="rival"?RED:"#252831");
    if(st.tag) txt(st.tag,W/2,408,10,st.key==="nemesis"?GOLD:RED,"center",800);
    const ln=[]; let cur="";
    String(st.line).split(" ").forEach(w=>{
      if((cur+" "+w).trim().length>78){ ln.push(cur); cur=w; } else cur=(cur+" "+w).trim(); });
    if(cur) ln.push(cur);
    ln.slice(0,3).forEach((l,i)=>txt(l,W/2,424+i*14,10,INK,"center",600));
  }

  const chips=[[LG("a","TO THE BELL"),"a",true],[LG("b","FIGHT MENU"),"b",true],
               [LG("y","DOSSIER"),"y",!d.tf&&!d.boss]].filter(c=>c[2]);
  const cwd=200, gap=18, ox=W/2-(chips.length*cwd+(chips.length-1)*gap)/2;
  chips.forEach((c,i)=>{
    const cbx=ox+i*(cwd+gap);
    panel(cbx,470,cwd,26,"rgba(10,11,14,.85)",i===0?RED:"#2a2d35");
    txt(c[0],cbx+cwd/2,487,11.5,i===0?((G.t/30|0)%2?INK:RED):DIM,"center",800);
    hot(cbx,470,cwd,26,null,()=>onKey(c[1]));
  });
  txt(o.mode+(d.ranked&&hr.badge?" - "+hr.badge:""),W/2,H-10,10,DIM,"center",700);
}
function rDuel(){
  const d=G.duel;
  if(d.ph===D.TAPE){ rTapeCard(d); return; }
  const eb = (d.ph === D.INTRO) ? entranceBeat(d.ent, d.t, motionOn()) : null;
  const zoom = (d.zoomT > 0 && motionOn()) ? 1 + 0.05 * Math.sin((d.zoomT / 20) * Math.PI) : 1;
  const sh = (d.shakeG > 0 && motionOn()) ? d.shakeG : 0;
  const cfxZoom = (typeof CombatFX !== "undefined" && motionOn()) ? CombatFX.cameraZoom : 1.0;
  const cfxPan = (typeof CombatFX !== "undefined" && motionOn()) ? CombatFX.cameraPan : { x: 0, y: 0 };
  const cfxShake = (typeof CombatFX !== "undefined" && motionOn()) ? CombatFX.shakeOffset : { x: 0, y: 0 };
  const totalZoom = zoom * cfxZoom;
  const totalPanX=cfxPan.x + cfxShake.x, totalPanY=cfxPan.y + cfxShake.y;
  cx.save();
  if(totalZoom!==1||sh||totalPanX!==0||totalPanY!==0){
    cx.translate(W/2+totalPanX, 300+totalPanY);
    cx.scale(totalZoom, totalZoom);
    if(sh){
      const rotAngle=(Math.random()-.5)*0.035*(sh/15);
      cx.rotate(rotAngle);
      cx.translate((Math.random()-.5)*sh*1.1,(Math.random()-.5)*sh*.8);
    }
    cx.translate(-W/2,-300);
  }
  {
    const venue=d.venue||((typeof pickVenue==="function")?pickVenue({boss:!!d.boss,ranked:!!d.ranked,daily:!!d.daily,stage:d.stage||1}):null);
    const crowdA=(G.crowdT>0&&motionOn())?Math.min(.34, G.crowdA*(G.crowdT/G.crowdMax)):0.10;
    const sway=(d.pos==="ROPES"||d.pos==="CORNER")?0.55+(motionOn()?0.25*Math.sin(G.t/14):0):0.12;
    if(typeof ThreeEngine!=="undefined"&&ThreeEngine.getState().initialized){
      ThreeEngine.setActiveScene("venue");
      if(typeof Venue3D!=="undefined"){
        Venue3D.setupVenue(venue?(venue.id||venue):"club");
        Venue3D.updateRopePhysics(d.pos, 1/60);
        Venue3D.updateVenueEffects(1/60);
        Venue3D.updateCamera(ThreeEngine.getCamera(), d, eb, 1/60);
      }
      if(d.ph!==D.CMD&&d.ph!==D.TECH&&typeof Card3D!=="undefined"){
        Card3D.hideHand();
      }
    } else if(typeof paintVenue==="function"){
      const v=venue||"club";
      const vid=(v&&v.id)||v;
      /* the embedded ARENA plate is the club night card; other skins are
         procedural so stage / ranked / boss actually change the room */
      paintVenue(cx,W,H,v,{
        arenaImage:(arenaReady()&&vid==="club")?ARENA:null,
        boss:!!d.boss,
        dim:eb?eb.dim:0,
        spot:(eb&&(eb.lit==="p"||eb.lit==="e"))?{x:eb.lit==="p"?200:760,r:Math.max(1,(120+220*eb.spot)*(1+eb.pulse)),pulse:eb.pulse||0}:null,
        crowdA:crowdA,
        pos:d.pos||"CENTRE",
        ropeSway:sway,
        t:(motionOn()?G.t/60:0),
        vignette:0.5
      });
    } else if(arenaReady()){
      cx.drawImage(ARENA,0,0,W,H);
      const sc=cx.createLinearGradient(0,0,0,H);
      sc.addColorStop(0,"rgba(5,6,9,.72)"); sc.addColorStop(.34,"rgba(5,6,9,.30)");
      sc.addColorStop(.62,"rgba(5,6,9,.10)"); sc.addColorStop(1,"rgba(5,6,9,.42)");
      cx.fillStyle=sc; cx.fillRect(0,0,W,H);
      if(d.boss){ cx.fillStyle="rgba(120,10,20,.16)"; cx.fillRect(0,0,W,H); }
    } else {
      bgFill(d.boss?"#150c12":"#12141a","#07080a");
      cx.fillStyle="rgba(255,255,255,.05)"; cx.fillRect(0,388,W,2);
    }
  }
  // the animation layer decides how a fighter moves; shake/lunge remain as
  // the fallback for anything that has not started an animation
  const pa=animTransform(d.p,1,motionOn()), ea=animTransform(d.e,-1,motionOn());
  /* during the walkout the lit man travels in from his own corner and the
     other waits in the dark. 280px is enough to start him off the canvas. */
  const entOff=(who)=>eb&&eb.lit===who?eb.travel*280:0;
  const entAl=(who,fallback)=>eb?(eb.lit===who||eb.lit==="both"?eb.alpha:1-eb.dim):fallback;
  const entFl=(who,fallback)=>eb&&eb.lit===who?eb.flash*10:fallback;
  drawFighterArt(d.p.fid, 200+entOff("p")+shake(d.p)+lunge(d.p,1)+pa.dx, 392+pa.dy, 300*pa.scale,
                 false, false, entAl("p",pa.alpha), entFl("p",Math.max(d.p.flash,pa.flash||0)), pa.rot||0);
  drawFighterArt(d.boss?BOSS_ID:d.e.fid, 760+entOff("e")+shake(d.e)+lunge(d.e,-1)+ea.dx, 392+ea.dy, 300*ea.scale,
                 true, ringSilhouette(d), entAl("e",ea.alpha), entFl("e",Math.max(d.e.flash,ea.flash||0)), ea.rot||0);
  
  if(motionOn()&&d.fx&&(G.t%5===0)&&typeof spectacleSpawnStatusAura==="function"){
    const pfx=200+entOff("p")+shake(d.p)+lunge(d.p,1)+pa.dx, pfy=392+pa.dy;
    const efx=760+entOff("e")+shake(d.e)+lunge(d.e,-1)+ea.dx, efy=392+ea.dy;
    if(d.p.cond&&d.p.cond.BLEEDING) spectacleSpawnStatusAura(d.fx,"BLEEDING",pfx,pfy,1);
    if(d.p.cond&&d.p.cond.STUNNED) spectacleSpawnStatusAura(d.fx,"STUNNED",pfx,pfy,1);
    if(d.p.cond&&d.p.cond.WINDED) spectacleSpawnStatusAura(d.fx,"WINDED",pfx,pfy,1);
    if((d.p.hp/d.p.maxhp)<=0.20) spectacleSpawnStatusAura(d.fx,"DESPERATION",pfx,pfy,1);

    if(d.e.cond&&d.e.cond.BLEEDING) spectacleSpawnStatusAura(d.fx,"BLEEDING",efx,efy,-1);
    if(d.e.cond&&d.e.cond.STUNNED) spectacleSpawnStatusAura(d.fx,"STUNNED",efx,efy,-1);
    if(d.e.cond&&d.e.cond.WINDED) spectacleSpawnStatusAura(d.fx,"WINDED",efx,efy,-1);
    if((d.e.hp/d.e.maxhp)<=0.20) spectacleSpawnStatusAura(d.fx,"DESPERATION",efx,efy,-1);
  }

  if(typeof spectaclePaint==="function") spectaclePaint(cx, d.fx);
  else d.fx.forEach(p=>{ cx.globalAlpha=Math.max(0,p.l/30); cx.fillStyle=p.c;
                    cx.fillRect(p.x,p.y,3,3); cx.globalAlpha=1; });
  if(typeof spectaclePaintPops==="function") spectaclePaintPops(cx, d.pops);
  if(d.p.dmgT>0) txt("-"+d.p.dmg, 200, 168-Math.max(0,(48-d.p.dmgT))*.8, 30, RED,"center",800);
  if(d.e.dmgT>0) txt("-"+d.e.dmg, 760, 168-Math.max(0,(48-d.e.dmgT))*.8, 30, RED,"center",800);
  cx.restore();

  // Modern Esports Broadcast Top-Bar HUD
  panel(16,12,384,84,"rgba(12,16,24,.85)","rgba(34,211,238,.35)",null,8);
  panel(W-400,12,384,84,"rgba(12,16,24,.85)","rgba(230,57,47,.35)",null,8);
  
  const pFighter=FIGHTERS[d.p.fid];
  const pDiscStr=(pFighter&&pFighter.disciplines&&pFighter.disciplines.length)?pFighter.disciplines.map(x=>DISCIPLINES[x]?DISCIPLINES[x].name:x).join(" / "):"MARTIAL ARTS";
  txt(pFighter.name+(d.hotseat?"  (P1)":""),28,28,13.5,INK,"left",900);
  txt(pDiscStr,28,40,8.5,AQUA,"left",700);
  hpBar(28,44,300,d.p.hp,d.p.maxhp,false,d.p.ghost);
  txt(d.p.hp,382,56,13,INK,"right",700);
  stamBar(28,62,300,d.p,false);
  focusPips(34,80,d.p,false);
  supBar(110,76,215,d.p,false);

  const eFighter=FIGHTERS[d.boss?BOSS_ID:d.e.fid];
  const eDiscStr=(eFighter&&eFighter.disciplines&&eFighter.disciplines.length)?eFighter.disciplines.map(x=>DISCIPLINES[x]?DISCIPLINES[x].name:x).join(" / "):"MARTIAL ARTS";
  const en=oppName(d)+(d.hotseat?"  (P2)":"");
  txt(en,W-28,28,13.5,d.boss?RED:INK,"right",900);
  txt(eDiscStr,W-28,40,8.5,d.boss?RED:GOLD,"right",700);
  hpBar(W-328,44,300,d.e.hp,d.e.maxhp,true,d.e.ghost);
  txt(d.e.hp,W-382,56,13,INK,"left",700);
  stamBar(W-328,62,300,d.e,true);
  focusPips(W-34,80,d.e,true);
  supBar(W-325,76,215,d.e,true);
  condChips(d.p,20,102,false); condChips(d.e,W-20,102,true);
  if(d.ph!==D.INTRO) rangeStrip(d);

  /* Broadcast Round Timer & Style Meter Centerpiece */
  if(d.attract){
    if(G.attract.banner){
      panel(W/2-82,12,164,30,"rgba(8,9,11,.82)",GOLD,null,6);
      txt(ATTRACT_CONFIG.label,W/2,33,18,GOLD,"center",800);
    }
    txt("PRESS ANY BUTTON",W/2,56,8.5,DIM,"center",700);
  } else if(d.ph!==D.INTRO){
    const rk=d.styleState&&typeof styleGradeForScore==="function"?styleGradeForScore(d.styleState.score):{grade:"D",label:"DULL",color:"#9ca3af"};
    panel(W/2-68,12,136,40,"rgba(10,13,20,.92)","rgba(34,211,238,.35)",null,8);
    /* "ROUND" was showing the adventure STAGE, so an exhibition read ROUND 1
       forever and a stage-seven fight read ROUND 7 on its opening turn. The
       thing next to a countdown clock should be the turn the clock counts. */
    const roundNum = (d.turn || 0) + 1;
    /* `d.turns` is not a field on the duel - it never has been; the counter is
       `d.turn`. So the most prominent readout in the HUD sat frozen at 03:00
       for every fight ever played, which is a good way to teach a player to
       ignore the middle of the screen. */
    const turnSec = Math.max(0, 180 - (d.turn || 0) * 12);
    const minStr = String(Math.floor(turnSec / 60)).padStart(2, "0");
    const secStr = String(turnSec % 60).padStart(2, "0");
    txt("TURN " + roundNum, W/2 - 20, 24, 9, AQUA, "center", 800);
    txt(minStr + ":" + secStr, W/2 - 20, 38, 11, INK, "center", 800);
    
    // Style Meter Badge on right of center box
    cx.fillStyle = rk.color;
    cx.fillRect(W/2 + 22, 18, 38, 28);
    txt(rk.grade, W/2 + 41, 38, 18, "#090b10", "center", 900, true);

    // Turbo Speed Toggle Chip
    const turboOn = !!d.turbo;
    const tbx = W - 116, tby = 12, tbw = 104, tbh = 24;
    panel(tbx, tby, tbw, tbh, turboOn ? "rgba(245,158,11,.22)" : "rgba(10,13,20,.85)", turboOn ? "#f59e0b" : "#374151", null, 6);
    txt(turboOn ? "\u23e9 TURBO [T]" : "\u25b6 NORMAL [T]", tbx + tbw / 2, tby + 16, 10, turboOn ? "#f59e0b" : "#9ca3af", "center", 800);
    hot(tbx, tby, tbw, tbh, null, () => {
      d.turbo = !d.turbo;
      sPick();
      if (typeof FloatingFeedback !== "undefined") {
        FloatingFeedback.add(d.turbo ? "TURBO SPEED: ON [T]" : "NORMAL SPEED [T]", W / 2, 190, "SYSTEM");
      }
    });
  }

  /* Standing challenge meter - live progress / fail state under the broadcast clock */
  if(d.fromAdv&&G.adv&&G.adv.challenge&&CHALLENGE_BY_ID[G.adv.challenge]&&d.ph!==D.INTRO){
    const c=CHALLENGE_BY_ID[G.adv.challenge];
    const done=!!G.adv.challengeDone;
    const prog=(typeof challengeProgress==="function")
      ? challengeProgress(G.adv.challenge,d.stats||{},d)
      : null;
    const broken=!!(prog&&prog.broken)||!!(d.challengeTrack&&d.challengeTrack.broken);
    const border=done?GRN:(broken?RED:AQUA);
    const fill=done?"rgba(34,197,94,.18)":(broken?"rgba(224,58,47,.2)":"rgba(34,211,238,.12)");
    panel(W/2-150,92,300,34,fill,border,null,6);
    txt(done?(G.adv.challengeMastery?"MASTERY MET":"CHALLENGE MET")
            :(broken?"CHALLENGE BROKEN":c.name.toUpperCase()),
        W/2,104,9.5,done?GRN:(broken?RED:AQUA),"center",800);
    const sub=done
      ? ((G.adv.challengeHits||1)+" HIT"+(G.adv.challengeHits===1?"":"S"))
      : (prog&&prog.label?prog.label:c.desc);
    txt(String(sub).toUpperCase(),W/2,118,8.5,INK,"center",600);
    if(prog&&!done){
      const fw=Math.max(2,Math.round(286*Math.max(0,Math.min(1,prog.frac||0))));
      cx.fillStyle=broken?RED:AQUA;
      cx.fillRect(W/2-143,122,fw,3);
    }
  }

  if(d.combo>1&&d.comboT>0){
    const cxp=d.comboBy==="p"?300:660, al=Math.min(1,d.comboT/26);
    cx.globalAlpha=al;
    txt(d.combo,cxp,196,40,GOLD,"center",800,true);
    txt("HIT CHAIN",cxp,212,10,INK,"center",800);
    cx.globalAlpha=1;
  }
  if(d.calloutT>0){
    const p=d.calloutT/64, s=26+(1-Math.min(1,p*1.6))*10;
    cx.globalAlpha=Math.min(1,p*2.2);
    txt(d.callout,W/2,250,s,GOLD,"center",800,true);
    cx.globalAlpha=1;
  }
  if(d.msg&&d.ph!==D.INTRO&&d.ph!==D.CMD&&d.ph!==D.TECH){
    txt(d.msg,W/2,198,28,INK,"center",800); txt(d.msg2,W/2,220,11.5,DIM,"center",600);
  }
  /* the rolling battle log. Four lines of 10.5px, three of them in #4f545d,
     sat unreadable over the lit ring floor. Two lines only, larger, bright,
     and haloed so they hold up against whatever the venue is doing. */
  if(d.log.length&&(d.ph===D.CMD||d.ph===D.TECH)){
    cx.save();
    cx.shadowColor="rgba(3,4,6,.95)"; cx.shadowBlur=6; cx.shadowOffsetY=1;
    /* a lesson card sits in this band for four seconds; the log steps under
       it rather than printing through it */
    const lb=d.lessonBox, ly=(lb&&lb.y<=207&&lb.y+lb.h>=178)?lb.y+lb.h+16:190;
    d.log.slice(0,2).forEach((l,i)=>txt(l,W/2,ly+i*17,12,i?"#a8adb6":INK,"center",i?600:700));
    cx.restore();
    cx.shadowColor="transparent"; cx.shadowBlur=0; cx.shadowOffsetY=0;
  }
  /* the tell is free and coarse; the read is paid and exact. Both live in the
     same band, in the same place, so the swap reads as an upgrade in situ.
     That band is docked on the command panel (top edge 398) with an opaque
     ground: at six percent alpha over the ring the rope line used to read
     straight through the text like a strikethrough. */
  if((d.ph===D.CMD||d.ph===D.TECH||d.ph===D.CHAIN)&&!d.hotseat&&!d.noTell){
    const bx=W/2-260, by=356, bw=520, bh=40;
    if(d.readShown){
      const label=d.eSuper?(d.e.sig?d.e.sig.name:"SIGNATURE"):d.eTech.name;
      /* the technique name is the thing focus was spent on, so it gets the
         big line; the caption carries the sentence. One line of
         "READ - THEY THROW <name>" at this size overruns the band on the
         longest names in the technique table. */
      panel(bx,by,bw,bh,"rgba(26,19,6,.94)",GOLD);
      txt("READ - THEY THROW",W/2,373,9.5,"#b08c3c","center",700);
      txt(label,W/2,391,15,GOLD,"center",800);
    } else {
      const it=intentFor(d);
      if(it){
        const pulse=.55+.2*Math.sin(G.t/9);
        /* the upsell only exists while there is focus to spend; with no second
           line the tell centres in the band instead of riding its top edge */
        const sell=d.p.focus>=1&&(d.ph===D.CMD||d.ph===D.TECH);
        panel(bx,by,bw,bh,"rgba(6,20,25,.92)","rgba(34,211,238,"+pulse+")");
        txt("TELL - "+it.line,W/2,sell?377:384,14,AQUA,"center",800);
        if(sell){
          txt(LG("y","READ THE EXACT TECHNIQUE (1 FOCUS)"),W/2,391,9,"#5aa8bd","center",600);
          hot(bx,by,bw,bh,null,()=>onKey("y"));
        }
      }
    }
  }

  if(d.ph===D.INTRO){
    drawEntrance(d,eb);
  } else if(d.ph===D.CMD){
    drawCommand(d,d.p,d.hotseat?"PLAYER ONE - CHOOSE":"CHOOSE YOUR ACTION");
    drawTeaching(d);
  } else if(d.ph===D.BAG){
    const bag=(G.adv&&G.adv.corner)||[];
    panel(16,398,W-32,H-406,"rgba(8,9,11,.92)","#252831");
    txt("THE CORNER BAG",30,414,11,AQUA,"left",700);
    txt("USING ONE TAKES YOUR TURN - YOU COVER UP WHILE THE CORNER WORKS",W-30,414,9,DIM,"right",600);
    bag.forEach((id,i)=>{
      const item=CORNER_ITEMS[id]; if(!item) return;
      const y=440+i*30, on=i===d.bagSel, lit=bagLit(d,item);
      if(on){ cx.fillStyle="rgba(34,211,238,.12)"; cx.fillRect(24,y-14,W-48,26); }
      txt(item.name,34,y,13,on?INK:(lit?"#b9bcc4":"#6a7078"),"left",on?800:600);
      txt(item.desc.toUpperCase(),34,y+11,8,on?DIM:"#4a4f58","left",600);
      txt(lit?"READY":"NOTHING TO FIX",W-34,y,9,lit?GRN:"#5d626c","right",700);
      hot(24,y-14,W-48,26,()=>{ d.bagSel=i; },()=>{ d.bagSel=i; onKey("a"); });
    });
    txt(LG("a","USE IT")+"      "+LG("b","BACK"),30,H-8,10.5,INK,"left",700);
  } else if(d.ph===D.TECH){
    // the legacy phase draws the one menu; duelKey folds it back on the next key
    drawCommand(d,d.p,d.hotseat?"PLAYER ONE - CHOOSE":"CHOOSE YOUR ACTION");
  } else if(d.ph===D.CHAIN){
    const opts=chainOptions(d,d.p);
    panel(16,398,W-32,H-406,"rgba(8,9,11,.92)","#252831");
    txt("COMBINATION",30,416,11,DIM,"left",700);
    txt(describeSequence(d.seq),W/2,416,13,GOLD,"center",800);
    const cost=sequenceCost(d.p,d.seq);
    const odds=Math.round(sequenceOdds(d.e,d.seq)*100);
    txt(cost+" STAM",W-30,416,11,cost>d.p.stam?RED:DIM,"right",700);
    opts.slice(0,5).forEach((tq,i)=>{
      const y=442+i*21, on=i===d.chainSel;
      if(on){ cx.fillStyle="rgba(216,162,74,.16)"; cx.fillRect(24,y-13,W-48,20); }
      txt("+ "+tq.name,32,y,12,on?INK:"#b9bcc4","left",on?800:600);
      const disc=DISCIPLINES[tq.disc];
      txt(disc?disc.name:"BASIC",300,y,9.5,on?DIM:"#5d626c","left",600);
      txt(RANGE_LABEL[tq.range]||"ANY",W-190,y,9,rangeFit(tq.range,d.range)>=1?GRN:"#8b5a4a","left",700);
      txt(tq.power||"-",W-92,y,11,INK,"right",700);
      txt(staminaCost(d.p,tq),W-30,y,10,DIM,"right",600);
      hot(24,y-13,W-48,20, ()=>{ d.chainSel=i; }, ()=>{ d.chainSel=i; onKey("a"); });
    });
    if(!opts.length) txt("NOTHING FOLLOWS THAT CLEANLY",W/2,470,12,DIM,"center",600);
    txt(d.seq.length+"/"+seqMaxLen(d)+" LINKS      "+odds+"% TO LAND THE WHOLE THING",
        W/2,H-32,11,odds>=70?GRN:odds>=45?GOLD:RED,"center",700);
    /* clickable footer: the three chain verbs are real buttons */
    const chainButtons = [
      [LG("a","ADD LINK"), "a"],
      [LG("b","EXECUTE"), "b"],
      [LG("y","CLEAR"), "y"]
    ];
    chainButtons.forEach((btn,i)=>{
      const bx=W/2-260+i*180;
      panel(bx,H-24,160,18,"rgba(10,11,14,.85)","#2a2d35");
      txt(btn[0],bx+80,H-11,9.5,DIM,"center",700);
      hot(bx,H-24,160,18,null,()=>onKey(btn[1]));
    });
  } else if(d.ph===D.PASS){
    cx.fillStyle="rgba(5,6,8,.9)"; cx.fillRect(0,0,W,H);
    txt("PASS THE DEVICE",W/2,240,34,GOLD,"center",800);
    txt("PLAYER TWO CHOOSES NEXT",W/2,276,12,DIM,"center",600);
    if((G.t/30|0)%2) txt(KH("a")+" TO CONTINUE",W/2,330,14,INK,"center",800);
  } else if(d.ph===D.CMD2){
    drawCommand(d,d.e,"PLAYER TWO - CHOOSE");
  } else if(d.ph===D.TECH2){
    drawCommand(d,d.e,"PLAYER TWO - CHOOSE");
  } else if(d.ph===D.DEFEND){
    const px=200, py=270, prog=Math.min(1,d.t/44);
    const rad=26+150*(1-prog), tgt=26+150*(1-30/44);
    const hot=d.t>=26&&d.t<=34;
    cx.save();
    cx.strokeStyle="rgba(155,232,155,.5)"; cx.lineWidth=2;
    cx.beginPath(); cx.arc(px,py,tgt,0,7); cx.stroke();
    cx.strokeStyle=hot?"#9be89b":AQUA; cx.lineWidth=hot?5:3;
    cx.beginPath(); cx.arc(px,py,rad,0,7); cx.stroke();
    cx.restore();
    panel(16,398,W-32,H-406,"rgba(8,9,11,.92)","#252831");
    txt("INCOMING - "+(d.ev?d.ev.name.toUpperCase():""),W/2,436,22,RED,"center",800,true);
    txt("TIME YOUR GUARD ("+KH("b")+") AS THE RING MEETS THE TARGET",W/2,466,15,INK,"center",800);
    txt(d.lessonFight?"HIT THE WINDOW. PRESS ON THE MARK.":"PERFECT GUARD CUTS 58% AND BANKS FOCUS",
        W/2,492,d.lessonFight?16:13,d.lessonFight?GOLD:INK,"center",800);

  } else if(d.ph===D.SUPER){
    const who=d.supFor==="p"?d.p:d.e, tech=who.sig;
    const live=jugTierAt(d,d.jugPos);
    panel(16,398,W-32,H-406,"rgba(8,9,11,.92)","#252831");
    beatMeter(d, (d.supFor==="p"?"YOUR SIGNATURE":"OPPONENT SIGNATURE")+"  -  BEAT "+(d.supBeat+1)+"/3",
              tech?tech.name:"FINISHER", live, who);
    txt(d.supFor==="p"||d.hotseat?"PRESS "+KH("a")+" ON EACH BEAT":"...",W/2,H-14,11,DIM,"center",700);
    for(let i=0;i<3;i++){
      cx.beginPath(); cx.arc(W/2-22+i*22,414,6,0,7);
      if(i<d.supHits){ cx.fillStyle=GOLD; cx.fill(); }
      else { cx.strokeStyle=i<d.supBeat?"#7a3a34":"#4a4d55"; cx.lineWidth=1.5; cx.stroke(); }
    }
  } else if(d.ph===D.JUGGLE||d.ph===D.JUGRES){
    const mine=d.jugFor>0, side=mine?d.p:d.e;
    const controllable=mine||(d.hotseat&&d.jugFor<0);
    const live=(d.ph===D.JUGGLE)?jugTierAt(d,d.jugPos):d.jugTier;
    panel(16,398,W-32,H-406,"rgba(8,9,11,.92)","#252831");
    if(d.ph===D.JUGGLE){
      beatMeter(d, (mine?"AIR COMBO":(d.hotseat?"PLAYER TWO - AIR COMBO":"YOU'RE AIRBORNE"))
                 +"  -  BEAT "+(d.jugBeat+1)+"/3",
                live<0?"MISS":("+"+Math.max(3,Math.round(airDmgFor(side,live)*(.5+.2*(d.jugChain+1))))),
                live, side);
      txt(controllable?("PRESS "+KH("a")+(d.jugSlow?"   (SLOWED)":"   "+LG("y","SLOW (1 FOCUS)"))):"...",W/2,H-14,11,DIM,"center",700);
    } else {
      txt(d.jugTotal>0?d.jugChain+" HIT AIR COMBO":"COMBO OVER",W/2,452,22,GOLD,"center",800);
      if(d.jugTotal>0) txt("+"+d.jugTotal,W/2,486,30,INK,"center",800);
    }
  } else if(d.ph===D.EXEC||d.ph===D.TURNEND){
    panel(16,398,W-32,H-406,"rgba(8,9,11,.92)","#252831");
    d.log.forEach((l,i)=>txt(l,W/2,432+i*22,i?12:15,i?"#6a6f79":INK,"center",i?600:800));
  } else if(d.ph===D.MENU){
    cx.fillStyle="rgba(5,6,8,.86)"; cx.fillRect(0,0,W,H);
    txt("FIGHT MENU",W/2,150,30,GOLD,"center",800,true);
    txt(FIGHTERS[d.p.fid].name.toUpperCase()+"   VS   "+oppName(d).toUpperCase(),W/2,178,12,DIM,"center",600);
    FIGHT_MENU.forEach((s,i)=>{
      const y=240+i*46, on=i===d.menuSel;
      if(on){ cx.fillStyle="rgba(224,58,47,.16)"; cx.fillRect(W/2-200,y-24,400,38); }
      const label=(i===2&&d.quitArm)?"PRESS "+KH("a")+" AGAIN TO FORFEIT":s;
      txt(label,W/2,y,17,on?(i===2?RED:INK):"#7a7f88","center",800);
      hot(W/2-200,y-24,400,38,()=>{ if(d.menuSel!==i){ d.menuSel=i; d.quitArm=0; } },
          ()=>{ d.menuSel=i; onKey("a"); });
    });
    if(d.menuSel===2) txt(d.ranked?"A FORFEIT COUNTS AS A RANKED LOSS":"A FORFEIT COUNTS AS A DEFEAT",
                          W/2,398,11,DIM,"center",600);
    txt(LG("b","RESUME THE FIGHT"),W/2,H-24,11,DIM,"center",700);
  } else if(d.ph===D.END){
    cx.fillStyle="rgba(5,6,8,.7)"; cx.fillRect(0,0,W,H);
    /* the repel leaves the player standing, so p.hp>0 is no longer the whole
       question - endDuel asks it the same way */
    const word=duelOutcomeWord(d);
    const win=word==="K.O."||word==="PLAYER ONE WINS";
    txt(word, W/2,250,win||d.hotseat?58:(d.repel?48:64),win?INK:RED,"center",800,true);
    txt("YOU "+Math.max(0,Math.round(d.p.hp))+"    OPPONENT "+Math.max(0,Math.round(d.e.hp)),
        W/2,312,13,DIM,"center",700);
    if(d.repel) txt("THE PATROL TOOK THE BETTER OF THE EXCHANGE",W/2,290,13,DIM,"center",700);
    if(win&&!d.p.tookDamage) txt("PERFECT",W/2,290,20,GOLD,"center",800);
    if((G.t/30|0)%2) txt("PRESS "+KH("a"),W/2,340,14,INK,"center",800);
  }
}
/* mastery and titles land under every result, whatever the mode - this is
   the "that run still counted" moment */
/* WHAT THE CORNER WOULD TELL YOU. AICoach.analyzeBout already graded the fight
   on four axes and wrote three specific lines about it; this is the only place
   that has ever shown them. Deliberately only on a defeat: after a win the
   player does not need correcting, and the screen has a payout to give. */
/* TEACHING, WHERE THE THING BEING TAUGHT IS ON SCREEN.

   Every combat concept in this game - the range ladder, priority before speed,
   the stamina budget, guard banking focus, the signature arming at half a bar,
   what a status condition actually takes away - lived in HOW_TOPICS.fight,
   which can only be opened from inside a fight, from a menu a new player does
   not know exists. So the answer to "how does this work" was reachable only by
   somebody who already knew.

   These draw over the arena during the command phase, which is the moment the
   player is asking the question. Neither takes input and neither blocks: a
   lesson shows for about four seconds the first time its trigger fires and
   marks itself seen, and the tip is one line that changes with the fight. */
/* WHERE A LESSON CARD SITS. Never over the fighters: the widest roster art is
   229px at the arena's 300px height, centred at x 200 and x 760, so the band
   between them runs from x 315 to x 645. Every card lives in that band, under
   the range strip (bottom edge 126) and the position line (152). The range
   lesson is anchored to a HUD element: the caret on its top edge sits under
   the lit range cell. The card used to be 472 wide at y 168 - across both
   fighters' faces. */
const LESSON_BOX={x:W/2-160,y:160,w:320};
function lessonBox(lesson){
  const n=Math.min(4,((lesson&&lesson.lines)||[]).length);
  return {x:LESSON_BOX.x,y:LESSON_BOX.y,w:LESSON_BOX.w,h:44+n*16,anchor:(lesson&&lesson.anchor)||"log"};
}
/* the technique the cursor is on - null on the bag tab or an empty list */
function cursorTech(d){
  if(d.ph!==D.CMD||cmdTabKey(d,d.p)==="BAG") return null;
  const list=menuTechsFor(d,d.p);
  if(!list.length) return null;
  return list[cmdFocus(d,d.p,list)]||null;
}
function drawTeaching(d){
  if(typeof Onboarding==="undefined"||d.hotseat||d.attract) return;
  /* the range lesson is only true while the cursor is on a technique that
     does not belong to the range the fight is in - hand that over */
  const tech=cursorTech(d);
  /* the labels come from the same table the keypress is resolved through, so
     a lesson can never name a key that does nothing */
  const octx={scene:"DUEL",duel:d,turn:d.turn,mode:d.ranked?"ranked":(d.tower?"tower":"fight"),
              tech:tech,fit:tech?rangeFit(tech.range,d.range):1,
              keys:{a:KH("a"),b:KH("b"),y:KH("y")}};
  const lesson=Onboarding.pendingLesson(SAVE,octx);
  d.lessonBox=null;
  if(lesson){
    /* latch it to this bout so the four seconds belong to this lesson rather
       than restarting every time the command phase is re-entered */
    if(d.lessonId!==lesson.id){ d.lessonId=lesson.id; d.lessonT=0; }
    d.lessonT=(d.lessonT||0)+1;
    if(d.lessonT<260){
      const lines=(lesson.lines||[]).slice(0,4);
      const b=lessonBox(lesson), y0=b.y;
      d.lessonBox=b;
      cx.globalAlpha=d.lessonT>220?Math.max(0,(260-d.lessonT)/40):1;
      if(b.anchor==="range"){
        /* the caret under the lit range cell - same geometry as rangeStrip */
        const w=94, gap=6, total=RANGE_ORDER.length*(w+gap)-gap, ox=(W-total)/2;
        const ix=Math.max(0,RANGE_ORDER.indexOf(d.range)), cxr=ox+ix*(w+gap)+w/2;
        cx.fillStyle=AQUA; cx.beginPath();
        cx.moveTo(cxr,y0-8); cx.lineTo(cxr-6,y0+1); cx.lineTo(cxr+6,y0+1); cx.closePath(); cx.fill();
      }
      panel(b.x,y0,b.w,b.h,"rgba(8,11,18,.94)",AQUA,"rgba(255,255,255,.06)",8);
      txt(String(lesson.title||"").toUpperCase(),W/2,y0+22,12.5,AQUA,"center",900);
      lines.forEach((ln,i)=>txt(String(ln),W/2,y0+44+i*16,11,"#c8ccd4","center",600));
      cx.globalAlpha=1;
      return;                       // one thing at a time
    }
    Onboarding.markSeen(SAVE,lesson.id);
    persist();
    d.lessonId=null;
  }
  if(d.lessonFight){
    const beat=teachBeat(d);
    if(beat){
      panel(W/2-310,312,620,40,"rgba(8,11,18,.94)",AQUA,null,6);
      txt(beat.line,W/2,d.tellGrade?328:336,13,INK,"center",800);
      if(d.tellGrade){
        const good=d.tellGrade.indexOf("ANSWERED")===0;
        const bad=d.tellGrade.indexOf("BAD")===0;
        txt(d.tellGrade,W/2,346,12,good?GRN:(bad?RED:GOLD),"center",800);
      }
      return;
    }
  }
  const tip=Onboarding.coachTip(d,d.p,octx);
  if(tip&&tip.text){
    const tone=tip.tone==="urgent"?RED:tip.tone==="warn"?GOLD:tip.tone==="good"?GRN:AQUA;
    const t=String(tip.text).toUpperCase();
    /* a plate, because this sits over the arena floor and unbacked text at
       10px is unreadable against a lit canvas */
    const w=Math.min(W-80,t.length*6.2+28);
    panel(W/2-w/2,332,w,18,"rgba(8,11,18,.88)",tone,null,4);
    txt(t,W/2,345,10,tone,"center",800);
  }
}
function drawCoachNotes(y0){
  const a=G.lastCoach;
  if(!a||!a.bullets||!a.bullets.length) return;
  const lines=a.bullets.slice(0,3);
  const h=26+lines.length*15;
  panel(W/2-260,y0,520,h,"rgba(10,13,20,.92)","#2a2d35",null,6);
  txt("FROM YOUR CORNER"+(a.overallGrade?"   -   "+a.overallGrade:""),
      W/2-244,y0+16,9.5,AQUA,"left",800);
  lines.forEach((b,i)=>{
    const line=String(b||"");
    txt("-  "+(line.length>72?line.slice(0,70)+"..":line),
        W/2-244,y0+34+i*15,10.5,"#b9bcc4","left",600);
  });
}
function drawPayout(){
  const P=G.payout;
  if(G.payPurse){
    cx.save();
    if(G.lastFightPay && G.lastFightPay.breakdown){
      cx.fillStyle="rgba(216,162,74,.14)";
      cx.fillRect(W/2-250,H-128,500,35);
      cx.strokeStyle="rgba(216,162,74,.4)";
      cx.lineWidth=1;
      cx.strokeRect(W/2-250.5,H-128.5,501,36);
      const fb=G.lastFightPay.breakdown;
      const bText="SHOW: $"+fb.show+(fb.win?" \u00b7 WIN: +$"+fb.win:"")+(fb.finish?" \u00b7 FINISH: +$"+fb.finish:"")+(fb.potn?" \u00b7 POTN: +$"+fb.potn:"")+(fb.fotn?" \u00b7 FOTN: +$"+fb.fotn:"");
      const dText="CAMP/CORNER (-20%): -$"+G.lastFightPay.deductions.total+" \u00b7 NET PURSE: +$"+G.payPurse;
      txt(bText,W/2,H-115,9.5,GOLD,"center",700);
      txt(dText+(G.lastFightPay.eventTokens?" \u00b7 +"+G.lastFightPay.eventTokens+" EVENT TOKENS":""),W/2,H-101,9.5,"#4ade80","center",700);
    } else {
      cx.fillStyle="rgba(216,162,74,.14)";
      cx.fillRect(W/2-210,H-118,420,24);
      cx.strokeStyle="rgba(216,162,74,.4)";
      cx.lineWidth=1;
      cx.strokeRect(W/2-210.5,H-118.5,421,25);
      txt("FIGHT PURSE: +$"+G.payPurse+(G.payRevenge?"  -  GRUDGE REVENGE BOUNTY":"")+"  -  SPEND IT AT THE GYM",W/2,H-105,12,GOLD,"center",800);
    }
    cx.restore();
  }
  if(!P) return;
  if(P.mastery){
    const m=P.mastery;
    /* canvas text, not markup - txt() draws the string verbatim, so an HTML
       entity here rendered as the literal "&MIDDOT;" across the result screen */
    const beltHint=(!m.levelled&&m.to&&m.to.level===0)?"   -   40 XP REACHES WHITE BELT AND +1 FOCUS":"";
    txt("+"+m.gained+" MASTERY XP   -   "+m.to.name.toUpperCase()
        +(m.levelled?"   -   NEW BELT UNLOCKED!":beltHint),
        W/2,H-84,12,m.levelled?GOLD:INK,"center",m.levelled?800:700);
  }
  if(P.titles&&P.titles.length)
    txt("TITLE EARNED: "+P.titles.map(id=>titleOf(id).toUpperCase()).join(", "),
        W/2,H-64,12,GOLD,"center",800);
  /* the second axis, on the row under the first. Only the arts that actually
     earned something this fight are named, best first, and a grade crossed is
     the one thing here worth shouting about. */
  if(P.disc&&P.disc.total>0){
    const up=P.disc.levelled&&P.disc.levelled.length?P.disc.levelled[0]:null;
    const named=P.disc.ranks.slice().sort((x,y)=>y.gained-x.gained).slice(0,2)
      .map(r=>((DISCIPLINES[r.disc]&&DISCIPLINES[r.disc].name)||r.disc).toUpperCase()+" +"+r.gained);
    txt("ART TRAINED: "+named.join("   ")
        +(up?("   -   "+((DISCIPLINES[up.disc]&&DISCIPLINES[up.disc].name)||up.disc).toUpperCase()
              +" IS NOW "+up.to.name.toUpperCase()):""),
        W/2,H-44,11,up?GOLD:DIM,"center",up?800:600);
  }
  if(G.payNemesis)
    txt("GRUDGE SETTLED - "+FIGHTERS[G.payNemesis.fid].name.toUpperCase()
        +"   "+G.payNemesis.wins+"-"+G.payNemesis.losses+" BETWEEN YOU",
        W/2,H-24,11,GOLD,"center",800);
}
/* THE PATROL CARD. One exchange against a silhouette is not a fight night:
   no method line, no grade slam, no stat tab, no brag card, no parade of
   titles. The result, the points, the purse, the one title a patrol may hand
   out, and the way on. */
function rewardGuideLines(){
  return [
    "CARD POINTS BUY A LEVEL AT A TEMPLE. 10 POINTS IS 1 LEVEL.",
    "PURSE IS SPENT AT THE GYM: CUT A TECHNIQUE, DRILL ONE, OR BUY CORNER KIT.",
    "MASTERY XP RAISES THE BELT. 40 REACHES WHITE AND STARTS YOU WITH FOCUS."
  ];
}
function drawPatrolCard(r){
  const P=G.payout||{};
  txt("PATROL CLEARED",W/2,150,34,INK,"center",800,true);
  if(r.perfect) txt("PERFECT",W/2,176,16,GOLD,"center",800);
  panel(W/2-280,188,560,250,"rgba(10,11,14,.94)","#3a4254",null,6);
  txt(r.msg,W/2,214,15,INK,"center",800);
  txt("SPEND CARD POINTS AT A TEMPLE. 10 POINTS IS 1 LEVEL.",W/2,236,13,AQUA,"center",700);
  txt("PURSE  +$"+(G.payPurse||0)+"   -   SPEND IT AT THE GYM",W/2,264,14,GOLD,"center",800);
  txt("THE GYM SELLS A CUT, A DRILL, AND CORNER KIT.",W/2,286,13,INK,"center",700);
  if(P.mastery){
    const beltHint=(!P.mastery.levelled&&P.mastery.to&&P.mastery.to.level===0)
      ?"   -   40 XP REACHES WHITE BELT":"";
    txt("+"+P.mastery.gained+" MASTERY XP   -   "+P.mastery.to.name.toUpperCase()+beltHint,
        W/2,314,13,P.mastery.levelled?GOLD:INK,"center",P.mastery.levelled?800:700);
    txt("THE BELT IS PERMANENT. WHITE STARTS THE NEXT FIGHT WITH FOCUS.",W/2,336,13,INK,"center",700);
  }
  if(P.titles&&P.titles.length)
    txt("TITLE EARNED: "+titleOf(P.titles[0]).toUpperCase(),W/2,364,14,GOLD,"center",800);
  const cer=G.cer;
  if((!cer||ceremonyPhase(cer,"prompt")>0)&&(G.t/30|0)%2)
    txt("PRESS "+LG("a","CONTINUE"),W/2,420,16,INK,"center",800);
}
function rResult(){
  const r=G.result;
  if(G.resTab===1&&G.lastStats){ rFightStats(); return; }
  bgFill("#0e1014","#08090b");
  if(r.kind==="win"&&resultIsShort(r)){ drawPatrolCard(r); return; }
  if(r.kind==="win"){
    txt("VICTORY",W/2,170,44,INK,"center",800,true);
    if(r.perfect) txt("PERFECT",W/2,205,18,GOLD,"center",800);
    txt(r.msg,W/2,240,14,DIM,"center",600);
    if(r.unlockName){
      panel(W/2-240,270,480,70,"rgba(216,162,74,.08)",GOLD);
      txt("NEW FIGHTER UNLOCKED",W/2,298,12,GOLD,"center",800);
      txt(r.unlockName,W/2,326,20,INK,"center",800);
    } else if(r.ladder) drawLadderDelta(r.ladder, r.perfect?255:270);
  } else if(r.kind==="steps"){
    txt("OUT OF STEPS",W/2,190,36,RED,"center",800);
    txt("-"+r.toll+" HP - THE FIELD RE-ROLLS",W/2,228,14,INK,"center",700);
    txt("CLEARED FIGHTERS, TEMPLES AND CARDS DO NOT COME BACK",W/2,252,11.5,DIM,"center",600);
  } else if(r.kind==="repel"){
    txt("DRIVEN OFF",W/2,190,36,RED,"center",800);
    txt("-"+r.lost+" HP AND -"+r.toll+" STEPS - THEY HOLD THE GROUND",W/2,228,14,INK,"center",700);
    txt("ONE EXCHANGE IS ALL A PATROL GETS - AND ALL YOU GET",W/2,252,11.5,DIM,"center",600);
  } else if(r.kind==="ko"){
    txt("YOU WERE K.O.'D",W/2,190,36,RED,"center",800);
    /* see drawCoachNotes - a loss is the one moment a player is actually
       asking what they did wrong */
    if(r.cont){
      txt("CONTINUES LEFT: "+(G.adv?G.adv.continues:0),W/2,232,15,GOLD,"center",800);
      txt("A CONTINUE RESTARTS THE FIELD AT 60% HP",W/2,256,11.5,DIM,"center",600);
      if(r.ladder) drawLadderDelta(r.ladder, 278);
      if((G.t/30|0)%2) txt(LG("a","CONTINUE")+"      "+LG("b","END THE RUN"),W/2,360,14,INK,"center",800);
      return;
    }
    txt("THE RUN ENDS - UNLOCKS AND RECORDS ARE KEPT",W/2,232,13,DIM,"center",600);
    if(r.ladder) drawLadderDelta(r.ladder, 250);
    drawCoachNotes(r.ladder?340:258);
  } else if(r.kind==="survwin"){
    txt("ROUND "+r.streak+" CLEARED",W/2,190,36,GOLD,"center",800);
    txt("+22% HP RESTORED - THE NEXT ONE HITS HARDER",W/2,228,12.5,DIM,"center",600);
    txt("BEST STREAK "+(SAVE.rec.bestSurv||0),W/2,254,12,INK,"center",700);
    if(r.ladder) drawLadderDelta(r.ladder, 278);
  } else if(r.kind==="survend"){
    txt("SURVIVAL OVER",W/2,190,36,RED,"center",800);
    txt("STREAK "+r.streak+" - BEST "+(SAVE.rec.bestSurv||0),W/2,228,14,DIM,"center",600);
    if(r.ladder) drawLadderDelta(r.ladder, 260);
  } else if(r.kind==="dailywin"||r.kind==="dailyloss"){
    const win=r.kind==="dailywin";
    txt("DAILY GAUNTLET",W/2,132,20,AQUA,"center",800);
    txt(win?"CLEARED":"FAILED",W/2,178,44,win?INK:RED,"center",800,true);
    panel(W/2-240,206,480,90,"rgba(10,11,14,.9)",AQUA);
    txt("SCORE",W/2-222,232,10,DIM,"left",700);
    txt(r.score,W/2-222,262,28,GOLD,"left",800);
    if(r.record) txt("PERSONAL BEST",W/2-222,282,10,GRN,"left",800);
    txt("STREAK",W/2+222,232,10,DIM,"right",700);
    txt(r.streak+(r.streak===1?" DAY":" DAYS"),W/2+222,262,26,AQUA,"right",800);
    txt("BEST "+r.best,W/2+222,282,10,DIM,"right",700);
    txt("COME BACK TOMORROW FOR A NEW ONE",W/2,320,11,DIM,"center",600);
  } else if(r.kind==="rankwin"||r.kind==="rankloss"){
    const win=r.kind==="rankwin";
    txt(win?"RANKED WIN":"RANKED LOSS",W/2,140,40,win?INK:RED,"center",800,true);
    if(r.upset&&win) txt("UPSET - THEY OUTRANKED YOU",W/2,168,12,GOLD,"center",800);
    txt("VS "+r.oppName.toUpperCase()+"  -  "+r.oppRank.title.toUpperCase(),W/2,192,12,DIM,"center",600);
    panel(W/2-250,214,500,96,"rgba(10,11,14,.9)",r.rankAfter.color);
    txt("GRADE",W/2-232,238,10,DIM,"left",700);
    txt(r.rankAfter.title.toUpperCase(),W/2-232,266,26,r.rankAfter.color,"left",800);
    txt(DIVISION[r.rankAfter.division].name.toUpperCase(),W/2-232,286,10,DIM,"left",700);
    txt("PROMOTION POINTS",W/2+232,238,10,DIM,"right",700);
    txt((r.delta>=0?"+":"")+r.delta,W/2+232,266,26,r.delta>=0?GRN:RED,"right",800);
    const mine=myRanking();
    txt(mine.promotionPoints+" TOTAL",W/2+232,286,10,DIM,"right",700);
    const bx=W/2-232, bw=464;
    panel(bx,296,bw,8,"#0a0b0e","#2a2d35");
    cx.fillStyle=r.rankAfter.color; cx.fillRect(bx+1,297,(bw-2)*mine.progress,6);
    if(r.promoted){ txt("PROMOTED",W/2,338,22,GOLD,"center",800,true);
                    txt(r.rankBefore.title.toUpperCase()+"  ->  "+r.rankAfter.title.toUpperCase(),W/2,358,12,INK,"center",700); }
    else if(r.demoted) txt("DEMOTED TO "+r.rankAfter.title.toUpperCase(),W/2,338,16,RED,"center",800);
    else if(r.held||r.pendingBelt)
      txt("BELT TEST READY - ENTER RANKED TO TAKE THE EXAM",W/2,338,12,GOLD,"center",800);
    else if(r.beltPass)
      txt("BELT TEST CLEARED",W/2,338,16,GOLD,"center",800);
    if(r.kind==="rankloss") drawCoachNotes(378);
    else if(!(r.promoted||r.demoted||r.held||r.beltPass))
      txt(mine.pointsToNext+" POINTS TO "+(mine.nextRank?mine.nextRank.title.toUpperCase():"THE TOP"),
             W/2,338,12,DIM,"center",700);
    /* THE SESSION LINE, AND WHERE IT IS ALLOWED TO SIT. One line at 208, in the
       gap between the opponent line (192) and the top of the grade panel (214).
       Everything below the panel is spoken for: 338 and 358 carry the promotion
       on a promotion, and the band from 370 down belongs to the method-of-
       victory line and the grade stamp. What A and B do is on the button hints
       at the foot of the screen, so it is not repeated here - only the record,
       and the one ending only the top of the ladder can write. */
    if(r.session){
      const sess=r.session;
      txt("SESSION   "+sess.wins+"W "+sess.losses+"L   -   "
          +sess.bouts+(sess.bouts===1?" MATCH":" MATCHES")
          +(r.sessionDone?"   -   THE LADDER IS CLIMBED":""),
          W/2,208,10,r.sessionDone?GOLD:AQUA,"center",700);
    }
  } else if(r.kind==="towerwin"||r.kind==="towerloss"){
    const win=r.kind==="towerwin";
    txt("HEAVENS TOWER - FLOOR "+r.floor,W/2,132,20,GOLD,"center",800);
    txt(win?"FLOOR CLEARED":"FLOOR DEFEAT",W/2,178,40,win?INK:RED,"center",800,true);
    if(win){
      panel(W/2-240,210,480,80,"rgba(10,11,14,.9)",GOLD);
      txt("REWARD: +"+r.reward+" PURSE COINS",W/2,246,16,GOLD,"center",800);
      txt(G.tower?"PRESS "+KH("a")+" FOR THE NEXT FLOOR OR "+KH("b")+" FOR THE TOWER LOBBY"
                 :"NEXT FLOOR UNLOCKED ON THE HEAVENS TOWER CLIMB",W/2,272,11,DIM,"center",600);
    } else {
      panel(W/2-240,210,480,70,"rgba(10,11,14,.9)",RED);
      txt("DEFEATED ON FLOOR "+r.floor,W/2,245,15,RED,"center",800);
      txt("PRESS "+KH("a")+" TO RETRY OR "+KH("b")+" FOR TOWER LOBBY",W/2,268,11,DIM,"center",600);
      drawCoachNotes(292);
    }
  } else if(r.kind==="gauntletvictory"){
    txt("GRAND GAUNTLET VICTORY",W/2,128,20,GOLD,"center",800);
    txt("APEX SOVEREIGN CONQUERED",W/2,172,36,GOLD,"center",800,true);
    panel(W/2-250,206,500,92,"rgba(10,11,14,.92)",GOLD);
    txt("CHAMPIONSHIP SCORE: "+r.score+" PTS",W/2,238,19,GOLD,"center",800);
    txt("REWARD: +500 RENOWN   |   +500 PURSE COINS   |   CHAMPION TROPHY",W/2,268,11.5,AQUA,"center",700);
    txt("PRESS "+KH("a")+" FOR GAUNTLET LOBBY (CLAIM OR ENTER ENDLESS OVERDRIVE)",W/2,318,11,INK,"center",700);
  } else if(r.kind==="endlesswin"||r.kind==="endlessloss"){
    const win=r.kind==="endlesswin";
    txt("SURVIVAL GAUNTLET",W/2,132,20,RED,"center",800);
    txt(win?("WAVE "+r.wave+" CLEARED"):"GAUNTLET CONCLUDED",W/2,178,38,win?INK:RED,"center",800,true);
    panel(W/2-240,210,480,80,"rgba(10,11,14,.9)",RED);
    txt("SCORE: "+r.score+" PTS",W/2-220,248,18,GOLD,"left",800);
    txt("HIGH WAVE: "+(SAVE.rec.bestEndless||r.wave),W/2+220,248,16,AQUA,"right",700);
  } else if(r.kind==="weekly_grand_win"||r.kind==="weekly_tier_win"||r.kind==="weekly_respite"||r.kind==="weekly_loss"||r.kind==="weeklywin"||r.kind==="weeklyloss"){
    const isGrand = r.kind==="weekly_grand_win";
    const isTierWin = r.kind==="weekly_tier_win" || r.kind==="weeklywin";
    const isRespite = r.kind==="weekly_respite";
    const col = (r.mutator && r.mutator.color) || AQUA;
    txt("WEEKLY MUTATOR CHAMPIONSHIP", W/2, 132, 18, col, "center", 800);
    if(isGrand){
      txt("GRAND WEEKLY CROWN VICTORY!", W/2, 172, 26, GOLD, "center", 900, true);
      txt("APEX WEEKLY SOVEREIGN CONQUERED", W/2, 196, 12, INK, "center", 700);
    } else if(isTierWin){
      txt("TIER " + (r.tier || 1) + " CLEARED", W/2, 178, 36, INK, "center", 800, true);
    } else if(isRespite){
      txt("CORNER RESPITE ACTIVATED", W/2, 178, 32, "#38bdf8", "center", 800, true);
    } else {
      txt("TOURNAMENT CONCLUDED", W/2, 178, 36, RED, "center", 800, true);
    }
    panel(W/2-240, 210, 480, 80, "rgba(10,11,14,.9)", isGrand ? GOLD : (isRespite ? "#38bdf8" : (isTierWin ? col : RED)));
    txt("SCORE: " + (r.score || 0) + " PTS", W/2-220, 248, 18, GOLD, "left", 800);
    if(isRespite){
      txt("RESPITES REMAINING: " + (r.respitesLeft || 0), W/2+220, 248, 14, "#38bdf8", "right", 700);
    } else {
      txt("HIGH SCORE: " + ((SAVE.weekly && SAVE.weekly.bestScore) || r.score || 0), W/2+220, 248, 14, AQUA, "right", 700);
    }
  } else if(r.kind==="dojoend"){
    txt("DOJO PRACTICE",W/2,140,22,AQUA,"center",800);
    txt("SPARRING SESSION CONCLUDED",W/2,186,34,INK,"center",800,true);
    panel(W/2-240,214,480,70,"rgba(10,11,14,.9)",AQUA);
    txt("FRAME DATA & STRATEGY RECORDED",W/2,252,14,GOLD,"center",800);
  } else if(r.kind==="survend"){
    txt("SURVIVAL OVER",W/2,190,36,RED,"center",800);
    txt("STREAK "+r.streak+"   -   BEST "+(SAVE.rec.bestSurv||0),W/2,232,16,GOLD,"center",800);
  } else {
    const p1=r.kind==="vswin";
    txt(r.hotseat?(p1?"PLAYER ONE WINS":"PLAYER TWO WINS"):(p1?"VICTORY":"DEFEAT"),
        W/2,210,42,p1?INK:RED,"center",800,true);
    if(r.exhibition){
      const ser=r.series;
      if(ser&&ser.format==="bo3"){
        txt("SERIES  "+ser.score[0]+" - "+ser.score[1]
            +(ser.done?(ser.winner==="p"?"  \u00b7  YOU TAKE THE SERIES":"  \u00b7  SERIES LOST"):"  \u00b7  BEST OF 3"),
            W/2,248,14,GOLD,"center",800);
      }
      if(typeof ExhibitionMode!=="undefined"){
        txt(ExhibitionMode.careerLine(SAVE),W/2,268,11,DIM,"center",600);
        const last=ExhibitionMode.getLastBout&&ExhibitionMode.getLastBout();
        if(last){
          const code=ExhibitionMode.encodeBout(last.p1,last.p2,last.settings);
          if(code){
            G.vsCodeMsg=code;
            txt("BOUT CODE",W/2,288,9,DIM,"center",600);
            txt(code.length>54?code.slice(0,52)+"..":code,W/2,302,9,AQUA,"center",600);
          }
        }
      }
    }
  }
  if(G.bountyResult&&G.bountyResult.ok){
    panel(W/2-220,335,440,26,"rgba(16,185,129,.15)",GRN);
    txt("BOUNTY MET: "+G.bountyResult.title.toUpperCase(),W/2,352,11,GRN,"center",800);
  }
  /* the y-band 370-405 is empty on every result kind - the deepest existing
     draw is the ranked promotion line at 358 and PRESS A sits at 420 */
  const cer=G.cer;
  if(G.lastStats&&r.kind!=="steps"){
    const mv=methodOfVictory(G.lastStats,{hotseat:!!r.hotseat});
    const ma=cer?ceremonyPhase(cer,"method"):1;
    if(ma>0){ cx.globalAlpha=ma;
      txt(mv.line,W/2,374,15,mv.tone==="good"?GOLD:RED,"center",800);
      cx.globalAlpha=1; }
    const ga=cer?ceremonyPhase(cer,"grade"):1;
    if(ga>0){
      const fg=fightGrade(G.lastStats);
      const gradeColors={S:GOLD, A:GOLD, B:AQUA, C:"#f59e0b", D:"#f97316", E:"#ef4444", F:RED};
      const gCol=gradeColors[fg.grade]||GOLD;
      const slamScale=ga < 1.0 ? 1.0 + (1.0 - ga) * 2.5 : 1.0;

      cx.save();
      cx.translate(W/2, 404);
      if(slamScale !== 1.0) cx.scale(slamScale, slamScale);
      cx.rotate(-0.10);
      cx.globalAlpha = Math.min(1.0, ga * 1.5);
      panel(-44, -22, 88, 44, "rgba(8,11,16,.92)", gCol, "rgba(255,255,255,.12)", 6);
      cx.strokeStyle = gCol; cx.lineWidth = 2; cx.strokeRect(-40, -18, 80, 36);
      txt(fg.grade, 0, 7, 28, gCol, "center", 900, true);
      cx.restore();

      if(!G.gradeSlammed && ga >= 0.85){
        G.gradeSlammed = true;
        if(typeof CombatFX!=="undefined"){
          CombatFX.triggerShake(12, 16);
          CombatFX.spawnSparks(W/2, 404, 24, gCol);
        }
      }

      cx.globalAlpha=ga;
      txt(fg.note,W/2,440,11,DIM,"center",600);
      cx.globalAlpha=1;
    }
    if(!resultIsShort(r)){
      txt(LG("y","FIGHT STATS"),W/2,H-14,10,DIM,"center",700);
      hot(W/2-90,H-28,180,20,()=>{},()=>{ G.resTab=1; sPick(); });
    }
  }
  drawPayout();
  /* the brag card is a fight-night souvenir; a patrol does not print one, and
     onKey refuses X there, so the button must not be on screen either */
  if(!resultIsShort(r)){
    const bragBtnX=W/2-105, bragBtnY=H-46, bragBtnW=210, bragBtnH=22;
    panel(bragBtnX,bragBtnY,bragBtnW,bragBtnH,"rgba(10,11,14,.88)",GOLD,null,4);
    txt("\ud83c\udfc6 EXPORT BRAG CARD [X]",bragBtnX+bragBtnW/2,bragBtnY+15,10,GOLD,"center",800);
    hot(bragBtnX,bragBtnY,bragBtnW,bragBtnH,null,()=>{ exportBragCard(); });
  }
  if((!cer||ceremonyPhase(cer,"prompt")>0)&&(G.t/30|0)%2){
    const r=G.result;
    const exhibPrompt=r&&(r.kind==="vswin"||r.kind==="vsloss")&&r.exhibition;
    const ser=exhibPrompt&&r.series;
    const nextLabel="PRESS "+LG("a",ser&&!ser.done&&ser.format==="bo3"?"NEXT BOUT":"REMATCH");
    txt(exhibPrompt?nextLabel:"PRESS "+KH("a"),W/2,460,14,INK,"center",800);
    if(exhibPrompt) txt(LG("b","MENU"),W/2,478,11,DIM,"center",700);
  }
}

function exportBragCard(){
  if(typeof document==="undefined"||typeof document.createElement!=="function") return;
  const st=G.lastStats, r=G.result;
  const fid=(G.adv?G.adv.hero:(G.duel?G.duel.p.fid:0));
  const heroObj=(typeof FIGHTERS!=="undefined"&&FIGHTERS[fid])?FIGHTERS[fid]:{name:"Champion"};
  const heroName=(typeof fighterDisplayName==="function"?fighterDisplayName(fid):heroObj.name).toUpperCase();
  const fg=st?fightGrade(st):{grade:"S",note:"APEX PERFORMANCE"};
  const mv=st?methodOfVictory(st,{hotseat:false}):{line:"DECISIVE VICTORY"};

  let ghostCode="";
  if(typeof encodeGhostBuild==="function"){
    const deck=(G.adv&&G.adv.drafted)?G.adv.drafted:(heroObj.deck||[]);
    const techs=(typeof techIdsOfDeck==="function")?techIdsOfDeck(deck):(deck.map(t=>t.id||t));
    ghostCode=encodeGhostBuild({
      hero: fid,
      name: heroName,
      techniques: techs,
      benefits: (G.adv&&G.adv.benefits)||[],
      relics: (G.adv&&G.adv.relics)||[],
      stats: st
    });
  }

  try{
    const cv=document.createElement("canvas");
    cv.width=1200; cv.height=675;
    const ctx=cv.getContext("2d");
    if(!ctx) return;

    // Deep arena backdrop
    const bg=ctx.createLinearGradient(0,0,1200,675);
    bg.addColorStop(0,"#07090e"); bg.addColorStop(0.5,"#0b0f19"); bg.addColorStop(1,"#050608");
    ctx.fillStyle=bg; ctx.fillRect(0,0,1200,675);

    // Subtle cyan grid
    ctx.strokeStyle="rgba(34,211,238,0.08)"; ctx.lineWidth=1;
    for(let x=40;x<1200;x+=60){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,675); ctx.stroke(); }
    for(let y=40;y<675;y+=60){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(1200,y); ctx.stroke(); }

    // Outer golden frame
    ctx.strokeStyle="#d4af37"; ctx.lineWidth=3; ctx.strokeRect(24,24,1152,627);
    ctx.strokeStyle="rgba(34,211,238,0.4)"; ctx.lineWidth=1; ctx.strokeRect(30,30,1140,615);

    // Corner brackets
    ctx.fillStyle="#f59e0b";
    ctx.fillRect(20,20,24,4); ctx.fillRect(20,20,4,24);
    ctx.fillRect(1156,20,24,4); ctx.fillRect(1176,20,4,24);
    ctx.fillRect(20,651,24,4); ctx.fillRect(20,631,4,24);
    ctx.fillRect(1156,651,24,4); ctx.fillRect(1176,631,4,24);

    // Header Title
    ctx.fillStyle="#22d3ee"; ctx.font="800 16px sans-serif";
    ctx.fillText("AQUA ZERO: HEAVEN'S ARENA  //  OFFICIAL COMBAT SCORECARD",60,68);

    // Fighter Name & Callout
    ctx.fillStyle="#ffffff"; ctx.font="900 44px sans-serif";
    ctx.fillText(heroName,60,126);
    ctx.fillStyle="#d4af37"; ctx.font="700 20px sans-serif";
    ctx.fillText(mv.line.toUpperCase(),60,160);

    // Grade Badge
    const gradeColors={S:"#f59e0b",A:"#22d3ee",B:"#3b82f6",C:"#10b981",D:"#f97316",F:"#ef4444"};
    const gCol=gradeColors[fg.grade]||"#f59e0b";
    ctx.fillStyle="rgba(10,15,26,0.85)"; ctx.fillRect(60,190,160,110);
    ctx.strokeStyle=gCol; ctx.lineWidth=2; ctx.strokeRect(60,190,160,110);
    ctx.fillStyle=gCol; ctx.font="900 64px sans-serif"; ctx.textAlign="center";
    ctx.fillText(fg.grade,140,272);
    ctx.font="800 12px sans-serif"; ctx.fillText("BATTLE GRADE",140,294);
    ctx.textAlign="left";

    // Stats Grid
    const statsX=250, statsY=190;
    const turns=st?(st.turns||1):1;
    const dmg=st?(st.dmgDealt||0):0;
    const taken=st?(st.dmgTaken||0):0;
    const bestHit=st?(st.bigDmg||0):0;
    const statItems=[
      ["EXCHANGE TURNS", String(turns)],
      ["DAMAGE INFLICTED", String(dmg)],
      ["DAMAGE TAKEN", String(taken)],
      ["APEX IMPACT", bestHit+" DMG"]
    ];
    statItems.forEach((item,idx)=>{
      const sx=statsX+(idx%2)*220;
      const sy=statsY+Math.floor(idx/2)*60;
      ctx.fillStyle="#94a3b8"; ctx.font="700 12px sans-serif";
      ctx.fillText(item[0],sx,sy+18);
      ctx.fillStyle="#ffffff"; ctx.font="900 26px sans-serif";
      ctx.fillText(item[1],sx,sy+48);
    });

    // Relics strip if in Adventure
    const relics=(G.adv&&G.adv.relics)||[];
    if(relics.length>0&&typeof RELICS!=="undefined"){
      ctx.fillStyle="#f59e0b"; ctx.font="800 13px sans-serif";
      ctx.fillText("ACTIVE RELICS // COMBINATORIAL SYNERGIES",60,350);
      relics.slice(0,5).forEach((rid,i)=>{
        const rel=RELICS[rid]; if(!rel) return;
        const rx=60+i*140;
        ctx.fillStyle="rgba(15,23,42,0.9)"; ctx.fillRect(rx,362,130,42);
        ctx.strokeStyle=rel.tier==="TRANSCENDENT"?"#a855f7":(rel.tier==="RARE"?"#f59e0b":"#38bdf8");
        ctx.lineWidth=1.5; ctx.strokeRect(rx,362,130,42);
        ctx.fillStyle="#f8fafc"; ctx.font="700 11px sans-serif";
        ctx.fillText(rel.name.slice(0,15),rx+8,382);
        ctx.fillStyle=ctx.strokeStyle; ctx.font="800 9px sans-serif";
        ctx.fillText(rel.tier,rx+8,396);
      });
    }

    // Draw Fighter Art if available
    const art=(typeof artOf==="function")?artOf(fid):null;
    if(art&&art.complete&&art.naturalWidth){
      const maxH=460;
      const rH=Math.min(maxH/art.naturalHeight, 420/art.naturalWidth);
      const aw=art.naturalWidth*rH, ah=art.naturalHeight*rH;
      ctx.save();
      ctx.shadowColor="rgba(34,211,238,0.4)"; ctx.shadowBlur=24;
      ctx.drawImage(art,820-aw/2,590-ah,aw,ah);
      ctx.restore();
    }

    // Ghost Battles Passcode Box
    if(ghostCode){
      const gBoxY=430;
      ctx.fillStyle="rgba(10,15,26,0.92)"; ctx.fillRect(60,gBoxY,680,180);
      ctx.strokeStyle="#22d3ee"; ctx.lineWidth=1.5; ctx.strokeRect(60,gBoxY,680,180);
      ctx.fillStyle="#22d3ee"; ctx.font="800 13px sans-serif";
      ctx.fillText("\u26a1 ASYNCHRONOUS GHOST BATTLES // CHALLENGE THIS BUILD IN THE DOJO",80,gBoxY+30);
      ctx.fillStyle="rgba(0,0,0,0.6)"; ctx.fillRect(80,gBoxY+44,640,46);
      ctx.strokeStyle="rgba(34,211,238,0.3)"; ctx.strokeRect(80,gBoxY+44,640,46);
      ctx.fillStyle="#fef08a"; ctx.font="700 13px monospace";
      ctx.fillText(ghostCode.length>68?ghostCode.slice(0,65)+"...":ghostCode,94,gBoxY+72);
      ctx.fillStyle="#94a3b8"; ctx.font="600 11px sans-serif";
      ctx.fillText("Copy this passcode into Main Menu > Ghost Challenger to pit any fighter against this build.",80,gBoxY+120);
    }

    const dataUrl=cv.toDataURL("image/png");
    const link=document.createElement("a");
    link.download="azx-"+heroName.toLowerCase().replace(/\s+/g,"_")+"-scorecard.png";
    link.href=dataUrl;
    link.click();
    if(typeof FloatingFeedback!=="undefined"){
      FloatingFeedback.add("BRAG CARD EXPORTED!",W/2,200,"SYSTEM");
    }
  }catch(e){
    console.error("exportBragCard error",e);
  }
}

/* The scorecard. Every number here was already being recorded by the battle
   model and thrown away at the end of the fight. `bar` null means no
   denominator existed - draw no rail at all, because an empty rail reads as a
   failed stat rather than an unmeasured one. */
function rFightStats(){
  const st=G.lastStats, r=G.result, cer=G.cer;
  bgFill("#0e1014","#08090b");
  const mv=methodOfVictory(st,{hotseat:!!(r&&r.hotseat)}), fg=fightGrade(st);
  txt(mv.line,W/2,72,22,mv.tone==="good"?GOLD:RED,"center",800,true);
  txt(mv.detail,W/2,96,11,DIM,"center",600);
  panel(W/2-250,114,500,44,"rgba(10,11,14,.9)",fg.grade==="F"?RED:GOLD,"rgba(255,255,255,.05)",8);
  const gradeColors={S:GOLD, A:GOLD, B:AQUA, C:"#f59e0b", D:"#f97316", E:"#ef4444", F:RED};
  const gCol=gradeColors[fg.grade]||GOLD;
  cx.save();
  cx.translate(W/2-200, 136);
  cx.rotate(-0.08);
  panel(-24, -16, 48, 32, "rgba(8,11,16,.9)", gCol, null, 4);
  txt(fg.grade, 0, 6, 20, gCol, "center", 900, true);
  cx.restore();
  txt("PERFORMANCE: "+fg.grade+" GRADE",W/2-156,142,14,gCol,"left",800);
  txt(fg.note,W/2+232,142,10.5,DIM,"right",600);
  const rows=fightStatRows(st);
  const ph=cer?ceremonyPhase(cer,"stats"):1;
  const shown=Math.min(rows.length,Math.ceil(ph*rows.length));
  panel(W/2-250,168,500,272,"rgba(10,11,14,.9)","#2a2d35");
  for(let i=0;i<shown;i++){
    const row=rows[i], y=196+i*28;
    txt(row.label,W/2-234,y,11,DIM,"left",700);
    txt(row.value,W/2+234,y,13,INK,"right",800);
    if(row.bar!==null&&row.bar!==undefined){
      cx.fillStyle="#161920"; cx.fillRect(W/2-234,y+6,468,4);
      cx.fillStyle=row.key==="taken"?RED:AQUA;
      cx.fillRect(W/2-234,y+6,468*row.bar,4);
    }
  }
  const fBragBtnX=W/2-105, fBragBtnY=H-52, fBragBtnW=210, fBragBtnH=22;
  panel(fBragBtnX,fBragBtnY,fBragBtnW,fBragBtnH,"rgba(10,11,14,.88)",GOLD,null,4);
  txt("\ud83c\udfc6 EXPORT BRAG CARD [X]",fBragBtnX+fBragBtnW/2,fBragBtnY+15,10,GOLD,"center",800);
  hot(fBragBtnX,fBragBtnY,fBragBtnW,fBragBtnH,null,()=>{ exportBragCard(); });
  txt(LG("b","BACK TO THE RESULT"),W/2,H-16,11,DIM,"center",700);
}
/* ---------- the run summary screen ----------
   Four questions, in the order a player asks them: how far did I get, what did
   I keep, what did I build, and what was the best thing I did. Then one button
   that means "again".

   The mastery bar is the reason this screen exists. mastery.js has awarded 18
   on a win and 7 on a loss since it landed and the player has never once seen
   it move. Here it moves: each row animates its xp from where the run started
   to where it finished, and the belt and the rail are recomputed from the
   ANIMATED value, so a belt crossed on the way down snaps over on screen
   instead of being reported after the fact. Reduced motion skips straight to
   the finished state - the numbers are the same either way. */
function rRunEnd(){
  const s=G.runEnd;
  /* No summary and yet here anyway - a hand-set scene, or a reload that landed
     mid-flight. Draw the two ways out rather than reassigning G.scene: render()
     runs at monitor cadence and must not be the thing that moves the game. Both
     keys work from here: runItBack() defaults to fighter 0 on a missing
     summary, and B is the title. */
  if(!s){
    bgFill("#150e0f","#08090b");
    txt("THE RUN ENDS",W/2,244,32,RED,"center",800,true);
    txt(LG("a","RUN IT BACK")+"        "+LG("b","TITLE"),W/2,290,14,INK,"center",800);
    return;
  }
  const hero=FIGHTERS[s.hero]?s.hero:0;
  bgFill("#150e0f","#08090b");
  drawFighterArt(hero, W/2, H+8, 470, false, false, .085);
  /* A join that cannot overflow its panel. measureText is stubbed in the test
     sandbox, so the budget is CHARACTERS - deterministic in both places - and
     the cap applies to the first entry too, because the longest technique name
     in the game is 55 characters and one of them alone must not run off the
     edge. */
  const joinCap=(list,cap)=>{
    let out="", left=0;
    for(let i=0;i<list.length;i++){
      const add=(out?"   ":"")+list[i];
      if(out&&out.length+add.length>cap){ left=list.length-i; break; }
      out+=add;
      if(out.length>cap){ out=out.slice(0,cap); left=list.length-i-1; break; }
    }
    return out+(left>0?"   +"+left+" MORE":"");
  };

  txt("THE RUN ENDS",W/2,58,32,RED,"center",800,true);
  txt(FIGHTERS[hero].name+"   -   "+traitsOf(hero).tag+(s.ng?"   -   NEW GAME +"+s.ng:""),
      W/2,80,12,DIM,"center",600);
  txt("NOTHING HERE IS LOST - MASTERY, UNLOCKS AND RECORDS ARE ALREADY BANKED",
      W/2,98,10.5,GOLD,"center",700);

  /* the ledger */
  const lost=Math.max(0,s.fights-s.won);
  const tiles=[["FIGHTS TAKEN", s.fights+"   ("+s.won+"-"+lost+")", INK],
               ["REACHED", "STAGE "+s.stage+"   LV "+s.level, INK],
               ["PURSE EARNED", "$"+s.earned, GOLD],
               [s.ogre?"THE GATE":"FROM THE DOOR",
                s.ogre?"TOWER UNFOUND":(s.cols+(s.cols===1?" COLUMN":" COLUMNS")),
                /* gold for "you could see the door" - which the gate has none of */
                (!s.ogre&&s.cols<=3)?GOLD:INK]];
  {
    /* 216 + 16 x 4 lands the row on exactly the 24..936 gutter the two panels
       below use, so the whole screen shares one pair of margins */
    const tw=216, gap=16, ox=W/2-(tiles.length*tw+(tiles.length-1)*gap)/2;
    tiles.forEach((t,i)=>{
      const x=ox+i*(tw+gap);
      panel(x,112,tw,58,"rgba(10,11,14,.9)","#252831");
      txt(t[0],x+tw/2,132,9.5,DIM,"center",700);
      txt(t[1],x+tw/2,158,18,t[2],"center",800);
    });
  }

  /* mastery - the one thing a loss cannot take back */
  panel(24,182,476,148,"rgba(10,11,14,.92)",AQUA);
  txt("MASTERY EARNED THIS RUN",40,204,11,AQUA,"left",800);
  txt("PERMANENT, PER FIGHTER - IT SURVIVED THE DEFEAT",40,219,9,DIM,"left",600);
  if(!s.mastery.length){
    txt("NO FIGHT WAS RECORDED THIS RUN",40,262,12,DIM,"left",700);
  } else {
    const rows=s.mastery.slice(0,2);
    const y0=rows.length>1?248:262;
    rows.forEach((m,i)=>{
      const y=y0+i*44, hold=16+i*24, span=44;
      const el=Math.max(0,(G.t-s.t0)-hold);
      const p=motionOn()?Math.max(0,Math.min(1,el/span)):1;
      const xp=Math.round(m.from+(m.to-m.from)*p);
      const rk=masteryRank(xp), was=masteryRank(m.from);
      const up=rk.level>was.level;
      txt(FIGHTERS[m.fid].name,40,y,13,INK,"left",800);
      txt("+"+Math.round(m.gained*p)+" XP",484,y,12,GOLD,"right",800);
      /* the rail. masteryProgress is 0..1 inside the CURRENT belt, so a belt-up
         resets it - which is the point: the bar visibly empties and starts
         again on the new colour. */
      const bx=40, bw=444;
      panel(bx,y+8,bw,8,"#0a0b0e","#2a2d35");
      /* the belt's own colour, except at the top: MASTERY_COLORS ends on black,
         which on a black rail is no bar at all. A mastered fighter gets gold. */
      cx.fillStyle=(rk.level>=MASTERY_MAX)?GOLD:(MASTERY_COLORS[rk.level]||AQUA);
      cx.fillRect(bx+1,y+9,Math.max(0,(bw-2)*masteryProgress(xp)),6);
      const next=masteryToNext(xp);
      /* "Unranked belt" is not a thing - rank 0 is the absence of one */
      txt((rk.level?(rk.name+" BELT"):"UNRANKED")+"   -   "+xp+" XP"
          +(next>0?"   -   "+next+" TO "+MASTERY_RANKS[rk.level+1].name:"   -   MASTERED"),
          bx,y+30,9.5,up?GOLD:DIM,"left",up?800:600);
      if(up) txt("NEW BELT",484,y+30,9.5,GOLD,"right",800);
      /* An adventure is fought by one hero, so this panel almost always holds a
         single row and 38px of the panel underneath it. Spend it on the thing
         the player actually wants to know - what the belt they just reached
         does the next time they pick this fighter. Two rows have no room. */
      if(rows.length===1&&rk.perk) txt("BELT PERK - "+rk.perk,bx,y+46,9.5,AQUA,"left",600);
    });
    if(s.mastery.length>2)
      txt("+"+(s.mastery.length-2)+" MORE FIGHTER"+(s.mastery.length===3?"":"S"),
          484,322,9.5,DIM,"right",600);
  }

  /* what the run built */
  panel(512,182,424,148,"rgba(10,11,14,.92)","#2a2d35");
  txt("WHAT THE RUN BUILT",528,204,11,INK,"left",800);
  txt("SPENT WITH IT - THE NEXT RUN STARTS CLEAN",528,219,9,DIM,"left",600);
  {
    const drNames=s.drafted.map(id=>(TECH[id]&&TECH[id].name)||String(id));
    const bnNames=s.benefits.map(id=>(BENEFITS[id]&&BENEFITS[id].name)||String(id));
    const block=(label,n,names,y,tone)=>{
      txt(label,528,y,9.5,DIM,"left",700);
      txt(String(n),920,y,13,n?tone:"#5d626c","right",800);
      txt(n?joinCap(names,64):"NONE",528,y+15,9.5,n?INK:"#5d626c","left",600);
    };
    block("TECHNIQUES DRAFTED",s.drafted.length,drNames,244,AQUA);
    block("CAMP BENEFITS TAKEN",s.benefits.length,bnNames,282,GOLD);
    txt("CARD POINTS",528,320,9.5,DIM,"left",700);
    txt(s.points+"   -   PURSE LEFT $"+s.purse,920,320,10.5,DIM,"right",700);
  }

  /* the best thing that happened */
  if(s.best&&s.best.n>0){
    panel(24,342,912,50,"rgba(216,162,74,.07)",GOLD);
    txt("BEST EXCHANGE OF THE RUN",40,362,9.5,GOLD,"left",800);
    txt((s.best.tech||"UNNAMED")+"   -   "+s.best.n+" DAMAGE",40,382,14,INK,"left",800);
    txt("VS "+(s.best.foe||"UNKNOWN")+"   -   STAGE "+(s.best.stage||1),920,382,10.5,DIM,"right",600);
  } else {
    panel(24,342,912,50,"rgba(10,11,14,.9)","#252831");
    txt("BEST EXCHANGE OF THE RUN",40,362,9.5,DIM,"left",800);
    txt("NOTHING LANDED CLEAN - IT NEVER GOT GOING",40,382,13,DIM,"left",700);
  }
  if(s.endedBy) txt("THE RUN ENDED AGAINST "+s.endedBy,W/2,408,11,RED,"center",700);

  /* one press means again */
  {
    const nl=masteryStartLevel(SAVE,hero);
    const chips=[[LG("a","RUN IT BACK"),"a",true],[LG("b","TITLE"),"b",false]];
    const cwd=250, gap=20, ox=W/2-(chips.length*cwd+(chips.length-1)*gap)/2;
    chips.forEach((c,i)=>{
      const bx=ox+i*(cwd+gap);
      panel(bx,422,cwd,30,"rgba(10,11,14,.9)",c[2]?GOLD:"#2a2d35");
      txt(c[0],bx+cwd/2,442,12.5,c[2]?((G.t/30|0)%2?INK:GOLD):DIM,"center",800);
      hot(bx,422,cwd,30,null,()=>onKey(c[1]));
    });
    txt("SAME FIGHTER, FRESH FIELD, STAGE 1 AT LEVEL "+nl
        +(nl>1?" - MASTERY PAID FOR THAT":""),W/2,472,10.5,nl>1?GOLD:DIM,"center",700);
  }
  /* RENOWN, AND THE MAN. The two things this run left behind that the NEXT one
     will actually feel. A currency the player never sees earned is worthless,
     so it is on the obituary screen with its arithmetic beside it, and the
     nemesis line is the only sentence this game tells about the player. */
  {
    const rw=s.renown;
    panel(24,484,912,44,rw?"rgba(216,162,74,.08)":"rgba(10,11,14,.9)",rw?GOLD:"#252831");
    if(rw){
      txt("RENOWN EARNED",40,502,9.5,GOLD,"left",800);
      txt("+"+rw.total+" "+META_CONFIG.unit,40,520,15,GOLD,"left",800);
      /* the arithmetic rather than one number nobody trusts */
      txt(rw.lines.map(l=>l.label+" +"+l.amount).join("   ")
          +(rw.mult>1?("   x"+rw.mult.toFixed(2)):""),200,504,9,DIM,"left",600);
      txt(metaSummary(SAVE.meta),920,504,9.5,INK,"right",700);
    } else {
      txt("RENOWN EARNED",40,502,9.5,DIM,"left",800);
      txt("ALREADY BANKED FOR THIS RUN",40,520,12,DIM,"left",700);
    }
    if(s.nem)
      txt("NEMESIS - "+FIGHTERS[s.nem.fid].name.toUpperCase()+"   "
          +s.nem.wins+"-"+s.nem.losses+" BETWEEN YOU   -   HE OPENS THE NEXT RUN",
          920,520,10,RED,"right",800);
    else if(s.challenge)
      txt((s.challengeDone?"CHALLENGE MET - ":"CHALLENGE MISSED - ")
          +((CHALLENGE_BY_ID[s.challenge]||{}).name||"").toUpperCase(),
          920,520,10,s.challengeDone?GRN:DIM,"right",800);
    /* it did not go quiet on you - say where the objective went */
    else if(s.challengeRetired)
      txt("OBJECTIVE RETIRED - "
          +((CHALLENGE_BY_ID[s.challengeRetired]||{}).name||"").toUpperCase()
          +" IS A LADDER TITLE",
          920,520,10,GOLD,"right",800);
  }
}
