/* ================================================================
   10. LOOP
   ================================================================ */
let sceneSaid=-1;
const SCENE_LABEL={};
SCENE_LABEL[S.TITLE]="Title screen. Press "+Keybindings.arenaKeysFor("a","TITLE").slice(0,3).join(", ")+" to start.";
SCENE_LABEL[S.MENU]="Main menu.";
SCENE_LABEL[S.SELECT]="Fighter select.";
SCENE_LABEL[S.MAP]="Adventure field. "+fieldMoveLegend()+". Reach the exit on the east side.";
SCENE_LABEL[S.PAUSE]="Paused.";
SCENE_LABEL[S.OPTIONS]="Options.";
SCENE_LABEL[S.RECORDS]="Career records.";
SCENE_LABEL[S.BENEFIT]="Choose a camp benefit.";
SCENE_LABEL[S.DRAFT]="Learn a technique.";
SCENE_LABEL[S.SHOP]="The gym.";
SCENE_LABEL[S.SERVICE]="The trainer's table.";
SCENE_LABEL[S.DAILY]="Daily gauntlet.";
SCENE_LABEL[S.TITLES]="Titles.";
SCENE_LABEL[S.BOARD]="Leaderboards.";
SCENE_LABEL[S.RENOWN]="The renown wall. Spend what your runs earned on what the next one can be dealt. A buys, B goes back.";
SCENE_LABEL[S.CHALLENGE]="Challenge run. Take a standing objective into the next adventure. A takes it and goes to fighter select, B goes back.";
SCENE_LABEL[S.HOW]="How to play.";
SCENE_LABEL[S.FIGHTER]="Fighter dossier.";
SCENE_LABEL[S.CREDITS]="Ending.";
SCENE_LABEL[S.TOWER]="Heavens Arena Tower. 200 floors of escalating combat.";
SCENE_LABEL[S.DOJO]="Dojo practice sandbox.";
SCENE_LABEL[S.CREATE_FIGHTER]="Register a fighter into the AZX league: gameplan, dossier, ratings, colors.";
SCENE_LABEL[S.REPLAY]="Match replay viewer.";
SCENE_LABEL[S.CODEX]="Martial arts codex compendium. 425 techniques mastery.";
SCENE_LABEL[S.TROPHY]="Championship trophy room and earned division belts.";
SCENE_LABEL[S.ENDLESS]="Survival Gauntlet Championship. 10-wave rogue-lite arena climb. A selects action, B goes back.";
SCENE_LABEL[S.WEEKLY]="Weekly seeded mutator tournament arena.";
SCENE_LABEL[S.DECK_BUILDER]="Custom deck builder. Construct 100-pt custom technique loadouts. A selects, B goes back.";
SCENE_LABEL[S.PERK]="Sacred Seal & Combat Relic forge. Choose one permanent tactical upgrade. A accepts, B skips.";
/* The static fallback, for any path that reaches the scene without going
   through openRunEnd. openRunEnd REPLACES this entry with the run's actual
   account before it switches scene, because the scene-change hook below runs
   in step() - after the key handler - and a say() made inside openRunEnd would
   be overwritten by this label one frame later. Writing the account here is
   what puts the numbers in the live region and on the canvas label rather than
   only in pixels. */
SCENE_LABEL[S.RUNEND]="The run is over. A runs it back with the same fighter, B returns to the title.";
/* The ONLY place that decides what plays. Track choice is intent, so it lives
   in one readable function rather than scattered across every scene handler.
   musicSwitch is idempotent - switching to the track already playing costs one
   string compare - so this can safely run every frame. It never mutates a
   scene; it only reads one. */
function musicScene(){
  const m=G.music, d=G.duel;
  if(G.scene===S.LOAD) return;
  if(G.scene===S.DUEL&&d){
    if(d.ph===D.INTRO){ musicSwitch(m,"entrance",{fade:MUSIC_CONFIG.fade}); return; }
    if(d.ph===D.END) return;                 // the stinger already fired at the bell
    /* the tension knob is the lower of the two HP fractions, inverted: the
       score tightens when ANYONE is in trouble, not just the player */
    const heat=1-Math.min(d.p.hp/d.p.maxhp, d.e.hp/d.e.maxhp);
    if(d.boss){ musicSwitch(m,"boss",{fade:MUSIC_CONFIG.swapFade}); musicIntensity(m,heat); return; }
    if(m.name!=="fight"&&m.name!=="fight_hot") musicSwitch(m,"fight",{fade:MUSIC_CONFIG.swapFade});
    musicHeat(m,heat);
    return;
  }
  if(G.scene===S.RESULT){
    const k=G.result&&G.result.kind;
    const lost=(k==="ko"||k==="steps"||k==="survend"||k==="dailyloss"||k==="rankloss"||k==="vsloss");
    /* no name guard here: musicSwitch refuses to restart a spent `once` track,
       which is what a stinger is. A hardcoded list of stinger names would have
       to be extended by hand for every new one, and forgetting is a fanfare
       that never ends. */
    musicSwitch(m,lost?"defeat":"victory",{hard:true});
    return;
  }
  if(G.scene===S.BRIEF){ musicSwitch(m,"entrance",{fade:MUSIC_CONFIG.fade}); return; }
  if(G.scene===S.TITLE||G.scene===S.CREDITS){ musicSwitch(m,"title",{fade:MUSIC_CONFIG.fade}); return; }
  musicSwitch(m,"menu",{fade:MUSIC_CONFIG.fade});
}
function step(){
  G.t++;
  if(typeof CombatFX!=="undefined") CombatFX.update();
  if(typeof FloatingFeedback!=="undefined") FloatingFeedback.update();
  /* the score keeps time even while the world is frozen - hit-stop holds the
     fight for a few frames, and a clock that stopped with it would drift out
     of the bar on every landed punch */
  if(!G.music) G.music=newMusicState("title");
  musicMute(G.music, !SAVE.sound || !SAVE.music);
  musicScene();
  musicTick(G.music).forEach(n=>beep(n.f,n.d,n.type,n.v));
  if(G.crowdT>0) G.crowdT--;
  // The title no longer waits on 1.4 MB of art - it waits on the two portraits
  // it actually draws, and after four seconds it stops waiting at all, so a
  // decode failure can never strand you on the loading screen.
  if(G.scene===S.LOAD && (artReady() || (loadedN>=4 && G.t>75) || G.t>240)){ G.scene=S.TITLE; focusArena(); }
  /* the cabinet fights itself when nobody is standing at it. attractTick runs
     unconditionally so the demo's own clock advances while the scene is DUEL;
     the else branch zeroes the idle counter on every screen but the title.
     `!!AC` is the real "audio has actually started" test - AC is only assigned
     inside beep() after a gesture, which is the browser's own rule. */
  attractTick(G.attract);
  if(G.scene===S.TITLE&&!G.attract.on){
    if(attractReady(G.attract.idle,{save:SAVE,gesture:G.attract.gesture,
        sound:!!SAVE.sound&&!!AC,runActive:!!G.adv,duel:G.duel,
        scene:G.scene,titleScene:S.TITLE,active:G.attract.on})) startAttract();
  } else if(!G.attract.on) G.attract.idle=0;
  if(G.scene!==sceneSaid){
    sceneSaid=G.scene;
    const lbl=SCENE_LABEL[G.scene];
    if(lbl) say(lbl);
    cv.setAttribute("aria-label","Aqua Zero Heavens Arena - "+(lbl||"in play"));
    /* built on the scene CHANGE rather than in endDuel: this is the one hook
       that catches all of endDuel's branches, outOfSteps, and a test that
       assigns G.scene=S.RESULT by hand. Resetting resTab here is what stops a
       second fight opening onto the previous fight's stat page. */
    if(G.scene===S.RESULT){ G.resTab=0; G.cer=ceremonyBeats(G.result,G.lastStats,{motion:motionOn()}); }
    else G.cer=null;
  }
  if(G.scene===S.RESULT&&G.cer) ceremonyStep(G.cer).forEach(id=>{
    if(id==="method") sTick();
    else if(id==="stats") sStep();
    else if(id==="grade"&&G.lastStats&&G.lastStats.win) sLevel();
  });
  const d=G.duel;
  /* placement is load-bearing: turnEnd sets D.END and hp<=0 in the same call,
     so the next step() sees it here and returns to the title WITHOUT ever
     reaching endDuel - which is what stops a demo writing to the save. The
     d.t>90 hold lets a knockout land before the screen goes away. */
  if(G.scene===S.DUEL&&d&&d.attract&&attractShouldExit(G.attract,d)){
    if(G.attract.input||G.attract.exit||d.ph!==D.END||d.t>90){ endAttract(); return; }
  }
  if(G.scene===S.DUEL&&d){
    // hit-stop: the whole fight holds for a few frames so impacts land
    if(d.freeze>0){ d.freeze--; return; }
    d.t++;
    if(d.zoomT>0) d.zoomT--;
    if(d.shakeG>0){ d.shakeG-=Math.max(.7,d.shakeG*.14); if(d.shakeG<.4) d.shakeG=0; }
    if(d.calloutT>0) d.calloutT--;
    if(d.comboT>0){ if(!--d.comboT){ d.combo=0; d.comboBy=""; } }
    [d.p,d.e].forEach(s=>{ tickAnim(s); if(s.dmgT>0)s.dmgT--; if(s.shakeT>0)s.shakeT--;
                           if(s.animT>0)s.animT--; if(s.flash>0)s.flash--;
                           if(s.ghost>s.hp) s.ghost=Math.max(s.hp,s.ghost-Math.max(.45,(s.ghost-s.hp)*.07));
                           else s.ghost=s.hp; });
    if(typeof spectacleStep==="function") spectacleStep(d.fx);
    else for(let i=d.fx.length-1;i>=0;i--){ const p=d.fx[i];
      p.x+=p.vx; p.y+=p.vy; p.vy+=.42; p.l--; if(p.l<=0) d.fx.splice(i,1); }
    if(typeof spectacleStepPops==="function") spectacleStepPops(d.pops);
    /* D.CMD is the only phase that needs hands - INTRO, DEFEND, EXEC and
       TURNEND all self-advance already */
    if(d.attract&&d.ph===D.CMD&&d.t>ATTRACT_CONFIG.beat){ attractCommit(d); return; }
    if(d.ph===D.MENU){ /* the fight holds until you choose */ }
    else if(d.ph===D.TAPE){
      const hold=paceTape(d);
      /* a zero hold means this bout does not get a tape at all - drop straight
         into the entrance, which INSTANT then slides to the bell below */
      if(d.t>hold){ d.ph=D.INTRO; d.t=0;
                    if(hold<=0&&d.ent&&typeof entranceSkip==="function") entranceSkip(d.ent,0); } }
    else if(d.ph===D.INTRO){
      /* entranceCues LATCHES, so it must appear exactly once in this file and
         it must be here. render() runs at monitor cadence while this loop runs
         up to 8 times per drawn frame - latching there would tie the bell to
         the refresh rate and swallow cues. */
      entranceCues(d.ent,d.t).forEach(entranceCue);
      if(entranceDone(d.ent,d.t)) beginRound(d);
    }
    else if(d.ph===D.DEFEND){ if(d.t>44&&!d.defDone){ d.defDone=1; resolveDefence(d,2); } }
    else if(d.ph===D.EXEC){ if(d.t>paceExec()) afterResolve(d); }
    else if(d.ph===D.TURNEND){ if(d.t>(d.turbo?2:16)) turnEnd(d); }
    else if(d.ph===D.SUPER){
      const spd=d.jugSpd*(d.jugSlow?.45:1);
      d.jugPos+=d.jugDir*spd;
      if(d.jugPos>=100){d.jugPos=100;d.jugDir=-1;} if(d.jugPos<=0){d.jugPos=0;d.jugDir=1;}
      if(d.supFor==="e"&&!d.hotseat){
        const want=SAVE.diff===2?2:1, at=jugTierAt(d,d.jugPos);
        if(d.t>14&&((at>=want&&Math.random()<.45)||d.t>110)) superBeat(d);
      } else if(d.t>360) superBeat(d);
    }
    else if(d.ph===D.JUGGLE){
      const spd=d.jugSpd*(d.jugSlow?.45:1);
      d.jugPos+=d.jugDir*spd;
      if(d.jugPos>=100){d.jugPos=100;d.jugDir=-1;} if(d.jugPos<=0){d.jugPos=0;d.jugDir=1;}
      /* a launcher thrown by the demo's own side sets jugFor=+1, and D.JUGGLE
         would then wait 300 frames for a keypress nobody is there to make */
      const cpuJuggling=(d.jugFor<0&&!d.hotseat)||!!d.attract;
      if(cpuJuggling&&d.t>14){
        // the CPU aims for a tier it can hit; better difficulties aim higher
        const want=SAVE.diff===2?2:SAVE.diff===1?1:0;
        const at=jugTierAt(d,d.jugPos);
        /* resolve for whoever is actually juggling. Identical for every real
           duel - this branch was only ever reached with jugFor<0 - but the
           demo can juggle from the player's side, and crediting that to the
           opponent would silently score the wrong man. */
        if((at>=want&&Math.random()<.5)||d.t>120) resolveJuggle(d,d.jugFor>0?d.p:d.e);
      }
      if(d.t>300) resolveJuggle(d,d.jugFor>0?d.p:d.e); // never hang the duel
    }
    else if(d.ph===D.JUGRES){ if(d.t>44){ d.jugFor=0; afterResolve(d); } }
  }
}
/* What A, B and Y do at this exact moment. The pad below the arena reads
   from this, so no button is ever a mystery. */
function hintFor(){
  const sc=G.scene, d=G.duel;
  if(sc===S.TITLE)   return {a:"START",b:"HOW TO PLAY",y:""};
  if(sc===S.MENU)    return {a:"SELECT",b:"TITLE",y:""};
  if(sc===S.HOW)     return {a:G.how<howPages().length-1?"NEXT PAGE":"BACK",b:"BACK",y:""};
  if(sc===S.RECORDS) return {a:"BACK",b:"BACK",y:"TITLES"};
  if(sc===S.BENEFIT) return {a:"TAKE IT",b:"",y:""};
  if(sc===S.DRAFT)   return {a:"LEARN IT",b:"TAKE NOTHING",y:""};
  if(sc===S.SHOP)    return {a:"BUY",b:"LEAVE",y:"REROLL"};
  if(sc===S.SERVICE) return {a:"CONFIRM",b:"BACK",y:""};
  if(sc===S.DAILY)   return {a:dailyState(SAVE,dayKey()).done?"":"FIGHT",b:"BACK",y:""};
  if(sc===S.TITLES)  return {a:"WEAR IT",b:"BACK",y:""};
  if(sc===S.BOARD)   return {a:"BACK",b:"BACK",y:""};
  if(sc===S.RENOWN)  return {a:(renownRows()[G.renownSel]||{}).id==="open_pick"?"":"BUY",
                             b:"BACK",y:""};
  if(sc===S.CHALLENGE) return {a:"TAKE IT",b:"BACK",y:""};
  if(sc===S.OPTIONS) return {a:"CHANGE",b:"BACK",y:""};
  if(sc===S.TOWER)   return {a:"ENTER",b:"BACK",y:""};
  if(sc===S.DOJO)    return {a:"DRILL",b:"BACK",y:""};
  if(sc===S.CREATE_FIGHTER) return {a:"CONFIRM",b:"BACK",x:"FOCUS",y:"RESET"};
  if(sc===S.DECK_BUILDER) return {a:"SELECT",b:"BACK",y:"EXPORT"};
  if(sc===S.REPLAY)  return {a:"PLAY/PAUSE",b:"BACK",y:"SPEED"};
  if(sc===S.ENDLESS) return {a:"SELECT",b:"MAIN MENU",y:""};
  if(sc===S.PERK)    return {a:"EMBRACE",b:"SKIP",y:""};
  if(sc===S.SELECT)  return {a:G.selMode==="browse"?"DOSSIER":"CHOOSE",
                             b:G.selMode==="vs2"?"BACK TO PLAYER ONE":"BACK",y:"DOSSIER"};
  if(sc===S.FIGHTER) return {a:"BACK",b:"BACK",y:"BACK"};
  if(sc===S.MAP)     return {a:"",b:"PAUSE MENU",y:"YOUR DOSSIER"};
  if(sc===S.PAUSE)   return {a:"SELECT",b:"RESUME",y:""};
  if(sc===S.STAGECLEAR) return {a:"NEXT STAGE",b:"PAUSE MENU",y:""};
  if(sc===S.BRIEF)   return {a:"FIGHT",b:(G.brief&&G.brief.ambush)?"":"RETREAT (1 STEP)",
                             y:(G.brief&&!G.brief.f.tf&&!G.brief.f.boss)?"DOSSIER":""};
  if(sc===S.RESULT){
    const rr=G.result, ladder=!!(rr&&(rr.kind==="rankwin"||rr.kind==="rankloss")&&G.ranked),
          climb=!!(rr&&(rr.kind==="towerwin"||rr.kind==="towerloss")&&G.tower);
    return {a:G.resTab===1?"":(ladder?(G.ranked.done?"LEAVE THE LADDER":"NEXT MATCH")
                              :climb?(rr.kind==="towerloss"?"RETRY FLOOR":"NEXT FLOOR")
                              :((rr&&rr.exhibition)?((rr.series&&!rr.series.done)?"NEXT BOUT":"REMATCH"):"CONTINUE")),
            b:G.resTab===1?"BACK":(ladder?"END SESSION":climb?"TOWER LOBBY"
                              :((rr&&rr.kind==="ko"&&rr.cont)?"GIVE UP":((rr&&rr.exhibition)?"MENU":"CONTINUE"))),
            x:resultIsShort(rr)?"":"BRAG CARD",
            y:(G.lastStats&&rr&&rr.kind!=="steps"&&!resultIsShort(rr))?(G.resTab===1?"BACK":"FIGHT STATS"):""};
  }
  if(sc===S.RUNEND)  return {a:"RUN IT BACK",b:"TITLE",y:""};
  if(sc===S.CREDITS) return {a:"NEW GAME +",b:"TITLE",y:""};
  if(sc===S.DUEL&&d){
    if(d.ph===D.MENU)   return {a:d.menuSel===2&&d.quitArm?"CONFIRM FORFEIT":"SELECT",b:"RESUME",y:""};
    if(d.attract)       return {a:"EXIT DEMO",b:"EXIT DEMO",y:""};
    if(d.ph===D.TAPE)   return {a:"TO THE BELL",b:"FIGHT MENU",y:(!d.tf&&!d.boss)?"DOSSIER":""};
    if(d.ph===D.INTRO)  return {a:"SKIP",b:"FIGHT MENU",y:""};
    if(d.ph===D.CMD||d.ph===D.CMD2)
      return {a:cmdTabKey(d,d.ph===D.CMD?d.p:d.e)==="BAG"?"OPEN THE BAG":"THROW IT",
              b:"FIGHT MENU",y:d.hotseat?"":(d.readShown?"READ USED":"READ (1 FOCUS)")};
    if(d.ph===D.TECH||d.ph===D.TECH2) return {a:"THROW IT",b:"BACK",y:""};
    if(d.ph===D.BAG)    return {a:"USE IT",b:"BACK",y:""};
    if(d.ph===D.CHAIN)  return {a:"ADD A LINK",b:"THROW IT",y:"CLEAR"};
    if(d.ph===D.PASS)   return {a:"CONTINUE",b:"FIGHT MENU",y:""};
    if(d.ph===D.DEFEND) return {a:"GUARD NOW",b:"GUARD NOW",y:""};
    if(d.ph===D.SUPER)  return {a:"HIT THE BEAT",b:"",y:""};
    if(d.ph===D.JUGGLE) return {a:"HIT THE BEAT",b:"",y:d.jugSlow?"":"SLOW METER (1 FOCUS)"};
    if(d.ph===D.END)    return {a:"CONTINUE",b:"FIGHT MENU",y:""};
    return {a:"",b:"",y:""};
  }
  return {a:"",b:"",y:""};
}
/* The title and the dek are a shop window: 170px of the viewport explaining
   the game to somebody who has not started it. They kept explaining it during
   play, which left the arena 446 of 897 vertical pixels. Once a run is under
   way they fold away and the canvas grows into the height (see body.in-run).
   A first-time visitor on LOAD or TITLE still gets the full greeting. */
let lastInRun=null;
function syncStageChrome(){
  const inRun=!(G.scene===S.LOAD||G.scene===S.TITLE);
  if(inRun===lastInRun) return;
  lastInRun=inRun;
  document.body.classList.toggle("in-run", inRun);
}
const ctxEl=document.getElementById("ctx");
const btnEl={a:document.querySelector('[data-k="a"]'),b:document.querySelector('[data-k="b"]'),y:document.querySelector('[data-k="y"]')};
const hudTxtA=document.getElementById("hudTxtA"), hudTxtB=document.getElementById("hudTxtB"), hudTxtY=document.getElementById("hudTxtY");
const hudBtnA=document.getElementById("hudBtnA"), hudBtnB=document.getElementById("hudBtnB"), hudBtnY=document.getElementById("hudBtnY");
const hudKeyA=document.getElementById("hudKeyA"), hudKeyB=document.getElementById("hudKeyB"), hudKeyY=document.getElementById("hudKeyY");
const hudStatus=document.getElementById("hudStatus");

function getSceneStatusText(){
  const sc=G.scene, d=G.duel;
  if(sc===S.TITLE) return "TITLE SCREEN";
  if(sc===S.MENU) return "MAIN MENU";
  if(sc===S.SELECT) return "FIGHTER SELECT";
  if(sc===S.MAP) return "ARENA EXPLORATION";
  if(sc===S.OPTIONS) return "SYSTEM SETTINGS";
  if(sc===S.DECK_BUILDER) return "DECK BUILDER";
  if(sc===S.DOJO) return "TRAINING DOJO";
  if(sc===S.TOWER) return "HEAVENS TOWER";
  if(sc===S.SHOP) return "MERCHANT VAULT";
  if(sc===S.BOARD) return "GLOBAL LEADERBOARD";
  if(sc===S.DUEL && d){
    const opp=(d.e && d.e.f)?d.e.f.name.toUpperCase():"OPPONENT";
    return "BOUT VS "+opp;
  }
  return "AZX FIGHTING LEAGUE";
}

let lastCtx="";
function syncHint(){
  const h=hintFor(), key=h.a+"|"+h.b+"|"+h.y;
  if(key===lastCtx) return;
  lastCtx=key;

  // Modern HUD action chips & status
  if(hudStatus) hudStatus.textContent=getSceneStatusText();
  if(hudBtnA && hudTxtA){
    hudBtnA.classList.toggle("off", !h.a);
    hudBtnA.disabled = !h.a;
    hudTxtA.textContent = h.a || "\u2014";
    if(hudKeyA && typeof Keybindings!=="undefined" && Keybindings.getGlyphForAction){
      hudKeyA.textContent = Keybindings.arenaKeysFor("a",sceneKey())[0]||"";
    }
  }
  if(hudBtnB && hudTxtB){
    hudBtnB.classList.toggle("off", !h.b);
    hudBtnB.disabled = !h.b;
    hudTxtB.textContent = h.b || "\u2014";
    if(hudKeyB && typeof Keybindings!=="undefined" && Keybindings.getGlyphForAction){
      hudKeyB.textContent = Keybindings.arenaKeysFor("b",sceneKey())[0]||"";
    }
  }
  if(hudBtnY && hudTxtY){
    hudBtnY.classList.toggle("off", !h.y);
    hudBtnY.disabled = !h.y;
    hudTxtY.textContent = h.y || "\u2014";
    if(hudKeyY && typeof Keybindings!=="undefined" && Keybindings.getGlyphForAction){
      hudKeyY.textContent = Keybindings.arenaKeysFor("y",sceneKey())[0]||"";
    }
  }

  /* hints are game-owned strings; escape anyway so innerHTML stays safe */
  const cell=(label,what)=>'<span class="'+(what?"":"off")+'"><b>'+escapeHtml(label)+'</b>'+escapeHtml(what||"-")+'</span>';
  if(ctxEl) ctxEl.innerHTML=cell("A",h.a)+cell("B",h.b)+cell("Y",h.y);
  for(const k in btnEl) if(btnEl[k])
    btnEl[k].setAttribute("aria-label",k.toUpperCase()+" button"+(h[k]?" - "+h[k].toLowerCase():" - unused here"));
}

function render(){
  cx.setTransform(DPR,0,0,DPR,0,0); cx.clearRect(0,0,W,H);
  G.hot.length=0;                    // regions live for exactly one frame
  if(typeof ThreeEngine!=="undefined"&&ThreeEngine.getState().initialized){
    if(G.scene===S.DUEL){
      ThreeEngine.setActiveScene("venue");
    } else if(G.scene===S.TROPHY){
      ThreeEngine.setActiveScene("trophy");
    } else {
      ThreeEngine.setActiveScene("background");
    }
  }
  switch(G.scene){
    case S.LOAD: rLoad(); break;
    case S.TITLE: rTitle(); break;
    case S.MENU: rMenu(); break;
    case S.HOW: rHow(); break;
    case S.OPTIONS: rOptions(); break;
    case S.RECORDS: rRecords(); break;
    case S.BOARD: rBoard(); break;
    case S.RENOWN: rRenown(); break;
    case S.CHALLENGE: rChallenge(); break;
    case S.BENEFIT: rBenefit(); break;
    case S.DRAFT: rDraft(); break;
    case S.SHOP: rShop(); break;
    case S.SERVICE: rService(); break;
    case S.DAILY: rDaily(); break;
    case S.TITLES: rTitles(); break;
    case S.SELECT: rSelect(); break;
    case S.FIGHTER: rFighter(); break;
    case S.MAP: rMap(); break;
    case S.PAUSE: rPause(); break;
    case S.STAGECLEAR: rStageClear(); break;
    case S.BRIEF: rBrief(); break;
    case S.DUEL: rDuel(); break;
    case S.RESULT: rResult(); break;
    case S.RUNEND: rRunEnd(); break;
    case S.CREDITS: rCredits(); break;
    case S.TOWER: rTower(); break;
    case S.DOJO: rDojo(); break;
    case S.CREATE_FIGHTER: rCreateFighter(); break;
    case S.DECK_BUILDER: rDeckBuilder(); break;
    case S.REPLAY: rReplayViewer(); break;
    case S.CODEX: rCodex(); break;
    case S.TROPHY: rTrophy(); break;
    case S.ENDLESS: rEndless(); break;
    case S.WEEKLY: rWeekly(); break;
    case S.PERK: rPerk(); break;
  }
  if(typeof CombatFX!=="undefined"&&SAVE&&SAVE.motion) CombatFX.applyToCanvas(cx,W,H);
  if(typeof FloatingFeedback!=="undefined") FloatingFeedback.render(cx);
  if(typeof CardTooltip!=="undefined") CardTooltip.render(cx);
  if(G.scene===S.OPTIONS&&typeof SettingsGUI!=="undefined"&&SettingsGUI.getRebindState().active){
    SettingsGUI.render(cx,W,H,G.optSel);
  }
  syncRom();
  syncHint();
  syncStageChrome();
}
const TICK=1000/60; let lastTs=0, acc=0;
function mainLoop(ts){
  requestAnimationFrame(mainLoop);
  if(!lastTs) lastTs=ts;
  acc+=Math.min(250,ts-lastTs); lastTs=ts;
  let guard=0;
  while(acc>=TICK&&guard++<8){ step(); acc-=TICK; }
  if(acc>TICK) acc=0;
  if(typeof Interactive3DBG!=="undefined"){
    Interactive3DBG.step();
    Interactive3DBG.render();
  }
  if(typeof ThreeEngine!=="undefined"&&ThreeEngine.getState().initialized){
    ThreeEngine.step(TICK/1000);
    ThreeEngine.render();
  }
  if(typeof syncShowcaseBar==="function") syncShowcaseBar();
  try{ render(); }
  catch(err){ console.error("render", err && err.message ? err.message : "error");
    cx.setTransform(DPR,0,0,DPR,0,0); bgFill("#0c0d10","#08090b");
    txt("DISPLAY FAULT - RELOAD",W/2,H/2,18,RED,"center",800); }
}

/* ================================================================
   11. FIGHT DATA READOUT (page footer)
   Shows the record the fight is actually using - the boss's sealed
   deck sits outside the 21-record table.
   ================================================================ */
let romKey="";
function romTarget(){
  if(G.scene===S.FIGHTER) return {id:G.dossier};
  if(G.scene===S.SELECT) return {id:selList()[G.sel]};
  if(G.scene===S.DUEL&&G.duel){
    if(G.duel.boss) return {id:BOSS_ID,boss:true};
    return {id:G.duel.e.fid,tf:G.duel.tf};
  }
  if(G.scene===S.BRIEF&&G.brief){
    const f=G.brief.f;
    if(f.boss) return {id:BOSS_ID,boss:true};
    return {id:f.tf?f.art:f.id,tf:!!f.tf};
  }
  /* the run is already nulled by the time the summary is on screen, so the
     footer would fall through to fighter 0 and silently swap the record out
     from under a screen that is still about the run's own fighter */
  if(G.scene===S.RUNEND&&G.runEnd) return {id:G.runEnd.hero};
  if(G.adv) return {id:G.adv.hero};
  if(G.surv) return {id:G.surv.hero};
  return {id:0};
}
function syncRom(){
  const t=romTarget(), key=t.id+"|"+(t.boss?1:0)+"|"+(t.tf?1:0);
  if(key!==romKey){ romKey=key; updateRom(t); }
}
function updateRom(t){
  if(t===undefined||t===null) t=romTarget();
  if(typeof t==="number") t={id:t};
  const id=t.id, f=FIGHTERS[id];
  const boss=!!t.boss;
  const dkI=f.deck, dk=boss?BOSS:DECKS[dkI], ord=ORDER[dkI];
  const tr=traitsOf(id);
  document.getElementById("romName").textContent=boss?f.name+" (sealed record)":f.name;
  document.getElementById("romTag").textContent=boss?" - sealed record, outside the 21-deck table"
      :" - data deck #"+String(dkI).padStart(2,"0");
  document.getElementById("romAddr").textContent=boss?"Sealed record - 5 cards - 20 bytes"
      :"Record "+String(dkI).padStart(2,"0")+" - offset +"+(dkI*75)+" - 75 bytes";
  const shared=(DECK_SHARERS[dkI]||[]).filter(i=>i!==id).map(i=>FIGHTERS[i].name);
  const bits=[];
  if(boss) bits.push("5 sealed cards - the champion does not fight on a roster deck");
  else{
    if(t.tf) bits.push("<em>AZX Force</em> fights silhouetted on a borrowed deck");
    if(shared.length) bits.push("deck shared with <em>"+escapeHtml(shared.join(", "))+"</em>");
    bits.push("trait <em>"+escapeHtml(tr.tag)+"</em> - power x"+tr.pow.toFixed(2)+", guard x"+tr.def.toFixed(2)
              +", air x"+tr.air.toFixed(2)+", HP "+tr.hp+", focus "+tr.foc+" (derived from the dossier, not the card record)");
  }
  document.getElementById("romSub").innerHTML=bits.join(" &middot; ");
  const body=document.getElementById("romBody"); body.innerHTML="";
  dk.forEach((c,i)=>{
    const tr2=document.createElement("tr");
    const gainPos=boss?-1:ord.indexOf(i);
    const cells=[i, c[0], c[1], "0x"+c[2].toString(16).toUpperCase().padStart(2,"0")];
    cells.forEach(v=>{ const td=document.createElement("td"); td.textContent=v; tr2.appendChild(td); });
    const k=document.createElement("td"); k.className="k";
    k.textContent=(!boss&&i>=12)?("AIR TIER "+(i-11)):(kindOf(c)+(isLauncher(c)?" / LAUNCHER":"")+(subOf(c)?" / "+subOf(c):""));
    tr2.appendChild(k);
    const g=document.createElement("td");
    g.textContent=boss?"SEALED":((i>=12)?"-":(gainPos<5?"START":"LV "+(gainPos-3)));
    tr2.appendChild(g);
    body.appendChild(tr2);
  });
}
updateRom({id:0});
try{ syncTouchControls(); }catch(e){}
/* Title keys have to work before the first click. The focus gate stays:
   a click outside the arena still releases the keyboard to the page. */
focusArena();
if (typeof navigator !== "undefined" && "serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("./sw.js").catch(() => {});
  });
}
requestAnimationFrame(mainLoop);
